const JBI_EXTRA = {"灯笼草":{"a":"爆卜草、灯笼泡、鬼灯笼、打卜草、水灯笼草、苦灯笼草、荷卜草、打额泡、天泡果、响铃子、地灯笼、母炮草、炮仔草","s":"味苦；性凉 \n\n①《陆川本草》：\"甘淡，微寒。\"\n\n②《南宁市药物志》：\"苦，寒，微甘。\"","f":"清热，行气，止痛，消肿。治感冒，痄腮，喉痛，咳嗽，腹胀，疝气，天疱疮。\n\n①《陆川本草》：\"行气，消胀，利尿。治腹胀，睾丸炎，疝气。\"\n\n②《南宁市药物志》：\"清热杀虫，止痛消肿。治热眼，喉痛，咳嗽；外敷毒疮，并熏洗阴囊肿大。\"\n\n③《生草药手册》：\"内服治伤寒或小肠疝气。外洗治天疱疮。\"\n\n④《中国药植图鉴》：\"功同酸浆。\"\n\n⑤广州空军《常用中草药手册》：\"治感冒发热，腮腺炎，支气管炎，疱疹，疖疮，疝气痛。\"","y":"内服：煎汤，3～5钱。外用：捣敷或煎水洗。","d":"性状鉴别 全草长25-60cm。茎略呈扁方柱形，具棱，表面灰黄白色或灰青色，密被白色茸毛。叶皱缩卷曲，展平后呈卵圆形，长2-5cm，宽2-3cm，先端尖，基部楔形或微心形，近全缘或有不规则疏粗齿，暗绿色或黄绿色，两面被白色茸毛；齿长叶柄。叶依处具膨大似灯笼状的花萼，有的已压扁，长约2.5cm，宽约2cm，淡黄绿色，薄纸质，半透明，被有柔毛，内有暗黄绿色奖学金果，近圆形，直径约1cm。气微，味甘、基。以全草幼嫩、色黄绿、带果宿萼多者为佳。"},"皂角刺":{"a":"皂荚刺、皂刺、天丁、皂角针、皂针","s":"辛，温。\n\n①《纲目》：\"辛，温，无毒。\"\n\n②《医林纂要》：\"辛咸，温。\"\n\n③《四川中药志》：\"性温，味辛，有小毒。\"\n\n归肝；肺经","f":"搜风，拔毒，消肿，排脓。治痈肿，疮毒，疠风，癣疮，胎衣不下。\n\n①《本草图经》：\"米醋熬嫩刺针作浓煎，以敷疮癣。\"\n\n②杨士瀛：\"能引诸药上行，治上焦病。\"\n\n③《本草衍义补遗》：\"治痈疽已溃，能引至溃处。\"\n\n④《纲目》：\"治痈肿，妒乳，风疠恶疮，胞衣不下，杀虫。\"\n\n⑤《本草崇原》：\"去风化痰，败毒攻毒。定小儿惊风发搐，攻痘疮起发，化毒成浆。\"\n\n⑥《四川中药志》：\"治风热疮疹，并能通乳。\"\n\n⑦《药材学》：\"治扁桃体炎。\"","y":"内服：煎汤，1～3钱；或入丸、散。外用：醋煎涂，研末撒或调敷。","d":"完整的棘刺有多数分枝，主刺圆柱形，长5～15厘米，基部粗约8～12毫米，末端尖锐；分枝刺一般长1.5～7厘米，有时再分歧成小刺。表面棕紫色，尖部红棕色，光滑或有细皱纹。质坚硬，难折断。药材多纵切成斜片或薄片，厚在2毫米以下，木质部黄白色，中心为淡灰棕色而疏松的髓部。无臭，味淡。以片薄、纯净，整齐者为佳。\n主产江苏、湖北、河北、山西、河南、山东。此外，广东、广西、四川、安徽、浙江、贵州、陕西、江西、甘肃等地亦产。"},"马钱子":{"a":"番木鳖、苦实把豆儿(《飞鸿集》)，火失刻把都(《纲目》)，苦实(《本草原始》)，马前，牛银(《本草求原》)，大方八(《中药材手册》)。","s":"苦，寒，有毒。\n\n①《纲目》：\"苦，寒，无毒。\"\n\n②《本草原始》：\"味苦，寒，大毒。\"","f":"散血热，消肿，止痛。治咽喉痹痛，痈疽肿毒，风痹疼痛，骨折。并治面神经麻痹，重症肌无力。通络止痛，散结消肿。用于风湿顽痹、麻木瘫痪、跌扑损伤、痈疽肿痛。\n\n①《纲目》：\"治伤寒热病，咽喉痹痛，消痞块，并含之咽汁，或磨水噙咽。\"\n\n②《中药志》：\"散血热，消肿毒。治痈疽，恶疮。\"","y":"内服：炮制后入丸、散，每次0.2-0.6g。大剂量0.9g。\n\n\n　　外用：适量，研末撒，浸水，醋磨、煎油涂敷或熬膏摊贴。","d":"干燥成熟的种子呈扁圆形，钮扣状，略弯曲，边缘微隆起，常一面稍凹下，另一面稍突起，直径1～3厘米.厚3～6毫米，表面灰棕色或灰绿色，密生匍伏的银灰色毛茸，呈辐射状排列，有丝光，底面中央有一稍突出的圆点，边缘有一小突起，在圆点与小突起之间有一条棱线。质坚硬，难破碎，破开后种仁淡黄白色，稍透明，角质状。纵切面可见心形的子叶。无臭，味极苦。毒性剧烈，口尝宜特别谨慎.以个大、肉厚、质坚者为佳。\n主产印度、越南、缅甸等地。\n\n马钱子历来多为进口药，现我国云南有马钱藤，经测定种子含番木鳖碱，可以代替进口马钱子。生药外形与马钱子相似，长径20～30毫米，短径15～22毫米，中央厚6～10毫米，每个重1.3～2.7克；外面密被棕白色至棕色，光亮的绢毛，自中央向四周辐射状匍匐排列；种脐在种子中央，珠孔在种子的边缘。\n\n　　显微鉴定： 种子横切面：种皮表皮细胞分化成单细胞毛，向一侧斜伸，长500～1100μm，宽约25μm以上，其部膨大，似石细胞状，直径约75μm，壁极厚，强木化，有纵长扭曲的纹孔，毛的体部肋状木化增厚，胸腔断面观类圆形;种皮内层为舫的棕色薄壁细胸，内胚乳细胞壁厚约25μm ，胞间连丝隐约可见，以碘液处理后较明显，细胞内含脂肪油滴及糊粉粒。"},"见血清":{"a":"羊耳蒜、立地好、毛慈姑、岩芋、黑兰、矮胖儿、肉螃蟹、铁耙梳、倒岩提、走子草、肉龙箭、香花羊耳蒜、紫星羊耳蒜、香羊耳蒜","s":"苦，凉。\n\n①《浙江民间常用草药》：\"苦，平。\"\n\n②《四川常用中草药》：\"苦，凉。\"\n\n　归肺；肾经","f":"凉血止血，清热解毒。治吐血，咯血，肠风下血，血崩，手术出血，小儿惊风，热毒疮疡，蛇咬伤。\n\n①《民间常用草药汇编》：\"清血，凉血，止血。治牙痛。酒泡服治跌打损伤。\"\n\n②《浙江民间常用草药》：\"清热解毒，补肺止血。\"\n\n③《四川常用中草药》：\"生新散瘀，清肺，止吐血。治各种吐血，劳伤咳嗽，肺肾阴虚咯血，肠风下血，红崩，拔脓生肌，刀伤。\"\n\n④《贵州药植目录》：\"治劳伤，小儿走子，搭背。\"","y":"内服：煎汤，2～4钱(鲜品1～2两)；或浸洒。外用：捣敷或煎水含漱。","d":"性状鉴别：茎类圆形，粗达30cm，或切片厚1cm。表面灰绿色或淡棕色，散布不规则灰白色斑纹。树心处的块片呈深黄色。横切片年轮明显，射线放射状排列。质坚硬，折断面纤维状。气微，味苦。 显微鉴别：茎横切面：外为木栓细胞，栓内层有纤维，单个或2-20个成束散在，薄壁细胞内有单晶及少数簇晶，韧皮部有许多纤维束切向排列呈层状，纤维壁薄，弱木化，纵切面观长140-240μm，直径12-20μm，两端细尖；射线内有单晶或簇晶，簇晶直径16-20μm。木质部由导管、木纤维及木细胞组成，均木化，导管内常含黄棕色内含物。木射线1-5列细胞，具单纹孔。含淀粉粒。 　　理化鉴别：（1）取本品粗粉1g，加水10ml，煮沸2-3min，趁热滤过，取滤液置试管中，用力振摇，产生持久性泡沫，加热后泡沫不消失。（检查皂甙）（2）溶血试验取2％去纤维红细胞生理盐水混悬液1滴，放在载玻片上，加盖玻片后，在显微镜下观察红细胞的形状，然后在盖玻片一侧加1滴样品生理盐水浸液（l：3），在盖玻片的另一端用滤纸吸引液体，使检波逐渐渗入盖玻片下，与红细胞接触处迅速发生溶血。（检查皂式）（3）本品水提取液蒸干，加1-2ml醋酐溶解，再加浓硫-醋酐试剂。颜色由黄转为红色、紫色、蓝色。（检查皂式） 。"},"石油菜":{"a":"石花菜、肥奴奴草(《广西中药志》)，小石芥、冷冻草、疳积草(《广西药植名录》)，石苋菜、肥猪菜、打不死(《广西中草药》)。","s":"《广西中草药》：\"味淡，性凉。\"","f":"①《广西中药志》：\"清热解毒，化痰止咳。治肺痨咳嗽，热毒恶疮。\"\n\n②《广西药植名录》：\"清热，利水，解毒。治火烫伤，疳积，疮疥。\"","y":"内服：煎汤，0.5～4两(鲜者2～4两)。外用：捣敷。","d":"?"},"姜三七":{"a":"三七姜、姜叶三七、土田七、竹叶三七、姜七","s":"辛，温。","f":"止血消肿。治跌打损伤，骨折，吐血，衄血子宫功能性出血，外伤出血。","y":"内服：煎汤，0.5～1钱。外用：研末撒。","d":"?"},"假酸浆":{"a":"水晶凉粉,蓝花天仙子,大千生,冰粉,鞭打绣球,草本酸木瓜,苦莪","s":"味甘；微苦；性平；小毒\n \n《云南中草药选》：\"甘淡微苦，平。\"(有毒)","f":"清热解毒；利尿镇静 \n\n①《广西药植名录》：\"止咳，治痧气，疥癣。\"\n\n②《云南中草药选》：\"镇静，祛痰，清热，解毒。治狂犬病，精神病，癫痫，风湿痛，疮疖，感冒。\"","y":"内服：煎汤，全草或工化3-9g，鲜品15-30g；果实1.5-3g。","d":"叶含假酸浆烯酮(nicandrenone)，即假酸浆酮-1(nic-1)，假酸浆烯酮内酯(nic-1-lactone)，假酸浆酮(nic)-1(nic-1)，假酸浆烯酮内酯(nic-1-lactone)，假酸浆酮(nic)-2、-3、-7、-10、-11、-12、17，叶中还含魏察假酸浆酮(withanicandrin)。新鲜的全草含假酸浆甙苦素(nicandrin)。\n种子中含少量曼陀罗甾内酯(daturalactone)，脱脂的种子含假酸浆甙苦素B，魏察假酸浆酮。种子油含脂肪酸和甾醇类化合物。脂肪酸主要为棕榈酸(palmoitic acid)，油酸(oleic acid)，亚油酸(linoleic acid)，还有少量亚麻酸(linolenic acid)；甾醇类化合物包括胆甾醇(cholesterol)，菜油甾醇(campesterol)，豆甾醇(stigmasterol)，谷甾醇(sitosterol)，24-亚乙基胆甾醇(24-ethylidene cholesterol)。\n根中含古豆碱(hygrine)，托品酮(tropinone)。"},"七里香":{"a":"台湾海桐花","s":"①《修订增补天宝本草》：\"味酸辛。\"\n\n②《四川中药志》：\"性温，味辛苦，有小毒。\"","f":"活血化瘀。治经闭，癥瘕，血崩，小儿疳积，腮腺炎。\n\n①《民间常用草药汇编》：\"调气血，通月经。\"\n\n②《四川中药志》：\"行血活血。治血瘀癥瘕及崩带。\"","y":"内服：煎汤，3～6钱(鲜者1～2两)。","d":"根长30～90厘米，粗1～2厘米，外表灰棕色，断面内心淡棕色，较坚硬。\n\n产四川、湖南。"},"珠子参":{"a":"鸡腰参、大金线吊葫芦、珠儿参、白地瓜","s":"甘，平。\n\n①《滇南本草》：\"性温平，味甘微苦。\"\n\n②《昆明民间常用草药》：\"性平，味淡甜。\"","f":"补肺止咳；止血；生肌。主肺虚咳嗽；外用力出血；刀伤疮\n\n\n①《滇南本草》；\"止血生肌。为末，捻刀伤疮，收口甚速。\"\n\n②《昆明民间常用草药》：\"补肺虚。治肺虚咳嗽。\"","y":"内服：煎汤，0.5～1两。外用：研末撒。","d":"（1）本品横切面：木栓层为数列木栓细胞。皮层稍窄，有分泌道，呈圆形或长圆形，直径32～500μm，周围分泌细胞5～18个 。韧皮部分泌道较小。形成层断续可见。木质部导管呈放射状或 “Ｖ” 字形排列；导管类多角形，直径约至76μm ；射线宽广。中央有髓。薄壁细胞含淀粉粒，有的含草酸钙簇晶。\n（2）取本品粉末1g，加水10ml，浸泡过夜，热浸10分钟，立即滤过。取具塞试管两支，各加入滤液1ml ，分别加氢氧化钠试液与盐酸溶液（1 →20）各2ml,用力振摇1 分钟，加酸管生成的泡沫比加碱管高出约1 倍。\n（3）取本品粉末约0.5g，加乙醇5ml ，振摇30分钟，滤过，滤液蒸干，滴加三氯化锑饱和的氯仿溶液，再蒸干，即显紫红色。\n（4）取本品粉末1g，加水5～10 滴，搅匀，再加水饱和的正丁醇10ml，密塞，振摇约10分钟，放置过夜，滤过，滤液蒸干，残渣加硫酸与30％乙醇的混合溶液 （1 →20）10ml ，加热回流2 小时，用氯仿20ml提取，分取氯仿层，用水10ml洗涤（必要时离心，使分层），弃去洗液，蒸干，残渣加甲醇1ml 使溶解，作为供试品溶液。另取齐墩果酸与人参二醇对照品，加甲醇制成每1ml 含齐墩果酸1.5mg 和人参二醇0.5mg 的混合溶液，作为对照品溶液。照薄层色谱法（附录Ⅵ B）试验，吸取上述两种溶液各10μl,分别点于同一硅胶Ｇ薄层板上，以苯－醋酸乙酯（1:1）为展开剂，展开，取出，晾干，喷以硫酸溶液（1→10），在 105℃加热至斑点显色清晰，置紫外光灯（365nm）下检视。供试品色谱中，在与对照品色谱相应的位置上，显相同颜色的荧光斑点。"},"红辣树根":{"a":"野辣椒根、红辣树、云南鸡骨常山","s":"性状：干燥根呈圆柱形，略弯曲，往往分枝，长10～25厘米，径1.5～3厘米，表面暗棕色至灰褐色，皮部薄，常脱落，露出白色的本部。质坚硬，难折断，支根较脆。断面呈裂片状，类白色。横切面射线显着。","f":"①《广西中药志》：\"外用消肿，治局部红肿。又降血压。\"\n\n②《广西本草选编》：\"清热解毒，截疟，消肿止痛。治疟疾，感冒发热，肺热咳嗽，咽喉肿痛，口腔炎。\"","y":"内服：煎汤，2～4钱。外用：捣敷。","d":"干燥根呈圆柱形，略弯曲，往往分枝，长10～25厘米，径1.5～3厘米，表面暗棕色至灰褐色，皮部薄，常脱落，露出白色的本部。质坚硬，难折断，支根较脆。断面呈裂片状，类白色。横切面射线显著。"},"金边龙舌兰":{"a":"金边莲,金边假菠萝,龙舌兰,黄边龙舌兰","s":"甘微辛，平。\n\n①《南宁市药物志》：\"甘微辛，平，无毒。\"\n\n②《成都中草药》：\"甘淡，平。\"","f":"润肺，化痰，止咳。治虚劳咳嗽，吐血，哮喘。\n\n①《民间常用草药汇编》：\"化瘀定喘。治咳嗽吐血。\"\n\n②《南宁市药物志》：\"有祛瘀生新作用。治肺胃出血。外敷治毒疮。\"\n\n③《成都中草药》：\"清热，润肺，止血。\"","y":"内服：煎汤，鲜者1～2两。外用：捣敷。","d":"性状鉴别 叶片皱缩折曲，展平后完整者呈剑形或长带状，最宽处在中产，长20-40cm，宽1.5-5cm。从基部到顶端两面边缘金黄色，约为叶片宽的1/3，中间暗绿色，具密集的细小纵纹及大小不等长的折断痕，有的断痕处可见黄棕色胶状物；先端细刺尖，两侧边缘显浅波状，其突起处均具极细小的硬刺。质坚韧，难折断。气稍臭，味酸、涩。"},"大蓑衣藤根":{"a":"?","s":"味辛，性温。","f":"行气活血，祛风湿，止痛。治跌打损伤，瘀血疼痛，风湿性筋骨痛，肢体麻木。","y":"内服：煎汤，3～4钱。","d":"?"},"松叶":{"a":"猪鬃松叶、松毛、山松须、松针","s":"苦；性温 \n\n①《别录》：\"味苦，温。\"\n\n②《日华子本草》：\"暖，无毒。\"\n\n归心；脾经 \n\n《本草再新》：\"入心、脾二经。\"","f":"祛风燥湿，杀虫，止痒。治风湿痿痹，跌打损伤，失眠，浮肿，湿疮，疥癣。并能防治流脑，流感，钩虫病。\n\n①《别录》：\"主风湿疮，生毛发，安五脏。\"\n\n②《日华子本草》：\"炙罯冻疮、风湿疮。\"\n\n③《纲目》：\"去风痛脚痹，杀米虫。\"\n\n④《生草药性备要》：\"杀螆，干水，止痒，埋口(合疮口)。洗疳疮，治螆疥。\"\n\n⑤《会约医镜》：\"辟瘟疫气。\"\n\n⑥广州部队《常用中草药手册》：\"治神经衰弱，维生素丙缺乏，营养性水肿；防治流脑，流感。\"","y":"内服：煎汤，3～5钱(鲜叶1～2两)；或浸酒。外用：煎水洗。","d":"干燥的松叶呈针状，长约12～18厘米，粗约0.1厘米，两叶并成一束，外包有长约0.5厘米的叶鞘，呈黑褐色。中央有长细沟，表面光滑，灰暗绿色，质轻脆，臭微。"},"回心草":{"a":"茴心草,茴薪草,铁脚一把伞,岩谷伞","s":"辛、苦，平。\n\n《云南中草药选》：\"淡微苦，平。\"","f":"安神镇静。治心脏病心慌、心悸，神经衰弱。\n\n①《云南中草药选》：\"镇静，壮阳。\"\n\n②《云南思茅中草药选》：\"安神镇静。治心慌、心悸。心脏病。\"","y":"内服：煎汤，2～3钱。","d":"性状鉴别 本品多干缩。茎长2-3.5cm，红褐色。茎下部叶鳞片状，贴生，膜质；顶叶簇生呈蔷薇花状，长倒卵形，长5-8mm，宽2-3mm，边缘上部有锯齿，下部全缘，内卷。蒴柄细，长3-5cm，孢蒴红黄色，下垂。气微，味淡微苦。"},"铁树花":{"a":"凤尾蕉","s":"性甘、平、涩，有小毒。","f":"止血，下痰\n\n①《药性考》：\"治痰火。\"\n\n②《岭南采药录》：\"止血，下痰。治痰火。\"","y":"?","d":"?"},"雷公藤":{"a":"震龙根、蒸龙草、莽草、水莽子、水莽兜、黄藤、大茶叶、水莽、黄藤草、红柴根、菜虫药、断肠草、黄藤根、黄药、水脑子根、南蛇根、三棱花、早禾花、红紫根、黄腊藤、水莽草、红药、山砒霜、黄藤木","s":"苦；辛；大毒 \n\n《湖南药物志》：\"苦，大毒。\"\n\n归心；肝经","f":"祛风除湿；活血通络；消肿止痛；杀虫解毒 \n主治类风湿性关节炎；风湿性关节炎；肾小球肾炎；肾病综合征；红斑狼疮；口眼干燥综合征；白塞病；湿疹；银屑病；麻风病；疥疮；顽癣 \n\n《湖南药物志》：\"杀虫，消炎，解毒。\"","y":"内服：煎汤，去皮根木质部分15-25g；带皮根10-12g。均需文火煎1-2h。也可制成糖浆、浸膏片等。岩研粉装胶囊服，每次0.5-1.5g，每日3次。外用：适量，研粉或捣烂或；或制成酊剂、软膏涂擦。","d":"性状鉴别 根圆柱形，扭曲，常具茎残基。直径0.5-3cm，商品常切成长短不一的段块。表面土黄色至黄棕色，粗糙，具细密纵向沟纹及环状或半环状裂隙；栓皮层常脱落，脱落处显橙黄色。皮部易剥离，露出黄白色的木部。质坚硬，折断时有粉尘飞扬，断面纤维性；横切面木栓层橙黄色，显层状；韧皮部红棕色；木部黄白色，密布针眼状孔洞，射线较明显。根茎性状与根相似，多平直，有白色或浅红色髓部。气微、特异，味苦徽辛。有大毒。显微鉴别 根横切面：木栓层为数十列木栓细胞组成，有的细胞内含红棕色或黄棕色物质。皮层菲薄，界限不甚明显。韧皮部有众多分泌细胞，内含黄棕色物质，韧皮射线漏斗状或略呈漏斗状，射线细胞和韧皮部薄壁细胞含淀粉粒及较大的草酸钙结晶。形成层环明显。木质部导管多单个径向排列，傍管纤维常成束分布；木薄壁细胞壁较厚，含淀粉粒；木射线细胞1-6列，其旁常有1-多列木纤维，有的纤维含淀粉粒。初生木质部三原型，多偏心性。根茎横切面：构造与根基本相似，但皮层明显，细胞2-4列；具髓。粉末特征：土黄色。①木纤维散在或成束，长梭形，长300-780μm，直径11-28μm，其中一种壁较薄，平直或略呈波状，胞腔中含有淀粉粒；另一种壁较厚，可至6μm，孔沟明显。②具缘纹孔及网纹导管，直径23-116μm。③管胞多为螺纹或孔纹。④淀粉粒众多，单粒类圆形、类三角形或类多角形，直径3-8 （-17)μm，脐点点状、星状或人字形；复粒2-3分粒组成。⑤草酸钙方晶众多，呈棱形、四面体、六面体或八面体，直径可至70μm。⑥木薄壁细胞类方形或长方形，孔沟及壁孔明显，有的胞腔内充满淀粉粒。⑦木柱细胞表面观多角形，有的含黄棕色物质。⑧分泌细胞类圆形或椭圆形，直径28-42μm，胸腔内含黄棕色物质。"},"苦丁茶":{"a":"苦灯茶","s":"①《医林纂要》：\"苦甘，大寒。\"\n\n\n②《纲目拾遗》：\"味甘苦。\"","f":"散风热，清头目，除烦渴。治头痛，齿痛，目赤，聤耳，热病烦渴，痢疾。\n\n\n①《本经逢原》：\"止痢。\"\n\n\n②《医林纂要》：\"治天行狂热。\"\n\n\n③《纲目拾遗》：\"逐风、活血，绝孕。\"\n\n\n④《本草再新》：\"消食化痰，除烦止渴，利二便，去油腻。\"\n\n\n⑤《本草求原》：\"清肺脾，止痢，清头目。\"\n\n\n⑥《中国医学大辞典》：\"散肝风，清头目，治耳鸣、耳聋、聤耳流脓，活血脉，凉子宫。\"\n\n\n⑦《四川中药志》：\"能清热散风，除烦解渴。治头痛、齿痛、耳鸣、目赤及食滞有痰。\"","y":"内服：煎汤，1～3钱；或入丸剂。外用：煎水熏洗。","d":"①枸骨叶;又名：角刺茶(《纲目拾遗》)。性状详\"枸骨叶\"条。也有用枸骨老树的叶，叶片呈卵圆形，先端短尖，基部圆形，上面光滑，革质而厚。\n\n\n产江苏、浙江等地。\n\n\n②大叶冬青叶，又名：苦灯茶((毒草求尿》)。呈卵状长椭圆形，革质，不皱缩，有的纵向微卷曲，上面黄绿色或灰绿色，有光泽，下面黄绿色，味微苦。\n\n\n产浙江、福建、广西等地。\n\n\n苦丁茶的品种较为复杂，除上述主要品种外，在江苏、安徽地区有用茶叶加枸骨叶煎汁焙制而成者，外表绿褐色或黄绿色，与一般粗茶相似，用沸水泡开后，伸展的叶片为阔披针形及卵状披针形，边缘有锯齿，浸液味苦，浓者不堪入口，与昔通茶叶不同。四川地区有用木犀科植物序梗女贞的叶;贵州地区则用日本毛女贞的叶作苦丁茶使用，参见\"苦茶叶\"条。"},"独一味":{"a":"巴拉努努、吉布孜、麦朵昌巴、哈努巴拉、札江温保、哈吾巴拉、达干木、达折合巴、野秦艽、大巴、打布巴","s":"苦，微寒。\n\n①《四川中药志》：\"苦，微寒，有小毒。\"\n\n②《青藏高原药物图鉴》：\"苦，温。\"","f":"；止血。治\n\n\n\n①《四川中药志》：\"活血行瘀，止痛，行气，消肿，续筋接骨。治跌伤筋骨及闪腰挫气等症。\"\n\n②《青藏高原药物图鉴》：\"补髓，止血。治浮肿后流黄水，关节积黄水，骨松质发炎。\"","y":"内服：浸酒或入散剂，1～2钱。","d":""},"驴阴茎":{"a":"驴鞭,驴三件,驴肾","s":"甘咸，温。\n\n\n①《纲目》：\"甘，温，无毒。\"\n\n\n②《四川中药志》：\"性温，味甘咸，无毒。\"","f":"益肾强筋。治阳痿，筋骨酸软，骨结核，骨髓炎，气血虚亏，妇女乳汁不足。\n\n\n①《纲目》：\"强阴壮筋。\"\n\n\n②《四川中药志》：\"滋肾壮阳。治阳痿不举，筋骨酸软及肾囊现冷。\"\n\n\n③《吉林中草药》：\"强筋，壮骨，滋阴扑虚。治骨结核、竹髓炎、血虚气弱、妇女乳汁不足。\"","y":"内服：煎汤，3～4钱；或入丸剂。","d":"为圆柱形长条，或稍带弯曲，长约30厘米，粗3～4厘米，前端圆形，较大，色黑；基部两侧各有一大型睾丸；肉质，坚硬。以整条，带有睾丸、无残肉油脂、体干燥者为佳。"},"过山龙":{"a":"羊葡萄蔓(《陕西中草药》)，草葡萄(《陕甘宁青中草药选》)。","s":"《陕西中草药》：\"辛，热。\"\n\n入心经","f":"《陕西中草药》：\"活血散瘀，消炎解毒，生肌长骨，除风祛湿。治跌打损伤，骨折，疮疖肿痛，风湿性关节炎。\"","y":"内服：煎汤，3～5钱；或研末。外用：捣敷。","d":"?"},"百合子":{"a":"?","s":"甘；苦；凉 \n\n归大肠经","f":"清热凉血 主肠风下血 \n\n孙思邈：\"治肠风下血，百合子酒炒微赤，研末，汤服。\"","y":"内服：煎汤，研末，3-9g。","d":"?"},"化橘红":{"a":"化皮、化州橘红、柚皮橘红、柚类橘红、兴化红、毛柑、毛化红、赖橘红","s":"苦辛，温。\n\n①《纲目拾遗》：\"味苦辛。\"\n\n②《岭南采药录》：\"味苦辛，性温平，无毒。\"\n\n归脾；肺经","f":"化痰，理气，健胃，消食。治胸中痰滞，咳嗽气喘，呕吐呃逆，饮食积滞。\n\n《纲目拾遗》：\"治痰症，消油腻、谷食积，醒酒，宽中，解蟹毒。\"","y":"内服：煎汤，1～2钱；或入丸、散。","d":"干燥的外果皮，呈对折的七角，六角或五角星形，展开后直径13～20厘米，厚2～3毫米。化州柚的外皮黄色或黄绿色，密布毛茸，有皱纹及小凹点，多作成七角，习称\"黄七爪\"、\"绿七爪\"；柚的外皮黄棕色，光而无毛茸，亦有皱纹及小凹点，多成五角形，习称\"大五爪\"；加工为六角形者，称\"六爪红\"，单片呈柳叶状者，习称\"尖化红\"，或称\"柳叶橘红\"。内表面多为黄白色，有脉络纹。质脆，易折断，断面不齐，外侧有一列不整齐的油点，内侧黄白色。气微香，味苦。以皮厚、多毛，气味浓厚者为佳。\n主产广东、广西等地。"},"橘叶":{"a":"橘子叶","s":"苦辛，平。\n\n①《滇南本草》：\"性温，味苦辛。\"\n\n②《纲目》：\"苦，平，无毒。\"\n\n归肝经  \n\n朱震亨：\"入足厥阴肝经气分。\"","f":"疏肝，行气，化痰，消肿毒。治胁痛，乳痈，肺痈，咳嗽，胸膈痞满，疝气。\n\n①朱震亨：\"导胸脯逆气，行肝气，消肿散毒，乳痈胁痛，用之行经。\"\n\n②《滇南本草》：\"行气消痰，降肝气。治咳嗽，疝气等症。\"","y":"内服：煎汤，2～5钱(鲜者2～4两)；或捣汁。","d":"干燥叶多卷缩，平展后呈菱状长椭圆形或椭圆形，长5～8厘米，宽2～4厘米，表面灰绿色或黄绿色，光滑，对光可照见众多的透明小腺点。质厚，硬而脆，易碎裂。气香，味苦。"},"草木灰":{"a":"冬灰、藜灰(《本经》)，薪柴灰(《纲目》)。","s":"辛，温。\n\n①《本经》:\"味辛，微温。\"\n\n②《纲目》:\"辛，微温，有毒。\"","f":"治大骨节病，蚀痈疽恶肉。\n\n①《本经》:\"主黑子，去肬息肉，疽蚀，疥瘙。\"\n\n②《唐本草》:\"煮小豆，大下水肿。\"\n\n③《本草拾遗》:\"和醋熨心腹冷气痛及血气绞痛，冷即易。\"\n\n④《纲目》:\"治犬咬，热灰敷之，蚀诸痈疽恶肉。\"","y":"草木灰3斤，加水10斤，充分搅拌后浸泡24小时，澄清，取上清夜或过滤取滤液，煮沸浓缩2斤，每次口服30～40毫升，一日3次，连服30天为一个疗程，可视病情，连用几个疗程。","d":"?"},"菊苣":{"a":"卡斯尼(维名)。","s":"性凉，味微苦、咸。归经暂无。","f":"《新疆中草药手册》：\"清肝利胆。治黄疸型肝炎。以菊苣三钱水煎服，并用适量煎水洗身。\"","y":"内服：煎汤，3-9g。外用：适量，煎水洗。","d":"?"},"血参":{"a":"乳腺草","s":"味甘；性温 \n\n归心、肝经。","f":"补血，活血。治贫血，产后大流血，子宫肌瘤，闭经，神经衰弱。","y":"内服：煎汤，3～5钱。","d":"?"},"玫瑰花":{"a":"徘徊花、笔头花、湖花、刺玫花、刺玫菊","s":"甘微苦，温.\n\n①姚可成《食物本草》：\"味甘微苦，温，无毒。\"\n\n②《随息居饮食谱》：\"甘辛，温。\"\n\n入肝、脾二经\n\n《本草再新》：\"入肝、脾二经。\"","f":"理气解郁，和血散瘀。治肝胃气痛，新久风痹，吐血咯血，月经不调，赤白带下，痢疾，乳痈，肿毒。\n\n①姚可成《食物本草》：\"主利肺脾，益肝胆，辟邪恶之气，食之芳香甘美，令人神爽。\"\n\n②《药性考》：\"行血破积，损伤瘀痛，浸酒饮。\"\n\n③《纲目拾遗》：\"和血，行血，理气。治风痹。\"\n\n④《本草再新》：\"舒肝胆之郁气，健脾降火。治腹中冷痛，胃脘积寒，兼能破血。\"\n\n⑤《随息居饮食谱》：\"调中活血，舒郁结，辟秽，和肝。酿酒可消乳癖。\"\n\n⑥《现代实用中药》：\"用于妇人月经过多，赤白带下及一般肠炎下痢等。\"\n\n⑦《山东中药》：\"治盱胃气痛，恶心呕吐，消化不良，泄泻，口舌糜破，吐血，噤口痢。\"\n\n⑧《泉州本草》：\"治肺病咳嗽痰血、吐血、咯血。\"","y":"内服：煎汤，1～2钱；浸酒或熬膏。","d":"干燥花略成半球形或不规则团状，直径1.5～2厘米。花瓣密集，短而圆，色紫红而鲜艳，中央为黄色花蕊，下部有绿色花萼，其先端分裂成5片。下端有膨大星球形的花托。质轻而脆。气苈香浓郁，味微苦。以朵大、瓣厚、色紫、鲜艳、香气浓者为佳。\n主产于江苏、浙江、福建、山东、四川、河北等地。"},"一枝蒿":{"a":"鹿角蒿、新疆一枝蒿","s":"辛苦，微温，有毒。\n\n①《四川中药志》：\"性微温，味辛麻苦，有毒。\"\n\n②《陕甘宁肯中草药选》：\"味辛苦，性子，有小毒。","f":"活血，祛风，止痛，解毒。治跌打损伤，风湿疼痛，痞块，痈肿。\n\n①《纲目》：\"蓍叶主治痞疾。\"\n\n②《纲目拾遣》：\"活血解毒，去一切积滞、沉痼阴寒等疾，驱风理怯。\"\n\n③《分类草药性》：\"治一切热毒，涂疮生肌。\"\n\n④《东北药植志》：\"为健胃、强壮剂，又为痔药。\"","y":"内服：煎汤，O.5～1钱；浸酒或入散剂。外用：捣敷或泡酒涂擦；研末调敷。","d":"干燥全草，多已折断，根头短，密生须根。全体被灰白色毛茸，茎之上部略有分枝，表面棕黄色略紫，有顺向细纹。断面中空，内表面白色.叶稍卷缩，灰绿色或棕黄色，叶缘裂片细小如蜈蚣足。花呈半球形，枯黄棕色。气微弱，味微苦。以干燥、完整、无根、无杂质者为佳。\n\n产东北，华北及四川、贵州等地。"},"落地生根":{"a":"土三七、叶生、叶爆芽、厚面皮、着生药、伤药、打不死、叶生根、晒不死、古仔灯、新娘灯、天灯笼、枪刀草、大疔癀、大还魂","s":"酸，寒。肺，肾经\n\n①《陆川本草》：\"性寒，味酸。\"\n\n②《南宁市药物志》：\"苦，寒。\"\n\n③《广西中药志》：\"味淡，性寒。\"\n\n④《泉州本草》：\"味甘淡，性大寒。\"","f":"凉血，止血，消肿，解毒。治吐血，刀伤出血，胃痛，关节痛，咽喉肿痛；乳痈，疔疮，溃疡，烫伤。\n\n①《植物名实图考》：\"凉血，止吐血。\"\n\n②《岭南采药录》：\"敷疮毒，能拔毒。\"\n\n③《陆川本草》：\"止血，消炎，生肌。治刀伤出血，疮痈溃烂，烫伤，中耳炎。\"\n\n④《南宁市药物志》：\"叶：消肿止痛。外用治跌打，刀伤，热疮红肿，热眼过膜(加冰片)；根：内服治肺热咳嗽(煲猪肉)。\"","y":"内服：煎汤，鲜叶1～2两，根1～2钱。外用：捣敷、绞汁晒粉干掺或捣汁含漱。","d":"?"},"绿萼梅":{"a":"梅、春梅、干枝梅、酸梅、乌梅","s":"苦、微甘，平。","f":"","y":"1～3钱。","d":"小乔木，稀灌木，高4-10米；树皮浅 灰色或带绿色，平滑；小枝绿色，光滑无毛。叶片卵形或椭圆形，长4-8厘米，宽2.5-5厘米，先端尾尖，基部宽 楔形至圆形，叶边常具小锐 锯齿，灰绿色，幼嫩时两面被短柔毛，成长时逐渐脱落，或仅下面脉 腋间具短柔毛；叶柄长1-2厘米，幼时具毛，老时脱落，常有腺体。\n\n　　花单生或有时2朵同生于1芽内，直径2-2.5厘米，香味浓，先于叶开放； 花梗短，长约1-3毫米，常无毛； 花萼通常红褐色，但有些品种的花萼为绿色或绿紫色；萼筒宽钟形，无毛或有时被短柔毛；萼片卵形或近圆形，先端圆钝；花瓣倒卵形，白色至粉红色；雄蕊短或稍长于花瓣；子房密被柔毛，花柱短或稍长于雄蕊。 果实近球形，直径2-3厘米，黄色或绿白色，被柔毛， 味酸；果肉与核粘贴；核椭圆形，顶端圆形而有小突尖头，基部渐狭成楔形，两侧微扁，腹棱稍钝，腹面和背棱上均有明显纵沟，表面具蜂窝状孔穴。花期冬春季，果期5-6月。"},"散血草":{"a":"地龙胆、山苦草、石灰菜、苦草、胆草","s":"苦，凉。肝经","f":"清热利湿；凉血止血。主痢疾；小儿泄泻；淋浊；便血；衄血","y":"","d":"?"},"南瓜子":{"a":"南瓜仁、白瓜子、金瓜米、窝瓜子、倭瓜子","s":"味甘；性平 \n\n《陆川本草》:\"甘，平。\"\n\n归大肠经","f":"治绦虫，蛔虫，产后手足浮肿，百日咳，痔疮。\n\n①《现代实用中药》:\"驱除绦虫。\"\n\n②《安徽药材》:\"能杀蛔虫。\"\n\n③《中国药植图鉴》:\"炒后煎服，治产后手足浮肿，糖屎病。\"","y":"内服:煎汤，1～2两；研末或制成乳剂。外用:煎水熏洗。","d":"干燥成熟的种子，呈扁椭圆形，一端略尖，外表黄白色，边缘稍有棱，长约1.2～2厘米，宽约0.7～1.2厘米，表面带有毛茸，边缘较多。种皮较厚，种脐位于尖的一端；除去种皮，可见绿色菲薄的胚乳，内有2枚黄色肥厚的子叶。子叶内含脂肪油，胚根小。气香，味微甘。以干燥、粒饱满、外壳黄白色者为佳。\n全国大部分地区均产。"},"黄皮果":{"a":"黄皮子(《桂海虞衡志》)，黄檀子(《八闽通志》)，黄弹子(《广东通志》)，金弹子(《本草求原》)。","s":"甘酸，温。\n\n①姚可成《食物本草》：\"酸，平，无毒。\"\n\n②《福建民间草药》：\"甘酸，微温。\"","f":"消食，化痰，理气。治食积不化，胸膈满痛，痰饮咳喘。\n\n①《广志》：\"消食，颗气，除暑热。\"\n\n②姚可成《食物本草》：\"主呕逆痰水，脚膈满痛，蛔虫上攻，心下痛。\"\n\n③《福建民间草药》：\"化气消疝，除积止痛。\"","y":"内服：煎汤，0.5～1两。","d":"性状鉴别 果实呈类圆形，直径0.8-2.3cm。外表面黄褐色或深绿色，具有皱纹。果肉较薄。种子\n扁卵圆形，长1.1-1.4cm，宽8-9mm，厚3-4mm，棕色或棕黄色，具个规则皱纹。气微，味辛、略苦。"},"乌骨藤":{"a":"确络风、牛耳风、火索藤、大叶酒饼藤","s":"性温，味辛涩。归肝经","f":"治痨伤，除风湿。","y":"内服：煎汤，10-20g，亦可酒泡服。外用：适量，研末调敷。","d":"1.性状鉴别 根圆柱形，略弯曲，直径0.5-1.5cm。表面棕黑色，具浅纵皱纹及点状突起的细根痕。质硬，断面皮部浅棕色，木部灰黄色，有细密放射状纹理和小孔。气微香，味微苦、辣。\n2.显微鉴别 根横切面：木栓层为数列黄棕色木栓细胞。韧皮部宽厚；韧皮纤维与薄壁组织相间排列；韧皮射线呈喇叭状，外侧有石细胞散在。形成层明显。木质部发达，导管单个散在或2-3个径向相连。本品溥壁细胞含淀粉粒和草酸钙方晶。"},"鸡屎藤":{"a":"斑鸩饭、女青、主屎藤(《质问本草》)，却节(《李氏草秘》)，皆治藤、臭藤根(《纲目拾遗》)，牛皮冻(《植物名实图考》)，臭藤(《天宝本草》)，毛葫芦(《岭南采药录》)，甜藤(《广西中兽医药植》)，五香藤、臭狗藤(《民间常用草药汇编》)，香藤、母狗藤(《四川中药志》)，鸡矢藤(《上海常用中草药》)，清风藤(《福建中草药》)。","s":"甘酸，平。\n\n①《岭南采药录》：\"味辛苦，平。\"\n\n②《上海常用中草药》：\"甘酸，平。\"","f":"祛风活血，止痛解毒，消食导滞，除湿消肿。治风湿疼痛，腹泻痢疾，肮腹疼痛，气虚浮肿，头昏食少，肝脾肿大，瘰疬，肠痈，无名肿毒，跌打损伤。\n\n①汪连仕《采药书》：\"治风痛肠痈，跌打损伤，流注风火瘴毒，散郁气。洗疝，合紫苏煎汤。\"\n\n②《李氏草秘》：\"煎洗腿足诸风，寒湿痛，拘挛不能转舒。\"\n\n③《生草药性备要》：\"其头治新内伤，煲肉食，补虚益肾，除火补血；洗疮止痛，消热散毒。其叶擂米加糖食，止痢。\"\n\n④《纲目拾遗》：\"中暑者以根、叶作粉食之。虚损者杂猪胃煎服。\"\"治瘰疬用.裉煎酒，未破者消，已溃者敛。\"\n\n⑤《本草求原》：\"理脚湿肿烂，蛇伤，同米擂食并敷。\"\n\n⑥《植物名实图考》：\"为洗药，解毒，去风，清热，散寒。\"\"敷无名肿毒，并补筋骨。\"\n\n⑦《草木便方》：\"补虚劳，调理脾胃元气，治病后虚肿、耳鸣。\"\n\n⑧《四川中药志》：\"治失眠，久咳。\"\n\n⑨《重庆草药》：\"健脾除湿，益气补虚。常用于小儿瘦弱，脾弱气虚，食积疳积，及成人气虚浮肿，臌胀，耳呜，腹泻，遗尿，妇女虚弱白带，干病。并虚弱劳伤，虚痢，痒子瘰疬之由于气虚不愈者。\"\n\n⑩《上海常用中草药》：\"祛风，活血，止痛，消肿。治风湿酸痛，跌打损伤，肝脾肿大，无名肿毒。\"","y":"内服：煎汤，3～5钱(大剂量1～2两)；或浸酒。外用：捣敷或煎水洗。","d":"?"},"一支箭":{"a":"一支枪,蛇咬子,小青藤。","s":"苦甘，凉。\n\n①《草木便方》：\"苦。\"\n\n②《分类草药性》：\"味甘，平，无毒。\"\n\n③《陕西中草药》：\"甘辛，凉，有小毒。\"\n\n④《四川常用中草药》：\"苦，平。\"","f":"清热解毒，活血散瘀。治乳痈，疔疮，疥疮身痒，跌打损伤，瘀血肿痛。\n\n①《草木便方》：\"清热毒，除风热。治肾囊种痛，疔肿恶毒，胸腹宿血，蛇毒。\"\n\n②《分类草药性》：\"治痒子，消疮毒，跌打损伤，肿毒。\"\n\n③《四川中药志》：\"清热解毒，消痈肿。治犬伤，疥疮。\"","y":"内服：煎汤，0.5～1两。外用：捣敷。","d":"?"},"降香":{"a":"降真香,紫藤香,花梨母。","s":"味辛；性温","f":"?","y":"研末冲服2.4~3g；入煎剂用3~6g。","d":"商品均已削去外皮，断截成15~30厘米的段块。表面紫棕色或暗红紫色，有刀削痕和纵直细纹，多较光滑。质坚硬，体重。微有香气，点燃后较浓，烧后留有白灰，味微苦。以紫红，坚硬，香气浓者为佳。"},"仙人掌":{"a":"风尾竻(《广东新语》)，龙舌(《桂乎县志》)，平虑草、老鸦舌(《南安府志》)，神仙掌，霸王(《本草求原》)，观音掌(《贵州民间方药集》)，观音刺(《广西中兽医药植》)。","s":"苦，寒。\n\n\n①《本草求原》：\"寒。\"\n\n\n②《岭南采药录》：\"味苦涩，性寒，无毒。\"\n\n\n③《陆川本草》：\"性凉，味酸。\"","f":"行气活血，清热解毒。治心胃气痛，痞块，痢疾，痔血，咳嗽，喉痛，肺痈，乳痈，疔疮，汤火伤，蛇伤。\n\n\n①《本草求原》：\"消诸痞初起，洗痔。\"\n\n\n②《分类草药性》：\"专治气痛，消肿毒、恶疮。\"\n\n\n③《贵州民间方药集》：\"为健胃滋养强壮剂，又可补脾，镇咳，安神。治心胃气痛，蛇伤，浮肿。\"\n\n\n④《民间常用草药汇编》：\"为解热镇静剂。治喉痛，疗疔毒及烫伤，又治精神失常。外用治小儿急惊风。\"\n\n\n⑤《陆川本草》：\"消炎解毒，排脓生肌。主治疮痈疖肿，咳嗽。\"\n\n\n⑥《中国药植图鉴》：\"外皮捣烂可敷火伤，急性乳腺炎，并治足胝。煎水服，可治痢疾。\"\n\n\n⑦《湖南药物志》：\"消肿止痛，行气活血，祛湿退热，生肌。\"\n\n\n⑧《闽东本草》：\"能去瘀，解肠毒，健胃，止痛，滋补，舒筋活络，疗伤止血。治肠风痔漏下血，肺痈，胃痛，跌打损伤。\"\n\n\n⑨《广西中草药》：\"止泻。治肠炎腹泻。\"","y":"内服：煎汤，鲜者1～2两；研末或浸酒。外用：捣敷或研末调敷。","d":"?"},"草乌":{"a":"鸭头、药羊蒿、鸡头草、百步草","s":"辛，热，有毒。\n\n\n　　① 《本经》：味辛，温。\n\n\n　　② 《别录》：乌头，甘，大热，有大毒。 乌喙:味辛，微温，有大毒。\n\n\n　　③ 《药性论》：味苦辛，大热，有大毒。","f":"搜风胜湿，散寒止痛，开痰，消肿。治风寒湿痹，中风瘫痪，破伤风，头风，脘腹冷痛，痰癖，气块，冷痢，喉 痹，痈疽，疔疮，瘰疬。\n\n\n　　① 《本经》：主中风，恶风，洗洗出汗，除寒湿痹，咳逆上气，破积聚寒热。\n\n\n　　② 《别录》：消胸上痰，冷食不下，心腹冷疾，脐间痛，肩胛痛不可俛仰，目中痛不可久视，又堕胎。主风湿，丈夫肾湿阴囊痒，寒热历节掣引腰痛，不能行步，痈肿脓结。\n\n\n　　③ 《药性论》：能治恶风，憎寒，冷痰包心，肠腹疞痛，痃癖气块，益阳事，治齿痛，主强志。治男子肾衰弱，阴汗，主疗风温湿邪痛。\n\n\n　　④ 《药类法象》：治风痹血痹，半身不遂，行经药也。\n\n\n　　⑤ 《纲目》：治头风喉痹，痈肿疔毒。主大风顽痹。\n\n\n　　⑥ 《东医宝鉴》：治风湿麻痹疼痛，发破伤风汗。\n\n\n　　⑦ 《纲目拾遗》：追风活血，取根入药酒。\n\n\n　　⑧ 《贵州民间方药集》：治麻痹症。又为伤科要药。","y":"内服：煎汤，0.5～2钱;或入丸、散。\n\n\n　　外用：生用，研末调敷或醋、酒磨涂。","d":"（1） 本品横切面：后生皮层为7～8列棕黄色栓化细胞；皮层有石细胞，单个散在或2～5个成群，类长方形、方形或长圆形，胞腔大；内皮层明显。韧皮部宽广，常有不规则裂隙，筛管群随处可见。形成层环呈不规则多角形或类圆形。木质部导管1～4列或数个相聚，位于形成层角隅的内侧，有的内含棕黄色物。髓部较大。薄壁细胞充满淀粉粒。粉末灰棕色。淀粉粒单粒类圆形，直径2～23μm；复粒由2～16 分粒组成。石细胞无色，与后生皮层连结的显棕色，呈类方形、类长方形、类圆形、梭形或长条形，直径20～133（234）μm ，长至465μm，壁厚薄不一，壁厚者层纹明显，纹孔细，有的含棕色物。后生皮层细胞棕色，表面观呈类方形或长多角形，壁不均匀增厚，有的呈瘤状突入细胞腔。\n（2） 取本品粉末0.5g，加乙醚10ml与氨试液0.5ml ，振摇10分钟，滤过，滤液置分液漏斗中，加0.25mol/L 硫酸溶液20ml，振摇提取，分取酸液适量，用水稀释后，照分光光度法（附录Ⅴ A）测定，在231nm 与275nm 的波长处有最大吸收。\n（3） 取本品粗粉1g，加乙醚15ml与氨试液1ml ，浸渍1 小时，时时振摇，滤过，取滤液5ml,蒸干，残渣加7％ 盐酸羟胺甲醇溶液5 滴与0.1％ 麝香草酚酞甲醇溶液1 滴，滴加氢氧化钾饱和的甲醇溶液至显蓝色后，再多加2 滴，置60℃水浴上加热1～2分钟，用冷水冷却，滴加稀盐酸调节pH值至2～3，加三氯化铁试液和氯仿各1 滴，振摇，下层液显紫色。"},"罗布麻":{"a":"吉吉麻(《江苏植药志》)，泽漆麻、缸花草、野茶(《陕西中草药》)，罗布欢的尔(维名)。","s":"甘苦，凉。\n\n①《陕西中草药》：\"味淡涩，性凉，有小毒。\"\n\n②《新疆中草药手册》：\"味甘苦，性平，有小毒。\"","f":"清火，降压，强心，利尿。治心脏病，高血压，神经衰弱，肝炎腹胀，肾炎浮肿。\n\n①《江苏植药志》：\"乳汁可愈合伤口。\"\n\n②《中国药植图鉴》：\"嫩叶，蒸炒揉制后代茶，有清凉去火，防止头晕和强心的功用。\"\n\n③《陕西中草药》：\"清凉泻火，强心利尿，降血压。治心脏病，高血压，神经衰弱，肾炎浮肿。\"","y":"内服：煎汤，2～3钱；或泡茶饮。","d":"?"},"双肾子":{"a":"天鹅抱蛋、玉凤花根(《江西草药》)，对对参(《昆明民间常用草药》)。","s":"甘苦，平。\n\n①《江西草药》：\"辛，平。\"\n\n②《昆明民间常用草药》：\"甘苦，平。\"\n\n③《云南思茅中草药选》：\"甘淡，平。\"","f":"利尿，消炎，解毒。治睾丸炎，尿路感染，虚咳，痈疽疔毒。\n\n①《江西草药》：\"散气，解毒。\"\n\n②《昆明民间常用草药》：\"滋补肺肾，利尿，消炎。\"\n\n③《云南思茅中草药选》：\"滋补，止咳化痰。治睾丸炎，输卵管炎，体虚咳嗽。\"","y":"内服：煎汤，3～5钱；或磨汁服。外用：捣敷。","d":"?"},"鱼脑石":{"a":"石首鱼头石(《千金方》)，石首鱼脑中枕(《日华子本草》)，石首鱼魫(《濒湖集简方》)，石首骨(《本草汇言》)，黄鱼脑石、鱼首石(《浙江中药手册》)。","s":"《医林纂要》：\"咸，平。\"\n\n入肾经","f":"化石，通淋，消炎。治石淋，小便不利，中耳炎，鼻炎，脑漏。\n\n①《日华子本草》：\"取脑中枕烧为末，饮下治石淋。\"\n\n②《开宝本草》：\"主下石淋，磨石服之，亦烧为灰末服。\"\n\n③《纲目》：\"研末或烧研水服，主淋沥、小便不通。煮汁服，解砒霜毒、野菌毒。\"","y":"内服：研末，1～3钱。外用：烧存性研末撒。","d":"为长卵形，具三棱的颗粒。大黄鱼的脑石长1.5～2厘米，宽0.8～1.8厘米。小黄鱼的较小，长1～1.2厘米，宽5～7毫米。中间宽，一端稍圆，另一端尖。全体磁白色。关节面较平坦，表面可见明显的圆形节痕；另一面向一侧隆起，近尖端部有一斜的凹沟，并有横突数个，其隆起一侧的下方可见细长纹理，即生长线。质坚硬，不易破碎。气微，味稍涩。以洁白、坚硬、无杂质者为佳。\n主产浙江。"},"鸟不宿":{"a":"鸟不踏,刺根白皮,鸟不停,老虎草,昏树","s":"味苦；辛；性平 \n\n①汪连仕《采药书》：\"性温。\"\n\n②苏医《中草药手册》：\"辛，平，有小毒。\"","f":"追风，行血。治风湿痹痛，紫云风，胃痛。\n\n①汪连仕《采药书》：\"行血追风。治紫云风，大麻风，筋骨疼痛。\"\n\n②《纲目拾遗》：\"追风定痛，有透骨之妙。治风毒流注，风痹，跌打，劳怯。下胎催生。\"\n\n③苏医《中草药手册》：\"祛风湿，利关节，止痛。治腰膝关节酸痛，胃痛。\"","y":"内服：煎汤，3～5钱。外用：煎水洗。","d":"①刺楸的干燥树枝\n多截成10～20匣米的小段，圆柱形，表面淡褐色，并有褐色圆点状皮孔和散生暗褐色的硬刺，刺尖锐，侧扁，略带光泽；断面中央可见白色的髓部。\n\n②橡木的干燥茎枝\n呈圆柱形，表面灰棕色至棕色，有细纵裂纹，并具不规则散在的灰白色角状刺，顶部大多已折断，刺基锥形。质坚硬，断面淡黄色，髓部约占茎粗的1／2。"},"血风藤":{"a":"青藤、铁牛入石、青筋藤(广州部队《常用中草药手册》)。","s":"甘，温。\n\n①广州部队《常用中草药手册》：\"甘涩，温。\"\n\n②《广西中草药》：\"味淡，性微温。\"","f":"补益气血，祛风活络。治气血亏损，风湿疼痛，跌打损伤。\n\n①广州部队《常用中草药手册》：\"补气补血，舒筋活络。治气血亏损，月经不调，风湿筋骨痛，四肢麻木，跌打损伤。\"\n\n②《广西中草药》：\"补血祛风，强壮筋骨。治贫血，风湿性关节炎，腰肌劳损。\"","y":"内服：煎汤，0.5～1两。","d":"理化鉴别 （1）取本品粉末1g，加乙醇10ml，振摇，冷浸过夜；滤过，滤液挥去乙醇，残渣加稀盐酸，调节PH约等于5，搅拌使溶；滤过，滤液加氨水碱化后，以三氯甲烷萃取；萃取液挥去三氯甲烷，残渣加水5ml，滴加稀盐酸使pH约为5，使溶；滤过，滤液加氨水调节PH8-9，置试管中，滴加碘化铋钾试液，产生黄白色沉淀。（检查生物碱）（2）取本品粉末2g，加甲醇20ml，振摇，冷浸过夜；滤过，滤液挥主甲醇；残渣加水10ml，滴加氢氧化钠试液碱化，搅拌使溶；滤过，滤液滴加稀盐酸使pH为中性；取滤液置试管中，加少许镁粉，滴加浓盐酸3-4滴；显紫红色。（检查黄酮）（3）取本品粉末0.2g，加10％的硫酸溶液10ml，置水浴上加热2-10min。放冷后，加入5ml乙醚振摇，静置分层后取醚层供试验：①取上述乙醚液2ml，加入1ml5％的氢氧化钠液振摇，已醚层由黄色退为无色，水层显红色。②取上述乙醚液2ml，滴加0.5％醋酸镁甲醇试液2-3滴，即产生紫红色的絮状沉淀，继续滴加过量的醋酸镁甲醇试液，沉淀消失，溶液变为紫红色。"},"猫须草":{"a":"猫须公,肾茶","s":"甘淡微苦，凉。","f":"清热去湿，排石利水。治急慢性肾炎，膀胱炎，尿路结石，风湿性关节炎。","y":"内服；煎汤，1～2两(鲜者3～4两)。","d":"性状鉴别：全草长30-70cm或更长。茎枝呈方柱形，节稍膨大;老茎表面灰棕色或灰褐色，有纵皱纹或纵沟，断面木质，周围黄白色，中央髓部白色;嫩枝对生，紫褐色或紫红色，被短小柔毛。叶对生，皱缩，易破碎，完整者展平后呈卵形或卵状披针形，长2-5cm，宽1-3cm，先端尖，基部楔形，中部以下的叶片边朋锯齿，叶脉紫褐色，两面呈黄绿色或暗绿色，均有小柔毛。叶柄长约2cm。轮伞花序每轮有6花，多已脱落。气微，茎味淡，叶味微苦。以茎枝幼嫩、色紫红、叶多者为佳。\n\n\n显微鉴别：\n\n\n(1)茎横切面：芭四棱形，表皮细胞1列，被有多种类型毛茸。皮层薄壁细胞5-10列，于棱角处有厚角细胞3-6列。中柱鞘纤维木化，3-10个一群，断续成环。韧皮部薄壁细胞小而略皱缩。形成层明显。木质部导管单个，少数2-3个相柔，径向散列，木薄壁细胞、木纤维均呈方殂或多角形，木射线宽1-2细胞。骨部薄壁细胞具壁孔。\n\n\n(2)叶横切面：上、下表皮均有毛茸，下表皮具气孔。栅栏组织细胞1列，海绵组织细胞4-6列，排列疏松。主脉处表皮内侧均有厚角组织，维管束外韧型。\n\n\n粉末特征：棕色。①茎的韧皮纤维直径26-42μm，长100μm以上，壁木化，具壁孔。②木纤维直径31-46μm，长1000μm以上，壁微木化，具壁孔。③管胞直径30-80μm，长500-1000μm。④叶表皮细胞垂周壁稍弯曲，气孔直轴式。⑤腺鳞头部8细胞，直径82-96μm，柄单细胞。⑥腺毛头部单位细胞，直径41-63μm柄单细胞。⑦单细胞非腺毛基部直径31-38μm，长81-108μm;多细胞非腺毛，2-5细胞，基部直径62-80μm，壁厚，具壁疣。⑧螺纹导管。此外，有茎表皮细胞长方形或类正方形;髓薄壁细胞类圆形，有纹孔;油滴。"},"大青叶":{"a":"大青(《本草经集庄》)。","s":"苦，寒。\n\n①《别录》：\"味苦，大寒，无毒。\"\n\n②《药性论》：\"味甘。\"\n\n③《纲目》：\"气寒，味微苦咸。\"","f":"清热，解毒，凉血，止血。治温病热盛烦渴，流行性感冒，急性传染性肝炎，菌痢，急性胃肠炎，急性肺炎，丹毒，吐血，衄血，黄疸，痢疾，喉痹，口疮，痈疽肿毒。\n\n①《别录》：\"疗时气头痛，大热，口疮。\"\"蓝叶汁，杀百药毒，解狼毒，射罔毒。\"\n\n②陶弘景：\"疗伤寒方多用此，除时行热毒为良。\"\"蓝汁，至解毒。以汁涂五心，又止烦闷。甚疗蜂蟹毒。\"\n\n③《纲目》：\"主热毒痢，黄疸，喉痹，丹毒。\"\"蓝叶汁，解斑蝥、芫青、樗鸡，朱砂、砒石毒。\"\n\n④《本草正》：\"治瘟疫热毒发狂，风热斑疹，痈疡肿痛，除烦渴，止鼻衄、吐血，杀疳蚀、金疮箭毒。凡以热兼毒者，皆宜蓝叶捣汁用之。\"\n\n⑤广州部队《常用中草药手册》：\"清热泻火，凉血解毒，散瘀止血。治肠炎，菌痢，咽喉炎，扁桃体炎，腮腺炎，感冒发热，齿龈出血。\"\n\n⑥《江西草药》：\"治急性肝炎，肺结核，矽肺，牙痛，蛇伤，过敏性皮炎。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)；或捣汁。外用：捣敷或煎水洗。","d":"①路边青叶\n干燥叶片(亦有将叶及幼枝切成小段者)，微皱折，呈长椭圆形至细长卵圆形，长5～16厘米。上面棕黄色、棕黄绿色至暗棕红色，下面色较浅，全缘，先端渐尖，基部钝圆。纸质而脆。气微臭，味稍苦而涩。以叶大、无柄者为佳。\n\n主产湖南、湖北、江西等地。此外，广西、福建等地亦产。\n\n②蓼蓝叶\n干燥叶(有时带枝)，多皱缩，有时破碎。完整者呈长圆形至倒卵圆形，长约5～8厘米，宽约3～5厘米，似桃叶而较阔，先端钝尖，基部渐狭窄，全缘多数呈波状，稍有黄色毛茸，主脉黄色，亦有稀疏的毛茸。叶柄扁平，长约1厘米，基部具膜质托叶鞘，透明，灰白色，其边缘有稀疏长毛。质脆易碎。气微臭，味微涩而苦。以叶厚、色蓝绿、无枝梗、杂脆者为佳。\n\n主产河北、北京，山西等地。\n\n③菘蓝叶\n干燥叶皱编成团块状，有时破碎，呈灰绿色或黄棕色。完整的叶呈长椭圆形至长圆状倒披针形，长4～11厘米，宽1～3厘米，全缘或微波状；先端钝尖，基部渐狭，延成翼状，上面有时可见点状突起，下面中脉明显。叶柄长5～7厘米，腹面稍凹下。质脆易碎。气微弱，味稍苦。以叶大、无柄、色暗灰绿者为佳。\n\n主产江苏、安徽、河北、河南、浙江等地。\n\n④马蓝叶\n牛燥叶(有时带幼枝)，多皱缩成团块状。完整者呈长圆形、倒卵状长圆形或椭圆殖针形，长8～15厘米，宽3～5厘米，先端渐尖，基部渐窄，叶缘有细小钝锯齿，上面黑绿色至暗棕黑色，下面色较淡，叶脉下面较显。叶柄长1～2厘米。质脆易碎。气微弱，味涩而微苦。以叶净、无枝梗、色黑绿者为佳。\n\n主产于福建、广西、广东、江西、浙江等地。此外，四川、云南、贵州、湖南、湖北等地亦产。\n\n《纲目》及《植物名实图考》所载的大青，均为马鞭草科植物路边青。"},"莲子心":{"a":"薏、苦薏、莲薏、莲心","s":"苦，寒。\n\n\n①陆玑《诗琉》：\"味甚苦。\"\n\n\n②《纲目》：\"苦，寒，无毒。\"\n\n\n③《重庆堂随笔》：\"甘苦咸。\"\n\n\n入心、肺、肾三经\n\n\n《本草再新》：\"入心、肺、肾三经。\"","f":"清心，去热，止血，涩精。治心烦，口渴，吐血，遗精，目赤肿痛。\n\n\n①《食性本草》：\"生取为末，以米饮调下三钱，疗血渴疾、产后渴疾。\"\n\n\n②《日华子本草》：\"止霍乱。\"\n\n\n③《大明一练志》：\"清心去热。\"\n\n\n④《医林纂要》：\"泻心，坚肾。\"\n\n\n⑤《本革再新》：\"清心火，平肝火，泻脾火，降肺火。消暑除烦，生律止渴，治目红肿。\"\n\n\n⑥《随息居饮食谱》：\"敛液止汗，靖热养神，止血固精。\"","y":"内服：煎汤，0.5～1钱；或入散剂。","d":"干燥的莲心，略成棒状，长1.2～1.6厘米。顶端膏绿色，有2个分歧，一长一短，先端反折，紧密互贴，用水浸软后展开，可见2片盾状卷曲的幼叶。中央的胚芽直立，长约2毫米。基部胚根黄绿色，略呈圆柱形，长2～4毫米。质脆，易折断，断面有多数小孔。气无，味苦。以个大、色青绿。未经煮者为佳。\n\n\n主产湖南、湖北、福建、江苏、浙江等地。"},"山胡椒":{"a":"山花椒、山龙苍、雷公尖、野胡椒、香叶子、楂子红、臭樟子","s":"辛，温。\n\n①《唐本草》：\"味辛，大热，无毒。\"\n\n②《陕西中草药》：\"味辛，性温。\"\n\n归肺；胃经","f":"治中风不语，心腹冷痛。\n\n《唐本草》：\"主心腹痛，中冷。破滞。\"","y":"内服：煎汤。","d":"?"},"牛筋草":{"a":"千金草(《纲目拾遗》)，千千踏、忝仔草、千人拔(《福建民间草药》)，穆子草(《广西中兽医药植》)，牛顿草、鸭脚草(《闽南民间草药》)，粟仔越、野鸡爪、粟牛茄草(《闽东本草》)，扁草、水枯草(《江西民间草药验方》)，油葫芦草，蟋蟀草、千斤草(《上海常用中草药》)，稷子草(《福建中草药》)。","s":"①《福建民间草药》：\"甘，平，无毒。\"\n\n②《闽东本草》：\"味甘淡，性凉。\"","f":"清热，利湿。治伤暑发热，小儿急惊，黄疸，痢疾，淋病，小便不利；并能防治乙脑。\n\n①《百草镜》：\"行血，长力。\"\n\n②《福建民间草药》：\"利尿，清热，消疝气。\"\n\n③《民间常用草药汇编》：\"强筋骨，治遗精。\"\n\n④《闽东本草》：\"治小儿急惊，石淋，腰部挫伤，肠风下血，反胃，喘咳。\"\n\n⑤《上海常用中草药》：\"活血补气。治脱力劳伤，肺结核。\"","y":"内服：煎汤，3～5钱(鲜者1～3两)；或捣汁。","d":"?"},"三七花":{"a":"田七花","s":"甘，凉。\n\n归肝经，心经。","f":"清热，平肝，降压。治高血压，头昏，目眩，耳鸣，急性咽喉炎。","y":"内服：开水冲泡茶服；适量。","d":"?"},"雪里开":{"a":"蛇松子(《浙江民间常用草药》)，地雷、拐子药(《湖南药物志》)。","s":"《湖南药物志》：\"辛苦，温，无毒。\"\n入心；肺；胃经","f":"行气活血，抗菌消炎，对头、胃、腹、肌肉及关节等疼痛均有止痛作用。亦治气管炎，疔疮肿毒，跌打损伤。","y":"内服：煎汤，1～3钱，酒磨汁0.5～1钱。外用：酒磨敷或捣敷。","d":"性状鉴别 块根纺锤形，长6-12cm，直径0.6-2cm，多弯曲不直。表面黄褐色，有纵皱纹。质硬，不易折断，断面白色，粉性，具稀疏的放射状纹理。气微，味微甘。"},"罂粟壳":{"a":"御米壳、米囊皮、米罂皮、粟壳、米壳、烟斗斗","s":"酸，平。\n\n①《医学启源》：\"味酸涩。\"\n\n②《纲目》：\"酸涩，微寒，无毒。\"\n\n③《本草从新》：\"酸涩，平。\"\n\n入肺、肾、大肠经。\n\n①《得配本草》：\"入足厥阴经。\"\n\n②《本草求真》：\"入肺、大肠，兼入肾。\"","f":"敛肺止咳，涩肠，定痛。治久咳，久泻，久痢，脱肛，便血，心腹筋骨诸痛，滑精，多尿，白带。\n\n①《医学启源》：\"固收正气。\"\n\n②《滇南本草》：\"收敛肺气，止咳嗽，止大肠下血，止日久泻痢赤白。\"\n\n③《纲目》：\"止泻痢，固脱肛，治遗精久咳，敛肺涩肠，止心腹筋骨诸痛。\"\n\n④《本经逢原》：\"蜜炙止嗽，醋炙止痢。\"\n\n⑤《本草从新》：\"固肾，治遗精多溺。\"\n\n⑥《现代实用中药》：\"适用于慢性衰弱之久下痢、肠出血、脱肛、贫血拘挛之腹痛、腰痛、妇女白带。又用于慢性久咳嗽、肺结核、咳血、喘息等症。\"","y":"内服：煎汤，0.8～2钱；或入丸、散。","d":"性状鉴别 果壳椭圆形或瓶状卵形，长4-6cm，直径2-4cm，有时破碎成片状。表面黄褐色或棕褐色，有纵或横的割痕，顶端有柱头7-15个，辐射状排列成盘状，基部有时有残存果柄。果皮硬脆，木质。断面可见7-15个侧膜胎座，其上有点状突起，为种子脱落的残痕。气清香，味徽苦。显微鉴别 果壳横切面：外果皮细胞1列，外被厚角质层。中果皮外侧为3-4列厚角细胞，其下为薄壁组织；维管束在，位于胎座基部的1个较大，其外侧有纤维束，韧皮部有乳汁管。内果皮为1列切向延长的细胞，壁稍厚，木化，纹孔明显。胎座薄壁组织中有小型维管束散在。"},"夜交藤":{"a":"棋藤,首乌藤","s":"干燥的藤茎呈细长圆柱状，通常扭曲，有时分枝，直径3～7毫米。表面紫褐色，粗糙，有扭曲的纵皱纹和节，并散生红色小斑点，栓皮菲薄，呈鳞片状剥落。质硬而鹿，易折断，断面皮部棕红色，木部淡黄色，木质部呈放射状，中央为白色疏松的髓部。气无，味微苦涩。以粗壮均匀、外表紫褐色者为佳。\n\n\n主产河南、湖北、湖南、江苏、浙江等地。\n\n\n四川商品为干燥的带叶嫩茎。茎细，黄绿色或黄褐色，叶多皱缩。","f":"养心，安神，通络，祛风。治失眠，劳伤，多汗，血虚身痛，痈疽，瘰疬，风疮疥癣。\n\n\n①《纲目》：\"风疮疥癣作痒，煎汤洗浴。\"\n\n\n②《本草再新》：\"补中气，行经络，通血脉，治劳伤。\"\n\n\n③《本草正义》：\"治夜少安寐。\"\n\n\n④《饮片新参》：\"养肝肾，止虚汗，安神催眠。\"\n\n\n⑤《安徽药材》：\"消痈肿、瘰疬和痔疮。\"\n\n\n⑥《陕西中草药》：\"祛风湿，通经络。治失眠，多汗，贫血，周身酸痛，疥癣等皮肤病。\"","y":"内服：煎汤，2～4钱。外用：煎水洗或捣敷。","d":"干燥的藤茎呈细长圆柱状，通常扭曲，有时分枝，直径3～7毫米。表面紫褐色，粗糙，有扭曲的纵皱纹和节，并散生红色小斑点，栓皮菲薄，呈鳞片状剥落。质硬而鹿，易折断，断面皮部棕红色，木部淡黄色，木质部呈放射状，中央为白色疏松的髓部。气无，味微苦涩。以粗壮均匀、外表紫褐色者为佳。\n\n\n主产河南、湖北、湖南、江苏、浙江等地。\n\n\n四川商品为干燥的带叶嫩茎。茎细，黄绿色或黄褐色，叶多皱缩。"},"雪猪油":{"a":"大旱癞、土拨鼠","s":"味辛；性温\n\n《四川中药志》：\"辛，温，无毒。\"\n\n入脾经\n\n《四川中药志》：\"入脾经。\"","f":"祛风除湿；解毒止痒。主风湿肿痛；湿热疮毒；皮肤溃疡；臁疮；体癣。\n\n《高原中草药治疗手册》：\"治风湿肿痛，痒疹疮毒，臁疮久烂。\"","y":"内服：浸酒。外用：配其他药涂敷。","d":"装入胃内的脂肪油，外形如卵石状，大小似鸭蛋，外表黄色。内部多已卷缩成团，伸张后，长宽约10～15厘米，厚约1厘米。质柔润，以张大、厚实、色白黄者为佳。\n产四川、青海等地。"},"五指山参":{"a":"红花马宁。","s":"甘淡，微温。","f":"滋养强壮。治神经衰弱，头晕，腰腿痛，胃痛，腹泻。","y":"内服：煎汤，3～5钱。","d":"?"},"砒霜":{"a":"白砒、信石、鹤顶红","s":"辛酸，热，有毒。\n\n①《开宝本草》:\"味苦酸，有毒。\"\n\n②《玉楸药解》:\"辛，热，大毒。\"","f":"劫痰截疟，杀虫，蚀恶肉。治寒痰哮喘，疟疾，休息痢，梅毒，痔疮，瘰疬，走马牙疳，癣疮，溃疡腐肉不脱。\n\n①《日华子本草》:\"治妇人血气冲心痛，落胎。\"\n\n②《开宝本草》:\"主诸疟，风痰在胸膈，可作吐药。\"\n\n③《本草蒙筌》:\"截疟除吼，膈上风痰可吐；溃坚磨积，腹内宿食能消。\"\n\n④《医学入门》:\"主恶疮瘰疬，腐肉，和诸药敷之，自然蚀落。又治蛇尿着人手足，肿痛肉烂，指节脱落。为末，以胶清调涂。\"\n\n⑤《纲目》:\"蚀痈疽败肉，枯痔，杀虫。\"\n\n⑥《玉楸药解》:\"治寒痰冷癖，久疟积痢，疗痔漏瘰疬，心疼呴喘，蚀痈疽腐肉，平走马牙疳。\"","y":"内服:入丸、散，1～5毫。外用:研末撒或调敷，或入膏药中贴之。","d":"为白色粉末，无臭，无味，能溶于水、乙醇、酸类及碱类。加热则升散而发蒜臭。"},"朱砂莲":{"a":"一点血(《广西中药志》)。","s":"味苦辛，性寒，无毒。\n入心、肺、肝经。","f":"清火消肿，散血止痛，解蛇毒。治红白痢疾，胸、腹、喉痛，毒蛇咬伤。(性味以下出《广西中药志》)","y":"内服：煎汤，0.5～1钱；或研末。","d":"块根纺锤状，长达14厚米，径至8厘米，有多数疣状凸起，表面浅棕色，有不规则的皱纹，并有少数残留的须根。质坚硬，断面鲜时浅紫褐色至橘黄色，干后呈淡暗赭色，粉质。气特异。\n四川地区所用的朱砂莲为同属植物避蛇生的块根，功效相同。"},"犁头草":{"a":"紫金锁、紫花地丁、小甜水茄(《植物名实图考》)，瘩背草(《南京民间药草》)，三角草、犁头尖、烙铁草(《江西民间草药》)，地丁草、紫地丁(《浙江民间常用草药》)。","s":"《浙江民间常用草药》：\"微苦，寒。\"","f":"清热，解毒。治痈疽，疔疮，瘰疬，乳痈，外伤出血。\n\n①《植物名实图考》：\"根：治火症，功同地丁。\"\n\n②《浙江民间常用草药》：\"清热，消肿，解毒。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)；捣汁或入丸剂。外用：捣敷或研末调敷。","d":"?"},"枇杷花":{"a":"土冬花","s":"淡；性平\n \n  归肺经","f":"治伤风感冒，咳嗽痰血。\n\n①《贵州民间方药集》：\"花蒸蜂蜜，治伤风感冒，润喉止咳。\"\n\n②《民间常用草药汇编》：\"治寒咳。\"","y":"内服：煎汤，2～3钱；或研末。每次3-6g，吞服；或入丸、散。外用：适量，捣敷。","d":"圆锥花序，密被绒毛。苞片凿状，有褐色绒毛。花萼5浅裂，萼管短，密被绒毛。花瓣5，黄白色，倒卵形，内面近基部有毛。雄蕊20-25；子房下位，5室，每室有胚珠2枚，花柱5，柱头头状。气微清香，味微甘、涩。"},"接骨木":{"a":"木蒴藋(《唐本草》)，接骨草(《履巉岩本草》)，续骨木(《纲目》)，扦扦活(《本经逢原》)，七叶黄荆、放棍行、珊瑚配(汪连仕《采药书》)，铁骨散(《植物名实图考》)，接骨丹(《草木便方》)，七叶金、透骨草(《福建民间草药》)，接骨风(《四川中药志》)。","s":"甘苦，平。\n\n①《唐本草》：\"甘苦，平，无毒。\"\n\n②《本草拾遗》：\"有小毒。\"\n\n③《现代实用中药》：\"苦，寒。\"","f":"祛风，利湿，活血，止痛。治风湿筋骨疼痛，腰痛，水肿，风痒，瘾疹，产后血晕，跌打肿痛，骨折，创伤出血。\n\n①《唐本草》：\"主折伤，续筋骨，除风痒、龋齿。可为浴汤。\"\n\n②《千金翼方》：\"打伤痕血及产妇恶血，一切血不行或不止，并煮汁服。\"\n\n③汪连仕《采药书》：\"行血败毒，洗一切疮疥、鬼箭风。\"\n\n④《百草镜》：\"治跌扑痈肿。\"\n\n⑤《现代实用中药》：\"为镇痛药。治手足偏风及风湿腰痛，骨间诸痛，四肢寒痛，脚肿。又跌伤骨痛、风疹、汗疹等为浴汤料。\"","y":"内服：煎汤，3～5钱；或入丸、散，外用：捣敷或煎水熏洗。","d":"干燥茎枝，多加工为斜向横切的薄片，呈长椭圆状，长2～6厘米，厚约3毫米，皮部完整或剥落，外表绿褐色，有纵行条纹及棕黑点状突起的皮孔；木部黄白色，年轮呈环状，极明显，且有细密的白色髓线，向外射出，质地细致；髓部通常褐色，完整或枯心成空洞，海绵状，容易开裂。质轻，气味均弱。以片完整、黄白色、无杂质者为佳。\n主产于江苏。此外福建、四川、广西、浙江等地亦产。\n\n同属植物毛接骨木、无梗接骨木在少数地区亦同等入药。"},"猫眼草":{"a":"猫儿眼,打碗花,打碗棵,打盆打碗","s":"性微寒，味苦，有毒。肺；肝经","f":"祛痰，镇咳，平喘，拔毒止痒。","y":"外用：适量，熬膏外敷或研末调敷。内服：煎汤，3-9g；或入丸剂。","d":"猫儿眼 多年生草本，高达40cm。茎通常分枝，基部坚硬。下部叶鳞片状，早落；中上部叶狭条状披针形，长2-5cm，宽2-3mm，先端钝或具短尖，两面无毛。杯状聚伞花序顶生者通常有4-9伞梗，基部有轮生叶与茎上部叶同形；腋生者具伞梗1；每伞梗再2-3分叉，各有扇状半圆形或三角状心形苞叶1对；总苞杯状，无毛，先端4裂，裂片间无片状附属物，腺体4，新月形，黄褐色，两端有短角；雄蕊1；子房3室，花柱3，分离，柱头2浅裂。蒴果扁球形，无毛；种子长圆形，长约2mm，光滑，一边有纵沟，无网纹及斑点。花期4-6月，果期6-8月。"},"绞股蓝":{"a":"七叶胆、小苦药、公罗锅底、落地生、遍地生根","s":"味苦;微甘;性凉\n\n\n归肺;脾;肾经","f":"体虚乏力；虚劳失精；白细胞减少症；高脂血症；病毒性肝炎；慢性胃肠炎；慢性气管炎","y":"内服：煎汤，15-30g，研末，3-6g；或泡茶饮。外用：适量，捣烂涂擦。","d":"为葫芦科植物绞股蓝的全草。"},"鹅不食草":{"a":"石胡荽","s":"辛，温。\n\n①《履巉岩本草》：\"温，无毒。\"\n\n②《医林纂要》：\"辛苦。温。\"","f":"祛风，散寒，胜湿，去翳，通鼻塞。治感冒，寒哮，喉痹，百日咳，痧气腹痛，阿米巴痢，疟疾，疳泻，鼻渊，鼻息肉，目翳涩痒，臁疮，疥癣，跌打。\n\n①《本草拾遗》：\"去目翳，按塞鼻中，翳膜自落。\"\n\n②《四声本草》：\"通鼻气，利九窍，吐风痰。\"\n\n③《纲目》：\"解毒，明目，散目赤肿、云翳，耳聋，头痛脑酸，治痰疟齁蛤，鼻塞不通，塞鼻息自落，又散疮肿。\"\n\n④《生草药性备要》：\"理跌打折骨，上痛消肿。\"\n\n⑤《医林纂要》：\"通郁，去寒，截疟，止痢。以于末搐鼻，可发嚏去寒郁。\"\n\n⑥《植物名实图考》：\"治痧症。\"\n\n⑦《广西药植图志》：\"治疳积。\"\n\n⑧《广西中药物》：\"治喉毒。\"\n\n⑨《广东中药》Ⅱ：\"治百日咳。\"\n\n⑩广州部队《常用中草药手册》：\"治风湿性腰腿痛。\"","y":"内服：煎汤，1.5～3钱；或捣汁。外用：捣烂塞鼻、研末搐鼻或捣敷。","d":"干燥的全草，相互缠成团，灰绿色或棕褐色。茎细而多分枝，颜色较深，质脆易断，断面黄白色，中央有白色的髓或日形成空洞。叶小，多皱折、破碎不全，完整的叶片呈匙形，边缘有3～5个锯齿，叶脉不明显，质极脆，易碎落。头状花序小，球形，黄色或黄褐色。微有香气，久嗅有刺激性，味苦、微辛。以灰绿色、有花序、无杂质、嗅之打喷嚏者为佳。\n主产浙江、湖北、江苏、广东等地。此外，广西、河南、江西、福建、安徽等地亦产。"},"桂花":{"a":"木犀花","s":"辛，温。\n\r\n1.《纲目》：“辛，温，无毒。”\n\r\n2.《本草汇言》：“味辛甘苦，气温，无毒。”","f":"化痰，散瘀。治痰饮嘲咳，肠风血痢，疝瘕，牙痛，口臭。\n\r\n1.《本草汇言》：“散冷气，消瘀血，止肠风血痢。凡患阴寒冷气，瘕疝奔豚，腹内一切冷病，蒸热布裹熨之。”\n\r\n2.《国药的药理学》：“治口臭及视觉不明。”\n\r\n3.《陆川本草》：“治痰饮喘咳。”","y":"内服：煎汤，0.5～1钱；或泡茶、浸酒。外用：煎水含漱，或蒸热外熨。","d":"?"},"野葱":{"a":"日葱(藏名)。","s":"性温，味辛。","f":"发汗，散寒，消肿，健胃。治伤风感冒，头痛发烧，腹部冷痛，消化不良；能接骨。","y":"内服：煎汤，3～5钱。外用：加蜂蜜捣烂敷。","d":"?"},"千斤拔":{"a":"金鸡落地、土黄鸡、老鼠尾、透地龙、牛大力、千里马、牛顿头、一条根、土黄昏、吊马桩、千斤吊、大力黄、千尾荡、三股丝、金牛尾、千金坠","s":"甘辛，温。\n\n①《岭南采药录》：\"味辛，性温。\"\n\n②《南宁市药物志》：\"甘，平，无毒。\"\n\n③《福建中草药》：\"甘微苦，平。\"\n\n归肺；肾；膀胱经","f":"祛风利湿，消瘀解毒。治风湿痹痛，慢性肾炎，跌打损伤，痈肿，喉蛾。\n\n①《植物名实图考》：\"补气血。\"\n\n②《岭南采药录》：\"祛风去湿。治手足痹痛，腰部风湿作痛，理跌打伤，能舒筋活络。\"\n\n③《南宁市药物志》：\"壮筋骨，去瘀积。治跌打损伤，风湿骨痛，四肢酸软无力，黄疸。\"","y":"内服：煎汤，0.5～1两。外用：磨汁涂或研末调敷。","d":"干燥根呈圆锥形，长15～30厘米，根头部较膨大。外表棕红色，有明显皮孔。皮部易剥落。商品多切成长约3～7厘米的斜片状。质坚硬，断面白色，粉性，呈菊花心。\n\n产广东、广西、四川等地。"},"舒筋草":{"a":"千金藤(《四川中药志》)，灯笼草(《中国主要植物图说·蕨类》)，青筋藤、毛伸筋(《广西植物名录》)，吊壁伸筋草、伸筋草、灯笼勾(《广西实用中草药新选》)。","s":"《四川中药志》：\"性温，味微甜，无毒。\"","f":"①《四川中药志》：\"能舒筋活血。治风湿关节痛，跌打损伤，筋骨疼痛，月经不调及脚转筋。\"\n\n②《广西实用中草药新选》：\"舒筋活络，消炎除湿。主治夜盲症，盗汗，风湿腰痛，小儿外感发热。\"","y":"内服：煎汤，0.3～1两。","d":"?"},"钻地风":{"a":"追地枫、桐叶藤、全叶钻地风、利筋藤","s":"凉；淡 \n\n《浙江天门山药植志》：\"性凉，味淡。\"\n\n归脾经","f":"治风湿脚气，四肢关节酸痛。\n\n①《植物名实图考》：\"治筋骨，行脚气。\"\n\n②《药材资料汇编》：\"去风湿，止痛。\"\n\n③《浙江天目山药植志》：\"驱风活血。治丝虫病。\"","y":"内服：煎汤，2～4钱；或浸酒。","d":"干燥的根皮呈半卷筒状，厚而宽阔，内层有网纹。以皮质松呢、不含木心、色红棕、味清香微带樟脑气者为佳。\n主产于广西。"},"南烛叶":{"a":"南烛枝叶(《开宝本草》)。","s":"酸涩，平。\n\n\n①《开宝本草》:\"苦，平，无毒。\"\n\n\n②《纲目》:\"酸涩。\"","f":"益精气，强筋骨，明目，止泄。\n\n\n①《本草拾遗》:\"止泄除睡，强筋益气力。\"\n\n\n②《日华子本草》:\"益肠胃，捣汁浸蒸，晒干服。\"\n\n\n③《本草汇言》:\"益气添精，凉血养筋。\"","y":"内服；煎汤，2～3钱；熬膏或入丸、散。","d":"干燥叶呈长椭圆形至披针形，两端尖锐，边缘有疏细锯齿，多向背面反卷，长2～6厘米，宽1～2.5厘米;革质而有光泽，上面暗棕色，主脉凹陷，下面棕色，主脉及侧脉均显著凸出;叶有短柄，多向后弯曲。质脆。气弱，味涩而苦。\n\n\n产江苏、浙江等地。"},"象牙":{"a":"象牙屑","s":"甘，寒。\n\n①《海药本草》：\"寒。\"\n\n②《日华子本草》：\"平。\"\n\n③《品汇精要》：\"味淡，性平，无毒。\"\n\n④《纲目》：\"甘，寒，无毒。\"","f":"?","y":"内服：研末，0.5～1钱；磨汁或入丸、散，外用：磨汁涂或研末调敷。","d":"多呈碎屑状，形状极不规则。表面浅赤或黄色，并有纵行的浅沟纹。内为银白色。片块状者，纵剖面有纵横交叉的波纹，横断面可见同心轮纹。质坚而脆。无臭，无味。以外面浅赤色，内面银白色、显油性者为佳。\n\n非洲象的牙，亦同等入药。"},"岩黄连":{"a":"岩胡。","s":"苦，凉。","f":"清热解毒，利湿，止痛止血。","y":"内服：煎汤，3-15g。外用：适量，研末点患处。","d":"?"},"土大黄":{"a":"吐血草、箭头草、救命王、金不换、红筋大黄、野蒿荬、广角、铁蒲扇、大晕药、包金莲、止血草、牛大黄、土三七、血当归、萝卜奇、血三七、癣药、化血莲","s":"辛苦，凉。\n\n①《纲目拾遗》：\"性平。\"\n\n②《植物名实图考》：\"性凉。\"\n\n③《浙江民间草药》：\"味辛，性平。\"\n\n④《江西草药》：\"性寒，味辛苦。\"\n\n肺；脾；大肠经","f":"清热，行瘀，杀虫，解毒。治咳血，肺痈，腮腺炎，大便秘结，痈疡肿毒，湿疹，疥癣，队打损伤，烫伤。\n\n①汪连仕《采药书》：\"治吐血。军中箭伤，罨之。\"\n\n②《纲目拾遗》：\"破瘀生新。治跌打，消痈肿，止血；愈疥癣，和糖醋捣擦。\"\"治肺痈。\"\n\n③《植物名实图考》：\"治无名肿毒，消血热。\"\n\n④《贵州民间方药集》：\"开胃健脾，补体虚力弱。\"\n\n⑤《湖南药物志》：\"疏风祛湿，杀虫止痒，清热解毒。\"","y":"内服：煎汤，3～5钱。外用：捣敷或磨汁涂。","d":"性状鉴别 根茎粗短，直径约3cm，有少数分枝，顶端有茎基与叶基残余呈棕色鳞片状及须毛纤维状，有的具侧芽及须状根，并有少数横纹。根粗长圆锥形，长约17cm，直径达1.8cm，表面棕色至棕褐色，上段具横纹，其下具多数纵皱纹，散有横长皮孔样疤痕及点状须根痕。质硬，断面黄色，可见棕色形成层环及放射状纹理。气微，味稍苦。\n显微鉴别 根横切面：木栓层薄。皮层为薄壁组织，有的薄壁细胞含有草酸钙簇晶，直径50-60μm。韧皮部细胞压缩。形成层环明显。木质部导管单个散在或数个成群，呈径向排列。无髓。本品薄壁细胞含淀粉粒，类梭形、类球形，长径5-32μm。根茎中央有髓部。"},"刺猬皮":{"a":"猬皮、仙人衣","s":"苦，平。\n\n①《本经》：\"味苦，平。\"\n\n②《别录》：\"无毒。\"\n\n③《药性论》：\"味甘，有小毒。\"\n\n归胃；大肠；肾经  \n\n①《本草求真》：\"入肠、胃。\"\n\n②《本草撮要》：\"入手足太阴、阳明经。\"","f":"降气定痛，凉血止血。治反胃吐食，腹痛疝气，肠风痔漏，遗精。\n\n①《本经》：\"主五痔阴蚀下血，赤白五色血汁不止，阴肿痛引腰背，酒煮杀之。\"\n\n②《别录》：\"疗腹痛疝积，烧为灰，酒服之。\"\n\n③《药性论》：\"主肠风泻血，痔病有头，多年不瘥者，炙末白饮下方寸匕；烧末吹主鼻衄。\"\n\n④孟诜：\"烧灰酒服治胃逆，又煮汁服止反胃。\"\n\n⑤《本草备要》：\"泻，凉血。\"\n\n⑥《本经逢原》：\"除目中翳障。\"\n\n⑦《随息居饮食谱》：\"煅研服，治遗精。\"","y":"内服：煎汤，2～3钱；或入散剂。外用：研末撒或调敷。","d":"干燥的皮呈多角形板刷状或直条状，有的边缘卷曲成简状或盘状，长约3～4厘米。外表面密生错综交插的棘刺，刺长1.5～2厘米，坚硬如针，灰白色、黄色或灰褐色不一。在腹部的皮上多有灰褐色软毛。皮内面灰白色或棕褐色，留有筋肉残痕。具特殊腥臭气。以张大、肉脂刮净、刺毛整洁为佳。\n主产河北、江苏、山东、河南、陕西、甘肃、内蒙古、浙江、安徽、吉林、湖北、湖南等地。"},"毛冬青":{"a":"乌尾丁、痈树、六月霜(《广西中草药》)，细叶冬青、细叶青、苦田螺、山桐油、老鼠啃、山冬青(《浙江民间常用草药》)，毛披树、茶叶冬青(广州空军《常用中草药手册》)，水火药(《新编中医学概要》)，喉毒药(《广西植物名录》)。","s":"《广西中草药》：\"味微苦甘，性平，无毒。\"","f":"清热解毒，活血通脉。治风热感冒，肺热喘咳，喉头水肿，扁桃体炎，痢疾，冠心病，脑血管意外所致的偏瘫，血栓闭塞性脉管炎，丹毒，烫伤，中心性视网膜炎，葡萄膜炎，以及皮肤急性化脓性炎症。用于冠状动脉硬化性心脏病、急性心肌梗塞、血柱闭塞性脉管炎；外用治烧、烫伤，冻疮。\n\n①《广西中草药》：\"清热解毒，消肿止痛，利小便。治刀枪打伤，肺热喘咳，外感风热，预防流脑。\"\n\n②《浙江民间常用中草药》；\"治感冒，扁桃体炎，痢疾，血栓闭塞性脉管炎。\"\n\n③《新编中医学概要》：\"活血通脉。治血栓闭塞性脉管炎，冠心病，脑血管意外所致的偏瘫。\"\n\n④《广西实用中草药新选》：\"清凉解毒，凉血散毒。治喉头水肿，咽喉炎症，暑季外感热症，皮肤急性化脓性炎症。\"","y":"内服：煎汤，1～3两。外用：煎汁涂或浸泡。","d":"根呈不规则块片，外皮灰褐色，略粗糙，易剥落，有纵行细纹。质坚。断面淡黄色，木质部纹理紧密。无臭，味微苦涩。"},"木蝴蝶":{"a":"千张纸、兜铃、磊刀树、三百两银药、玉蝴蝶、云故纸、破布子、白故纸、海船果心、白玉纸、白千层、纸肉、故纸、洋故纸、鸭船层纸、千纸肉、海船皮、满天飞","s":"苦，寒。\n\n①《岭南采药录》：\"味酸苦。\"\n\n②《药材资料汇编》：\"味苦，寒。\"\n\n③《广西中药志》：\"味甘淡，性凉，无毒。\"\n\n入肺、肝经。\n\n①《滇南本草》：\"入肺、脾、胃经。\"\n\n②《岭南采药录》：\"入肝经。\"","f":"润肺，舒肝，和胃，生肌。治咳嗽，喉痹，音哑，肝胃气痛，疮口不敛。治干咳不止常配夏枯草。\n\n①《云南通志》：\"焚为灰，可治心气痛。\"\n\n②《滇南本草》：\"定喘，消痰，破蛊积，除血蛊、气蛊之毒。又能补虚，宽中，进食。\"\n\n③《纲目拾遗》：\"治心气痛，肝气痛，下部湿热。又项秋子云，凡痈毒不收口，以此贴之。\"\n\n④《岭南采药录》：\"消痰火，除眼热。\"\n\n⑤《现代实用中药》：\"镇咳，治百日咳及干性气管炎。\"\n\n⑥《药材资料汇编》：\"治咽喉失音。\"\n\n⑦广州部队《常用中草药手册》：\"清肺热，利咽喉。治急慢性支气管炎，肺结核咳嗽，咽喉肿痛，扁桃体炎。\"","y":"内服：煎汤，2～3钱；或研末。外用：敷贴。","d":"种子类椭圆形，扁平而菲薄.外种皮除基部外，三边延长成宽大的翅，呈半透明薄膜状，淡棕白色，有绢样光泽，并有放射状纹理，边缘多破碎。连翅种子长径约5.5～8厘米，短径3.5～4厘米.除去翅后，种子长径约2～3厘米，短径约1.5～2厘米。剥去膜质的外种皮后可见一层薄膜状的胚乳，紧裹于子叶之外。珠柄线形，黑棕色，着生于基部。子叶2枚，黄绿色，扁平，蝶形，质脆，胚根明显。气无，味微苦。以干燥，色白、大而完整者为佳。\n\n主产云南、广西、贵州。此外，福建，广东、四川凉山彝族自治州亦产少量。"},"白花丹":{"a":"山坡芩、假茉莉、总管(《生草药性备要》)，千里及、乌面马(《植物名汇》)，白雪花(《广州植物志》)，野苜莉、隔布草(《福建民间草药》)，千槟梅、照药(《广西药植图志》)，天槟榔(《南宁市药物志》)，白皂药、白花皂药(《四川中药志》)，一见消(广州部队《常用中草药手册》)，白花岩陀(《云南中草药》)。","s":"辛苦涩，温，有毒。\n\n①《生草药性备要》：\"味苦，性寒，无毒。\"\n\n②《广西药植图志》：\"味辛，气烈，性热，有大毒。\"\n\n③《四川中药志》：\"性温，味淡，无毒。\"\n\n④《岭南草药志》：\"性微温；根茎：味微涩微苦；叶：辣，有毒。\"","f":"祛风，散瘀，解毒，杀虫。治风湿关节疼痛，血瘀经闭，跌打损伤，肿毒恶疮，疥癣。\n\n①《生草药性备要》：\"散疮，消肿，祛风。治蛇咬，痢症，去眼膜，迎风下泪；擦癣疥癞，去毒俱妙。\"\n\n②《岭南采药录》：\"其叶捣烂敷跌打伤，能去瘀。\"\n\n③《四川中药志》：\"治痨伤吐血，虚弱带下及咳嗽心累。\"\n\n④广州部队《常用中草药手册》：\"祛风除湿，散瘀消肿。根：治风湿骨痛，陈旧性关节扭伤，心胃气痛。\"","y":"内服：煎汤，3～5钱。(须久煎)外用：煎水洗，捣敷或涂擦。","d":"?"},"地丁":{"a":"箭头草(《普济方》)，羊角子(《乾坤生意秘韫》)，独行虎(《纲目》)，地丁草(《本草再新》)，如意草(《随息居饮食谱》)。","s":"苦，寒.\n\n①《滇南本草》：\"性寒，味苦。\"\n\n②《纲目》：\"苦辛，寒，无毒。\"\n入心、肝经。\n\n①《玉楸药解》：\"入手少阴心。足少阳胆经。\"\n\n②《要药分剂》：\"入肝、脾二经。\"","f":"请热利湿，解毒消肿。治疔疮，痈肿，瘰疬，黄疸，痢疾，腹泻，目赤，喉痹，毒蛇咬伤。\n\n①《滇南本草》：\"破血，解痈疽疥癞，九种痔疮，诸疮毒症。\"\n\n②《纲目》：\"主治一切痈疽发背，疔肿瘰疬，无名肿毒，恶疮。\"\n\n③《本草求原》：\"凉血，消肿毒。治血热筋痿，敷疮妙。\"\n\n④《岭南采药录》：\"作泻药及吐药。\"\n\n⑤《上海常用中草药》：\"清热解毒，外用拔毒消肿。治目赤肿痛，麦粒肿，疗疮肿毒，乳痈，肠炎腹泻，毒蛇咬伤。\"\n\n⑥苏医《中草药手册》：\"治一切化脓性感染，毒蛇咬伤，淋巴结核，黄疸，肾炎，膀胱炎，关节肿痛，便血，鼻出血，眼结膜炎，前列腺炎。\"","y":"内服：煎汤，0.5～1两(鲜者2～3两)；捣汁或研末。外用：捣敷或熬膏摊贴。","d":"①紫花地丁\n又名：堇菜地丁。为植物紫花地丁或犁头草的带根全草。市售品多皱缩弯曲成不规则的团块，主根数条，长3～5厘米，直径1～3毫米。表面皱缩而粗糙，土黄?，波状弯曲，具须根痕。地上部分呈深绿色至绿黄色，叶柄细长，扭曲，叶片极皱缩，用热水浸软摊开后，呈长椭圆形或线状披针形，全体被毛。花茎细长，顶端常具三裂蒴果，内含多数种子，长圆球形，淡黄棕色。质脆易碎。气微臭，味微苦而涩并稍粘。以色黄绿、整齐、无杂质者为佳。\n主产江苏、浙江、安徽等地。\n\n②甜地丁\n又名：米口袋地丁、萝卜地丁。为植物米口袋或小米口袋的根或带根的全草。主根呈纺锤形、长锥形或长圆柱形，长10～20厘米，直径3～6毫米。表面红棕色至土黄色，粗糙，有纵皱纹，多少扭曲，或有残存的支根及须根，皮孔横生，稍突起，呈点线状，色稍深。上端有多数基生叶。叶为羽状复叶，叶柄细长，小叶片椭圆形或长椭圆形，被白色柔毛，多呈灰绿色。有时可见圆筒形的荚果，表面密被柔毛，开裂或不开裂。主根质坚而稍韧，难折断。折断面纤维极多，乳白色，内面不平坦，微显颗粒状，乳黄色，并有放射状花纹，气微臭，味淡而梢甜。以根粗壮而长、叶绿，无杂质者为佳。\n主产东北、江苏、江西、湖南、湖北等地。\n\n③龙胆地丁\n又名：华南地丁，为植物华南龙胆带花的全草。多干燥皱缩成不规则团块，根部土黄色。用热水浸软，摊开观察：茎自基部丛生，多数，紫红色，顶端具淡紫色或淡土黄绿色的钟状花。叶两两对生，长圆形至长椭圆形，叶柄较短或无；近基部的叶密集，形状较大，上部的叶稀疏，形状较小。质地较脆而易碎。有青草气，味淡而稍苦。以株矮小，叶色青、花色紫者为佳。\n主产广西，广东等地。\n\n地丁药材，较为复杂，除上述品种外，在广东以长萼堇菜、陕西以白花堇菜、新疆以香堇的带根全草作紫花地丁入药。\n\n另有一种苦地丁，为罂粟科植物地丁紫堇的全草。东北、内蒙古、河北、青海、山东等地作\"地丁\"入药。详\"苦地丁\"条。"},"夏天无":{"a":"一粒金丹、洞里神仙、野延胡、飞来牡丹、伏地延胡索、落水珠","s":"苦；辛；凉 \n\n归肝；肾经","f":"降压镇痉，行气止痛，活血去瘀。治高血压，偏瘫，风湿性关节炎，坐骨神经痛，小儿麻痹后遗症。\n\n①《浙江民间常用草药》：\"行血，活血，止血，止痛，镇痉。\"\n\n②江西《中草药学》：\"降压止痛，行气活血。治各型高血压、偏瘫症，风湿性关节炎，腰肌劳损。\"","y":"内服：煎汤，1.5～5钱；或研末。","d":"性状鉴别 块茎类球形、长圆形或呈不规则块状，长0.5-3cm，直径0.5-2.5cm。表面灰黄色、暗绿色或黑褐色，有瘤状突起和不明显的细皱纹，上端钝圆，可见茎痕，四周有淡黄色点状叶痕及须根痕。质硬，断面黄白色或黄色，颗粒状或角质样，有的略带粉性。气无，味苦。以个大、质坚、断面黄白色者为佳。\n\n显微鉴别 块茎横切面：皮层为3至数列淡黄色、扁平的细胞，常具纹孔。维管束外韧型，4-7束，呈放射状排列。韧皮部宽广。木质部导管细小。中央有髓。薄壁细胞中淀粉粒已糊化。"},"鸦胆子":{"a":"老鸦胆、鸦胆、苦榛子、苦参子、鸦蛋子、鸭蛋子、鸭胆子、解苦楝、小苦楝","s":"苦，寒，有毒。\n\n①《医学衷中参西录》：\"味极苦，性凉。\"\n\n②《本草正义》：\"大苦，大寒。\"\n\n③《广西中药志》：\"味极苦，性寒，有毒。\"\n\n归大肠；肝经","f":"清热，燥湿，杀虫，解毒。治痢疾，久泻，疟疾，痔疮，疔毒，赘疣，鸡眼。\n\n①《生草药性备要》：\"凉血，去脾家疮，理跌打。\"\n\n②《纲目拾遗》：\"治痢，痔。\"\n\n③《岭南采药录》：\"治冷痢，久泻。又能杀虫。\"\n\n④《医学衷中参西录》：\"凉血解毒，善治热性赤痢，二便因热下血。\"\"治梅毒及花柳毒淋。捣烂醋调敷疔毒。善治疣。\"\n\n⑤《科学的民间药草》：\"截疟和治阿米巴痢疾。\"\"制成油质，可治外耳道乳状瘤，乳头瘤，以及尖锐性湿疣。\"\n\n⑥《广西中药志》：\"治疳匿。外用(油亦可)治皮肤瘤。\"","y":"内服：用龙眼肉或胶囊包裹，饭后吞服，每次5～20粒，1日3次。外用：捣敷。","d":"干燥成熟的果实呈长圆形或卵形，两头稍尖，长6～10毫米，直径3～7毫米。表面灰黑色，有不规则多角形的网纹，底端有凹陷的果柄痕。外壳质硬而脆，破开后内向灰红色或灰黄色，光滑而油润。内有黄白色种仁，呈卵形，长4～7毫米，直径3～5毫米，外包抽皱的薄膜，富有油性。无臭，味极苦。以质坚、仁白、油性足者为佳。\n主产广东、广西。福建、台湾亦产。"},"九香虫":{"a":"臭屁虫,屁板虫,瓜黑蝽。","s":"咸，温。\n\n①《纲目》：\"咸，温，无毒。\"\n\n②《本草新编》：\"味甘辛，气微温。\"","f":"理气止痛，温中助阳。用于胃寒胀痛，肝胃气痛，肾虚阳痿，腰膝酸痛。膈脘滞气，脾肾亏损，元阳不足。用九香虫一两（半生焙），车前子（微炒）、陈桔皮各四钱，白术（焙）五钱，杜仲（酥炙）八钱，人研为末，加炼蜜做成丸子，如梧子大。每服一钱五分，以盐开水或盐酒磅下，早晚各服一次。\n\n①《纲目》：\"治膈脘滞气，脾肾亏损，壮元阳。\"\n\n②《本草新编》：\"兴阳益精。\"\n\n③《现代实用中药》：\"适用于神经性胃痛，腰膝酸痛，胸脘郁闷，因精神不快而发胸窝滞痛等症，配合其他强壮药同服有效。\"","y":"内服：煎汤，1～2钱；或入丸、散。","d":"干燥虫体呈六角状椭圆形而扁平，表面红棕色咸棕黑色，长约2厘米，宽约1.2厘米。头很小，呈类三角形。背部有膜质半透明的翅2对，将翅除去后可见背部橙红色，有节，近边缘有1毫米宽的边，棕褐色与棕色相间排列成节纹状。胸部的足多己脱落。腹部棕红色至棕黑色，有油光，每节近边缘处有突起的小点。质脆，折断后腹内有浅棕色油样粉状物。气如茴香，味微咸。以个均匀、棕褐色、油性大、无虫蛀者为佳。\n\n主产云南、四川、贵州、广西等地。"},"青果":{"a":"橄榄子,白榄,黄榄果。","s":"味甘；性平","f":"?","y":"4.5～9g。","d":"纺锤形，长约3～4厘米，直径约1.5～2厘米，表面黄棕色，皱缩。内果皮木质（果核），致密，坚硬，内三室，每一室内含一红棕色细长棱形种子，除去种皮可见白色富油质子叶两片。气微，味涩，久嚼微甜。"},"土黄连":{"a":"鸡足黄连、三颗针","s":"《滇南本草》：\"味苦，性大寒。\"","f":"清热解毒，利小便。治腹泻，赤痢，火眼赤痛，齿龈肿痛，咽喉炎，热淋，痄腮，丹毒，湿疹。\n\n①《滇南本草》：\"泻小肠经实火，胃中实火，利小便。止热淋疼痛，牙根肿疼，咽喉痛，小儿乳蛾，痄腮。\"\n\n②《四川常用中草药》：\"清热解毒，消炎抗菌。治目赤，亦痢，劳伤吐血，咽喉肿痛，腹泻，齿痛，耳心痛，跌打损伤红肿。\"","y":"内服：煎汤，根2～3钱，茎叶1～2两。外用：乳汁泡点眼或研末调敷。","d":"?"},"桃花":{"a":"?","s":"《别录》：味苦，平，无毒。","f":"利水，活血，通便。治水肿，脚气，痰饮，积滞，二便不利，经闭。\n\n\n①《别录》：\"主除水气，破石淋，利大小便，下三虫。\"\n\n\n②《唐本草》：\"主下恶气，消肿满，利大小肠。\"\n\n\n③《纲目》：\"利宿水痰饮，积滞。治风狂。\"\n\n\n④《本草汇言》：\"破妇人血闭血瘕，血风癫狂。\"\n\n\n⑤《岭南采药录》：\"带蒂入药，能凉血解毒，痘疹通用之。\"","y":"内服：煎汤，1～2钱；或研末。外用：捣敷或研末调敷。","d":"?"},"龙涎香":{"a":"龙尿(《酉阳杂俎》)，龙腹香。","s":"甘酸，气腥。\n\n①《药性考》：\"味甘，气腥，性涩。\"\n\n②《纲目拾遗》：\"气腥，味微酸咸，无毒。\"","f":"行气活血，散结止痛，利水通淋。治咳喘气逆，气结癥积，心腹疼痛，淋病。\n\n①范咸《台湾府志》：\"止心痛，助精气。\"\n\n②《纲目拾遗》：\"活血，益精髓，助阳道，通利血脉。又廖永言：利水通淋，散癥结，消气结，逐劳虫。周曲大：能生口中津液，凡口患干燥者含之，能津流盈颊。\"\n\n③《药材学》：\"治咳喘气逆，神昏气闷，心腹诸痛。\"","y":"内服：研末，1～3分。","d":"干燥的龙涎香，呈不透明的蜡状胶块.色黑褐如琥珀，有时有五彩斑纹。质脆而轻，嚼之如蜡，能粘齿。气微腥，味带甘酸。比重约0.7～O.9，融点为60℃，可溶于纯酸中。燃烧时发蓝焰，香气四溢，酷似麝香而幽雅，被熏过之物，能保持持久的香气。以黑褐色、体松质韧、焚之有幽香者为佳。"},"穿山龙":{"a":"穿龙骨、穿地龙(《东北药植志》)，狗山药(《河北药材》)，山常山(《山东中药》)，穿山骨(《中国药植图鉴》)，火藤根(《陕西中草药》)，粉萆薢、黄姜、土山薯(《中国经济植物志》)，竹根薯、铁根薯、雄姜、黄鞭(《浙江民间常用草药》)，地龙骨、山花啦、金刚骨(《河北中药手册》)，串山龙(《东北常用中草药手册》)。","s":"①《浙江民间常用草药》：\"性平，味苦。\"\n\n②《辽宁常用中草药手册，：\"甘苦，温。\"","f":"活血舒筋，消食利水，祛痰截疟。治风寒湿痹，慢性气管炎，消化不良，劳损扭伤，疟疾，痈肿。\n\n①《东北药植志》：\"舒筋活血，治腰腿疼痛，筋骨麻木。\"\n\n②《山东中药》：\"治风寒湿痹。\"\n\n③《陕西植药调查》：\"制疟，止疼，消肿。\"\n\n④《陕西中草药》：\"治咳嗽，风湿性关节炎，大骨节病关节痛，消化不良，疟疾，跌打损伤，痈肿恶疮。\"","y":"内服：煎汤，0.5～1两(鲜者1～2两)；或浸酒。外用：鲜品捣敷。","d":"干燥根茎，星长圆柱形，长10～20厘米，直径约1.5厘米，具多数不规则的分枝.外表土黄色，有多数细纵纹及突起的须根残基，全形略似鹿角。质坚硬，断面淡黄色，粉性，可见多数带细孔的维管束散在。气微，味苦。以根茎粗长，土黄色，质坚硬者为好。\n产辽宁、古林、黑龙江、山东、浙江、河北、山西等地。"},"甘松":{"a":"甘香松、香松","s":"甘，温。\n\n①《开宝本草》：\"甘，温，无毒。\"\n\n②《汤液本草》：\"气平。\"\n\n③《本草从新》：\"辛甘，温。\"\n\n④江西《中草药学》：\"甘，温，有小毒。\"\n\n入脾、胃经。\n\n①《本草汇言》：\"入足太阴、阳明经。\"\n\n②《本草再新》：\"入心、脾二经。\"","f":"理气止痛，醒脾健胃。治胃痛，胸腹胀满，头痛，癔病，脚气。\n\n①《本草拾遗》：\"主熏皮黚黯，风疳齿匿，野鸡痔。\"\n\n②《日华子本草》：\"治心腹胀，下气。\"\n\n③《开宝本草》：\"主恶气，卒心腹痛满。\"\n\n④王好古：\"理元气，去气郁。\"\n\n⑤《纲目》：\"治脚气膝浮，煎汤淋洗。\"\n\n⑥《现代实用中药》：\"适用于头痛、腹痛及精神忧郁等证，并能驱蛔，凡因蛔虫而发惊瘸者，用此有效。\"","y":"内服：煎汤，0.8～1.5钱；或入丸、散。外用：泡水含漱或煎水洗。","d":"甘松香干燥的根茎及根，全形弯曲如虾，上粗下细。根茎上附有地上茎残基及多层的枯叶残基，长约1～2厘米；外层棕黑色，内层棕色至黄色；呈狭长膜质片状或纤维状。地上茎残基中空，显棕色。主根条柱形，单一，有的数股交结，并列或分枝；长约5～13厘米，少数达20厘米，直径约0.3～1厘米；表面皱缩，呈棕褐色，常裂成片状；中心木质部灰棕色，老根下部为单一中柱，而上部有2～4个分体中柱。幼根和须根弯曲，表面皱缩，浅棕黄色。气芳香，味苦。以主根肥壮、条长、芳香味浓、无碎片泥砂者为佳。\n主产四川。此外，甘肃、青海等地亦产。"},"橘皮":{"a":"陈皮(孟诜)，贵老(侯宁极《药谱》)，黄橘皮(《鸡峰普济方》)，红皮(《汤液本草》)。","s":"辛苦，温。\n\n①《本经》：\"味辛，温。\"\n\n②《别录》：\"无毒。\"\n\n③崔禹锡《食经》：\"味辛苦。\"","f":"理气，调中，燥湿，化痰。治胸腹胀满，不思饮食，呕吐哕逆，咳嗽痰多。亦解鱼、蟹毒。\n\n①《本经》：\"主胸中瘕热、逆气，利水谷，久服去臭，下气。\"\n\n②《别录》：\"下气，止呕咳，除膀胱留热、停水、五琳，利小便，主脾不能消谷，气冲胸中，吐逆霍乱，止泄，去寸白。\"\n\n③《药性论》：\"治胸膈间气，开胃，主气痢，消痰涎，治上气咳嗽。\"\n\n④《本草拾遗》：\"去气，调中。\"\n\n⑤《日华子本草》：\"消痰止嗽，破癥瘕痃癣。\"\n\n⑥《医学启源》：\"去胸中寒邪，破滞气，益脾胃。\"\n\n⑦《纲目》：\"疗呕哕反胃嘈杂，时吐清水，痰痞，痎疟，大肠闭塞，妇人乳痈。入食料解鱼腥毒。\"\n\n⑧《随息居饮食谱》：\"解鱼、蟹毒。治噫噎，胀闷，疳疟。泻痢，便秘，脚气。\"","y":"内服：煎汤，1～3钱；或入丸、散。","d":"完整的果皮常剖成4瓣，每瓣多呈椭圆形，在果柄处连在一起。有时破碎分离，或呈不规则形的碎片状。片厚1～2毫米，通常向内眷曲：外表面鲜橙红色、黄棕色至棕褐色，有无数细小而凹入的油室；内表面淡黄白色，海绵状，并有短线状的维管束(橘络)痕，果蒂处较密。质柔软，干燥后质脆，易折断，断面不平。气芳香，味苦。以皮薄、片大、色红、油润、香气浓者为佳。\n主产四川、浙江、福建。此外，江西、湖南等地亦产。\n\n橘皮药材，除上述橘类的果皮外，柑类及甜橙的果皮，有时亦作橘皮使用，商品名前者习称\"广陈皮\"，参见\"柑皮\"条；后者习称\"土陈皮\"，参见\"橙皮\"条。"},"淡菜":{"a":"壳菜(《嘉祐本草》)，海蜌(《纲目》)，红蛤(《东医宝鉴》)，珠菜(《本草撮要》)。","s":"咸，温。\n\n①孟诜：\"温，无毒。\"\n\n②《本草拾遗》：\"味甘，温，无毒。\"\n\n③《本草从新》：\"甘咸，温。\"","f":"补肝肾，益精血，消瘿瘤。治虚劳羸瘦，眩晕，盗汗，阳痿，腰痛，吐血，崩漏，带下，瘿瘤，疝瘕。\n\n①孟诜：\"产后血结，腹内冷痛，治癥瘕，润毛发，治崩中带下。\"\n\n②《本草拾遗》：\"主虚羸劳损，因产瘦瘠，血气结积，腹冷、肠鸣、下痢，腰疼、带下、疝瘕。\"\n\n③《日华子本草》：\"煮熟食之，能补五脏，益阳事，理腰脚气，消宿食，除腹中冷气，痃癖。\"\n\n④《嘉祐本草》：\"治虚劳伤惫，精血少者，及吐血，妇人带下、漏下，丈夫久痢，并煮食之。\"\n\n⑤《纲目》：\"消瘿气。\"\n\n⑥《随息居饮食谱》：\"补肾，益血填精，治遗、带、崩、淋，阳痿阴冷，消渴，瘿瘤。\"","y":"内服：煎汤，0.5～1两。或入丸、散。","d":"?"},"山葛薯":{"a":"山萝卜,十兄弟,山江豆,山岗荚,立蝶豆","s":"甘微苦；平\n\n 归肺；心经","f":"止咳祛痰，消肿拔毒。治老年慢性气管炎，疮肿。\n\n①《南宁市药物志》：\"消肿拔毒，杀虫，治毒疮。\"\n\n②《广西药植名录》：\"解毒，拔脓，消肿，治疮痈。\"","y":"内服：煎汤，3～5钱(每日2剂)。外用：捣敷。","d":"?"},"半枝莲":{"a":"狭叶韩信草、通经草、紫连草、并头草、牙刷草、水韩信、溪边黄芩、金挖耳、野夏枯草、言草儿、半向花、偏头草、四方草、耳挖草、小号向天盏、狭叶向天盏","s":"味辛；苦；性平。归肺；肝；肾经。\n\n\n①《广西药植图志》：\"味辛微腥，性平，无毒。\"\n\n②《南宁市药物志》：\"甘，平，无毒。\"\n\n③《江西民间草药验方》：\"性平，味辛微苦，无毒。\"\n\n④广州部队《常用中草药手册》：\"微苦，凉。\"","f":"清热，解毒，散瘀，止血，利尿消肿，定痛。治吐血，衄血，血淋，赤痢，黄疸，咽喉疼痛，肺痈，疔疮，瘰疬，疮毒，癌肿，跌打刀伤，蛇咬伤。\n\n①《南京民间药草》：\"破血通经。\"\n\n②《广西药植图志》：\"消炎，散瘀，止血。治跌打伤，血痢。\"\n\n③《南宁市药物志》：\"消肿，止痛。治跌打，刀伤，疮疡。\"\n\n④《泉州本草》：\"清热，解毒，祛风，散血，行气，利水，通络，破瘀，止痛。内服主血淋，吐血，衄血；外用治毒蛇咬伤，痈疽，疔疮，无名肿毒。\"\n\n⑤广州部队《常用中草药手册》：\"清热解毒。治癌见到改善症状的效果；阑尾炎，肝炎。\"\n\n⑥成都《常用草药治疗手册》：\"治食道癌、胃癌、子宫癌。\"","y":"内服：煎汤，15-30g，鲜品加倍，或入丸、散。外用：适量，鲜品捣敷。","d":"干燥全草，叶片多已脱落，为带有花穗的茎与枝，长15～25厘米，四棱形，表面黄绿色或紫棕色，光滑，质柔软，折断面纤维状，中空；残留的叶片深黄绿色，多破碎不全，皱缩卷曲，质脆而易脱落；花穗着生在枝端，黄绿色。臭微弱，味微咸苦。\n产江苏、江西、福建、广东、广西等地。"},"石蝉草":{"a":"火伤叶、胡椒草(《广西药植名录》)，散血胆、豆瓣七、散血丹、石马菜(《云南中草药选》)，豆瓣绿、红豆瓣(《云南思茅中草药选》)。","s":"辛，凉。\n\n①《云南中草药选》：\"辛淡，平。\"\n\n②《云南思茅中草药选》：\"性凉，味淡。\"","f":"①《云南中草药选》：\"祛瘀散结，抗癌。治胃癌，食道癌，肝癌，乳腺癌，肺癌。\"\n\n②《云南思茅中草药选》：\"清热解毒，消肿散瘀，止痛利水。治跌打损伤，烫烧伤，痈肿疮疖，肾炎水肿，肺结核，哮喘，气管支气管炎，肺热咳嗽。\"","y":"内服：煎汤，1～2两；或浸酒。外用：捣敷。","d":"?"},"粟米":{"a":"白粱粟、粢米、粟谷、小米、硬粟、籼粟、谷子、寒粟、黄粟、稞子","s":"甘咸，凉。陈粟米：苦，寒。\n\n①《别录》：\"味咸，微寒，无毒。陈粟米：味苦。\"\n\n②《本草衍义》：\"陈粟米：性冷。\"\n\n③《纲目》：\"咸淡。\"\n\n④《本草备要》：\"甘咸，微寒。\"\n\n⑤《陆川本草》：\"甘，平。\"\n\n归肾；脾；胃经  \n\n①《本草求真》：\"专入肾，兼入脾、胃。\"\n\n②《本草撮要》：\"入手足太阴、少阴经。\"","f":"和中，益肾，除热，解毒。治脾胃虚热，反胃呕吐，消渴，泄泻。陈粟米：止痢，解烦闷。\n\n①《别录》：\"主养肾气，去胃脾中热，益气。陈粟米：主胃热，消渴，利小便。\"\n\n②陶弘景：\"陈粟米：作粉尤解烦闷。\"\n\n③孟诜：\"陈粟米：止痢。\"\n\n④《本草拾遗》：\"粟米粉解诸毒，水搅服之；亦主热腹痛，鼻衄，并水煮服之。\"\n\n⑤《日用本草》：\"和中益气，止痢，治消渴，利小便，陈者更良。\"\n\n⑥《滇南本草》：\"主滋阴，养肾气，健脾胃，暖中。治反胃，小儿肝虫，或霍乱吐泻，肚疼痢疾，水泻不止。\"\n\n⑦《纲目》：\"煮粥食益丹田，补虚损，开肠胃。\"","y":"内服：煎汤，0.5～1两；或煮粥。外用：研末撒或熬汁涂。","d":"栽培植物中的梁，与粟为同种。李时珍谓：梁即粟也，大而毛长者为粱，细而毛短者为粟。参见青粱米、黄粱米、白梁米各条。"},"大金钱草":{"a":"神仙对坐草,地蜈蚣,蜈蚣草,铜钱草,野花生,仙人对坐草,四川大金钱草,大金钱草,对坐草,一串钱,临时救,黄疸草,一面锣,金钱肺筋草,藤藤侧耳根,白侧耳根,铜钱花,水侧耳根,大连钱草,遍地黄,黄花过路草,龙鳞片,真金草,走游草,铺地莲","s":"甘淡，平。\n\n\n①《草木便方》：\"淡。\"\n\n\n②《浙江民间草药》：\"性寒，味酸。\"\n\n\n③《四川中药志》：\"性平，味谈，无毒。\"\n\n\n④《上海常用中草药》：\"苦酸，凉。\"\n\n\n归肝;胆;肾;膀胱经","f":"清热，利湿，消肿，解毒。治黄疸，水肿，胆结石、肾结石、膀胱结石，反胃噎膈，跌打损伤，疔疮肿毒。\n\n\n①王安卿《采药志》：\"治反胃噎膈，水肿臌胀，黄白火丹，阴症伤寒。\"\n\n\n②《草木便方》：\"除风毒。癫狗咬伤，捣酒服。疠风，丹毒，生服、(外)涂。\"\n\n\n③《四川中药志》：\"清血热，清肺止咳，消水肿。治肾结石，胆结石，跌打损伤及疟疾。\"\n\n\n④《重庆草药》：\"治痨伤咳嗽带血。\"","y":"内服：煎汤，0.5～2两；或捣汁。外用：捣敷。","d":"干燥全草多皱缩成团。根纤细，淡黄色;茎扭曲，暗红棕色，表面多细纵沟纹，径约1毫米，无毛;断面外圈深棕色，中心淡黄色;下部茎节处有须根。叶对生，多皱缩，卵形或心形，主脉1条，于下面突出，侧脉不显，上面棕绿色，下面较浅，性脆易碎。用水浸后，透光可见黑色短条纹。花果一般不见。气微香，味淡微酸。\n\n\n主产四川;此外，江苏、广西、浙江、湖南等地亦产。\n\n\n四川地区还有同属植物点腺过路黄，其全草或带根全草亦可作大金钱草使用。"},"辣椒":{"a":"番椒、秦椒(《群芳谱》)，辣茄(《花镜》)，辣虎(《药性考》)，腊茄(《药检》)，海椒、辣角(《遵义府志》)，鸡嘴椒(《广州植物志》)。","s":"辛，热。\n\n①《群芳谱》：\"味甚辣。\"\n\n②姚可成《食物本草》：\"味辛，温，无毒。\"\n\n③《食物宜忌》：\"辛苦，大热。\"","f":"温中，散寒，开胃，消食。治寒滞腹痛，呕吐，泻痢，冻疮，疥癣。\n\n①姚可成《食物本草》：\"消宿食，解结气，开胃口，辟邪恶，杀腥气诸毒。\"\n\n②《百草镜》：\"洗冻瘃，浴冷疥，泻大肠经寒澼。\"\n\n③《药性考》：\"温中散寒，除风发汗，去冷癖，行痰逐湿。\"\n\n④《食物宜忌》：\"温中下气，散寒除湿，开郁去痰，消食，杀虫解毒。治呕逆，疗噎膈，止泻痢，祛脚气。\"\n\n⑤《药检》：\"能祛风行血，散寒解郁，导滞，止澼泻，擦癣。\"","y":"内服：入丸、散，3～8分。外用：煎水熏洗或捣敷。","d":"干燥成熟的果实，带有宿萼及果柄。果皮带革质，干缩而薄，外表鲜红色或红棕色，有光泽。内部空，由中隔分隔成2～3室，中轴胎座，每室有多数黄色的种子；种子扁平，呈肾形或圆形，直径达5毫米。气特殊，具催嚏性，味辛辣如灼。"},"虎骨胶":{"a":"虎胶(《医林纂要》)。","s":"咸，温。\n\n①《医林纂要》：\"辛咸，热。\"\n\n②《四川中药志》：\"性温，味淡，无毒。\"","f":"①《医林纂要》：\"功同骨而滋益从容。\"\n\n②《四川中药志》：\"补益气血，强健筋骨。治中风瘫痪，筋骨受风拘挛，四肢麻木，不能屈伸及痿躄。\"","y":"内服：用黄酒炖化，冲入药汁中，1～2钱；或入丸剂。","d":"?"},"白毛藤":{"a":"苻(《尔雅》)，蜀羊泉、谷菜(《本经》)，鬼目草(《尔雅》郭璞注)，白草(《别录》)，排风、白幕(《本草拾遗》)，鬼目菜(《吴志》)，天灯笼、和尚头草(《纲目拾遗》)，望冬红、酸尖菜(《植物名实图考》)，排风藤(《分类草药性》)，土防风、耳坠菜(《贵州民间方药集》)，金线绿毛龟草、葫芦草(《福建民间草药》)，毛风藤(《江西民间草药》)，毛老人(《江西中药》)，红道士、毛和尚(《浙江民间草药》)，野猫耳朵(《四川中药志》)，胡毛藤、羊仔耳、生毛梢、龙毛龟、毛燕仔、红麦禾(《闽东本草》)。","s":"甘苦，寒。\n\n①《本经》：\"味苦，微寒。\"\n\n②《别录》：\"无毒。\"\n\n③《福建民间草药》：\"微苦涩，平。\"","f":"请热，利湿，祛风，解毒。治疟疾，黄疸，水肿，淋病，风湿关节痛，丹毒，疔疮。\n\n①《本经》：\"主头秃恶疮热气，疥瘙痂癣虫。\"\n\n②陶弘景：\"叶作羹饮，甚疗劳。\"\n\n③《本草拾遗》：\"主烦热，风疹，丹毒，疟瘴，寒热，小儿结热。\"\n\n④《开宝本草》：\"别本注，茎叶煮粥极解热毒。\"\n\n⑤《百草镜》：\"除骨节风湿痛。\"\n\n⑥王安卿《采药志》：\"活血追风生血，治鬼箭有效。\"\n\n⑦《纲目拾遗》：\"止血淋，疟，疝气。汁滴耳中，止脓不干。治疬癖，用煮牛肉精者食之。\"清湿热，治黄疸水肿，小儿蛔结腹痛。\"\n\n⑧《植物名实图考》：\"治腰痛。\"\n\n⑨《分类草药性》：\"治惊风，咳嗽。\"\n\n⑩《药材学》：\"清热解毒。治恶疮，漆疮。\"","y":"内服：煎汤，5～8钱(鲜者1～2两)；或浸酒。外用：煎水洗、捣敷或捣汁涂。","d":"干燥的茎，类圆柱形，直径约2～7毫米，外表黄绿色至暗棕色，密被灰白色的毛茸，在较粗的茎上，毛茸极少或无，具纵皱纹，且有光泽；质硬而脆，断面淡绿色，纤维性，中央形成空洞。叶皱缩卷曲，密被毛茸，叶柄长约1～2厘米。有的带有淡黄色至暗红色的果实。以干燥、肥嫩、叶绿、无子、无杂草者为佳。\n主产江苏、浙江。安徽等地。"},"伸筋藤":{"a":"宽筋藤,无地生须,青宽筋藤,砍不死,舒筋藤","s":"苦，寒\n\n《南宁市药物志》：\"苦，寒。\"","f":"祛风化湿、活血通络、舒筋壮骨、入肝肾经。主治关节痛、风湿四肢痛、腰痛、足根酸痛等。\n \n①《南宁市药物志》：\"舒筋活络，杀虫。外敷跌打筋断，风湿骨痛；内服舒筋活络。\"\n\n②广州部队《常用中草药手册》：\"舒筋活络，清热利湿。治风湿筋骨痛，腰肌劳损，跌打损伤。\"","y":"内服：煎汤，3～5钱。外用：捣敷。","d":"?"},"合欢花":{"a":"夜合花(《本草衍义》)，乌绒(《雷公炮制药性解》)。","s":"甘，平。\n\n①《四川中药志》：\"性平，味苦，无毒。\"\n\n②江西《中草药学》：\"甘，平。\"","f":"舒郁，理气，安神，活络。治郁结胸闷，失眠，健忘，风火眼疾，视物不清，咽痛，痈肿，跌打损伤疼痛。\n\n①《本草便读》：\"能养血。\"\n\n②《分类草药性》：\"能清心明目。\"\n\n③《四川中药志》：\"能合心志，开胃理气，消风明目，解郁。治心虚失眠。\"\n\n④江西《中草药学》：\"解郁安神，和络止痛。治肝郁胸闷，忧而不乐，健忘失眠。有时还用于跌打损伤，痈肿疼痛。\"\n\n⑤《东北常用中草药手册》：\"治咽喉疼痛。\"","y":"内服：煎汤，1～3钱；或入丸、散。","d":"①合欢花：干燥花序呈团块状，有如棉絮。小花长约0.8～1厘米，弯曲，淡黄褐色或绿黄色；花冠筒状，先端5裂，外面有长柔毛；花萼细筒状，绿黄色；雄蕊多数，花丝细长，伸出花冠外，交织紊乱，易断。微香。\n\n②合欢米：干燥花蕾，青绿色，不分瓣。\n\n以上两种药材产浙江、安徽、江苏、四川等地。\n\n四川地区尚用同属植物山合欢的花和花蕾。"},"伸筋草":{"a":"石松、过山龙、宽筋藤、火炭葛、金毛狮子草、金腰带、狮子草、狮子毛草、立筋草、舒筋草、铺筋草、抽筋草、分筋草、过筋草、地棚窝草、筋骨草、绿毛伸筋、小伸筋、凤尾伸筋、蜈蚣藤、大地毛公、缠身龙、猫藤草、通伸草、山猫儿、老虎垫坐、盘龙草、烂腰蛇、宽筋草、穿山龙","s":"苦辛，温。\n\n①《本草拾遗》：\"味苦辛，温，无毒。\"\n\n②《本草求原)：\"甘涩，平。\"\n\n归肝；脾；肾经 \n\n《四川中药志》：\"入肝、脾、肾三经。\"","f":"祛风散寒，除湿消肿，舒筋活血。治风寒湿痹，关节酸痛，皮肤麻木，四肢软弱，水肿，跌打损伤。\n\n①《本草拾遗》：\"主久患风痹，脚膝疼冷，皮肤不仁，气力衰弱。\"\n\n②《滇南本草》：\"下气，消胸中痞满横格之气，推胃中隔宿之食，去年久腹中之坚积，消水肿。\"\n\n③《生草药性备要》：\"消肿，除风湿。浸酒饮，舒筋活络。其根治气结疼痛，损伤，金疮内伤，去痰止咳。\"\n\n④《浙江民间常用草药》：\"舒筋，消炎。治关节酸痛，带状疱疹。\"\n\n⑤《东北常用中草药手册》：\"舒筋活血，祛风散寒，止痛。治腰腿酸痛，风湿性关节肿痛，月经不调。\"","y":"内服：煎汤，3～5钱；或浸酒。外用：捣敷。","d":"干燥匍匐茎细长而弯曲，黄色或黄绿色，长30～120厘米，径粗1～3毫米。质柔韧，不易折断，折断面近白色，内有黄白色木心，常可见近直角生出的黄白色细根，外皮常脱落。直立茎2歧式分枝。鳞叶常皱而弯曲，密生于茎上，线形或线状钻形，黄绿色或黄色，无毛，略有光泽。叶端渐尖呈芒状，全缘，叶脉不明显。质薄，易碎。气无，味淡。以茎长、黄绿色者为佳。\n主产浙江、湖北、江苏等地，湖南、四川亦产。\n\n同属植物玉柏和垂穗石松的全草在浙江、四川等地均称伸筋草，并同等使用。参见\"玉柏\"、\"铺地蜈蚣\"条。"},"虎尾轮":{"a":"狐狸尾、猫尾草、老虎尾、统天草、大本山青、古钱窗草、铁金锏、狗尾射","s":"甘；微苦；平。归心；肺；肝经\n\n《闽南民间草药》：\"甘微苦，平。\"","f":"清肺止咳；散瘀止血。主肺热咳嗽；肺痈；积聚；乳吹；脱肛；子宫脱垂；吐血；尿血；外伤出血\n\n①《闽南民间草药》：\"润燥解热，消痈解毒。\"\n\n②《广西中草药》：\"散瘀止血，清热止咳。治吐血，咯血，尿血，刀伤出血，肺热咳嗽，子宫脱垂，脱肛。\"\n\n③龙溪《实用中草药》：\"活血通络，理气和中。治胃及十二指肠溃疡，肺结核，白带、关节炎、小儿疳积。\"","y":"内服：煎汤，鲜者1～2两。","d":""},"葡萄":{"a":"草龙珠(《纲目》)，山葫芦(《中国树木分类学》)。","s":"甘酸，平。\n\n①《本经》：\"味甘，平。\"\n\n②孟诜：\"甘酸，温。\"\n\n③《纲目》：\"甘涩，平，无毒。\"","f":"补气血，强筋骨，利小便。治气血虚弱，肺虚咳嗽，心悸盗汗，风湿痹病，淋病，浮肿。\n\n①《本经》：\"主筋骨湿痹，益气倍力，强志，令人肥健耐饥，忍风寒。可作酒。\"\n\n②《别录》：\"逐水，利小便。\"\n\n③《药性论》：\"除肠间水气，调中治淋，通小便。\"\n\n④《本草图经》：\"治时气发疮疹不出者，研酒饮。\"\n\n⑤《滇南本草》：\"大补气血，舒筋活络，泡酒服之。治阴阳脱症，又治盗汗虚证。汁，治咳嗽。\"\n\n⑥《滇南本草图说》：\"治痘症毒，胎气上冲，煎汤饮之即下。\"\n\n⑦《百草镜》：\"治筋骨湿痛。利水甚捷，除遍身浮肿。\"\n\n⑧《本耳再新》：\"暖胃健脾，治肺虚寒嗽，破血积疽瘤。\"\n\n⑨《随息居饮食谱》：\"补气，滋肾液，益肝阴，强筋骨，止渴，安胎。\"\n\n⑩《新疆药材》：\"解毒，散表。\"\n\n⑾《陆川本草》：\"滋养强壮，补血，强心利尿。治腰痛，胃痛，精神疲惫，血虚心跳。\"","y":"内服：煎汤、捣汁或浸酒。","d":"琐琐葡萄：干燥的果实外皮红褐色，小颗粒，果皮有皱纹，味甜。以色红褐、粒整齐、无杂质者为佳，粒瘦破烂者为次。产新疆。"},"毛冬青叶":{"a":"?","s":"《浙江民间常用草药》：\"性平，味苦涩。\"","f":"①《广西中草药》：\"治汤火伤。\"\n\n②《浙江民间常用草药》：\"清热解毒，止痛消炎。治牙周炎，疖痈，带状疱疹，脓疱疮。\"","y":"内服：煎汤，1～3钱。外用：煎水湿敷。研末或捣汁涂敷。","d":"?"},"金刚藤":{"a":"菝葜、铁菱角、马加勒、筋骨柱子、红灯果","s":"性温，味微辛。","f":"祛风，活血，解毒。治风湿腰腿痛，跌打损伤，瘰疬。","y":"内服：煎汤，1～3钱。","d":"?"},"肾炎草":{"a":"杏叶兔耳风,争叶子,马蹄草","s":"微苦，凉。","f":"消炎利尿，清热解毒。治急、慢性肾炎、肾盂炎、尿路感染。","y":"内服：煎汤，1～2两。","d":"?"},"石见穿":{"a":"紫参、五凤花、小丹参、月下红、乌沙草、墨面风、大发汗、石打穿、石大川、山缝拿、紫丹花、红根参、半枝莲、田芹菜、活血草","s":"味辛；苦；性微寒 \n\n《苏州本产药材》：\"苦辛，平。\"\n\n归肝；脾经","f":"治噎膈，痰喘，肝炎，赤白带，痈肿，瘰疬。\n\n①《纲目》：\"主骨痛，大风，痈肿。\"\n\n②《苏州本产药材》：\"治噎膈，痰饮气喘。\"\n\n③《江苏药材志》：\"治瘰疬。\"","y":"内服：煎汤，0.5～1两；或捣汁和服。","d":"性状鉴别 茎方柱形，长20-70cm，直径1-4mm，单一或分枝；表面灰绿色或暗紫色，有白色长柔毛，以茎的上部及节处为多；质脆，易折断，折断面椭部白色或褐黄色。叶多卷曲，破碎，有时复叶脱落，仅见单叶，两面被白色柔毛，下面及叶脉上较明显，轮伞花序多轮，集成假总状，花冠二唇形，蓝紫色，多已脱落，宿萼筒外面脉上有毛，筒内喉部有长柔毛。小坚果椭圆形，褐色。气微，味微苦、涩。\n以叶多、色绿、带花者为佳。\n显微鉴别 叶横切面：上表皮细胞长方形，下表皮细胞较小，外被角质层，有气孔及毛茸。栅栏组织1-2列细胞，海绵组织4-5列细胞。主脉维管束外韧型，上下表皮内方均有厚角组织，维管束上下两侧可见纤维。\n茎横切面：呈四棱形。表皮细胞1列，外被角质层，可见毛茸。皮层外侧在四角棱处有4-6列厚角细胞；内皮层清晰。维管束外韧型，角隅处发达，韧皮部外侧有纤维2-4列，木质部连成环。髓部大。\n叶表面观：下表皮细胞垂周壁波状弯曲，呈连珠状增厚，具角质纹理；腺鳞头部4细胞，直径30-45μm，柄单细胞；小腺毛头部单细胞，直径18-23μm，柄短，单细胞；非腺毛多存在于叶脉处，1-11细胞，长72-1620μm，壁厚，具疣状突起，有时细胞缢缩；气孔直轴式。上表皮细胞垂周壁略弯曲，毛少，无气孔。"},"海麻雀":{"a":"?","s":"咸，温","f":"散结，消肿，解毒。用于淋巴腺肿大，咽喉肿痛，疮疔肿毒。","y":"?","d":"本品形状稍似麻雀，褐色或灰黄色，全体长 5～8厘米；嘴尖，眼骨突起；躯干宽扁，腹部扁平，背部有四条纵棱，另有4～5条弧形横纹与纵棱相交成瓦格形，尾部有纵棱4条，呈节状，方柱形，愈近尾端愈小。气腥，味咸。以完整、只大者为佳。"},"过江龙子":{"a":"木腰子,阴阳子","s":"苦辛；温 \n\n归肝；胃经","f":"理气止痛，活血散瘀。\n\n①《岭南采药录》：\"止气痛，理跌打伤，去瘀生新。\"\n\n②《生草药手册》：\"妇科消郁气痛，肝胃痛。\"","y":"1. 手把玩可治疗手凉手麻，长期把玩能预防心脑血管疾病，是不可多得的天然保健品． 　　\n\n2. 失眠多梦，小儿惊吓：成年人放入枕下，小儿放入枕中，有安神压惊之功效。 　　\n\n3. 风湿疼、关节疼、颈椎疼等各种疼症：过江龙子沾着高度白酒从上往下去刮，效果显著， 　　一天一次，晚间休息的时间刮效果最佳。 　　\n\n4. 便秘，肠胃炎症：七粒煮三斤水，煮开即可，一天二次，早晚各一杯，一 杯80毫升，可 　　煮三次。 　　\n5. 胃病（胃寒，胃胀，胃酸）把过江龙子打开取仁放入锅内小炒将其仁烘干碾成粉，温水 　　顺服（2两）即服见效，数月治愈。忌 酒，辛辣食物。 　　\n\n6. 痔疮：把过江龙子打开取仁放入锅内小炒将其仁烘干碾成粉和黄酒调匀，匀铺在沙布上 　　类似膏药状贴肚脐三天，三疗程即可，忌 酒，辛辣食物。 　\n　\n7. 顽固性风湿：七粒泡二斤酒，泡至稠状（用其筷能拉出丝状）即可服用，早晚各三钱。","d":"?"},"见血飞":{"a":"散血飞、黄椒(《贵州草药》)，刺三加，红三百棒(《陕西中草药》)。","s":"辛，温。\n\n①《贵州草药》：\"辛，温。\"\n\n②《陕西中草药》：\"涩辛，平。\"","f":"祛风散寒，活血舒筋，镇痛。治风寒咳嗽，风湿麻木，跌打损伤，外伤出血，大便秘结。\n\n①《贵州草药》：\"驱风，散寒。\"\n\n②《陕西中草药》：\"舒筋活血，止血，消肿，镇痛。治跌打损伤，外伤出血，瘀血肿痛。\"","y":"内服：煎汤，3～5钱；或研末冲服。外用：捣敷或研末撒。","d":"理化鉴别 薄层色谱：取本品粉末2g，加甲醇20ml，冷浸过夜，回收甲醇至成2ml作供试品溶液。另取木兰花碱，以甲醇溶解成每1ml含1mg的对照溶液。取上述两种溶液各约10μl点于同一硅胶H0.3％CMC板上，以氯仿-甲醇-氨水（15：4：1）展开，展距1.2cm。在紫外光灯（254nm）下观察，供试品色谱中在与对照品色谱相应的位置上显相同的亮蓝色斑点，喷雾改良碘化铋钾试剂显橙红色。"},"苦碟子":{"a":"满天星、苦荬菜","s":"味苦；辛；性平\n\n①《内蒙古中草药》：\"苦，寒。\"\n\n②苦辛，平。","f":"清热解毒，排脓，止痛。治阑尾炎，肠炎，痢疾，各种化脓性炎症，吐血，衄血，头痛，牙痛，胸、腹痛，黄水疮，痔疮。\n\n①《内蒙古中草药》：\"清热解毒，凉血，活血，排脓，治阑尾炎，肠炎，痢疾，疮疖痈肿，吐血，衄血。\"\n\n②止痛。治头痛，牙痛，胸痛，胃、腹痛，外伤疼痛以及中、小手术后疼痛。(辽宁)","y":"内服：煎汤，3～5钱；或制成片剂，1～2片。外用：煎水熏洗或研末调敷。","d":"理化鉴别 取本品粉末5g，加70%乙醇液35ml，浸渍30min，回流加热30min，趁热滤过，滤液在水浴上蒸干，残渣加水10ml，煮沸，趁热滤过，滤液用石油醚（60-90℃）适量除去色素，水液再用乙酸乙酯10ml提取，提取液置水浴上蒸干，残渣用95%乙醇6ml溶解，供下述试验：①取乙醇提取液1ml，加少量镁粉，加工厂浓盐酸5滴，沸水浴上加热3min，溶液由黄变到橙色。（检查黄酮类成分）②取乙醇提取液，用毛细管点于滤纸上，在紫外灯下观察显灰蓝色荧光，点加3%碳酸钠溶液后，斑点显黄色，在紫外灯下观察，显亮黄色荧光。"},"过江龙":{"a":"蒲地虎、地蜈蚣(《滇南本草》)，地刷子(《中国中部植物》)，伸筋草、扁心草(《贵州民间方药集》)，小伸筋、木金草、公鱼秧草、风尾草、马尾松(《湖南药物志》)，猴子草、猴子尾巴、舒筋草、乌龙不过江、过山龙、扫天晴明草、扁叶石松(《云南中草药》)。","s":"【性味】①《滇南本草》：\"性大温，味辛。\"\n\n②《云南中草药》：\"辛，微温。\"\n\n辛，微温。\"\n\n入脾肺经。","f":"疏风胜湿，舒筋活络，利尿，散瘀。治湿痹麻木不仁，筋骨疼痛，淋病，跌打损伤。\n\n①《滇南本草》：\"行周身经络，发散风寒湿气。治手足湿痹，不仁麻木，湿气流痰，筋骨疼痛，或打伤筋骨，误伤经络。能强筋舒筋，活络定痛。\"\n\n②《贵州民间方药集》：\"治肺咳。\"\n\n③《四川中药志》：\"治月经不调及脚转筋。\"\n\n④《湖南药物志》：\"利尿，舒筋。\"","y":"内服：煎汤，1.5～3钱；或浸酒。","d":"?"},"草苁蓉":{"a":"金笋、地精、肉松蓉、苁蓉、不老草","s":"味甘；咸；性温","f":"补肾壮阳，润肠，止血。治肾虚阳痿，腰膝冷痛，老年习惯性便秘，膀胱炎。\n\n①《长白山药用植物调查》:\"滋阴补阳，止血。治膀胱炎，膀胱出血及肾脏出血。\"\n\n②《吉林中草药》:\"补肾壮阳，润肠通便。治肾虚阳痿，腰膝冷痛，肠燥便秘，膀胱炎，\"","y":"内服:煎汤，0.5～1两；或浸酒。","d":"1.性状鉴别茎肉质，长圆柱形，有时稍扁，略弯曲，长3-15cm，直径5-15cm，向上渐细，直径2-5cm，有的切成段，上下直径相近。表面灰棕色或棕褐色，有纵沟，密被覆瓦状排列的肉质鳞叶，鳞叶菱形或三角形，宽0.5-1.5cm，厚约2mm，尚可见鳞叶脱落后留下的弯月形叶迹。质坚实，不易折断。断面棕色，有淡棕色维管束小点，环列成深波状或锯齿状。木部约占4/5，有时中空。表面和断面在光亮处有时可见结晶样小亮点。气微，味甜，略苦。 　　以条粗壮、密生鳞叶、质柔润者为佳。 　　\n显微鉴别茎横切面：表皮为1列扁平细胞，外被角质层。皮层由数十列薄壁细胞组成，排列紧密，近维管束处的细胞具纹孔，散有叶迹维管束。维管束处韧型，常16-22个排列成深波状或锯齿状圆环；韧皮部薄壁细胞排列紧密，有时产分成颓废状；形成层不甚明显；木质部可见非木化纤维。射线明显。髓部多分形。皮层及髓部薄壁细胞含淀粉粒。 　　鳞叶横切面：上下表皮细胞各1列，扁长方形，外被薄角质层。下皮细胞1列，稍大。叶肉组织均为海绵组织，细胞类圆形，壁薄，含叶绿体，细胞间隙小。维管束5-7，外韧型，切向排列。"},"野菊花":{"a":"山菊花,千层菊,黄菊花","s":"苦辛，凉。\n\n①《本草汇言》：\"味苦辛，气凉，有小毒。\"\n\n②《四川中药志》：\"性微寒，味甘苦，无毒。\"\n\n归肺；肝经 \n\n《本草求真》：\"入肺、肝。\"","f":"疏风清热，消肿解毒。治风热感冒，肺炎、白喉，胃肠炎：高血压，疔，痈，口疮，丹毒，湿疹，天泡疮。\n\n①《本草汇言》：\"破血疏肝，解疔散毒。主妇人腹内宿血，解天行火毒丹疔。洗疮疥，又能去风杀虫。\"\n\n②《现代实用中药》：\"用于痈疽疔肿化脓病。\"\n\n③《苏州本产药材》：\"解毒疏风。治目疾眩晕。\"\n\n④《浙江中药手册》：\"排脓解毒，消肿止痛。治痈肿疔毒，天泡湿疮。\"\n\n⑤《江苏植药志》：\"治霍乱，腹痛。\"\n\n⑥《山西中药志》：\"疏风热，清头目，降火解毒。治诸风眩晕，头痛，目赤，肿毒。\"\n\n⑦《江西草药》：\"治白喉，口疮，小儿高热抽搐等症。\"\n\n⑧《上海常用中草药》：\"治高血压。\"","y":"内服：煎汤，2～4钱(鲜者1～2两)。外用：捣敷，煎水漱口或淋洗。","d":"性状鉴别 （1)野菊花 头状花序类球形，直径1.5-2.5cm，棕黄色。总苞片4-5层，外层苞片卵形或卵状三角形，长2.5-3mm，外表面中部灰绿色或淡棕色，常被有白毛，边缘膜质；中层苞片卵形；内层苞片长椭圆表。总苞基部有的残留总花梗。舌状花1轮，黄色，皱缩卷曲，展平后，舌片长1-1.3cm，先端全缘或2-3齿；筒状花多数，深黄色。气芳香，味苦。\n（2)岩香菊花 头状花序直径1-1.5cm；总苞片4-5层，外层苞片线形或线状长圆形，长2.5mm；中内层苞片卵形、长椭圆形至倒披针形。舌状花黄色，舌片椭圆形，长5-7.5mm。\n均以完整、色黄、气香者为佳。\n显微鉴别 野菊花粉末特征：黄棕色。①花粉粒黄色，类圆形，直径20-33μm，每裂片4-5刺。②腺毛头部鞋底形，4-6（-8)细胞，两面相对排列，长径35-120μm，短径33-67μm，外被角质层。③T形毛较多，顶端细胞长大，壁一长一短，直径23-50μm，壁稍厚或一边稍厚，基部1-13细胞，其中一个稍膨大或皱缩。"},"丝瓜根":{"a":"?","s":"甘，平。\n\n①《岭南采药录》：\"味甘，性寒。\"\n\n②《重庆草药》：\"味甘微苦，性平，无毒。\"","f":"活血，通络，消肿。治偏头痛，腰痛，乳腺炎，喉风肿痛，肠风下血，痔漏。\n\n①《分类草药性》：\"治脑漏，痔疮，蛇伤。\"\n\n②《重庆草药》：\"通经络，行血，消肿胀，下乳。治乳房肿痛，腰背胀痛。\"","y":"内服：煎汤，1～3钱(鲜者1～2两)；或烧存性研未。外用：煎水洗或捣汁涂。","d":"?"},"杏仁":{"a":"杏核仁、杏子、木落子、苦杏仁、杏梅仁、杏、甜梅","s":"苦，温，有毒。\n\n\n①《本经》：\"味甘，温。\"\n\n\n②《别录》：\"苦，冷利，有毒。\"\n\n\n③《本草正》：\"味苦辛微甘。\"\n\n\n入肺、大肠经。\n\n\n①《汤液本草》：\"入手太阴经。\"\n\n\n②《滇南本草》：\"入脾、肺二经。\"\n\n\n③《雷公炮制药性解》：\"入肺、大肠二经。\"","f":"祛痰止咳，平喘，润肠。治外感咳嗽，喘满，喉痹，肠燥便秘。\n\n\n①《本经》：\"主咳逆上气雷鸣，喉痹，下气，产乳金疮，寒心奔豚。\"\n\n\n②《本草经集注》：\"解锡、胡粉毒。\"\n\n\n③《别录》：\"主惊痫，心下烦热，风气去来，时行头痛，解肌，消心下急，杀狗毒。\"\n\n\n④《药性论》：\"治腹痹不通，发汗，主温病。治心下急满痛，除心腹烦闷，疗肺气咳嗽，上气喘促。入天门冬煎，润心肺。可和酪作汤，益润声气。宿即动冷气。\"\n\n\n⑤崔禹锡《食经》：\"理风噤及言吮不开。\"\n\n\n⑥《医学启源》：\"除肺中燥，治风燥在于胸膈。《主治秘诀》云，润肺气，消食，升滞气。\"\n\n\n⑦《滇南本草》：\"止咳嗽，消痰润肺，润肠胃，消面粉积，下气，治疳虫。\"\n\n\n⑧《纲目》：\"杀虫，治诸疮疥，消肿，去头面诸风气鼓疱。\"","y":"内服：煎汤，1.5～3钱，或入丸、散。外用：捣敷。","d":"干燥种子，呈心脏形略扁，长1～1.5厘米，宽约1厘米左右，顶端渐尖，基部钝圆，左右不对称。种皮红棕色或暗棕色，自基部向上端散出褐色条纹，表面有细微纵皱;尖端有不明显的珠孔，其下方侧面脊棱上，有一浅色棱线状的种脐，合点位于底端凹入部，自合点至种脐，有一颜色较深的纵线，是为种脊，种皮菲薄，内有乳白色肥润的子叶两片，富于油质，接合面中间，常有空隙，胚根位于其尖端，味苦，有特殊的杏仁味。以颗粒均匀、饱满肥厚、味苦、不发油者为佳。\n\n\n主产东北、华北各省。\n\n\n除上述品种外，以下两种同属植物的种子亦同等使用。其形态特点：\n\n\n①西伯利亚杏\n\n\n叶片卵形或阔卵形，叶基部圆形或稍狭，边缘具细钝齿，背面脉腋常具有白色柔毛。花梗极短或缺如。核果球形，果肉薄，直径约2厘米，成熟时开裂。分布东北、内蒙古、河北、山西。\n\n\n②辽杏\n\n\n大部分的特征与杏相同，但其叶基部很少呈心形，边缘有粗而深锐的重锯齿，花梗一般较萼筒为长，无毛。核边缘圆钝。分布东北。\n\n\n杏仁有甜、苦之分，栽培杏所产者甜的较多，野生的一般均为苦的。从原植物来看，西伯利亚杏、辽杏及野生山杏的杏仁为苦杏仁，而杏及山杏的栽培种的杏仁有些是苦杏仁，有些是甜杏仁。"},"洋虫":{"a":"九龙虫","s":"味辛；甘；性温 \n\n《纲目拾遗》：\"性温。\"\n\n归肺；胃；大肠经","f":"活血祛瘀，温中理气。治劳伤咳嗽，吐血，中风瘫痪，跌打损伤，心胃气痛，噎膈反胃。\n\n①《药性考》：\"活吞数枚，止血，(治)劳怯。\"\n\n②《纲目拾遗》：\"行血分，暖脾胃，和五脏，健筋骨，去湿搜风，壮阳道，治怯弱。\"\"治老人不寐，茯苓引；小儿夜啼，朱砂引；女童夜溺，枸杞引；少妇阴寒，附子引；痈疽发背，沉香末引；舌燥作渴，麦冬引；眼目闭痛，甘草引；耳鸣耳聋，当归引；感冒风寒，防风引；中湿瘟毒，苍术引；跌打损伤，全蝎引；酒醉伤人，葛花引；怒气伤人，沉香引；绞肠痧痛，青蒿引。以上诸症，俱用虫十四个，好陈酒冲服。\"","y":"内服：生吞、研末或入丸剂。外用：捣敷。","d":"?"},"蟾酥":{"a":"蟾蜍眉脂、蟾蜍眉酥、癞蛤蚂浆、蛤蟆酥、蛤蟆浆","s":"味甘辛，性温，有毒。归心经。\n\n①《纲目》：\"甘辛，温，有毒。\"\n\n②《本草正》：\"味辛麻，性热，有毒。\"\n\n③《本草汇言》：\"味辛苦烈，气热，有毒。\"","f":"解毒，消肿，强心，止痛。治疔疮，痈疽，发背，瘰疬，慢性骨髓炎，咽喉肿痛，小儿疳积，心衰，风、虫牙痛。\n\n①《药性论》：\"脑疳，以奶汁调滴鼻中。\"\n\n②《日华子本草》：\"治蚛牙，和牛酥摩；治腰肾冷，并助阳气，以吴茱萸苗汁调敷腰眼并阴囊。\"\n\n③《本草衍义》：\"齿缝中血出，以纸紝子蘸干蟾酥少许，于血出处按之。\"\n\n④《医学入门》：\"主痈疽疔肿瘰疬，一切恶疮顽癣。\"\n\n⑤《纲目》：\"治发背疔疮，一切恶肿。\"\n\n⑥《本草正》：\"治风、虫牙痛，以纸拈蘸少许点齿缝中。\"","y":"外用：研末调敷或掺膏药内贴患处。内服：0.5～1厘，多入丸、散用。","d":"干燥的蟾酥呈扁圆形团块状、饼状、棋子状或片状。表面光亮，有的不平而具有皱纹，淡黄色、紫红色或棕黑色。团块状或饼状者质坚硬，不易折断，断面茶褐色，如胶质状而有光泽。片状者质脆易折断，红棕色，半透明。气微腥，嗅之作嚏，味麻辣。遇水即起泡沫，并泛出白色乳状液；用锡纸包碎块少许，烧之即熔为油状。以质明亮、紫红色、断面均一、沾水即泛白色者为佳。\n产河北、山东、四川、湖南、江苏、浙江等地。此外，辽宁、湖北、新疆亦产。"},"葛花":{"a":"葛条花","s":"甘，凉。\n\n①《滇南本草》：\"性微寒，味甘平微苦。\"\n\n②《纲目》：\"甘，平，无毒。\"\n\n③《医林纂要》：\"甘，寒。\"\n\n归胃经\n\n《得配本草》：\"入足阳明经。\"","f":"解酒醒脾。治伤酒发热烦渴，不思饮食，呕逆吐酸，吐血，肠风下血。\n\n①《别录》：\"消酒。\"\n\n②《滇南本草》：\"治头晕，憎寒，壮热，解酒醒脾，酒痢，饮食不思，胸膈饱胀，发呃，呕吐酸痰，酒毒伤胃，吐血，呕血，消热。\"\n\n③《纲目》：\"治肠风下血。\"\n\n④《医林纂要》：\"清肺。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。","d":"干燥花蕾呈不规则的扁长圆形或略成扁肾形，长5～15毫米，宽2～6毫米，厚2～3毫米。萼片灰绿色，基部连合，先端5齿裂，裂片披针形，其中2齿合生，表面密被黄白色毛茸。基部有两片披针钻形的小苞片。花瓣5片等长，突出于萼外或被花萼包被，蓝紫色，外部颜色较浅，呈淡蓝紫色或淡棕色。雄蕊10枚，其中9枚连合，雌蕊细长，微弯曲，外面被毛。气微弱，味淡。以朵大、淡紫色、未开放者为佳。\n主产湖南、河南、广东、广西、浙江、四川、安徽等地。"},"走马胎":{"a":"大发药(《陆川本草》)，走马风(《广西中药志》)，山鼠、血枫(《广西中草药》)，山猪药(海南)。","s":"辛，温。\n\n\n\n①《生草药性备要》：\"味劫辛，性温。\"\n\n\n\n②《岭南采药录》：\"味辛，性温。\"\n\n\n\n③《陆川本草》：\"甘，平。\"","f":"祛风湿，壮筋骨，活血祛瘀。治风湿筋骨疼痛，跌打损伤，产后血瘀，痈疽溃疡。\n\n\n\n①《生草药性备要》：\"祛风痰，除酒病。治走马风。\"\n\n\n\n②《纲目拾遗》：\"研粉敷痈疽，长肌化毒，收口。\"\n\n\n\n③《本草求原》：\"壮筋骨，已劳倦。\"\n\n\n\n④《岭南采药录》：\"理跌打伤，止痛，治四肢疼痛，俱水煎服。\"\n\n\n\n⑤《陆川本草》：\"祛风湿，治风湿骨痛，风瘫鹤膝。\"\n\n\n\n⑥《广西中药志》：\"活血行血。治产后血瘀。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)；或浸酒。外用：研末调敷。","d":"干燥根茎呈圆柱形，常膨大呈念珠状，径1.5～4厘米，表面灰褐色至暗紫色，有纵向沟纹，皮部易剥离，厚约2毫米。质坚硬，断面皮部淡紫红色，有紫色小窝点，木部白色。加工的切片，斜切呈长椭圆形，厚约2毫米，皮部与木部分离，木射线清晰。有时掺入茎基部的切片，中央有淡红紫色的髓部。以干燥，念珠状、皮色紫褐多皱缩、断面有菊花纹者为佳。\n\n产广西、广东等地。"},"皮蛋":{"a":"皮蛋(《随息居饮食谱》)，彩蛋、松花蛋(江苏)。","s":"《医林篆要》：\"味辛涩甘咸，寒。\"","f":"《医林纂要》：\"泻肺热，醒酒，去大肠火，治泻痢。能散、能敛。\"","y":"?","d":"?"},"金刚刺":{"a":"金刚藤(《陕西中草药》)。","s":"《陕西中草药》：\"味苦辛，性平。\"","f":"《陕西中草药》：\"除风湿，活血，解毒，镇惊息风，抗癌。治风湿腰腿痛，小儿惊风，肠炎，疮疖，瘰疬，癌肿。\"","y":"内服：煎汤，2～3钱(大剂可用至一两)；或浸酒。外用：研粉、磨汁调敷或煎水洗。","d":"?"},"红孩儿":{"a":"石莲、红天葵、虎斑海棠、半边莲、九齿莲、红莲(《广西药植名录》)，岩红(《云南中草药选》)。","s":"《陆川本草》：\"甘，寒。\"","f":"治感冒咳嗽，风湿骨痛，腰痛，消化不良，跌打肿痛，疔疮。\n\n①《植物名实图考》：\"治腰痛。\"\n\n②《陆川本草》：\"叶：消炎解毒。治疔疮，痈肿，小便淋沥，蛇咬伤。\"\n\n③《广西药植名录》：\"全株：治风湿骨痛，肚痛，消化不良。根：治吐血。\"\n\n④《云南中草药选》：\"清热解毒，润肺止咳，散瘀消肿。治感冒，急性支气管炎，肺炎。\"","y":"内服：熬汤，2～3钱。外用：捣敷。","d":"?"},"铁包金":{"a":"乌龙根、勾儿茶、乌口仔、小叶铁包金、假榄仔(《广东中药》)，细纹勾儿茶(广州部队《常用中草药手册》)。","s":"苦，平。\n\n①《岭南采药录》：\"味苦，性温。\"\n\n②《福建民间草药》：\"微苦，平，无毒。\"\n\n③广州部队《常用中草药手册》：\"甘淡，平。\"","f":"化瘀血，祛风湿，消肿毒。治肺痨久咳，喀血，吐血，跌打损伤，风湿疼痛，痈肿，荨麻疹。\n\n①《岭南采药录》：\"解蛇毒，理恶疮，捣敷之；理跌打伤，能驳骨止痛；治小肠气痛，水煎服。\"\n\n②《福建民间草药》：\"祛风湿，解毒。治鼠疣，痔疮，脱肛，乳痈，风湿痛，风毒流注。\"\n\n③《岭南草药志》：\"能化瘀，治咯血，咳血。\"","y":"内服：煎汤，1～3两。外用：捣敷或煎水洗。","d":"干燥根圆柱状，粗细不一，商品多锯成小段或切成厚片。栓皮结实，黑褐色或棕褐色，有网状裂隙及纵皱。质坚硬，断面本部甚大，质纹细致，暗黄棕色至橙黄色。\n产广东、福建等地。\n\n此外，尚有一种大叶铁包金，为同属植物牛鼻拳的根，在广东同等入药，药材性状相类。参见\"勾儿茶\"条。"},"洋葱":{"a":"球葱、圆葱、玉葱、葱头，荷兰葱","s":"性温，味辛甘","f":"有祛痰、利尿、健胃润肠、解毒杀虫等功能。可治食欲不振、大便不畅、痢疾、肠炎、虫积腹痛、创伤溃疡、赤白带下等病症。\n\n\n《药材学》：\"新鲜的捣成泥剂，治疗创伤、溃疡及妇女滴虫阴道炎。\"","y":"内服：生食或烹食，1～2两。外用：捣敷或捣汁涂。","d":"?"},"莲花":{"a":"菡萏、荷花、水花、芙蓉","s":"苦，甘，温。归心，肝经。\n\n①《日华子本草》：\"暖，无毒。\"\n\n②《纲目》：\"苦甘，温，无毒。\"\n\n③《本草再新》：\"味苦甘，性凉，无毒。\"","f":"活血止血，去湿消风。主损伤呕血；血淋；崩漏下血；天泡湿疮；疥疮瘙痒 \n①《日华子本草》：\"镇心，益色驻颜。\"\n\n②《日用本草》：\"涩精气。\"\n\n③《滇南本草》：\"治妇人血逆昏迷。\"\n\n④《本草再新》：\"清心凉血，解热毒，治惊痫，消湿去风，治疮疥。\"\n\n⑤《河北药材》：\"揉碎贴肿毒，促脓肿之吸收。\"\n\n⑥《山东中药》：\"活血祛瘀。\"","y":"内服：研末，0.5～1钱；或煎汤。外用：敷贴患处。","d":"干燥花蕾呈圆锥形，长2.5～4厘米，直径约2厘米。表面灰棕色。花瓣多层，呈螺旋状排列；散落的花瓣呈卵圆形或椭圆形，略皱缩或折叠，表面有多数细筋脉，基部略厚；质光滑柔软。去掉花瓣，中心为幼小的莲蓬，顶端圆而平坦，上有小孔10余个，基部渐窄，周围着生多数花蕊。花柄呈细圆柱状，上有皱沟或顺纹，表面紫黑色，具刺状突起，断面有大型孔隙。微有香气，味苦涩，以未开放、瓣整齐、洁净、气清香者为佳。\n全国大部分地区均产。"},"山芝麻":{"a":"岗油麻、岗脂麻、田油麻、仙桃草、野芝麻、狗屎树、假芝麻、山麻、假油麻、芝麻头、牛釜尾、山野麻、白头公、油麻甲、野麻甲、假麻甲、苦麻、山脂麻、被油麻、坡片公。","s":"辛微苦，凉。\n\n①《岭南采药录》：\"味苦，性凉。\"\n\n②《福建民间草药》：\"甘，寒，无毒。\"\n\n③《南宁市药物志》：\"辛微苦，凉。\"\n入胃经","f":"解表清热，消肿解毒。治感冒发热、头痛，口渴，痄腮，麻疹，痢疾，肠炎，痈肿，瘰疬，疮毒，湿疹，痔疮。\n\n①《生草药性备要》：\"根：治疮，去毒，止血，埋口；又能开大肠，食多大便必快。\"\n\n②《广州植物志》：\"叶：捣烂敷患处，治疮毒。\"\n\n③《福建民间草药》：\"去瘀生新，消痈解毒。\"\n\n④《南宁市药物志》：\"解表清热，治痧气，热性感冒，毒疮。\"\n\n⑤《泉州本草》：\"清热止渴，祛痰止咳。治肺病，瘰疬。\"","y":"内服：煎汤，3～6钱(鲜者1～2两)。外用：捣敷。","d":"理化鉴别 取本品粗粉5g，加水50ml，煮沸，滤过。滤液加羟胶一三氯化铁试液，发生紫褐色沉淀（检查酯类）；滤液加2，4-二硝基苯肼试液，发生黄棕色沉淀。（检查羰基化合物）。"},"半边莲":{"a":"急解索(《纲目》)，蛇利草(《岭南采药录》)，细米草(《中国药植志》)，蛇舌草(《福建民间草药》)，鱼尾花(《江西中药》)，半边菊、半边旗(《广西中药志》)，奶儿草、半边花(《浙江民间草药》)，箭豆草(《四川中药志》)，顺风旗、单片芽(《岭南草药志》)，小莲花草、绵蜂草、吹血草，腹水草、疳积草、白腊滑草、金菊草(《湖南药物志》)，金鸡舌(《闽东本草》)，片花莲、偏莲、瓜仁草(《江西民间草药验方》)，蛇啄草(《上海常用中草药》)。","s":"甘，平。\n\n①《纲目》：\"辛，平，无毒。\"\n\n②《生草药性备要》：\"味甜，性平。\"\n\n③《本草求原》：\"甘淡，平。\"","f":"利水，消肿，解毒，治黄疸，水肿，臌胀，泄泻，痢疾，蛇伤，疔疮，肿毒，湿疹，癣疾，跌打扭伤肿痛。用于大腹水肿、面足浮肿、痈肿疔疮、蛇虫咬伤、晚期血吸虫病腹水。\n\n①《纲目》：\"治蛇虺伤，捣汁饮，以滓围涂之。\"\n\n②《生草药性备要》：\"敷疮，消肿毒。\"\n\n③《岭南采药录》：\"治鱼口便毒，跌打伤瘀痛，恶疮，火疮，捣敷之。\"\n\n④《中国药植志》：\"治血吸虫病腹水。\"\n\n⑤《福建民间草药》：\"清热解毒，利尿消肿。\"\n\n⑥《陆川本草》：\"解毒消炎，利尿，止血生肌。治腹水，小儿惊风，双单乳蛾，漆疮，外伤出血，皮肤疥癣，蛇蜂蝎伤。\"\n\n⑦《南宁市药物志》：\"消肿解毒。治疳积和疔疮初起。\"\n\n⑧《中国药植图鉴》：\"煎服治风湿性神经痛，头晕。\"","y":"内服：煎汤，0.5～1两；或捣汁服。外用：捣敷或捣汁调涂。","d":"干燥带根全草，多皱缩成团。根细长，圆柱形，带肉质，表面淡棕黄色，光滑或有细纵纹，生有须根。茎细长多节，灰绿色，靠近根茎部呈淡紫色，有皱缩的纵向纹理，节上有时残留不定根。叶互生，狭长，表面光滑无毛，多皱缩或脱落。花基部筒状，花瓣5片。臭微，有刺激性，味初微甘，后稍辛辣。以干燥、叶绿、根黄、无泥杂者为佳。\n\n主产安徽、江苏、浙江。此外，广东、广西、江西、四川等地亦产。"},"小黑药":{"a":"铜脚威灵仙、叶三七。","s":"甘微苦，温。\n\n归肺；肾经","f":"补肺益肾。治肺结核，肾虚腰痛，头昏。","y":"内服：煎汤，3～5钱。","d":"?"},"天葵子":{"a":"紫背天葵子,千年老鼠屎,金耗子屎,千年耗子屎,地丁子,天去子,野乌头子,鸡腿,散血珠,天葵根","s":"甘苦，寒。\n\n①《滇南本草》：\"性寒，味苦辛。\"\n\n②《本草求原》：\"甘淡，平。\"\n\n③《浙江民间草药》：\"性寒，味酸，有毒。\"\n\n入脾，小肠、膀胱三经\n\n《四川中药志》：\"入脾，小肠、膀胱三经。\"","f":"清热，解毒，消肿，散结，利尿。治痈肿，瘰疬，疔疮，淋浊，带下，肺虚咳嗽，疝气，癫痫，小儿惊风，痔疮，跌打损伤。毒蛇咬伤。\n\n①《滇南本草》：\"散诸疮肿，攻痈疽，排脓定痛，治瘰疬，消散结核，治妇人奶结，乳汁不通，红肿疼痛，乳痈，乳岩坚硬如石，服之或散或溃。\"\n\n②《百草镜》：\"清热，治痈疽肿毒，疔疮，跌扑，疯犬伤，疝气，痔疮，劳伤。\"\n\n③《本草求原》：\"主内伤痰火，消瘰疬恶疮，浸酒佳。\"\n\n④《贵州民间方药集》：\"消炎，明目，去眼翳；又可驱风，表寒，治小儿惊风及母猪疯。\"\n\n⑤《贵阳民间药草》：\"清热解毒。治癫痫、蛇咬伤。\"\n\n⑥《四川中药志》：\"利水通淋，解毒。治尿酸结石，小便淋沥不清。\"\n\n⑦《贵州草药》：\"定惊，镇痛，平喘，解毒。\"\n\n⑧《陕西中草药》：\"治蛇、虫咬伤，跌打损伤，尿路结石，皮肤干燥。\"","y":"内服：煎汤，1～3钱；研末或浸酒。\n外用：捣敷或捣汁点眼。","d":"干燥块根多数为椭圆形、纺锤形，或呈圆柱形而扭曲，长1～3厘米，宽0.5～1厘米，外面暗褐色，表面粗糙，具不规则纵槽纹及横向线纹；块根顶端常有叶柄残基，外被数层黄褐色鞘状鳞片，有须根或须根痕。质较脆，断面较平坦，皮部类白色，木部黄色。气微弱，味先甘而后涩。以干燥、形大、外黑内白、无须根杂质者为佳。\n\n主产江苏、湖南、湖北。此外，安徽、广西、贵州、云南、江西、浙江等地亦产。"},"青天葵":{"a":"独叶莲、珍珠草、独脚莲、珍珠叶、坠千斤、铁帽子、山米子、天葵、入地珍珠、假天麻","s":"甘，凉。\n\n①《岭南采药录》：\"味甘，性和。\"\n\n②《陆川本草》：\"味淡辛麻，微温。\"\n\n③《南宁市药物志》：\"甘，凉，无毒。\"","f":"清热，润肺，散瘀，解毒。治肺痨，痰火咳血，瘰疬，肿毒，跌打损伤。\n\n①《岭南采药录》：\"治瘰疬，和肉煎汤服或炒食；理痰火咳血，消火疮，水煎服；浸酒治内伤。\"\n\n②《陆川本草》：\"止血，去瘀，治跌打损伤。\"\n\n③《南宁市药物志》：\"润肺止咳，解热清心。治肺痨，并解煤毒。\"\n\n④《广西中药志》：\"捣烂外涂，可解疮毒。\"\n\n⑤《云南思茅中草药选》：\"散瘀消肿，镇静止痛。治精神病，跌打损伤，结肿瘀痛。\"","y":"内服：煎汤，3～5钱；或浸酒。外用：捣敷。","d":"干燥叶呈灰褐色至灰绿色，卷成团粒状，叶柄扁平，有纵向条纹。广东产的商品，叶中多裹有球茎。以干燥、叶小、有香味者佳。\n产广西、广东等地。"},"竹叶":{"a":"淡竹叶(《别录》)。","s":"甘淡，寒。\n\n①《别录》：\"味辛平，大寒。\"\n\n②《药性论》：\"味甘，无毒。\"\n\n③《履巉岩本草》：\"苦，甘，微寒，无毒。\"\n\n④《本草正》：\"味甘淡，气平微凉。\"","f":"清热除烦，生津利尿。治热病烦渴，小儿惊痫，咳逆吐衄，面赤，小便短亦，口糜舌疮。\n\n①《别录》：\"主胸中痰热，咳逆上气。\"\n\n②《药性论》：\"主吐血热毒风，止消渴。\"\n\n③《食疗本草》：\"主咳逆，消渴，痰饮，喉痹，除烦热。\"\n\n④《日华子本草》：\"消痰，治热狂烦闷，中风失音不语，壮热，头痛头风，并怀妊人头旋倒地，止惊悸，温疫迷闷，小儿惊痫天吊。\"\n\n⑤张元素：\"凉心经，益元气，除热，缓脾。\"\n\n⑥《纲目》：\"煎浓汁，漱齿中出血，洗脱肛不收。\"\n\n⑦《本草正》：\"退虚热烦躁不眠，止烦渴，生津液，利小水，解喉痹，并小儿风热惊痫。\"\n\n⑧《重庆堂随笔》：\"内息肝胆之风，外清温署之热，故有安神止痉之功。\"\n\n⑨《本草再新》：\"凉心健脾，治吐血、鼻血，聪耳明目。\"","y":"内服：煎汤，2～4钱。","d":"?"},"鸭脚板草":{"a":"辣子草、野芹菜(《分类草药性》)。","s":"①《分类草药性》：\"性热，味苦，有毒。\"\n\n②《湖南药物志》：\"辛，有毒。\"","f":"治疟疾，瘿肿，毒疮，跌打损伤。\n\n①《分类草药性》：\"治一切恶疮，包鱼口，外治蛇咬。\"\n\n②《四川中药志》：\"治跌打损伤。\"\n\n③《重庆草药》：\"可以截疟。\"\n\n④《湖南药物志》：\"治瘿肿。\"","y":"外用：捣敷。","d":"?"},"零陵香":{"a":"熏草(《山海经》)，燕草(《南越志》)，蕙草(《别录》)，香草(《开宝本草》)，铃铃香、铃子香(《梦溪笔谈》)，黄零草(《庚辛玉册》)，熏香(《本草求真》)，陵草(《中药材手册》)。","s":"辛甘，温。\n\n①《别录》：\"味甘，平，无毒。\"\n\n②《药性论》：\"味苦，无毒。\"\n\n③《海药本》：\"味辛，温，无毒。\"","f":"祛风寒，辟秽浊。治伤寒、感冒头痛，胸腹胀满，下利，遗精，鼻塞，牙痛。\n\n①《别录》：\"主明目止泪，疗泄精，去臭恶气，伤寒头痛，上气，腰痛。\"\n\n②《药性论》：\"能治鼻中息肉、鼻齆。\"\n\n③《海药本草》：\"主风邪冲心，牙车肿痛，虚劳疳匿，凡是齿煮，煎含良。\"\n\n④《日华于本草》：\"治血气腹胀，酒煎服。\"\n\n⑤《开宝本草》：\"主恶气疰，心腹痛满，下气，和诸香作汤丸用之。\"\n\n⑥《广西中药志》：\"散风寒，辟瘟疫岚瘴。治时邪感冒头痛。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。外用：研末掺或煎水含漱。","d":"干燥全草，多扭曲不直，呈灰绿至紫棕绿色。表面有纵走线纹及3条棱翘，一侧常生有须状不定根。质脆，易折断，断面三角形，类黄白色。叶互生，有长柄，叶片卵形多皱折，基部楔形具翼，羽状网脉显著，类纸质。有时于叶腋处带有球形蒴果，类白色，果柄细长，长达3.5厘米，萼宿存，果皮薄，内藏多数细小的棕黑色种子，呈立体三角形。根须状，棕黑色。气芳香浓郁，味微苦。以茎叶嫩细、灰绿色、干燥、香气浓、无泥沙者为佳。\n产广西、广东及四川、云南、贵州等地。\n\n据《证类本草》濠州零陵香及《植物名实图考》的零陵香附图，均似唇形科植物罗勒或九层塔，但目前用罗勒作零陵香者，仅见于江浙地区。九层塔则仅在台湾及海南岛有分布。市售之零陵香商品主要为灵香草，该种与《证类本草》所载之蒙州零陵香相符。"},"老鹳草":{"a":"五叶草、老官草(《滇南本草》)，五瓣花、老贯草(《滇南本草图谱》)，天罡草(《分类草药性》)，五叶联、生扯拢、破铜钱(《贵州民间方药集》)，老鸹筋(《东北资源植物手册》)，贯筋(《新疆药材》)，五齿耙、老鸹嘴(《河北药材》)，鹌子嘴(《山东中药》)。","s":"苦辛，平。\n\n①《救荒本草》：\"味微苦。\"\n\n②《滇南本草》：\"性微温，味苦辛。\"","f":"祛风，活血，清热解毒。治风湿疼痛，拘挛麻木，痈疽，跌打，肠炎，痢疾。\n\n①《滇南本草》：\"祛诸风皮肤发痒。治筋骨疼痛，痰火痿软，手足筋挛，麻木，利小便，泻膀胱积热，攻散诸疮肿毒，退痨热发烧，治风火虫牙，痘疹疥癞等症。\"\n\n②《纲目拾遗》：\"去风，疏经活血，健筋骨，通络脉。治损伤，痹症，麻木，皮风，浸酒常饮。\"\n\n③《现代实用中药》：\"止久痢，厚肠胃，调中健脾。\"\n\n④《贵州民间方药集》：\"治跌打损伤，止刀伤出血，又可止咳，益肺气。\"\n\n⑤《药材学》：\"清热解毒。治热病消渴，痈疽疮肿。\"","y":"内服：煎汤，2～5钱；浸酒或熬膏。","d":"老鹤草的药材商品，主要可分为长嘴老鹳草和短嘴老鹤草两类，以长嘴老鹳草应用较广。\n\n①长嘴老鹳草\n为植物牻牛儿苗的干燥全草。多数不带根，长30～50厘米，或已截成长6～8厘米的小段。茎粗2～5毫米，节明显膨大，节间长5～12厘米，多分枝，表面灰绿色，基部或带紫红色，有纵纹，并被稀疏的白毛，质较坚脆，折断时粗纤维性，有空心。叶对生，有长柄，叶片卷曲皱缩，质脆易碎，润湿展平后，可见为羽状深裂，裂片很细。果实长圆形，长约6～10毫米，深黄棕色或暗紫色，有宿存的长花柱，通称\"长嘴\"，嘴长2.5～4厘米；成熟后5裂，各与1枚种子相连，并向外反卷或卷曲成螺旋形。?臭，味淡。以灰绿色、果实多、无根及泥土者为佳。\n主产于河北、山西、山东。此外，河南、陕西、辽宁、吉林、黑龙江、新疆等地亦产。\n\n②短嘴老鹳草\n为植物老鹳草、尼泊尔老鹳草、西伯利亚老鹳草等的干燥全草。茎较纤细，长约30厘米，直径约1～2毫米。节间短，多在5厘米以下。叶片裂片较宽。果实较小，花长3～5毫米，嘴长1～1.5厘米。其余与长嘴老鹳草同。无臭，味淡。以灰绿色、果实多、无根及泥土者为佳。\n主产于云南、四川、湖北。此外，东北及新疆等地亦产。"},"昏鸡头":{"a":"鸡脑壳(《草木便方》)，鸡公头、鸡头枣、鸡老盖(《分类草药性》)，铁狼鸡、小贯众(《贵州民间方药集》)，鸡头风尾、乌鸡儿、鸱头鸡(《民间常用草药汇编》)，小晕鸡头(《陕西中草药》)，大叶狼衣、地鸡头、凤凰衣、小叶贯众(金华《常用中草药单方验方选编》)，小鸡娃菜(《陕西草药》)。","s":"苦，微寒。\n\n①《四川中药志》：\"性微寒，味苦，有小毒。\"\n\n②成都《常用中草药治疗手册》：\"性平，味苦涩。\"\n入肝经","f":"清热解毒，凉血息风，散痰止血，驱钩、蛔、绦、蛲诸虫。治感冒，热病斑疹，痧秽中毒，疟，痢，肝炎，肝阳眩晕头痛，吐血便血，血崩，带下，乳痈，瘰疬，跌打损伤。\n\n①《分类草药性》：\"治一切虚损，妇女崩带，头昏耳聋。\"\n\n②《天宝本草》：\"清火解毒，除瘟症，红白痢症，赤白带下。\"\n\n③《贵州民间方药集》：\"补虚弱，消伤肿，接骨。治跌打损伤，活血逐瘀。\"\n\n④《民间常用草药汇编》：\"治盗汗。\"\n\n⑤《四川中药志》：\"治头昏头痛，血气胀痛。\"\n\n⑥成都《常用草药治疗手册》：\"息风，清利头目，凉血，养血，解毒，散瘀。治时行瘟疫，疟疾，瘰疬，疮疡肿毒，虫积腹痛。\"\n\n⑦《陕西中草药》：\"清热解毒，凉血，散瘀，降血压，杀虫。治高血压，头晕头痛；预防及治疗急性传染病，蛔虫、蛲虫症。\"\n\n⑧金华《常用中草药单方验方选编》：\"活血散瘀，止血，杀虫。治热病斑疹，肝炎，痢疾，吐血，便血，尿路感染，蛔虫，蛲虫，绦虫，刀伤出血，毒蕈中毒，预防流感。\"","y":"内服：煎汤，3～5钱。","d":"根茎短小，形如鸡头，黑褐色；长5～8厘米，粗3～4厘米。表面密被多数叶柄残基，并有棕黑色弯曲的细根，顶端部有红棕色微带光泽的鳞片。叶柄残基瘦小，断面呈四方形，维管束3～4个，气微，味淡。以根茎大、须根少者为佳。"},"紫苏梗":{"a":"紫苏茎(《雷公炮炙论》)，苏梗(《药品化义》)，紫苏杆(《湖南药物志》)。","s":"辛甘，微温。\n\n①《纲目》：\"辛，温，无毒。\"\n\n②《药品化义》：\"味甘微辛，性微温。\"\n\n③《本草崇原》：\"气味辛，平。\"","f":"理气，舒郁，止痛，安胎。治气郁，食滞，胸膈痞闷，脘腹疼痛，胎气不和。\n\n①《本草图经》：\"宣通风毒。\"\n\n②《本草蒙筌》：\"下诸气略缓，体稍虚者用宜。\"\n\n③《本草通玄》：\"能行气安胎。\"\n\n④《本草崇原》：\"主宽中行气，消饮食，化痰涎。治噎膈反胃，止心腹痛。\"\n\n⑤《得配本草》：\"疏肝，利肺，理气，和血，解郁，止痛，定嗽，安胎。\"","y":"内服：煎汤，1.5～3钱。","d":"老苏梗：呈方柱形，有槽。长0.3～1米，中部直径约0.7～1.3厘米。表面紫棕色或淡棕色。具纵沟及顺纹，上有稀疏的柔毛。分枝对生，或已除去。上部分枝常残留花萼或果实。质硬体轻，断面黄白色，中心有白色疏松的髓，或中空。嫩苏梗：色淡或青绿色，质松，髓部较大。以老而粗壮、外皮紫棕色、分枝少、香气浓者为佳。\n产湖北、江苏、河南、四川、广西、山东、广东、浙江、河北、山西等地。\n\n同属植物白苏的茎(白苏梗)在江苏、四川等地与紫苏梗同等使用，并通称为苏梗。参见\"白苏梗\"条。"},"香橼":{"a":"枸橼,西柠檬,西柠,香泡树，","s":"辛苦酸，温。\n\n①陶弘景：\"温。\"\n\n②《本草拾遗》：\"味辛酸，性温。\"\n\n③《饮膳正要》：\"味酸甘，平，无毒。\"\n\n④《本草通玄》：\"苦酸辛，温。\"","f":"理气，舒郁，消痰，利膈。治胃痛胀满，痰饮咳嗽气塑，呕哕少食。\n\n①《本草拾遗》：\"去气，除心头痰水。\"\n\n②《饮膳正要》：\"下气，开胸膈。\"\n\n③《本草通玄》：\"理上焦之气，止呕逆，进食，健脾。\"\n\n④《本经逢原》：\"治咳嗽气壅。\"\n\n⑤《医林纂要》：\"治胃脘痛，宽中顾气，开郁。\"\n\n⑥《本草再新》：\"平肝舒郁，理肺气，通经利水，治腰脚气。\"\n\n⑦《本草求原》：\"除久哮。\"","y":"内服：煎汤，1～2钱；或入丸、散。","d":"①枸橼\n完整的果实，呈长椭圆形或卵圆形，顶端有乳状突起，表面黄色或绿黄色。商品多已横切成片，切片厚2～3毫米，直径5～10厘米。切开面淡黄色，表面粗糙，有皱缩不规则的网纹凸起，果皮部分较宽，约有2～3.5厘米，占果片横断面的1/2；中央瓤囊12～16室，宽3～5厘米，每室成三角形，室内有时残阳种子飞～2枚；果实中心柱坚实，直径0.8～2厘米；外侧边缘的果皮黄色或绿黄色，表面不规则皱缩，散有多数凹入的油点。质柔软，气芳香，味初甜而后酸苦。\n主产云南、四川等地。\n\n②香圆\n干燥果实，呈球形或矩圆形，直径5～6.5厘米。表面黄棕色或黄绿色，常具有大小不规则的黄白色斑块，并密布多数油点及网状隆起的粗皱纹，顶端凹入，基部呈环状，有果柄痕。横断面果皮为淡黄白色，厚3～8毫米；中央有瓤囊10～12室，每瓤囊内有种子数枚。商品有时纵切成大小不等的瓣状，或横切为二半，除去瓤肉，或偶有瓤肉残留。气香，味酸而苦。\n主产浙江、江苏等地。\n\n古代《本草》所载的香橼多指枸橼而言，有时包括佛手在内。但目前商品香橼的来源，有枸橼与香圆二种，且产量以后者为大，使用亦较广。其幼果及近成熟果实，在少数地区亦作枳实、枫壳入药。"},"灯盏细辛":{"a":"地顶草、灯盏花(《云南中草药》)，地朝阳、双葵花、东菊(《云南中草药选》)。","s":"①《云南中草药》：\"甘，温。\"\n\n②《云南中草药选》：\"辛，微温。\"\n\n归肺；胃经。","f":"散寒解表，活血舒筋，止痛，消积。治感冒头痛鼻塞，风湿痹痛，瘫痪，急性胃炎，小儿疳积，跌打损伤。\n\n①《广西药植名录》：\"治小儿头疮。\"\n\n②《云南中草药》：\"发表散寒，健脾消积，消炎止痛。\"\n\n③《云南中草药选》：\"散寒解表，止痛，舒筋活血。治牙痛，急性胃炎，高热，跌打损伤，风湿痛，胸痛，疟疾，小儿麻痹后遗症，脑炎后遗症之瘫痪，血吸虫病。\"","y":"内服：煎汤，3～5钱；或蒸蛋。外用：捣敷。","d":"全草含焦迈康酸（pyromeconic acid），飞蓬甙（双称灯盏细辛甙）（erigeroside）[1，2，4，5，6，7-四羟基黄酮-7-O-β-D-吡喃葡萄糖酣酸甲酯甙（4，5，6，7-tetrahydroxyflavone-7-O-β-D-glucronopyranoside methyl ester）[3]，芹菜素（apigenin），高山黄芩素（scutellarein），大波斯菊甙（cosmosiin），芹菜素-7-O-葡萄糖糖酣酸甙（灯盏花甲素）（apigenin-7-O-glucronide），车前黄酮甙（plantaginin）和高山黄芩素-7-O-葡萄糖酣酸甙（灯盏花乙素）（scutellarein-7-O-glucronide），其中以前者为主含少量芹菜素-7-O-葡萄糖酣酸甙的混合物命名为灯盏花素（breviscapine）[4]。"},"铁树果":{"a":"凤凰蛋(《植物名实图考》)。","s":"苦涩，平。有毒。\n\n①《现代实用中药》：\"苦，平，酸涩，无毒。\"\n\n②《陆川本草》：\"味淡，性寒。\"","f":"①《现代实用中药》：\"为收敛剂，通经，助消化，镇咳祛痰。果实内的淀粉，治痢疾及呃逆。\"\n\n②《陆川本草》：\"消炎，止血。治痰多咳嗽，痢疾，刀伤，跌打。\"","y":"内服：煎汤，3～5钱；或研末。外用：研末敷。","d":"?"},"眼镜蛇":{"a":"膨颈蛇(薛德焴《系统动物学》)，蝙蝠蛇、五毒蛇、扁头风、琵琶蛇(《脊椎动物分类学》)，吹风蛇、吹风鳖、饭铲头、饭匙头、万蛇(《广西中药志》)。","s":"味甘咸，性温，有毒。","f":"通经络，祛风湿。治风湿关节痛，脚气。(性味以下出《广西中药志》)","y":"内服：浸酒(蛇半斤浸酒三斤)。","d":""},"杉木油":{"a":"杉树油、杉木脂、杉树脂","s":"苦；辛；微温","f":"《纲目拾遗》：\"治一切顽癣。先用***刮破，甩羊毛软笔蘸油涂上，甚加疼痛，停半日再涂，癣自结痂而愈；如已破者，不必刮。\"","y":"内服：煎汤，3-20g；或冲服。外用：适量，搽患处。","d":"?"},"橘络":{"a":"橘丝(《纲目拾遗》)，橘筋(《中药材手册》)。","s":"甘苦，平，\n\n①《本草撮要》：\"味淡微苦。\"\n\n②《本草便读》：\"甘，寒。\"\n\n③《四川中药志》：\"性平，味甘苦，无毒。\"","f":"通络，理气，化痰，治经络气滞，久咳胸痛，痰中带血，伤酒口渴。\n\n①《日华子本草》：\"治渴及吐酒，炒煎汤次甚验。\"\n\n②《纲目拾遗》：\"通经络滞气、脉胀，驱皮里膜外积痰，活血。\"\n\n③《本草求原》：\"通经络，舒气，化痰，燥胃去秽，和血脉。\"\n\n④《四川中药志》：\"化痰通络，治肺劳咳痰、咳血及湿热客于经隧等症。\"","y":"内服：煎汤，0.8～1.5钱。","d":"①凤尾橘络\n呈长条形的网络状。多为淡黄白色，陈久则变成棕黄色。上端与蒂相连，其下则筋络交叉而顺直，每束长约6～10厘米，宽约0.5～1厘米。蒂呈圆形帽状，十余束或更多压紧为长方形块状。质轻虚而软，干后质脆易断。气香，味微苦。以整齐、均匀、络长不碎断、色黄者为佳。\n\n②金丝橘络\n呈不整齐的松散团状，又如乱丝，长短不一，与蒂相混合，其余与凤尾橘络相同。\n\n③铲络\n筋络多疏散碎断，并连带少量橘白，呈白色片状小块，有时夹杂橘蒂及少量内瓤碎皮。以凤尾橘络品质最佳，铲络品质最差。\n主产四川、福建、浙江。此外，广西、广东、江西、湖南、湖北、云南、贵州等地亦产。"},"雪莲花":{"a":"雪莲、雪荷花、大拇花、大木花","s":"甘苦，温(大苞雪莲花有毒)。\n\n①《纲目拾遗》：\"性大热。\"\n\n②《四川中药志》：\"性温，味淡酸，无毒。\"\n\n③《新疆中草药手册》：\"味微苦，性热，有毒。\"\n\n④《云南中草药》：\"甘微苦，温。\"\n\n入肝、脾、肾三经\n\n《高原中草药治疗手册》：\"入肝、脾、肾三经。\"","f":"除寒，壮阳，调经，止血。治阳萎，腰膝软弱，妇女崩带，月经不调，风湿性关节炎，外伤出血。\n\n①《柑园小识》：\"除冷痰，助阳道。\"\n\n②《纲目拾遗》：\"治-切寒症。又，陈海曙云：治痘不起发及闷瘄闷痘，用一瓣入煎药中。\"\n\n③《四川中药志》：\"除寒痰水饮，壮阳，补血，温暖子宫。治男子阳痿，女子月经不调及崩带。\"\n\n④《新疆中草药手册》：\"通经活血，强筋骨，促进子宫收缩。治风湿性关节炎，妇女小腹冷痛，闭经，胎衣不下，麻疹不透，肺寒咳嗽，阳萎。\"\n\n⑤《云南中草药》：\"调经，止血，治月经不调，雪盲，牙痛，外伤出血。\"","y":"内服：煎汤，3～5钱(大苞雪莲花2～5分)；或浸酒。外用：捣敷。","d":"性状鉴别 （1)绵头雪莲花 全草干缩呈棉花团状，上宽下狭，略呈倒圆锥形，长10-30cm；全体密被交织的白色或淡黄色长棉毛。根茎粗壮，表面棕褐色，外层易剥落，有褐色残留叶柄。叶极密集，倒披针形或匙形，枯绿或棕色，长8-15cm，宽1.5-2cm，先端稍尖，基部渐狭成长柄，边缘有波状浅齿，上面密生蛛丝状绵毛工脱落，下面密生褐色绒毛。头状花序多数，无梗，在茎上部排成椭圆形穗状，苞片条状披针表、棕绿色，被白色密绵毛；总苞半球形，外层总苞片条状披针形，有白色密绵毛；内层披针形，有黑褐色长毛。花白色，常脱落。瘦果长约3mm；冠毛黑褐色。气微，味淡。\n（2)鼠曲雪莲花 地上产分长1.5-6cm。根茎纤细而长，常有1至数个莲座状叶丛。叶短圆形或匙形，长2-4cm，宽3-8mm，两面被白色或黄褐色绒毛，上部边缘有疏圆齿工全缘；叶柄稍扩大，紫色；上部叶小，包裹球状花序。花浅红色。冠毛淡褐色，外层少数，毛状，内层羽状。\n（3)水母雪莲花 地上部分长8-15cm。柱根长约15cm。根茎细长，有褐色残留叶柄。基部地倒卵形或匙形或匙形，上半部边缘有8-12个粗齿，基部楔形；上部叶渐小，卵形或卵状披针形，两面被白色绵毛；最上部叶条形或条状披针形，边缘条裂或细齿。花紫色或淡红色。冠毛白色，内层羽状。\n（4)三指雪莲花 地上部分长达15cm。根圆柱形，肉质。叶羽状分裂，裂片先端钩卷。头状花序紫红色多数，集成半球形，半外露于白色叶及苞片之外；花擅长 有刺毛。冠毛淡褐色，刺毛状。\n（5)槲叶雪莲花 地上部分长4-6cm，簇生。根茎粗，常分枝。基部叶椭圆形或狭倒卵形，长3-4cm，宽6-15mm，边缘有粗锯齿，上面扔白色疏毛，下面密被白以绒毛；上部叶渐小，披针形，有疏齿或全缘。头状花序序多数密集成球状。花红紫色。冠毛黑褐色，外层易脱落，内层羽毛状。"},"鸡骨草":{"a":"黄头草、黄仔强、大黄草、假牛甘子、红母鸡草、猪腰草、黄食草、小叶龙鳞草","s":"甘，凉。\n\n①《南宁市药物志》：\"甘，平，无毒。\"\n\n②《岭南草药志》：\"味微甘，性凉。\"\n\n归心；肺；肝；胃；肾经","f":"清热解毒，舒肝散瘀。治黄疸肝炎，胃痛，乳痈，瘰疬，跌打伤瘀血疼痛。\n\n①《南宁市药物志》：\"消炎解毒。治传染性肝炎，跌打驳骨。叶：捣绒敷乳疮。\"\n\n②《中国药植图鉴》：\"治风湿骨痛，跌打瘀血内伤；并作清凉解热药。\"\n\n③《岭南草药志》：\"清郁热，舒肝，和脾，续折伤。\"\n\n④广州部队《常用中草药手册》：\"清热利湿，舒肝止痛。治急慢性肝炎，肝硬化腹水，胃痛，小便刺痛，蛇咬伤。\"","y":"内服：煎汤，3～5钱，或入丸、散。外用：捣敷。","d":"干燥的带根全草，多缠扎成束。根长短粗细不等，主根圆柱状或圆锥状，表面灰褐色，具纵横皱纹，侧根多与主根垂直横生；主根坚硬，不易折断。茎藤状，粗1.5～2.5毫米，表面灰棕色，粗糙，小枝红棕色，较平滑；质坚，断面不平。气微，味淡。以干燥、洁净，根、茎、叶全者为佳。\n产广东、广西。"},"苦丁":{"a":"小山萝卜、龙喳口(《草木便方》)，叉头草(《四川中药志》，蛾子草(《中草药通讯》(3)：58，1972)。","s":"①《草木便方》：\"苦。\"\n\n②《四川中药志》：\"性寒，味苦，无毒。\"","f":"清热解毒。治疥癣，疔疮，痈肿，蛇咬伤。\n\n①《草木便方》：\"解毒，散热，清火，利筋骨，治中恶，羊疔，同蕌用。蛇伤起疱，捣涂。\"\n\n②《四川中药志》：\"清热解毒，调经种子。治疮毒痈肿及蛇伤。\"","y":"内服：煎汤，0.5～1两；或浸酒。外用：捣敷或煎水洗。","d":"?"},"五指毛桃根":{"a":"南芪,土黄芪,土五加皮,粗叶榕,三龙爪,亚桠木,五爪龙","s":"辛，甘，温 入脾、肺、肝经 \n\n①广州部队《常用中草药手册》：\"辛甘，微温。\"\n\n②广州空军《常用中草药手册》：\"味甘淡，性平。\"","f":"健肿补肺，行气利湿。治肺痨咳嗽，盗汗，肢倦无力，食少腹胀，水肿，风湿痹痛，肝炎，白带，产后无乳。\n\n①广州部队《常用中草药手册》：\"健脾化湿，行气止痛，除痰止咳。治肝硬化腹水，慢性肝炎，肝脾作痛，水肿，风湿性关节炎，劳伤咳嗽。\"\n\n②广州空军《常用中草药手册》：\"益气固表，舒筋活络，行气化湿。治肺结核咳嗽，慢性支气管炎，盗汗，病后体弱，产后无乳，妇女白带，胃痛，胸痛，无名肿毒。\"","y":"内服：煎汤，1～2两。","d":"?"},"小柿子叶":{"a":"黑面叶","s":"味苦；涩；性凉 \n\n归肺经","f":"燥湿止痒；收敛止血 主治湿疹；皮炎；外伤出血；疮疖；烫伤 \n\n《云南中草药》：\"治湿疹，皮炎，皮肤瘙痒，烧伤。\"\n\n②《云南思茅中草药选》：\"治外伤出血，疮疡湿疹。\"","y":"外用：捣敷；捣汁涂或研末撒。","d":"?"},"金不换":{"a":"独脚乌桕,石琴薯,山乌龟,地乌龟,地不容","s":"苦，寒\n \n广州部队《常用中草药手册》：\"苦，寒。\"","f":"清热解毒，健胃止痛，散瘀消肿。治外感咳嗽，咽痛，口舌生疮，呕吐腹泻，痢疾，胃痛，痈疽肿毒，跌打损伤。\n\n①广州部队《常用中草药手册》：\"清热解毒，散瘀止痛。治胃及十二指肠溃痔疼痛，跌打肿痛，神经痛，牙痛，急性胃肠炎，菌痢，上呼吸道感染，咽痛。\"\n\n②《常用中草药彩色图谱》：\"健胃止痛，消肿解毒。\"\n\n③广州空军《常用中草药手册》：\"治肺结核，痈疮，脓肿，消化不良，口腔炎。\"\n\n④《文山中草药》：\"治胃痛，腹胀，腹泻，疟疾。\"\n\n⑤南川《常用中草药手册》：\"治对口疮及汤火伤。\"","y":"内服：煎汤，3～5钱；研末、磨汁或浸酒。外用：捣敷、研末撒或磨汁涂。","d":"性状鉴别 根呈类圆锥形、纺锤形或不规则块状，长1-6cm，直径1-4cm。表面灰黄至棕黑色，具蜡样光泽，顶部有根茎痕，周围有瘤状突起，侧面有断续的纵皱及支根断痕。体重，质坚实，击啐后皮部与木部常分离；横断面灰绿、黄绿或灰白色，皮部有细小棕色脂道斑点，中心微显放射状纹理。气微，味苦，微凉而后回甜。以体重，质坚，表面光滑、断面色灰绿或绿者为佳。取滤液数滴点于滤纸上，干后置紫外光灯（365nm)下一下观察，显淡蓝色荧光，滴加硼酸饱和的丙酮溶液与10%枸椽酸溶液各1滴，干后，置紫外光灯下观察，有强烈的黄绿色荧光。（检查查黄酮类) （2)薄层色谱 取粉末0.5g，加水5滴搅匀，再加水饱和的正丁醇5ml密塞，振摇10min，放置2h，离心，取上清液，加正丁醇饱和的水3倍量摇匀，放置使分层（必要时离心)。取正丁醇层，蒸发皿中蒸干，残潭加甲醇1ml使溶解，作供试品溶液。另取人参皂甙Rb1、Rg1，及三七皂甙R1加甲醇制成对照品溶液。吸取上述两种溶液各1μl，分别点于同一硅胶G薄层板上，以氯仿-醋酸已酯-甲醇-水（15：40：22：10)10℃以下放置的上层溶液为展开剂，展开。喷以硫酸溶液（1：10)，于105℃烘约10min。供试品色谱中，在与对照品色谱相应的位置上，显相同颜色的斑点，紫外灯下，显相同的荧光斑点。"},"鬼箭羽":{"a":"卫矛、鬼箭(《本经》)，神箭(《广雅》)，六月凌(《植物名实图考》)，八树、四棱锋、芸杨，鬼见愁(《中国树木分类学》)，四面锋、篦箕柴(《浙江中药手册》)，风枪林(《中国药植志》)，山鸡条子(《东北药植志》)，四面戟(《药材学》)，千层皮、刀尖茶，雁翎茶、四棱茶(《辽宁经济植物志》)。","s":"苦，寒。\n\n①《本经》：\"味苦，寒。\"\n\n②《吴普本草》：\"苦，无毒。\"\n\n③《药性论》：\"有小毒。\"\n\n④《日华子本草》：\"味甘涩。\"\n\n⑤《纲目》：\"味酸涩。\"","f":"破血，通经，杀虫。治经闭，癥瘕，产后瘀滞腹痛，虫积腹痛。\n\n①《本经》：\"主女子崩中下血，腹满汗出。\"\n\n②《别录》：\"主中恶腹痛，去白虫，消皮肤风毒肿，令阴中解。\"\n\n③《药性论》：\"破陈血，落胎。主中恶腰腹痛。\"\n\n④《唐本草》：\"疗妇人血气。\"\n\n⑤《日华子本草》：\"通月经，破癥结，止血崩、带下，杀腹脏虫，及产后血绞肚痛。\"\n\n⑥《概物名实图考》：\"治肿毒。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。","d":"干燥枝条呈细长圆柱形，多分枝，长40～50厘米左右，直径0.4～1厘米。表面灰绿色，有纵皱纹，四面生有灰褐色片状翅，形似箭羽。枝坚硬而韧，难折断，断面淡黄白色，粗纤维性.翅质轻而脆，易折断，断面较平坦，暗红棕色，细颗粒性。气微，味微苦涩。以枝条均匀、翅状物齐全者为佳。\n全国大部分地区多有生产。"},"螃蟹脚":{"a":"枫香槲寄生、枫树寄生、螃蟹脚、桐树寄生、赤柯寄生","s":"苦，凉。","f":"清热，消食，利尿。治宿食内停，小便赤热。","y":"内服：煎汤，1～2两。","d":"?"},"四叶草":{"a":"冷水丹、风车草、四方草(《江西草药》)。","s":"《江西草药》：\"甘，平。\"","f":"清热，利尿，解毒，消肿。治尿路感染，赤白带下，痢疾，痈肿，跌打损伤。\n\n①《江西草药》：\"清热解毒；消肿止痛，通利小便。\"\n\n②苏医《中草药手册》：\"利尿消肿，抗癌。治尿路感染，赤白带下，子宫颈糜烂，化脓性炎症，并治脑脊髓膜炎，脓毒性败血症，痈疽，毒蛇咬伤，皮肤疮毒水肿，癌肿。\"","y":"内服：煎汤，0.5～1两(鲜品2～3两)；或捣烂开水送服。外用：捣敷。","d":"?"},"金刚藤头":{"a":"铁菱角、饭巴坨、冷饭巴(《四川常用中草药》)。","s":"《四川常用中草药》：\"甘，平。\"","f":"《四川常用中草药》：\"清热，除风毒。治崩带，血淋，瘰疬，跌打损伤。嫩叶：治臁疮。\"","y":"内服：煎汤，0.5～1两；或浸酒。外用：捣敷。","d":"?"},"大九股牛":{"a":"绿天麻、大接骨、羊角天麻。","s":"微苦，凉。","f":"消炎，止痛，止咳，撵疮毒。治肺热咳嗽，乳腺炎，腮腺炎，痈疮。","y":"内服：煎汤，3～5钱；研末或泡酒。外用：研末调敷。","d":"?"},"七叶莲":{"a":"小叶鸭脚木、汉桃叶、狗脚蹄、手树、七加皮、七叶藤","s":"微苦，温。\n\n①《广西中草药》：\"性温，味辛。\"\n\n②广州部队《常用中草药手册》：\"苦甘，温。\"","f":"祛风除湿，活血止痛。治风湿痹痛，胃痛，跌打骨折，外伤出血。\n\n《广西实用中草药新选》：\"行气止痛，活血消肿，壮筋骨。治急性风湿性关节炎，胃痛，骨折，扭挫伤，腰腿痛，瘫痪。\"","y":"内服：煎扬，3～5钱。外用：捣烂敷患处。","d":"?"},"人尿":{"a":"溲、小便、人溺、轮回酒、还元汤","s":"咸，凉。\n\n①《本草拾遗》：\"寒。\"\n\n②《日华子本草》：\"凉。\"\n\n③《品汇精要》：\"味咸，性寒，无毒。\"","f":"滋阴降火，止血消瘀。治阴虚发热，劳伤咳血，吐血，衄血，产后血瘀，血晕，跌打损伤，血瘀作痛。\n\n①《别录》：\"疗寒热，头疼，温气。\"\n\n②《唐本草》：\"主卒血攻心，被打内有瘀血，煎服之，一服一升。又主癥积腹满，诸药不差者服之皆下血片肉块。亦主久嗽上气失声。\"\n\n③《本草拾遗》：\"主明目益声，润肌肤，利大肠，推陈致新，去咳嗽肺痿，庢病。\"\n\n④《日华子本草》：\"止劳渴，嗽，润心肺，疗血闷热狂，扑损瘀血运绝及困乏。揩洒皮肤治皲裂，能润泽人。蛇犬等咬，以热尿淋患处。难产及胞衣不下，即取一升，用姜、葱各一分煎三、两沸，乘热饮，便下。吐血，鼻洪，和生姜一分，绞汁，乘热顿饮瘥。\"\n\n⑤《本草衍义补遗》：\"降火最速。\"\n\n⑥《纲目》：\"杀虫解毒，疗疟、中暍。\"\n\n⑦《长沙药解》：\"清心泄火，退热除烦。\"\n\n⑧《医林纂要》：\"通利三焦，降热去瘀，滋补心血，降泻肾邪。\"","y":"内服：取新鲜者温饮1～2杯，或和汤药内。","d":"?"},"冬瓜皮":{"a":"白瓜,白冬瓜,枕瓜。","s":"甘，凉。\n\n①《滇南本草》：\"性微寒平，味甘淡。\"\n\n②《本草再新》：\"味甘，性凉，无毒。\"","f":"利水消肿。治水肿，腹泻，痈肿。\n\n①《本草图经》：\"功用与冬瓜等。\"\n\n②《滇南本草》：\"止渴，消痰，利小便。\"\"治中风。\"\n\n③《纲目》：\"主驴马汗入疮肿痛，阴干为末涂之，又主折伤损痛。\"\n\n④《本草再新》：\"走皮肤，去湿追风，补脾泻火。\"\n\n⑤《重庆堂随笔》：\"解风热，消浮肿。\"\n\n⑥《分类草药性》：\"治水肿，痔疮。\"\n\n⑦《江苏植药态》：\"治腹泻、足跗浮肿。\"\n\n⑧《山东中药》：\"利湿消暑。\"","y":"内服：煎汤，0.3～1两；或入散剂。外用：煎水洗或研末调敷。","d":"干燥果皮，常向内卷曲成筒状或双筒状，大小不一。表面光滑，淡黄色、黄绿色至暗绿色，革质，被有白色粉霜，内表面较粗糙，微有筋脉。质脆，易折断。气无，味淡。以皮薄、条长，色灰绿、有粉霜，干燥、洁净者为佳。\n全国大部地区均产。"},"藤黄":{"a":"玉黄、月黄","s":"《海药本草》：\"酸涩，有毒。\"","f":"消肿，化毒，止血，杀虫。治痈疽肿毒，顽癣恶疮，损伤出血，牙疳蛀齿，汤火伤。\n\n①《海药本草》：\"主蚛牙蛀齿，点之便落。\"\n\n②《纲目拾遗》：\"治痈疽，止血化毒，敛金疮，亦能杀虫。\"\n\n③《现代实用中药》：\"为峻下剂，治绦虫及水肿。\"","y":"外用：研末调敷、磨汁涂或熬膏涂。内服：入丸剂(一次量1～2厘)。","d":"藤黄\n又名：玉黄、月黄。为管状或不规则的块状物，直径3～5厘米，显红黄色或橙棕色，外被黄绿色粉霜，有纵条纹。质脆易碎，断面平滑，呈贝壳状或有空腔，具黄褐色而带蜡样的光泽，用水研和则星黄色乳剂，投火中则燃烧。气微，味辛辣。以半透明、红黄色者为佳，黑色者次之。\n产印度及泰国。"},"牛耳大黄":{"a":"土大黄(《民间常用草药汇编》)，四季菜根(《四川中药志》)，火风棠(《重庆草药》)，羊蹄根(《吉林中草药》)。","s":"苦，寒。\n\n①《草木便方》：\"苦。\"\n\n②《东北常用中草药手册》：\"苦，寒。\"\n\n③《陕甘宁青中草药选》：\"酸苦，寒，有小毒。\"","f":"清热凉血，化痰止咳，通便杀虫。治急性肝炎，慢性气管炎，吐血，血崩，血小板减少性紫瘢。大便燥结，痢疾，疥癣。秃疮，疔，疖。\n\n①《草木便方》：\"活血，补精，壮力。能走表。捣烂合稠靛缸水，搽疥癣秃癞。\"\n\n②《四川中药志》：\"解毒，清热，消疮癣。治大便燥结。\"\n\n③《重庆草药》：\"清火，解毒，清血热，利便。治吐血诸症。酒炒能调气敛血，治红崩。\"\n\n④《闽东本草》：\"除热，杀虫，排脓拔毒。治白秃疮，癣，疔，疖。\"\n\n⑤《齐齐哈尔中草药》：\"治出血性紫斑，血小板减少和内出血。\"\n\n⑥《高原中草药治疗手册》：\"清热凉血，润肠通便。治急性肝炎，经闭腹胀，无名肿毒。\"\n\n⑦《陕甘宁青中草药选》：\"清热解毒，消炎退肿，止血。\"","y":"内服：0.6～1两。外用：捣敷，磨汁涂或煎水洗。","d":"?"},"费菜":{"a":"养心草、倒山黑豆，马三七、白三七、胡椒七，七叶草，晏海豆爿、回生草，血草","s":"酸，平。\n\n①《救荒本草》：\"味酸。\"\n\n②《福建民间草药》：\"酸，平，无毒。\"\n归肝，心，脾经。\n《闽东本草》：入心、肝、脾三经。","f":"活血，止血，宁心，利湿，消肿，解毒。治跌打损伤，咳血，吐血，便血，心悸，痈肿。\n\n①《福建民间草药》：\"抑肝宁心，清血热，疗心悸。\"\n\n②《湖南药物志》：\"破血，活血，凉血。\"","y":"内服：煎汤，1.5～3钱(鲜者1～2两)，外用：捣敷。","d":"费菜根茎短小，略呈块状；表面灰棕色，根数条，粗细不等；质硬，断面暗棕色或类灰白色。茎圆柱形，长15-40cm，直径2-5mm；表面暗棕色或紫棕色，有纵校；质脆，易折断，断面常中空。叶互生或近对生，几无柄；叶片皱缩，展平后呈长披针形至倒披针形，长3-8cm，宽l-2cm；灰绿色或棕褐色，先端渐尖，基部楔形，边缘上部有锯齿，下部全缘。聚伞花序顶生，花黄色。气微，味微涩。"},"刺五加":{"a":"五加皮、　刺拐棒","s":"根茎结节状不规则圆柱形，直径1.4～4.2cm;表面灰褐色，有皱纹;上端有不定芽发育的细枝。根圆柱形，多分枝，常扭曲，长3.5～12cm，直径0.3～1.5cm;表面灰褐色或黑褐色，粗糙、皮薄，剥落处呈灰黄色。质硬，断面黄白色，纤维性。有特异香气，味微辛、稍苦、涩。","f":"益气健脾，补肾安神。用于脾肾阳虚、体虚乏力、食欲不振、腰膝酸痛、失眠多梦。","y":"9～27g","d":"（1） 本品根的横切面：木栓细胞数十列。皮层菲薄，散有分泌道；薄壁细胞大多含草酸钙簇晶，直径11～64μm。韧皮部外侧散有较多纤维束，向内渐稀少；分泌道类圆形或椭圆形，径向25～51μm，切向48～97μm；薄壁细胞含簇晶。形成层成环。木质部占大部分，射线宽1 ～3 列细胞；导管壁较薄，多数个相聚；木纤维发达。\n根茎的横切面：韧皮部纤维束较根为多；有髓。\n茎的横切面：髓部较发达。\n（2） 取本品粉末约5g，加75％乙醇50ml，加热回流 1小时，滤过，滤液蒸干，残渣加水10ml使溶解，置分液漏斗中，用氯仿提取2 次，每次5ml ，合并氯仿液，蒸干，残渣加甲醇 1ml使溶解，作为供试品溶液。另取刺五加对照药材5g，同法制成对照药材溶液。再取异秦皮啶对照品，加甲醇制成每 1ml含1mg 溶液，作为对照品溶液。照薄层色谱法（附录Ⅵ B）试验，吸取上述三种溶液各10μl ，分别点于同一以羧甲基纤维素钠为黏合剂的硅胶Ｇ薄层板上，以氯仿－甲醇（19:1）为展开剂，展开，取出，晾干，置紫外光灯（254nm） 下检视。供试品色谱中，在与对照药材色谱相应的位置上，显相同颜色的斑点；在与对照品色谱相应的位置上，显相同的蓝色斑点。"},"脱力草":{"a":"野蚊子草(《苏南种子植物》)，苍蝇花(《中药志》)，水白参、白花壹瓶、小叶鲤鱼胆、瞿麦沙参、八月白、白花瞿麦、小仙桃草、白葫芦、蛇王草(《浙江民间常用草药》)。","s":"《浙江民间常用草药》：\"辛涩，凉。\"","f":"清热利涅，补虚活血。治尿路感染，白带，痢疾，病后体虚，扭、挫伤。\n\n①《江苏药材志》：\"滋补强壮。治体虎或病后虚弱少力。\"\n\n②《浙江民间常用草药》：\"清热利湿，解毒消肿。\"","y":"内服：煎汤，1～2两；或捣烂绞汁服。外用：捣敷。","d":"?"},"梦花":{"a":"金腰袋、打结花、梦冬花(《中国树木分类学》)，喜花、迎春花(《重庆草药》)。","s":"《重庆草药》：\"味淡，性平，无毒。\"","f":"治青盲，翳障，多泪，羞明，梦遗，虚淋，失音。\n\n①《分类草药性》：\"治失音。\"\n\n②《重床草药》：\"养阴安神。治阴虚火旺，夜梦遗精。\"\n\n③《广西中药志》：\"明目，祛障翳。治青盲，云翳，多眵泪，羞明，小儿疳眼。\"","y":"内服：煎汤，0.8～1钱。","d":"多为散在的单个花蕾，少数为头状花序，通称新蒙花或蒙花珠。花序半球形，略似向日葵的头状花序。花有总苞片6～9，总花梗钩状弯曲，全体被淡黄色毛茸。单个花蕾呈短棒状，稍弯曲，长6～8毫米，径3～5毫米，表面密被浅黄色或灰白色有光泽的绢丝状长毛茸。以干燥、无杂质者为佳。\n产四川、贵州、湖北、广西等地。\n\n本品在湖北、四川及广西等地作密蒙花使用。参见\"密蒙花\"条。"},"麻油":{"a":"胡麻油(《别录》)，乌麻油(《外台》)，脂麻油(《近效方》)，香油(苏轼《物类相感志》)，生油(《本草衍义》)，清油(《岭南卫生方》)。","s":"甘，凉。\n\n①《别录》：\"微寒。\"\n\n②《品汇精要》：\"味甘，性微寒，无毒。\"","f":"润燥通便，解毒，生肌。治肠燥便秘，蛔虫、食积腹痛，疮肿，溃疡，疥癣，皮肤皲裂。\n\n①《别录》：\"利大肠，胞衣不落。生者摩疮肿，生秃发。\"\n\n②《千金·食治》：\"去头面游风。\"\n\n③孟诜：\"杀五黄，下三焦热毒气，通大小肠，治蛔心痛，敷一切恶疮疥癣，杀一切虫。取一合，和鸡子两颗，芒硝一两，搅服，少时即泻下热毒。\"\n\n④《本草拾遗》：\"主天行热，肠秘内结热，服一合，下利为度。\"\n\n⑤《日华子本草》：\"陈油煎膏，生肌长肉，止痛，消痈肿，补皮裂。\"\n\n⑥《纲目》：\"解热毒，食毒、虫毒。\"","y":"内服：生用或熬熟。外用：涂搽。","d":"取本品1ml ，置试管中，加含蔗糖0.1g的盐酸10ml，振摇半分钟，酸层即显粉红色，静置后，渐变为红色。"},"樟木":{"a":"樟材(《本草拾遗》)，香樟木(《药材资料汇编》)，吹风散(《广西中药志》)。","s":"辛，温。\n\n①《本草拾遗》：\"味辛，温，无毒。\"\n\n②《本草再新》：\"味苦，性温，无毒。\"\n\n③《广西中药志》：\"味辛，性温，有小毒。\"","f":"祛风湿，行气血，利关节。治心腹胀痛，脚气，痛风，疥癣，跌打损伤。\n\n①《本草拾遗》：\"主心腹痛，霍乱，腹胀，宿食不消，常吐酸臭水，酒煮服之。亦作浴汤治脚气，除疥癣风痒。\"\n\n②《本草再新》：\"暖血道，利关节，治跌打折骨，气逆血滞，兼能堕胎。\"","y":"内服：煎汤，3～5钱；或浸酒。外用：煎水熏洗。","d":"为形状不规则的木块，外表呈赤棕色至暗棕色，横断面可见年轮，质地重而硬，有强烈的樟脑香气，尝之有清凉感。以块大、完整、香气浓郁者为佳。\n盛产我国沿海一带，广西、江西、福建、台湾、湖南、湖北、四川、云南等地均有，以台湾产量最大。\n\n四川地区有以本品制成的船底板，经多年水浸腐朽，取出入药者，名\"甲沉香\"。"},"虎耳草":{"a":"石荷叶(《纲目》)，金线吊芙蓉、老虎耳(《生草药性备要》)，系系叶(《简易草药》)，天荷叶、金丝荷叶(《现代实用中药》)，丝棉吊梅(《中国药植志》)，耳聋草、猪耳草、狮子草(《福建民间草药》)，金钱荷叶(《民间常用草药汇编》)，金线莲(《江西民间草药》)，石丹药(《四川中药志》)，佛耳草、丝丝草、蟹壳草、搽耳草、猫耳朵(《湖南药物志》)，耳朵草(《闽东本草》)，红丝络、红线草、红线绳、水耳朵、月下红、金丝草、耳朵红、铜钱草(《浙江民间常用草药》)。","s":"①《履巉岩本草》：\"性凉，有毒。\"\n\n②《纲目》：\"微苦辛，寒，有小毒。\"","f":"祛风，清热，凉血解毒。治风疹；湿疹，中耳炎，丹毒，咳嗽吐血，肺痈，崩漏，痔疾。\n\n①《履巉岩本草》：\"治痔疾肿毒，用少些晒干人马子(便桶)内烧熏。\"\n\n②《纲目》：\"治瘟疫，擂酒服。生用吐利人，熟用则止吐利。又治聤耳，捣汁滴之。\"\n\n③《生草药性备要》：\"治耳内暴热毒，红肿流脓疼痛，捶汁滴入耳，或加冰片消散而愈。\"\n\n④《植物名实图考》：\"喉闭无音，用以代茶。亦治吐血。\"\n\n⑤《分类草药性》：\"清肺热，治咳嗽，疗风疹、丹毒。\"\n\n⑥《现代实用中药》：\"涂疮痈，冻疮，及毒虫刺伤等。\"\n\n⑦《江西民间草药》：\"治肺热咳嗽气逆，吐血，肺痈吐臭脓，百日咳，肝火，童子痨。\"\n\n⑧广州部队《常用中草药手册》：\"祛湿消肿，凉血止血，清热解毒，治外伤出血，急慢性中耳炎。\"","y":"内服：煎汤，3～5钱。外用：捣汁滴或煎水熏洗。","d":"?"},"还阳参":{"a":"天竺参、万丈深、竹叶青、独花蒲公英(《滇南本草》)，铁刷把、有根无叶(《文山中草药》)。","s":"①《滇南本草》：\"性温平，味甘。\"\n\n②《文山中草药》：\"苦，温。\"","f":"补肾阳，益气血，健脾胃。治性神经衰弱，妇人宫冷不孕，白带漏下，头晕耳鸣，心慌怔忡，小儿消化及营养不良。\n\n①《滇南本草》：\"治诸虚百损，五痨七伤，血气衰败，头晕耳鸣，心慌怔忡，妇人白带漏下，损伤督任二脉。\"\n\n②《文山中草药》：\"健胃消食，补肾壮刚。治小儿消化及营养不良，胃痛，性神经衰弱。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"独角莲":{"a":"野半夏、犁头尖、剪刀草、玉如意、野慈菇、副本一粒红","s":"味辛、甘，性温，有毒。归胃、肝经。","f":"治毒蛇咬伤、瘰疬、跌打损伤。","y":"外用：捣敷。","d":"性状鉴别： \r\n　　块茎卵圆形或椭圆形，长2－5cm，直径1-3cm，顶端残留茎痕或芽痕。表面白色或淡黄色略平滑，有环纹及点状很痕。质坚硬，断面白色粉质。无臭味淡，麻辣刺舌。 \r\n　　以个大、质坚实、色白、粉性足者为佳。 \r\n　　显微鉴别： \r\n　　块茎横切面：木栓细胞有时残存。基本组动外侧有大型粘液腔及粘液细胞，内含草酸钙针晶束，长28－84μm；维管束散列，以外韧型为多见，偶有周木型。薄壁细含有众多淀粉粒。 \r\n　　粉末特征：类白色。①淀粉粒单粗球形或类球形，直径4- \r\n　　29μm，脐点点状、裂缝状、人字状、十字状、三叉状或星状，大粒层纹隐约可见；复粒由2-12个分粒组成，有的1个较大分粒与2-4个小分粒复合。②草酸钙针晶散在或成柬存在于类圆形或长圆形粘液细胞中，针晶束长约全116μm。③螺纹及环纹导管，直径9-46μm。"},"还魂草":{"a":"打不死。","s":"苦涩，平。肝经","f":"消肿，止血，解毒。治创伤，无名肿毒，蛇咬及蝎螫。","y":"外用：捣敷或绞汁涂。","d":"?"},"铧头草":{"a":"地黄瓜(《分类草药性》)，青地黄瓜(《四川中药志》)，烙铁草、犁头草(《重庆草药》)。","s":"辛微苦，寒。\n\n①《四川中药志》：\"性寒，味辛酸，无毒。\"\n\n②《南宁市药物志，：\"苦，寒，无毒。\"\n\n③《广西中药志》：\"味淡，性平，无毒。\"","f":"清热解毒，散瘀消肿。治肠痈，疔疮，红肿疮毒，黄疸，淋浊，目亦生翳。\n\n①《草木便方》：\"治月瘕胀满，刀斧伤。\"\n\n②《分类草药性》：\"去风火，消毒肿疔疮，散瘀血。\"\n\n③《四川中药志》：\"通经，消肿，解毒。治红肿疮毒，疔疮及淋浊。\"\n\n④《南宁市药物志》：\"清热解毒。治阳黄，肠痈，疔疮，热毒。\"\n\n⑤《广西中药志》：\"治眼疾及瘩背。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)。外用：捣敷。","d":"理化鉴别 （1）取本品粉末2g，加已醇20ml，加热回流30min，滤过，取滤液1滴，点于滤纸上，置紫外光灯（365nm）下检视，显紫红色荧光。（2）取上述滤淮蒸干，列潭加热水3ml，使溶解，滤过，滤液照下述方法试验：①取滤液1ml，加盐酸3-4滴及镁粉少量，加热显棕红色。（检查黄酮）②取滤液1滴点于滤纸片上，置紫外光灯（365nm）下观察，显黄绿以荧光，再滴加氨试液1滴，即显亮黄绿以荧光。（检查黄酮）"},"手掌参":{"a":"佛手参、掌参(《宁夏中草药手册》)，手儿参(《陕西中草药》)，旺拉(藏名)。","s":"甘，平。\n\n①《宁夏中草药手册》：\"甘微苦，微寒。\"\n\n②《四川常用中草药》：\"甘，平。\"\n\n③《高原中草药治疗手册》：\"性微温，味甘，无毒。\"","f":"补益气血，生津止渴。治肺虚咳喘，虚劳消瘦，神经衰弱，久泻，失血，带下，乳少，慢性肝炎。\n\n①《东北药植志》：\"制成粘液，用于中毒和泻下；泡酒为强壮、强精剂。\"\n\n②《山西中药志》：\"收敛止血，解毒。治久泻失血，淋病，带下。\"\n\n③《黑龙江民间中药》：\"泡酒治阴痿。\"\n\n④《中国药植图鉴》：\"消瘀。治跌打损伤，积血不行。\"\n\n⑤《四川常用中草药》：\"补血益气，生津止渴。治肺虚咳喘，虚痨羸瘦，缺乳汁。\"\n\n⑥《西藏常用中草药》：\"治慢性肝炎。\"\n\n⑦《陕西中草药》：\"滋补强壮，补脾润肺，安神镇惊，益气止痛。治身体虚弱，神经衰弱，劳伤，咳嗽，气喘。\"","y":"内服：煎汤，O.3～1两；研末或制成糖浆或浸酒。","d":"干燥块茎形如手掌，指状分裂，通常4～6裂不等，稍扁，长2.5～3.5厘米，径2～2.5厘米，表面皱缩，淡黄色，有时茎痕周围有1褐色环。质坚硬；断面白色，胶质。气特异，味淡。\n产东北及山西、陕西、甘肃、宁夏、青海、河北等地。\n\n同科植物长苞凹舌兰的块茎在陕、甘、宁、青地区亦同等入药。与手参的主要区别是：叶椭圆形或卵圆形，宽3厘米以上；苞片远比花长；花黄绿色，唇瓣2～3裂，距短囊状。"},"滴水珠":{"a":"石半夏、石里开、一滴珠、水滴珠(《江西草药》)，水半夏、独叶一支花、岩芋、天灵芋、一粒珠、岩珠、蛇珠、独龙珠(《浙江民间常用草药》)。","s":"《江西草药》：\"性温，味辛，有小毒。\"","f":"止痛，行瘀，消肿，解毒。治头痛，胃痛，腹痛，腰痛，跌打损伤，乳痈，肿毒。\n\n①《江西草药》：\"消肿解毒，散瘀止痛。\"\n\n②《浙江民间常用草药》：\"散结。\"","y":"内服：研末装胶囊，1～2分。外用：捣敷。","d":"理化鉴别（1）取粉末2g，加温水20ml浸泡4h后，滤过，浓缩后点于圆形层析滤纸上，以甲醇展开，喷以0.7%茚三酮醇溶液。在80℃烘干10min，显蓝紫色斑点（检查氨基酸）。（2）薄层角谱，取粉末1g，加石油醚(60-90℃ )10ml，冷浸1昼夜，吸取上清液作供试品溶液。另取β-谷甾醇制成对照品溶液。分别吸取供试品和对照品溶液。分别吸取供试品和对照品溶液，点于硅胶G薄层板上以氯仿-甲醇(9.5:0.5)展开，展距20cm。以10%磷钼酸乙醇深液作显色剂，供试品和对照品相应位置上均为蓝色斑点。"},"柳絮":{"a":"柳实(《本经》)，柳子(《别录》)。","s":"《本草别说》:\"性凉。\"","f":"祛湿，溃痈，凉血止血，解毒消痈。主吐血；创伤出血；痈疽；恶疮\n\n\n①《本经》:\"主溃痈，逐脓血。\"\n\n②《别录》:\"主痂疥，恶疮，金疮。\"\"子:汁疗渴。\"\n\n③陶弘景:\"贴灸疮。\"\n\n④《药性论》:\"主止血。治湿痹四肢挛急，膝痛。\"","y":"","d":""},"土田七":{"a":"小田七、竹田七、毛七、贼佬姜、姜三七、三七姜、姜叶三七、竹叶三七、姜七、姜田节","s":"辛微苦，温。\n\n归心；脾经","f":"散瘀消肿，活血止血，行气止痛。治跌打瘀痛，风湿骨痛，吐血，衄血，月经过多，虫蛇咬伤。","y":"内服：煎汤，2～3钱；或浸酒。外用：研粉敷。","d":"性状鉴别，本品略呈扁圆锥形或纺锤形，长1-2.5cm，直径0.5-0.8cm。表碳 棕色或棕红色，常皱缩，节密，具白色点状须根痕，节间长1-2mm。质硬脆，易折断，断面平坦，角质化，内皮层明显，灰白色或灰色，可见白色点状维管束。气微，味辛。"},"鸦片":{"a":"底野迦(《唐本草》)，阿片、阿芙蓉(《纲目》)，亚片(《随息居饮食谱》)。","s":"苦，温，有毒。\n\n①《唐本草》：\"味辛苦，平。\"\n\n②《纲目》：\"酸涩，温，微毒。\"","f":"敛肺，止咳，涩肠，止痛。治久咳，久泻，久痢，脱肛，心腹筋骨诸痛。\n\n①《唐本草》：\"主百病中恶，客忤邪气，心腹积聚。\"\n\n②《纲目》：\"泻痢脱肛不止，能涩丈夫精气。\"\n\n③《本草求原》：\"性同于粟壳，而止痢止痛行气之效尤胜。\"\n\n④王殿翔《生药学》：\"用于失眠为催眠药；神经痛、月经痛、胸绞痛、肠绞痛等为镇痛药。\"","y":"内服：入丸、散，0.5～1分。","d":"鸦片形状不一，有成圆球形、饼形、砖块或不规则形，棕色或黑色，带蜡质，外部往往附有罂粟叶或纸片。新鲜时质软，贮藏日久，则渐变坚硬。臭特异，带麻醉性，味极苦而特异。"},"山莲藕":{"a":"大力牛、大口唇、扮山虎、牛大力、扒山虎、坡莲藕、地藕、血藤、大莲藕、大力薯、倒吊金钟","s":"甘，寒。\n\n①《生草药性备要》：\"味甜，性劫。\"\n\n②《陆川本草》：\"苦，寒。\"\n\n③《南宁市药物志》：\"甘，平，无毒。\"","f":"润肺滋肾，清热止咳。治肺虚咳嗽。\n\n①《生草药性备要》：\"壮筋骨，解热毒，理内伤，治跌打，浸酒滋肾。\"\n\n②《陆川本草》：\"清肺止咳，清凉解毒。治咳血，痢疾，温病身热口渴，头昏。\"\n\n③《南宁市药物志》：\"润肺止咳。治喘咳，肺炎，疝气。\"\n\n④广州部队《常用中草药手册》：\"舒筋活络，补虚润肺。治腰腿痛，风湿痹痛，慢性肝炎，肺结核。\"\n\n⑤广州空军《常用中草药手册》：\"治腰肌劳损，溃疡病，跌打损伤后遗症。\"\n\n⑥《广东中草药》：\"治肺虚咳嗽，产后虚弱，四肢乏力，痈疮。\"","y":"内服：煎汤，1～2两；或浸酒。","d":"?"},"毛薯":{"a":"参薯、黎洞薯、大薯、薯子(《广州植物志》)，脚板薯、鸡窝薯(《南宁市药物志》)，红毛薯(《广西药植名录》)。","s":"《南宁市药物志》：\"甘，平，无毒。\"","f":"①《南宁市药物志》：\"块茎能促进溃疡的肉芽生长。并有收水生肌，使疮面结疤作用。研末治汤火伤及面部烂疮。配猪腱肉服，治眼珠突出，俗称螃蟹眼。\"\n\n②《广西药植名录》：\"补脾肺，涩精气，消肿，止痛。\"","y":"内服：煎汤，9-15g；或入丸、散。外用：适量，研末敷。","d":"?"},"高丽参(天字)":{"a":"?","s":"?","f":"大补元气、生津止渴。补养五脏、安精神、定魂魄、明目开心、益智健脑，作用较强。","y":"","d":"?"},"剪刀草":{"a":"塔花(《植物学大辞典》)，玉如意(《苏州本产药材》)，山薄荷、土薄荷(《泉州青草药》)，野薄荷(《泉州本草》)，野仙人草、小叶仙人草(《江西民间草药验方》)，节节花、野香草(《浙江民间常用草药》)。","s":"苦辛，凉。\n\n①《饮片新参》：\"苦，平。\"\n\n②《江西民间草药验方》：\"苦辛，凉。\"","f":"祛风清热，散瘀消肿。治感冒头痛，菌痢，肠炎，乳痈，疔疮，跌打损伤，血崩，荨麻疹。\n\n①《饮片新参》：\"消疮肿丹毒，虫咬伤。\"\n\n②《苏州本产药材》：\"止血。治乳痈，疔疮。\"\n\n③《泉州青草药》：\"祛风，止血，消痈，止痢。\"\n\n④《泉州本草》：\"清热解毒，祛风止痛，消痈止痢。治妇人血崩，乳痈，赤白痢。外敷痈疽肿毒。\"\n\n⑤苏医《中草药手册》：\"清热解毒，消肿止痛，祛风散热。治肠炎，白喉，咽喉肿痛，痈疽疮疖，荨麻疹，过敏性皮炎。\"\n\n⑥《江西草药》：\"散瘀解毒。治跌打损伤，感冒头痛，中暑腹痛。\"\n\n⑦《湖南药物志》：\"行气，散血，消积。\"","y":"内服：煎汤，0.5～1两(鲜者1～2两)；或捣汁。外用：煎水洗。","d":"干燥全草，茎枝柔细，直径不过1毫米；表面紫棕色，有纵棱；折断面黄棕色。叶皱缩卷曲，黄棕色或淡绿色；质脆易落。上部花穗仅留黄绿色的花萼，花冠多已脱落，有时残存黄白色的小坚果。气微，味微苦。以干燥、黄棕色至青棕色、无泥土者为佳。\n产于江苏、浙江、福建等地。"},"一点红":{"a":"红背叶、羊蹄草、野木耳菜、红头草、叶下红、紫背叶","s":"性凉，味微苦。","f":"?","y":"0.5-1两；外用适量，鲜品捣烂缚患处。","d":"?"},"鹧鸪菜":{"a":"蛔虫菜、乌菜、石疤(《中国经济海藻志》)。","s":"性味：咸；平\n性状：性状鉴别 藻体黑色，扁平，叶状，长1-4cm；具有不规则叉状分枝，节间狭长，类圆形，节部缢缩。叶片中央有明显的中肋；中肋分枝点常有次生副枝，有时生出毛状根。膜质。气腥，味咸。","f":"《纲目拾遗》：\"疗小儿腹中虫积，食之即下。\"","y":"内服：煎汤，鲜品30-60g；小儿酌减；或干品研末。当晚临睡前和次晨空腹两次分服。","d":"1.取鹧鸪菜适量，经过粗提，得海人草酸粗品(1-2mg)，加入1-2ml 0.2%香草醛丙酮溶液，于水浴上加热，挥去丙酮，残渣加2ml 1%氢氧化钠乙醇液，显橙色。(海人草酸反应)。2.取粗提物的甲醇溶液，点于滤纸上，喷以0.2%吲哚醌丙酮溶液，70℃加温后呈橙色。(海人草酸反应)"},"丁香油":{"a":"?","s":"味辛；甘；性热 \n\n《纲目拾遗》：\"味甘辛，性大热。\"\n\n归脾；胃；肾经","f":"暖胃，温肾。治胃寒痛胀、呃逆、吐泻、痹痛，疝痛，口臭，牙痛。\n\n①《药性考》：\"壮阳暖肾。治疝痛阴寒。\"\n\n②王殿翔《生药学》：\"用于肠胃多气、绞痛，消化不良，恶心与呕吐；风湿痛，神经痛，牙痛。\"","y":"内服：以少许滴入汤剂中或和酒坎。外用：涂擦患处。","d":"为淡黄或无色得澄明油状物，有丁香的特殊芳香气。露置空气中或贮存日久，则渐渐浓厚而色变综黄。不溶于水，易溶于醇、醚或冰醋酸中。比重为1.038～1.060。"},"凤尾草":{"a":"井口边草(《本草拾遗》)，小金星风尾、铁脚鸡(《履巉岩本草》)，山鸡尾，井茜(《生草药性备要》)，井阑草、石长生(《植物名实图考》)，凤凰草(《分类草药性》)，井边茜(《岭南采药录》)，旋鸡头、阉鸡尾(《中国药植志》)，凤尾蕨、野鸡尾(《广西中兽医药植》)，青蕨(《陆川本草》)，鸡脚草(《南宁市药物志》)，百脚草、龙须草(《江西民间草药》)，金鸡尾、腊肾草(《四川中药志》)，百脚鸡(《中国药植图鉴》)，金鸡爪、井口鸡胶舌(《闽东本草》)，井栏茜、小叶凤尾草(《广东中药》Ⅱ)，小风尾(广州空军《常用中草药手","s":"味淡微苦，性寒。\n\n①《生草药性备要》：\"味辛，性平。\"\n\n②《分类草药性》：\"性凉，无毒。\"\n\n③《福建民间草药》：\"咸，寒，微毒。\"\n\n④《本草推陈》：\"酸苦，寒。\"\n\n⑤广州部队《常用中草药手册》：\"甘淡微苦，寒。\"","f":"清热利湿，凉血止血，消肿解毒。治黄疸型肝炎，肠炎，菌痢，淋浊，带下，吐血，衄血，便血，尿血，扁桃体炎，腮腺炎，痈肿疮毒，湿疹。\n\n①《生草药性备要》：\"洗疳、疗、痔，散毒，敷疮。\"\"治蛇咬诸毒，刀伤，能止血生肌，舂汁调酒服，渣敷患处。研末收贮治气痛。\"\n\n②《岭南采药录》：\"晒干为末，治气痛热痛。\"\n\n③《植物名实图考》：\"治五淋，止小便痛。\"\n\n④《分类草药性》：\"治一切热毒，消肿，清火。治痈疮，乳痈，淋症。\"\n\n⑤《中国药植志》：\"止泻。\"\n\n⑥《贵州民间方药集》：\"解热，利尿。治小儿惊风，夜哭。\"\n\n⑦《广西药植志》：\"清大肠、肺热。治热性赤痢及齿痛，止吐血。\"\n\n⑧《中国药植图鉴》：\"治疥癣。\"\n\n⑨《泉州本草》：\"治湿热小便不通，血淋，咽喉肿痛。\"\n\n⑩《湖南药物志》：\"治疳积，感冒，目翳。\"\n\n⑾广州部队《常用中草药手册》：\"清热，利湿，凉血。治菌痢，肠炎，外感发热，尿路感染，白带，腮腺炎，疔疮，湿疹。\"\n\n⑿《江西草药》：\"治瘰疬，鼻衄，便血。\"\n\n⒀《上海常用中草药》：\"治黄疸型肝炎，扁桃体炎，遗精，蛲虫病。\"","y":"内服：煎汤，3～6钱(鲜品1～2两)；研末或捣汁饮。外用：捣敷或煎水洗。","d":"1.性状鉴别 商品多扎成小捆。全草长25-70cm。根茎短，棕褐色，下面丛生须根，上面有簇生叶，叶柄细，有棱，棕黄色或黄绿色，长4-30cm，易折断，叶片草质，一回羽状，灰绿色或黄绿色；不育叶羽片工4-8cm，边缘有不整齐锯齿，能育叶长条形，宽3-6cm，边缘反卷，孢子囊群生于羽片下面边缘。气微，味淡或微涩。2.显微鉴别 叶表面观：上下表皮细胞垂周壁波状弯曲，下表皮有气孔及少数腺毛。气孔主为不定式，副卫细胞3-4个。腺毛头部2-3个细胞，长91-125μm，直径18-33μm，细胞含棕色分泌物；无柄。孢子囊长圆形或类圆形，直径约至320μm，环带纵行细胞类长方形，外壁薄，内壁及侧壁增厚；囊柄4-6细胞，2列，长短不一。孢子极面观类三角形，直径33-47μm，近极面具三裂缝，有瘤状或颗粒状纹饰，远极面纹饰较大，呈块状。"},"肿节风":{"a":"草珊瑚,接骨木,九节茶。","s":"：性微温，味苦、辛。","f":"?","y":"内服：煎汤，9-15g；或浸酒。外用：适量，捣敷；研末调敷；或煎水熏洗。","d":"理化鉴别 （1）取本品粉末0.5g，置试管中，加锌粉少许和0.5％氯化铵溶液2滴，微火加热至干，在试管口盖以一小片在5％对二甲氨基本甲醛和20％三氯乙酸苯溶液中浸润过的滤纸，继续微火加热约lmin，滤纸显粉红色至紫色圆斑。（检查琥珀酸及延胡索酸）（2）取本品粉末少许，加乙醇0.5ml，置水浴中微热，取滤液点于滤纸上，干燥后在紫外光灯下观察，显亮蓝色荧光，氨熏后，显黄色荧光。（检查黄酮类）"},"鹿角":{"a":"花鹿角、马鹿角","s":"咸，温。\n\n①《本经》：\"温。\"\n\n②《别录》：\"味咸，微温，无毒。\"","f":"行血，消肿，益肾。治疮疡肿毒，瘀血作痛，虚劳内伤，腰脊疼痛。\n\n①《本经》：\"主恶疮痈肿，逐邪恶气，留血在阴中。\"\n\n②《别录》：\"除小腹血急痛，腰脊痛，折伤恶血，益气。\"\n\n③《千金·食治》：\"屑服方寸匕，日三，益气力，强骨髓，补绝伤。\"\n\n④孟诜：\"妇人梦交者，鹿角末三指撮，和清酒服；女子胞中余血不尽欲死者，以清酒和鹿角灰服方寸匕，日三夜一。\"\n\n⑤《日华子本草》：\"疗患疮痈肿热毒等，醋摩敷；脱精尿血，水摩服；小儿重舌鹅口疮，炙熨之。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。外用：磨汁涂或研末调敷。","d":"①花鹿角\n为梅花鹿的老角，呈分枝状，三岔或四岔，长约30～50厘米，左右两枝对称.主枝稍向后面弯曲，直径2.5～4.5厘米。分枝向两旁伸张；枝端渐细。基部有盘状突起，习称\"珍珠盘\"。表面黄棕色，枝端浅黄白色，无毛，有光泽，具疣状突起，习称\"骨钉\"，并有纵棱。质硬。断面周围白色，中央灰色，并有细蜂窝状小孔。气无，味微咸。以质坚、全体有骨钉、光泽者为佳。\n主产吉林、辽宁、黑龙江；河北、北京等地亦产。\n\n②马鹿角\n为马鹿的老角。形与花鹿角相似，每枝多为3～6岔。全长50～60厘米，直径约3～6厘米。表面灰褐色或灰黄色，骨钉不显著，基部有珍珠盘。骨质坚硬，断面外围白色层极厚，中央多灰黑色，有的微呈红色，具粗蜂窝状孔。气无，味微咸。以粗壮坚实、无枯朽者为佳。\n主产黑龙江、吉林、内蒙古、新疆、青海；甘肃、云南、湖南、西藏等地亦产。\n\n鹿角除上述品种外，尚有野生的白鹿、白唇鹿、水鹿的角亦作鹿角使用。商品在四川称为草角(白鹿角)、岩角(白唇鹿角)、春角(水鹿角)，产量均少，品质亦差。"},"飞天蠄蟧":{"a":"龙骨风、大贯众(《广西实用中草药新选》)，山蠄蟧(广东)。","s":"苦涩，凉。\n\n《广西实用中草药新选》：\"苦湿，平，有小毒。\"\n\n入肺经。","f":"清肺胃热，祛风除湿。治流感，肺热咳喘，吐血，风火牙痛，风湿关节痛，腰痛。\n\n①《岭南采药录》：\"治哮喘咳嗽，内伤吐血，骨痛，腹痛，风火牙痛，小肠气痛。\"\n\n②《广西实用中草药新选》：\"驱风湿，强筋骨。治风湿性关节痛，跌打损伤；并可预防流感。\"","y":"内服：煎汤，0.5～1两；或炖肉。外用：煎水洗或取鲜汁擦患部。","d":"干燥的主干呈圆柱形，直径约12厘米，表面棕色，全体有排列较整齐的叶柄痕；每一叶柄痕近圆形，直径约3～4厘米，下方有凹陷，边缘有多数排列紧密的叶迹维管束，中间亦有叶迹维管束散在。断面中空，周围的维管束排成折叠状，形成隆起的脊和纵沟。质坚硬。\n主产广东、广西。"},"韭菜":{"a":"丰本、草钟乳、起阳草、懒人菜、长生韭、壮阳草、扁菜","s":"辛，温。\n\n\n①《别录》：\"味辛酸，温，无毒。\"\n\n\n②《日华子本草》：\"热。\"\n\n\n③《滇南本草》：\"性温，味辛咸。\"\n\n\n④《纲目》：\"生性涩，熟甘酸。\"\n\n\n入肝、胃、肾经。\n\n\n①《滇南本草》：\"入肾。\"\n\n\n②《纲目》：\"入足厥阴经。\"\n\n\n③《雷公炮制药性解》：\"入肺、脾、肾三经。\"","f":"温中，行气，散血，解毒。治胸痹，噎膈、反胃，吐血、衄血、尿血，痢疾，消渴，痔漏、脱肛，跌扑损伤，虫、蝎螫伤。\n\n\n①《别录》：\"安五藏，除胃中热。\"\n\n\n②陶弘景：\"以煮鲫鱼蚱，断卒下利。\"\n\n\n③《食疗本草》：\"利胸膈。\"\n\n\n④《本草拾遗》：\"温中，下气，补虚，调和腑脏，令人能食，益阳，止泄白脓、腹冷痛，并煮食之。叶及根生捣绞汁服，解药毒，疗狂狗咬人欲发者;亦杀诸蛇、虺、蝎、恶虫毒。\"\n\n\n⑤《日华子本草》：\"止泄精尿血，暖腰膝，除心腹痼冷、胸中痹冷、痃癖气及腹痛等，食之肥白人。中风失音研汁服，心脾胃痛甚，生研服，蛇、犬咬并恶疮，捣敷。\"\n\n\n⑥《本草衍义补遗》：\"研汁冷饮，可下膈中瘀血，能充肝气。\"\n\n\n⑦《丹溪心法》：\"经血逆行，或血腥、或吐血、或唾血，用韭汁服之。\"\"跌扑损伤在上者，宜饮韭汁，或和粥吃。\"\n\n\n⑧《滇南本草》：\"滑润肠胃中积，或食金、银、铜器于腹内，吃之立下。\"\n\n\n⑨《纲目》：\"饮生汁，主上气喘息欲绝，解肉脯毒。煮汁饮，止消渴、盗汗，熏产妇血运，洗肠痔脱肛。\"\n\n\n⑩《贵州民间方药集》：\"治年久喘吼，又可通经催乳。\"","y":"内服：捣汁饮，1～2两；或炒熟作菜食。外用：捣敷、取汁滴注、炒热熨或煎水熏洗。","d":"?"},"山楂叶":{"a":"?","s":"酸；平","f":"叶和花泡茶服可治高血压。\n\n《肘后方》：\"茎叶煮汁，洗漆疮。\"","y":"内服：煎汤，3-10g；或泡茶饮。外用：适量，煎汤洗。","d":"?"},"分心木":{"a":"胡桃衣(《本草再新》)，胡桃夹(《现代实用中药》)，胡桃隔(《山东中草药手册》)。","s":"《本草再新》：\"味苦涩，性平，无毒。\"\n《本草再新》：\"入脾、肾二经。\"","f":"固肾涩精。治遗精滑泄，淋病，尿血，遗溺，崩中，带下，泻痢。\n\n①《本草再新》：\"健脾固肾。\"\n\n②陈念祖：\"收涩精气。\"\n\n③《山西中药志》：\"利尿清热。治淋病尿血，暑热泻痢。\"\n\n④《中药材手册》：\"治遗溺，崩中下血。\"\n\n⑤《陕西中药志》：\"治耳聋。\"\n\n⑥《天津中草药》：\"固涩收敛。治遗精，尿频，带下。\"","y":"内服：煎汤，2～3钱。","d":"木质隔膜呈薄片状，多弯曲、破碎而不整齐。表面淡棕色至棕褐色，或棕黑色，略有光泽。质脆，易折断，气微，味微苦。以块大、质薄、色黄为佳。\n主产河北、山西、山东。"},"乌榄":{"a":"木威子、乌橄榄、黑榄。","s":"味酸、涩；性平。归脾，肺经。\n\n①《广州记》：\"苦涩。\"\n\n②《本草拾遗》：\"酸，平，无毒。\"\n\n③《纲目》：\"酸，辛，无毒。\"\n\n④《纲目拾遗》：\"性温，味涩甘。\"","f":"止血，化痰，利水，消痈肿。主内伤吐血；咳嗽痰血；水肿；乳痈；外伤出血\n\n\n①《本草拾遗》：\"主心中恶水，水气。\"\n\n②《生草药性备要》：\"止血。\"\n\n③《本草求原》：\"功近橄榄。\"\n\n④《岭南采药录》：\"火煅存性，止血化痰。少盐渍之，名榄豉，乳痈初起，煎水洗之可消。\"","y":"内服：煎汤，3-10g。外用：适量，煎水洗；或捣敷；或研末撒。","d":""},"老头草":{"a":"小矛香艾,老头艾","s":"味苦；性寒。\n\n《东北常用中草药手册》：\"微苦，寒。\"","f":"清热凉血。用于感冒发热；咽喉炎；肾炎。\n\n①《东北常用中草药手册》：\"清热凉血，益肾利水。治急性肾炎，尿血。\"\n\n②《北方常用中草药手册》：\"清热凉血，消炎利尿。治急，慢性肾炎，对消失蛋白尿和血尿有效。\"","y":"内服：煎汤，3～4钱。","d":"?"},"枸橘":{"a":"臭橘(《本草图经》)，枸棘子(《履巉岩本草》)，野橙子(《纲目》)，唐橘(《中国树木分类学》)，枸橘李、钢橘子(《江苏植药志》)，枸甏李、野梨子、苦桶子(《上海常用中草药》)。","s":"辛苦，温。\n\n①《本经逢原》:\"辛，温，无毒。\"\n\n②《上海常用中草药》:\"辛苦，温。\"","f":"疏肝，和胃，理气，止痛。治胸腹胀满，胃痛，疝气，睾丸肿胀，乳房结核，子宫下垂，跌打损伤；解酒毒。\n\n①《本经逢原》:\"破气散热，解酒毒。\"\n\n②《纲目拾遗》:\"疗子痈及疝气，整个枸橘煅存性，研末，陈酒送服。\"\n\n③《植物名实图考》:\"治跌打。\"\n\n④《中国药植图鉴》:\"发汗，健胃，祛痰，利尿。治胸腹满痛。\"\n\n⑤《上海常用中草药》:\"利气，健胃，通便。治胃部胀满，消化不良，便秘，子宫脱垂，乳房结核。\"","y":"内服:煎汤，1.5～3钱(大剂可用至1两)；或煅存性研末。外用:煎水洗或熬膏涂。","d":"干燥果实呈圆球形，直径2～3.5厘米，表面黄色或黄绿色，散有无数小油点及网状隆起的皱纹，密被短柔毛，顶端有显明的柱基痕，基部有短果柄或果柄痕存在，断面果皮厚2～3毫米，黄白色，沿外缘散有黄色油点，中间有6～8果瓤，每瓢内有黄白色长椭圆形的种子数粒。\n产江苏、浙江、四川、江西、福建、广东、广西等地。"},"柳叶":{"a":"?","s":"①《纲目》:\"苦，寒，无毒。\"\n\n②《本草再新》:\"柳头(枝梢嫩叶)味苦，性凉，无毒，\"","f":"清热，透疹，利尿，解毒。治痧疹透发不畅，白浊，疔疮疖肿，乳腺炎，甲状腺肿，丹毒，烫伤，牙痛。\n\n①《别录》:\"疗心腹内血，止痛。\"\n\n②陶弘景:\"疗漆疮。\"\n\n③《日华子本草》:\"治天行热病，疔疮，传尸骨蒸劳，汤火疮毒入腹热闷；并下水气；煎膏续筋骨，长肉止痛；牙痛煎含。\"\n\n④《纲目》:\"疗白浊，解丹毒。\"\n\n⑤《本草再新》:\"柳头平肝，发(散)热，能托能升，败毒，发斑，治小儿痧痘等症。\"","y":"内服:煎汤，鲜者1～2两。外用:煎水洗、研末调敷或熬膏涂。","d":"?"},"百药煎":{"a":"?","s":"酸甘，平。\n\n①《医学入门》：\"味酸，无毒。\"\n\n②《纲目》：\"酸咸微甘，无毒。\"\n\n③《要药分剂》：\"味酸咸，无毒。\"\n\n归心；肺；胃经\n\n\n①《本草求真》：\"入肺、胃。\"\n\n\n②《要药分剂》：\"入心、肺二经。\"","f":"润肺化痰，生津止渴。治久咳痰多，咽痛，便血，久痢脱肛，口疮，牙疳，痈肿疮疡。\n\n①《本草蒙筌》：\"治肺胀喘咳不休。\"\n\n②《医学入门》：\"润肺治嗽，化痰，止渴。疗肠风下血；为末糁诸疮，干水敛口。\"\n\n③《纲目》：\"清肺化痰，定嗽解热，生津止渴，收湿消酒。止下血，久痢，脱肛，牙齿宣匿，面鼻疳蚀，口舌糜烂，风湿诸疮。\"","y":"内服：煎汤，1～3钱；或入丸、散。外用：研末撒、调敷或泡汤含漱。","d":"为灰褐色之小方块，表面间有黄白色斑点，微具香气。"},"猪胆":{"a":"?","s":"苦，寒。\n\n①《别录》：\"微寒。\"\n\n②《本草图经》；\"大寒。\"\n\n③《汤液本草》：\"味苦咸，寒。\"\n\n肝；胆；肺；大肠经","f":"清热，润燥，解毒。治热病里热燥渴、便秘，黄疸，百日咳，哮喘，泄泻，痢疾，目赤，喉痹，聤耳，痈肿疔疮。\n\n①《别录》：\"疗伤寒热渴。\"\n\n②《本草拾遗》：\"主小儿头疮，取胆汁敷之。\"\n\n③《本草图经》：\"主骨热劳极，伤寒及渴疾，小儿五疳，杀虫。\"\n\n④《纲目》：\"通小便，敷恶疮，杀疳匿，治日赤、目翳，明日，清心脏，凉肝脾。\"\n\n⑤《随息居饮食谱》：\"补胆，清热，治热痢，通热秘。治厥颠疾。\"","y":"内服；煎汤，取汁冲服1～2钱；或入丸，散。外用：涂敷、点眼或灌肠。","d":"?"},"枳椇子":{"a":"木蜜(陆玑《诗疏》)，树蜜、木饧(崔豹《古今注》)，白石木子(《荆楚岁时记》)，蜜屈律(《太平广记》)，鸡距子、癞汉指头(《苏沈良方》)，栞栱(《埤雅》)，背洪子、兼穹(《朱子大全》)，拐枣(《救荒本草》)，天藤、还阳藤(《滇南本草》)，木珊瑚、鸡爪子、鸡橘子、结留子、曹公爪、棘枸(《纲目》)，白石枣(《医林纂要》)，万寿果(《药物出产辨》)，鸡爪梨、甜半夜，龙爪(《中国树木分类学》)，碧久子(《广州植物志》)，金钩钩、酸枣(《江苏植药志》)，鸡爪果(《南宁市药物志》)，枳枣(《中药志》)，转钮子(江西《","s":"甘酸，平。\n\n①《唐本草》:\"味甘，平，无毒。\"\n\n②《本草再新》:\"味甘酸，性平，无毒。\"","f":"治酒醉，烦热，口渴，呕吐，二便不利。\n\n①《荆楚岁时记》:\"辟虫毒。\"\n\n②《唐本草》:\"主头风，小腹拘急。\"\n\n③《本草拾遗》:\"止渴除烦，润五脏，利大小便，去膈上热，功用如蜜。\"\n\n④《滇南本草》:\"治一切左瘫右痪，风湿麻木，能解酒毒；或泡酒服之，亦能舒筋络。小儿服之，化虫，养脾。\"\n\n⑤《滇南本草图说》:\"补中益气。痰火闭结于胸中，用此可解。\"\n\n⑥《纲目》:\"止呕逆。\"","y":"内服:煎汤，3～5钱；浸酒或入丸剂。","d":"①干燥带果柄的果实\n果柄膨大，肉质肥厚，多分枝，弯曲不直，形似鸡爪，在分枝及弯曲处常更膨大如关节状，分枝多呈丁字形或相互成垂直状，长3～5厘米或更长，直径4～6毫米。表面棕褐色，略具光泽，有纵皱纹，偶见灰白色的点状皮孔。分枝的先端，着生1枚钝三棱状圆球形的果实，果皮纸质，甚薄，3室，每室含种子1粒。果柄质稍松脆，易折断，折断面略平坦，角质样，淡红棕色至红棕色。气微弱，味淡或稍甜。\n\n②干燥种子\n呈扁平圆形，背面稍隆起，腹面较平，直径3～5毫米，厚约2毫米。表面红棕色至红褐色，平滑光泽，基部有描圆形点状的种脐，顶端有微凸的合点，腹面有一条纵行而隆起的种脊。种皮坚硬，厚约1毫米，胚乳乳白色，油质，其内包围有2片肥厚的子叶，呈淡黄色至草绿色，亦油质。气微弱，味苦而涩。\n\n上述药材，主产陕西、广东、湖北、浙江、江苏、安徽、福建，此外，江西、湖南、四川、云南、贵州、河北；西藏等地亦产。"},"野葡萄根1":{"a":"刺葡萄、 千斤藤、山葡萄，蛇葡萄","s":"味甘，微苦，性平，无毒；归肝，肾经。\n《重庆草药》：\"味甘，性平，无毒。\"","f":"清热解毒，祛风除湿，散瘀消肿。用于：（1）肺痈，肠痈；（2）瘰疬，结核；（3）风湿关节痛，腰腿痛；（4）跌打损伤，骨折肿痛；（5）痈肿疮毒，烧烫伤，毒蛇咬伤等；（6）慢性骨髓炎\n①《分类草药性》：\"治痔疮，遗精白浊。\"\n\n⑧《重庆草药》：\"行血，活血，消积。治吐血，消肿胀。也用于跌打药酒中。\"","y":"内服：煎汤，2～4两。外用：适量，捣敷","d":"性状鉴别：根呈圆柱形，长短不一，直径1.5--5cm，表面灰褐色或棕褐色，粗糙，具不规则的纵皱纹及深浅不一的横向裂纹。细根的栓皮常呈片状脱落。质坚硬，难折断，这段是有粉尘飞出。断面呈棕红色，显粗纤维性，有多数孔洞（导管）及放射状纹理。气微，味淡。"},"血见愁":{"a":"大叶藜、杂配藜，杂灰藜，大叶灰菜，八角灰菜。","s":"《东北常用中草药手册》：\"甘，平。\"","f":"止血，活血。治月经不调，崩漏，咯血，衄血，尿血，疮痈肿毒。\n\n①《东北药植志》：\"止血。\"\n\n②《黑龙江中药》：\"用于月经不调，妇女血病。\"\n\n③《东北常用中草药手册》：\"治月经不调，崩漏，肺结核咯血，尿血。\"","y":"内服：煎汤，1～3钱；或熬膏。","d":"?"},"莲须":{"a":"金樱草(《品汇精要》)，莲花须(《医学正传》)，莲花蕊(《孙天仁集效方》)，莲蕊须(《纲目》)。","s":"甘涩，平。\n\n①《本草从新》：\"甘，平而涩。\"\n\n②《医林纂要》：\"苦甘涩，平。\"\n\n③《本草再新》：\"味甘淡，性清凉，无毒。\"","f":"清心，益肾，涩精，止血。治梦遗滑泄，吐、衄、崩、带，泻痢。\n\n①《本草蒙筌》：\"益肾，涩精，固髓。\"\n\n②《纲目》：\"清心通肾，固精气，乌须发，悦颜色，益血，止血崩、吐血。\"\n\n③《本草通玄》：\"治男子肾泄，女子崩带。\"\n\n④《会约医镜》：\"除泻痢。\"\n\n⑤《本草再新》：\"清心肺之虚热，解暑除烦，生津止渴。\"","y":"内服：煎汤，0.8～1.5钱；或入丸、散。","d":"干燥雄蕊呈线状，花药长1～1.5厘米，直径约0.5毫米，多数扭转呈螺旋状，黄色或浅棕黄色，2室，纵裂，内有多数黄色花粉。花丝呈丝状而略扁，稍弯曲，长1～1.6厘米，棕黄色或棕褐色。质轻。气微香，味微涩。以干燥、完整、色淡黄、质软者为佳。\n主产湖南、湖北、福建、江苏、浙江、江西等地。"},"木馒头":{"a":"木莲(《本草拾遗》)，水馒头(《岭外代答》)，鬼馒头(《纲目》)，蔓头萝(《生草药性备要》)，凉粉果、木铎，桔杷、文头果、文头榔、糖馒头(《中国树木分类学》)，馒头郎(《广州植物志》)，牛奶子、牛奶柚、金柚奶、假秤锤、程邦子、水子(《福建民间草药》)，鬼球(《药材资料汇编》)，木果蒲、胖朴(《浙江中药手册》)，爬墙果、爬壁果(《四川中药志》)，薜荔果、膀膀子(《湖南药物志》)，凉粉子、烹泡子(《江西草药》)。","s":"甘。平.\n\n①《纲目》：\"甘，平，涩，无毒。\"\n\n②《得配本草》：\"甘酸，寒。\"","f":"通乳，利湿，活血，消肿。治乳汁不下，遗精，淋浊，乳糜尿，久痢，痔血，肠风下血，痈肿，疔疮。\n\n①《本草拾遗》：\"破血。\"\n\n②《本草图经》：\"能壮阳道。\"\n\n③《纲目》：\"固精，消肿，散毒，止血，下乳。治久痢肠痔，心痛阴颓。\"\n\n④《生草药性备要》：\"通经行血。煲食下乳，消肿毒；洗疳、疔、痔，理跌打。\"\n\n⑤《本经逢瓯》：\"治一切风癣恶疮，为利水活血通乳要药。\"\n\n⑥《得配本草》；\"活血生用，止血煅用。\"","y":"内服；煎汤，2～5钱；或入丸、散；外用：煎水洗。","d":"干燥花序托，膨大成梨形或倒卵形，黄褐色至黑褐色，长4～6厘米，直径约4厘米，顶端近截形，中央有一稍突出的小孔，孔内有膜质的小苞片充塞，孔外通常有细密的褐色绒毛；下端渐狭，具有短的果柄痕迹，质坚硬而轻，内生无数单性花或黄棕色圆球状瘦果。以个大、干燥者为佳。\n\n主产江苏、四川、浙江、广东，广西等地。"},"紫金龙":{"a":"串枝莲、黑牛膝、川山七、豌豆跌打、大麻药、豌豆七、野豌豆。","s":"辛，苦，凉；肝胃肾经\n①《云南中草药》：\"辛微苦，凉，有毒。\"\n\n②《云南思茅中草药选》：\"苦麻，性寒。\"","f":"镇痛；止血；降血压。主神经性头痛；牙痛；胃痛；风湿关节痛等各种痛证；跌打损伤；外伤出血；产后出血不止；崩漏下血及高血压病\n①《云南中草药》：\"止血，清热消炎，麻醉镇痛。治高血压，外伤出血，跌打损伤，骨折。\"\n\n②《云南思茅中草药选》：\"止血收敛，舒筋络，止痛。治神经性头痛，牙痛，关节痛，胃痛，痧症。\"\n\n③《云南中草药选》：\"止血。治血崩，妇女产后流血过多。\"","y":"","d":""},"桐油":{"a":"桐子油(《纲目》)。","s":"甘辛，寒，有毒。\n\n①《日华子本草》：\"冷，微毒。\"\n\n②《纲目》：\"甘微辛，寒，有大毒。\"","f":"探吐风痰。外用治疥癣，臁疮，汤火伤，冻疮皲裂。\n\n①《本草拾遗》：\"摩疥癣虫疮，毒肿。\"\n\n②《日华子本草》：\"敷恶疮疥及宣水肿。\"\n\n③《纲目》：\"涂胫疮、汤火伤疮；吐风痰喉痹，及一切诸疾，以水和油，扫入喉中探吐。\"","y":"外用：涂擦、调敷或探吐。","d":"?"},"白降丹":{"a":"降丹、降药、水火丹","s":"味辛，性热；有毒。归脾经。","f":"消痈；溃脓；蚀腐；杀虫。主痈疽发背；疔疮；瘰疬；脓成不溃；腐肉难消；风癣疥癞\n.\n《医宗金鉴》：\"治痈疽发背，一切疔毒。水调敷疮头上，初起者立刻起疱消散，成脓者即溃，腐者即脱，消肿。\"","y":"外用：研末撒疮头上，或合他药研末调涂，或作药拈。","d":"1.性状鉴别 为针状结晶聚集而成的块状物；白色或微黄色，与碗接触的一面平滑而光亮，有时微带淡玫瑰紫色，另一面与折断面，均呈明显的针状结晶，微有光泽。不透明。质重，易碎。比重5.4。气无，味辣，并有持久性金属味。粉末为白色针状结晶。以色白、条状、有光泽、贮存年久者为佳。于闭口管中加热至227℃时，熔成无色液体，约300℃时升华，水溶液显汞化合物与氯化物的各种特殊反应。\n各地均可制造，以江西、湖南、湖北产量较大。\n2.显微鉴别 取碎屑少许，制成油浸薄片，于透射偏光镜下，无色透明，条柱状；正高突起。斜消光，消光角26°。正延性。\n3.化学鉴别 （1）取本品约0.1g，加水5ml与稀硝酸1滴，使其溶解，静置。①取上清液显汞盐的鉴别反应。参见朱砂条。②取上清液，加硝酸，使成酸性后，滴加硝酸银试液，即生成白色凝乳状沉淀，分离，沉淀加氨试液即溶解，再加硝酸，沉淀复生成。（检查氯化物）（2）X射线衍射分析曲线 4.12(10),3.15(>10),2.23(3)，1.96（4），1.58（3）(相当于汞膏)；3.26(<1),2.71(<1),2.06(1)(相当于黄氯汞矿)。\n(3)差热分析曲线 吸热290℃(小)，250℃始溶解。整个特点同轻粉"},"冰糖":{"a":"?","s":"味甘，性平，无毒。\n\n\n入脾、肺二经。","f":"补中益气，和胃润肺。止咳嗽，化痰涎。","y":"内服：煎汤，3～5钱；含化或入丸剂、膏剂。","d":"?"},"燕窝":{"a":"燕窝菜(《闽部疏》)，燕蔬菜(《纲目拾遗》)，燕菜(《现代实用中药》)。燕根(《药材学》)。","s":"甘，平。\n\n\n1.《本经逢原》：“甘，平，无毒。”\n\n\n2.《本草从新》：“甘淡，平。燕窝脚：微咸。”\n\n\n3.《本草再新》：“味甘咸，性平，有微毒。”\n\n\n入肺、胃、肾经。\n\n\n①《本草求真》：\"入肺、脾、肾。\"\n\n\n②《本草再新》：\"入心、肺、肾三经。\"","f":"养阴润燥，益气补中。治虚损，痨瘵，咳嗽痰喘，咯血，吐血，久痢，久疟，噎膈反胃。\n\n\n1.《物理小识》：.“止小便数。”\n\n\n2.《本经逢原》：“调补虚劳，治咳吐红痰。”\n\n\n3.《闽小记》：“白色(者)能愈痰疾，红色(者)有益小儿痘疹。”\n\n\n4.《本草从新》：“大养肺阴，化痰止嗽，补而能清，为调理虚损痨瘵之圣药，一切病之由于肺虚，不能清肃下行者，用此皆可治之。开胃气，已痨痢，益小儿痘疹。\"\"燕窝脚：能润下，治噎膈甚效。”\n\n\n5.《岭南杂记》：“血燕，能治血痢;白者入梨加冰糖蒸食，能治膈痰。”\n\n\n6.《食物宜忌》：“壮阳益气，和中开胃，添精补髓，润肺，止久泻，消痰涎。”\n\n\n7.《本草再新》：“大补元气，润肺滋阴，治虚劳咳嗽，咯血，吐血，引火归源，滑肠开胃。”","y":"内服：绢包煎汤，隔汤炖，1.5～3钱：或入膏剂。","d":"呈不整齐的半月形，长约6.5～10厘米，宽约3～5厘米，凹陷成兜状。附着于岩石的一面较平，外面微隆起，附着面粘液凝成层排列较整齐，较隆起面细致，呈波状，窝的内部粗糙，呈丝瓜络样。质硬而脆，断面微似角质。入水则柔软而膨大。\n\n\n商品有白燕、毛燕、血燕之分。白燕(又名官燕)色洁白，偶带少数绒羽;毛燕色灰，内有较多的灰黑色羽毛;血燕则含有赤褐色的血丝。以白燕的品质为最佳。\n\n\n产印度尼西亚、泰国、缅甸、日本等地。"},"黄鹌菜":{"a":"苦菜药、三枝香(《广西药植名录》)，黄花菜、山芥菜、土芥菜、野芥菜、野芥兰、芥菜仔，臭头苦苴(福建晋江《中草药手册》)。","s":"福建晋江《中草药手册》：\"甘微苦，凉，无毒。\"\n\n入肺经。","f":"清热，解毒，消肿，止痛，治感冒，咽痛，乳腺炎，结膜炎，疮疖，尿路感染，白带，风湿关节炎。\n\n①《广西药植名录》：\"消肿，止痛。治感冒。\"\n\n②福建晋江《中草药手册》：\"清热解毒，通结气，利咽喉。\"\n\n③《常见混淆中草药的识别》：\"抗菌消炎。治疮疖，乳腺炎，扁桃体炎，尿路感染，白带，结膜炎，风湿性关节炎。\"","y":"内服：煎汤，3～5钱(鲜品1～2两)。外用：捣敷或捣汁含漱。","d":"?"},"番茄":{"a":"西红柿、番李子(《广州植物志》)，金橘(《陆川本草》)。","s":"《陆川本草》：\"甘酸，微寒。\"","f":"《陆川本草》：\"生津止渴，健胃消食。治口渴，食欲不振。\"","y":"内服：煎汤或生食。","d":"?"},"水红花子":{"a":"水荭子(《本草衍义》)，荭草实(《纲目》)，河蓼子(《山东中药》)，川蓼子、水红子(《上海常用中草药》)。","s":"咸，寒。\n\n①《别录》：\"味咸，微寒，无毒。\"\n\n②《滇南本草》：\"性寒平，味苦。\"\n\n③《药材资料汇编》：\"辛，无毒。\"\n\n④《药材学》：\"性平，味甘。\"","f":"消瘀破积，健脾利湿。治胁腹癥积，水臌，胃疼，食少腹胀，火眼，疮肿，瘰疬。\n\n①《别录》：\"主消渴，去热，明目，益气。\"\n\n②《滇南本草》：\"破血，治小儿痞块积聚，消年深坚积，疗妇人石瘕症。\"\n\n③《品汇精要》：\"明眼目，消疮毒。\"\n\n④《国药提要》：\"去热，治烦渴及颈淋巴腺炎。\"\n\n⑤《药材学》：\"清肺化痰，降气通便，透疹。治痰嗽喘咳，大小便不利，麻疹不透。\"\n\n⑥《上海常用中草药》：\"散血，消积，止痛。\"\n\n⑦《新疆中草药手册)：\"健脾利湿，清热明目。治慢性肝炎，肝硬化腹水，颈淋巴结核，脾肿大，消化不良，腹胺胃痛，小儿食积，结膜炎。\"","y":"内服：煎汤，2～3钱(大剂1两)；研末、熬膏域浸酒。外用：熬膏或捣烂敷。","d":"①水荭子\n为植物荭草的干燥果实，呈扁圆形，直径2～3毫米，厚1～1.5毫米。表面棕黑色，或红棕色，有光泽，两侧面微凹入，其中央呈微隆起的线状，先端有刺状突起的柱基，基部有浅棕色略突起的果柄痕，有时残留膜质花被。果皮厚而坚硬。种子扁圆形，种皮浅棕色膜质；胚乳粉质，类白色，胚细小弯曲，略成环状。气微弱，味淡。以饱满充实，色红黑者为佳。\n\n②辣蓼草子\n又名：水红蓼子。为植物酸模叶蓼或柳叶蓼的干燥果实，呈卵圆形，直径约1～2毫米，厚不及1毫米。表面红棕色。细小弯曲的胚位于一侧，成半环状，其余与水荭子同。\n主产江苏、辽宁。四川、山东、吉林等地亦产。"},"鸡爪草":{"a":"凤尾草、井口边草、铁脚鸡、山鸡尾、井阑草","s":"《四川中药志》：\"性温，味甘辛，无毒。\"","f":"《四川中药志》：\"散寒表汗。治风湿麻木，鸡爪风，消瘰疬。\"","y":"内服：煎汤，0.5～1两；或浸酒。","d":"?"},"猪毛菜":{"a":"扎蓬棵、刺蓬、三叉明棵、猪毛缨、叉明棵、猴子毛、蓬子菜、乍蓬棵子、蓬豆芽、轱辘娃子","s":"淡；性凉 \n\n①《河北中药手册》：\"淡，凉。\"\n\n②《甘肃中草药手册》：\"甘，凉。\"\n\n归肝经","f":"平肝潜阳；润肠通便。主高血压病；多病；眩晕；失眠；肠燥便秘 \n\n《河北中药手册》：\"降血压。治高血压病、头痛。\"","y":"内服：煎汤，0.5～1两。","d":"性状鉴别 全草黄白色。叶多破碎，完整叶片丝状圆柱形，长2-5cm，宽0．5-1mm，先端有硬针刺。花序穗状，着生于枝上部，苞片硬，卵形，顶部延伸成刺尖，边缘膜质，背部有白色隆脊；花被片先端向中央折曲，紧贴果实，在中央聚成小圆锥体。种子直径约1．5mm，先端平。 \r\n　　显微鉴别 本品花粉粒，在扫描电镜下观察：花粉粒直径1．4-19．9μm，圆形，轮廓线波浪状。孔36-44个，孔径1．15-2．77μm，孔间距离2．26-2．99μm。孔具膜，膜上小刺10-28个。 \r\n　　理化鉴别 取本品粉末5g，用氨水润湿，氯仿20ml浸泡过夜，滤过。滤液挥去氯仿，以1％盐酸2ml溶解，放入试管中，滴加改良碘化铋钾试液，立即产生红棕色沉淀。（检查生物碱）"},"狗肉":{"a":"香肉、地羊、犬肉","s":"咸，温。\n\n①《别录》：\"味咸酸，温。\"\n\n②《日用本草》：\"咸酸，平。\"\n\n③《医学入门》：\"咸酸，有毒。\"","f":"补中益气，温肾助阳。治脾肾气虚，胸腹胀满，鼓胀，浮肿，腰膝软弱，寒疟，败疮久不收敛。\n\n①《别录》：\"主安五藏，补绝伤。\"\n\n②孟诜：\"补血脉，厚肠胃，实下焦，填精髓。\"\n\n③《日华子本草》：\"补胃气，壮阳，暖腰膝，补虚劳，益气力。\"\n\n④《本经逢原》：\"治败疮稀水不敛。\"\n\n⑤《医林纂要》：\"补肺气，固肾气，壮营卫，强腰膝。\"","y":"内服：煮食。","d":"?"},"虎刺":{"a":"刺虎(《本草图经》)，寿星草(《寿域神方》)，寿庭木(《花镜》)，雀不踏、绣花针(《植物名实图考》)，黄脚鸡、天针、老鼠刺(《江西民间草药》)，虎牙刺、千金刺、鹅嘴花根、黄鸡兰、千口针，针上叶、顺茶风、脚不踏、土鸡爪黄连、猫儿刺、小黄连(《湖南药物志》)，两面针、细花针(《广西药植名录》)，鸟不踏(《江西草药》)，蛇不过、朝天刺、钢针木、虎叶、老鼠枪、老虎刺、小叶刺风、高骨老虎刺、红老鼠刺、红远志、白凤珠(《浙江民间常用草药》)。","s":"苦甘，平。\n\n①《本草图经》：\"味甘。\"\n\n②《浙江民间草药》：\"味甘，性平，无毒。\"\n\n③《江西民间草药验方》：\"性平，味苦甘，无毒。\"","f":"祛风利湿，活血消肿。治痛风，风湿痹痛。痰饮咳嗽，肺痈，水肿，痞块，黄疸，妇女经闭，小儿疳积，荨麻疹，跌打损伤。\n\n①《本草图经》：\"理一切肿痛风疾。\"\n\n②《植物名实图考》：\"补气血。\"\n\n③《浙江民间草药》：\"根及花：活血，利关节。治风气。\"\n\n④《杭州药植志》：\"治风湿痛。\"\n\n⑤《广西药植名录》：\"根：止咳，补血气。治肺病，内伤。\"\n\n⑥广州部队《常用中草药手册》：\"利尿消肿，活血散瘀。治急慢性肝炎，脾脏肿大。\"","y":"内服：煎汤，3～5钱(鲜用1～2两)；或入散剂。外用：捣敷、捣汁潦或研末撒。","d":"?"},"蜻蜓":{"a":"灯烃、负劳(《尔雅》)，蟌(《淮南子》)，蝍蛉(《方言》)，桑蜋(《说文》)，胡蝶(崔豹《古今注》)，狐梨(《尔雅》郭璞注)，蜻蛉(《别录》)，诸乘(《本草经集注》)，蜻虰，纱羊(《纲目》)，青娘子(《东医宝鉴》)。","s":"①《别录》：\"微寒。\"\n\n②《日华子本草》：\"凉，无毒。\"","f":"益肾强阴。治肾虚遗精，阳痿。\n\n①《别录》：\"强阴止精。\"\n\n②《日华子本草》：\"壮阳，暖水脏。\"\n\n③《民间常用草药汇编》：\"息风镇惊。\"\n\n④《陆川本草》：\"治肾虚阴萎。\"","y":"内服：煎汤，2～4只；或研末。","d":"?"},"暴马子":{"a":"白丁香,棒棒木,荷花丁香","s":"苦；辛；性微寒 \n\n\n《东北常用中草药手册》：\"苦，微寒。\"\n\n \n归肺经","f":"宣肺化痰；止咳平喘；利水 \n\n主治 慢性支气管炎；哮喘；心脏性浮肿 \n\n《吉林中草药》：\"消炎，镇咳。利水。治痰鸣喘嗽，心脏性浮肿。\"","y":"内服：煎汤，0.5～1两。","d":"树皮含蒿属香豆精（scoparone）即6，7-二甲氧基香见精（6，7－dimethoxy coumarin）[1]，3，4-二羟基-β-羟乙基苯（β-hydroxyethyl-3，4-dihydroxy benzene）［2］，暴马子醛酸甲酯（methylsyramuraldehydate）[3]。"},"忍冬藤":{"a":"老翁须、金钗股、大薜荔、水杨藤、千金藤(《苏沈良方》)，鸳鸯草(《墨庄漫录》)，鹭鸶藤(《履巉岩本草》)，忍冬草(《证治要诀》)，左缠藤(《余居士选奇方》)，忍寒草(《洪氏集验方》)，通灵草、蜜桶藤(《土宿本草》)，金银花藤(《丹溪心法》)，金银藤(《乾坤生意秘韫》)，金银花杆(《滇南本草》)，甜藤(《本草述》)，右篆藤(《分类草药性》)，右旋藤(《贵州民间方药集》)，二花秧、银花秧(《河南中药手册》)。","s":"甘，寒。\n\n①《别录》：\"甘，温，无毒。\"\n\n②《药性论》：\"味辛。\"\n\n③《本草拾遗》：\"小寒。\"\n\n④《本草再新》：\"味甘苦，性微寒。\"","f":"清热，解毒，通络。治温病发热，热毒血痢，传染性肝炎，痈肿疮毒，筋骨疼痛。\n\n①《别录》：\"主寒热身肿。\"\n\n②陶弘景：\"煮汁以酿酒，补虚疗风。\"\n\n③《药性论》：\"主腹胀满，能土气下澼。\"\n\n④《本草拾遗》：\"主热毒血痢水痢。\"\n\n⑤《履巉岩本草》：\"治筋骨疼痛。\"\n\n⑥《滇南本草》：\"宽中下气，消痰，祛风热，清咽喉热痛。\"\n\n⑦《纲目》：\"治一切风湿气及诸肿毒，痈疽疥癣，杨梅恶疮，散热解毒。\"\n\n⑧《本草再新》：\"治心虚火旺，补气宽中，咳嗽，痈痿。。\n\n⑨《南京民间药草》：\"茎叶及花对眼睛发炎时有疗效。\"\n\n⑩《贵州民间方药集》：\"叶：外敷治刀伤。\"\n\n⑾广州部队《常用中草药手册》：\"治湿热腿痛。\"","y":"内服：煎汤，0.3～1两；入丸、散或浸酒。外用：煎水熏洗、熬膏贴或研末调敷。","d":"干燥茎呈细长圆柱形，直径1.5～6毫米，表面暗红色或灰棕色，有细柔毛，尤以嫩枝为多。皮部易剥落，常撕裂作纤维状。茎上常带有椭圆形、绿黄色的叶，多破碎不全。质坚脆，断面灰白色或黄白色，中央髓部有空隙。气弱，味淡。以外皮枣红色、质嫩带叶者为佳。\n主产浙江、四川、江苏、河南、陕西、山东、广西、湖南等地。此外安徽、甘肃、湖北、江西、福建、山西、云南、辽宁、河北等地亦产。"},"三七草":{"a":"土三七,见肿消,乳香草,奶草,泽兰,叶下红,散血草,和血丹,天青地红,破血丹,血牡丹,九头狮子草,白田七草","s":"甘，平。\n\n①《纲目》：\"味甘。\"\n\n②《湖南药物志》：\"辛，平，无毒。\"","f":"活血，止血，解毒。治跌打损伤，衄血，咳血，吐血，乳痈，无名肿毒，毒虫螫伤。\n\n①《百草镜》：\"治乳痈肿毒，金疮止血，喉癣，双蛾，咳嗽。\"\n\n②《湖南药物志》：\"行血止血，清热解毒。\"","y":"内服：煎汤，0.5～1两；或捣汁。外用：捣敷。","d":"?"},"海龙":{"a":"水雁，海蛇","s":"味咸、甘，性温。归肝，肾经。\n\n①《药材资料汇编》：\"甘，温，无毒。\"\n\n②《中药材手册》：\"味咸。\"\n\n③《中药鉴别手册》：\"咸甘，温。\"","f":"补肾壮阳；散结消肿。主阳痿；遗精；不育；肾虚作喘；症瘕积聚；瘰疬瘿瘤；跌打损伤；痈肿疔疮\n\n\n①《纲目拾遗》：\"功倍海马。催生尤捷效。\"\n\n②《现代实用中药》：\"为强壮药，有兴奋作用，用于老人及衰弱者之精神衰惫。治血气痛。\"\n\n③《中药鉴别手册》：\"补肾壮阳。治阳萎、不育。\"","y":"内服：煎汤，3-9g；研末，1.5-3g。外用：适量，研末掺敷。","d":"性状鉴别（1）刁海龙，本品体狭长侧扁，长30-50cm，躯干部宽3cm。表面黄白色或灰褐色。头部前方具一侧扁的管状长吻，口小，无牙，两眼圆而深陷，头与体轴略呈钝角；躯干部五棱形；尾部前方冰棱形，后方渐细呈四棱形，尾端卷曲；背棱两侧各有一列灰黑色斑点状色带，腹部中央棱特别突出。全体被以具花纹的骨环及细横纹，各骨环内有突起粒状棘。胸鳍宽短，背鳍较长，有的不明显，无尾鳍。骨质坚硬。气微腥，味微咸。\n（2）拟海龙，体平扁，全长20-22cm。表面灰黄色或黄白色。头常与体轴成一直线；躯干部粗壮，近四棱形，后方渐细呈四棱形，尾部细尖微卷曲，短于头与躯干部合长，无尾鳍。\n（3）尖海龙，体细长，呈鞭状，长10-20cm，中部直径4-5mm。表面黄褐色，或黄棕色，头较小而细尖，吻细长而呈管状；躯干部七棱形，尾部四棱形，后方渐细，末端不卷曲，有尾鳍。腹部中央微凸出，有的腹面可见育儿囊。质较脆，易撕裂。\n（4）蓝海龙，体部的要夫较尖锐，体部中侧棱和尾部下侧棱几相连，而上侧棱不相连结。黑褐色，具不规则的环带，腹面有较宽的黑色纵带。\n（5）低海龙，较小，长12-14cm，淡黄褐色或暗褐色，有黑褐色环带与浅色斑相间隔。\n（6）舒海龙，累加长鞭状，灰褐色。\n显微鉴别（1）刁海龙，粉末白色或乳白色。①横纺肌纤维较多，多成束而长，近无色或淡黄色，多碎断，横断面类圆形，表面平滑。②胶原纤维多单一或2-3成束。隐约可见纵向纹理，偶然可见与含棕色颗粒状物组织碎片相连接。③皮肤碎片近无色或淡黄色，极少见。表面观细胞界线不明显，可见微波状纵横纹理，布有棕色颗粒状色素物，聚休成星芒状。④骨质碎片无色，呈不规则块状，骨陷窝裂缝状，排列不规则，边缘骨小管稀疏。"},"土牛膝":{"a":"掇鼻草、擦鼻草、倒扣草、毛蟹目、土牛七、红骨蛇","s":"苦酸，平。\n\n①《福建民间草药》：\"苦酸，平，无毒。\"\n\n②《广西中草药》：\"味微苦酸，性寒，无毒。\"\n\n③《云南中草药》：\"甘微酸，凉。\"","f":"活血散瘀，祛湿利民，清热解毒。治淋病，尿血，妇女经闭，癥瘕，风湿关节痛，脚气，水肿，痢疾，疟疾，白喉，痈肿，跌打损伤。\n\n①《本草图经》：\"治妇人血块。\"\n\n②《纲目拾遗》：\"活血化瘀，宽筋，理跌打损伤。治破伤风，七十二般恶疾。功胜川产。又：善能理疮，并箭入肉。\"\n\n③《岭南采药录》：\"为收敛药及利小便药，清血消毒。治喉症捣汁含漱；又散血止痛，理脚气，煎酒服。\"\n\n④《福建民间草药》：\"散瘀血，强足膝，引药下行。\"\n\n⑤《南宁市药物志，：\"清热，散血止痛。治疟疾、痔疮及红白痢；外用治跌打损伤。\"\n\n⑥《江西草药》：\"治竹木刺伤，毒蜂咬伤等症；并可引产。\"\n\n⑦《上海常用中草药手册》：\"通经利尿，清热解毒，活血止痛。治脚气肿胀，关节炎，风湿痛，白喉，急慢性咽炎。\"\n\n⑧《贵州草药》：\"生用可破血利湿，炒用补肝肾，强筋骨。\"\n\n⑨《云南中草药》：\"活血祛瘀，清热除湿，治咳血，鼻衄，尿血，尿路感染，湿热带下。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)。外用：捣敷，捣汁滴耳或研末吹喉。","d":"①牛膝(野生者)的干燥根茎及根，又名：野牛膝。根茎呈圆柱状，长1～3厘米，直径6～10毫米，灰棕色，上端有茎基残留，周围着生多数粗细不一的根。根长圆柱形，略弯曲，长约15厘米以下，径可达4毫米；表面淡灰棕色，有细密的纵皱纹。质稍柔软，干透后易折断，断面黄棕色，可见成圈状散列的维管束。气微，味微甜。\n\n产陕西、甘肃、安徽、江西、福建、浙江、江苏、四川、贵州等地。\n\n②柳叶牛膝的干燥根茎及根，又名：苏木红、荔支红、透血红(《纲目拾遗》)，红牛膝、牛克膝。根茎短粗，长2～6厘米，径1～1．5厘米。根4～9条，扭曲，长10～20厘米，径0．4～1．2厘米，向下渐细。表面灰黄褐色，具细密的纵皱纹及须根除去后的痕迹。质硬而稍有弹性，易折断，断面皮部淡灰褐色，略光亮，可见多数点状散布的维管束。气微，味初微甜后涩。\n\n产江西、浙江、湖北、湖南、四川、贵州等地。\n\n③粗毛牛膝的干燥根茎及根。根茎短圆柱形，灰棕色，周围着生众多圆柱状细长的根，长约6～10余厘米，粗约2～5毫米，略弯曲。表面灰棕色，有细浅的纵皱纹。质坚硬，易折断，断面纤维性，淡灰青色至灰白色。味淡无臭。\n\n产广东、福建、广西等地。"},"磨盘草":{"a":"金花草、磨挡草、耳响草、帽笼子、磨笼子、木磨子、磨盆草、苘麻、白麻、磨谷子、磨龙子、牛姑仔磨、磨爿果、复盆子、半截磨、磨仔草、假茶仔、牛响草、挨砻地堵、磨砻草、磨盘花、累子草、米兰草、帽子盾、倒绋草、四米草、研仔盾草","s":"①《生草药性备要》：\"味甘，性平，无毒。\"\n\n②《本草求原》：\"叶：甘涩，微温。\"\n\n归肺；肾经","f":"清热，利湿，开窍，活血。治泄泻，淋病，耳鸣耳聋，疝气，痈肿，荨麻疹。\n\n①《生草药性备要》：\"散风、盘热。耳鸣、耳聋，煲鸡、肉食亦可。\"\n\n②《本草求原》：\"健脾，止泻，同米擂煮黄糖食。\"\n\n③《岭南采药录》：\"能升清降浊，开窍活血，又捣敷搭手、痈疮。\"\n\n④《广东中药》Ⅱ：\"治小肠疝痛，肾虚余沥，小便刺痛或小便浑浊，腮腺炎，骨蒸劳热。\"\n\n⑤广州部队《常用中草药手册》：\"疏风清热，升清降浊。治感冒高热不退，流行性腮腺炎，耳聋，耳鸣，甲状脓肿，遗精。\"","y":"内服：煎汤，1～2两；或炖肉。外用：捣敷。","d":"干燥全草主干粗约2厘米，有分枝，外皮有网格状皱纹，淡灰褐色如被粉状，触之有柔滑感。叶皱缩，浅灰绿色，背面色淡，少数呈浅黄棕色，被短柔毛，手捻之较柔韧面不易碎，有时叶腋有花或果。气微。\n产广东、广西等地。"},"狗爪豆":{"a":"狗踭豆(《中国主要植物图说·豆科》)，白黎豆(《中国种子植物分类学》)，龙爪豆、猫爪豆(《浙江天目山药植志》)，猫豆(《广西药植名录》)。","s":"《浙江天目山药植志》：\"性温，味甘微苦，有小毒。\"","f":"①《浙江天目山药植志》：\"温中益气。治腰脊酸痛。狗爪豆二至三两，炖猪腰子服。\"\n\n②《广西药植名录》：\"嫩叶(擦遍全身)，清热，凉血。\"","y":"?","d":"?"},"无花果":{"a":"阿驲、阿驿、底珍(《酉阳杂俎》)，天生子(《滇南本草》)，映日果(《便民图纂》)，优昙钵(《广州志》)，蜜果(《群芳谱》)，文仙果(《草木便方》)，奶浆果(《湖南野生植物》)，品仙果(《民间常用草药汇编》)。","s":"①《滇南本草》：\"苦，有小毒。\"\n\n\n②《纲目》：\"甘，平，无毒。\"\n\n\n③《随息居饮食谱》：\"甘，寒。\"\n\n\n④《药材学》：\"性平，味甘酸。\"","f":"健胃清肠，消肿解毒。治肠炎，痢疾，便秘，痔疮，喉痛，痈疮疥癣，利咽喉，开胃驱虫。\n\n\n用于食欲不振，脘腹胀痛，痔疮便秘，消化不良，痔疮，脱肛，腹泻、乳汁不足，咽喉肿痛，热痢，咳嗽多痰等症。\n\n\n①《滇南本草》：\"敷一切无名肿毒，痈疽疥癞癣疮，黄水疮，鱼口便毒，乳结，痘疮破烂;调芝麻油搽之。\"\n\n\n②《便民图纂》：\"治咽喉疾。\"\n\n\n③汪颖《食物本草》：\"开胃，止泄痢。\"\n\n\n④《纲目》：\"治五痔，咽喉痛。\"\n\n\n⑤《生草药性备要》：\"洗痔疮。子，煲肉食，解百毒。蕊，下乳汁。\"\n\n\n⑥《医林纂要》：\"益肺，通乳。\"\n\n\n⑦《随息居饮食谱》：\"清热，润肠。\"\n\n\n⑧《江苏植药志》：\"鲜果的白色乳汁外涂去疣。\"\n\n\n⑨《云南中草药》：\"健胃止泻，祛痰理气。治食欲不振，消化不良，肠炎，痢疾，咽喉痛，咳嗽痰多，胸闷。\"","y":"内服：煎汤，1～2两；或生食1～2枚。外用：煎水洗、研末调敷或吹喉。","d":"干燥的花托呈倒圆锥形或类球形，长约2厘米，直径约1.5～2.5厘米;表面淡黄棕色至暗棕色、青黑色，有波状弯曲的纵棱线;顶端稍平截，中央有圆形突起，基部较狭，带有果柄及残存的苞片。质坚硬，横切面黄白色，内壁着生众多细小瘦果，有时上部尚见枯萎的雄花。瘦果卵形或三棱状卵形，长约1～2毫米，淡黄色，外有宿萼包被。气微，味甜。以干燥、青黑色或暗棕色，无霉蛀者为佳。\n\n\n南方各地均产。"},"海狗油":{"a":"腽肭脂、海豹油","s":"性热。","f":"善消利。治三焦浊逆之气，能清水脏积寒、停饮。涂皲瘃。","y":"?","d":"?"},"黄泡果":{"a":"?","s":"酸，平。入肾经","f":"补肾涩精。治神经衰弱，多尿，遗精，早泄。","y":"内服：煎汤，鲜者1～2两。","d":"?"},"凤凰衣":{"a":"鸡卵中白皮(《别录》)，鸡子白皮(孟诜《必效力》)，凤凰退(《本草蒙筌》)，鸡蛋膜衣(《现代实用中药》)，鸡蛋衣(《浙江中药手册》)。","s":"①《饮片新参》：\"淡，平。\"\n\n①《四川中药志》：\"性温，味甘，无毒。\"","f":"养阴，清肺.治久咳，咽痛失音，瘰疬结核，溃疡不敛。\n\n①《别录》：\"主久咳结气，得麻黄，紫菀和服之。\"\n\n②《医学入门》：\"治小儿头身诸疮，烧灰猪脂调敷。\"\n\n③《分类草药性》：\"治小儿惊风肚痛；煅研涂疮，生皮。\"\n\n④《饮片新参》：\"清肺热，开声喑，治虚咳，生滓。\"\n\n⑤《浙江中药手册》：\"清肺火，化燥痰。治咽痛失音。\"\n\n⑥《中药志》：\"治头晕、目翳。\"","y":"内服：煎汤，1～3钱；或入散剂。外用：敷贴或研末撒。","d":"为辕折状的薄膜，碎片大小不等，边缘不整齐，一面白色无光泽；另一面淡黄色，略有光泽，并附有棕色线状血丝。质轻松，略有韧性，易破碎。气微，味淡。以身干，色白、宪整、无碎壳及杂质者为佳。"},"八月札":{"a":"八月瓜、八月炸、野毛蛋","s":"甘，寒。\n\n①孟诜：\"平。\"\n\n②《食性本草》：\"寒，无毒。\"\n\n③《四川中药志》：\"性温平，味苦涩辛，无毒。\"","f":"舒肝理气，活血止痛，除烦利尿。治肝胃气痛，胃热食呆，烦渴，亦白痢疾，腰痛，胁痛，疝气，窟经，子宫下坠。\n\n①崔禹锡《食经》：\"食之去淡(痰)水，止赤白下利。\"\n\n②孟诜：\"厚肠胃，令人能食，下三焦，除恶气，和子食之更好。\"\"通十二经脉。\"\n\n③《本草拾遗》：\"利大小便，宣通，去烦热，食之令人心宽，止渴，下气。\"\n\n④《食性本草》：\"主胃口热闭，反胃不下食，除三焦客热。\"\n\n⑤《本草汇言》：\"以蜜水煮食之，治噤口热痢。\"\n\n⑥《南京民间草药》：\"治腰痛。\"\n\n⑦《四川中药志》：\"疏肝，纳肾气。治膀胱疝气，吐血。\"\n\n⑧《药材学》：\"利气，活血，杀虫，解毒，止痛。用于肝胃气痛，胁痛，月经痛等症。\"\n\n⑨《陕西中草药》：\"疏肝益肾，健脾和胃。治消化不良，腹痛，泻痢，疝气，子宫下坠。\"","y":"内服：煎汤，0。5～1两；或浸酒。","d":"干燥的肉质浆果呈卵状圆柱形，稍弯曲，长3～8厘米，直径2.5～3.5厘米，顶端钝圆，基部具果柄痕。表面浅黄棕色至土棕色，皱缩，成熟者皱纹粗大而疏，未熟者皱纹细小而密。果皮厚，革质或微角质。种子多数，包被在絮状果瓤内，形状不规则，呈圆形、长圆形或卵圆形，略扁平，外表红棕色或棕黑色，有光泽，皱纹细密。果肉气微香，味涩而淡。以肥壮、皮皱者为佳。\n产江苏、浙江、安徽、陕西等地。\n\n西藏地区使用的八月札，为同科植物五风藤的果实；四川地区除用白木通的果实外，还使用狭叶八月瓜的果实。"},"藏红花":{"a":"撒法即,番红花,西红花","s":"甘，平。\n\n\n①《饮膳正要》：\"味甘，平，无毒。\"\n\n\n②《品汇精要》：\"味甘微酸，性平温，无毒。\"\n\n\n入心、肝经。","f":"活血化瘀，散郁开结。治忧思郁结，胸膈痞闷，吐血，伤寒发狂，惊怖恍惚，妇女经闭，产后瘀血腹痛，跌扑肿痛。\n\n\n①《饮膳正要》：\"主心忧郁积，气闷不散，久食令人心喜。\"\n\n\n②《品汇精要》：\"主散郁调血，宽胸膈，开胃进饮食，久服滋下元，悦颜色，及治伤寒发狂。\"\n\n\n③《纲目》：\"活血，又治惊悸。\"","y":"煎汤，1～2钱；或浸酒。","d":"①湿红花\n\n\n柱头红棕色，有油润光泽，细长线形，长约3厘米，基部较窄，向顶端逐渐变宽，内方有一短裂缝，顶端边缘为不整齐的齿状。柱头常单独存在，有时三个柱头与一短花柱相联。花柱橙黄色。浸于水中时，柱头即扩大膨胀，呈长喇叭状，水被染成黄色。气香甜，味苦。以滋润而有光泽、色红、黄丝少者为佳。\n\n\n②干红花\n\n\n为弯曲的细丝状，暗红棕色，带有黄棕色部分。质轻松，无光泽及油涡感。其余与湿红花同。\n\n\n上述药材，产西班牙、希腊及苏联等地。"},"小血藤":{"a":"钻骨风、八仙草(《分类草药性》)，血糊藤(《经济植物手册))，钻石风(《重庆草药》)，天青地红(《陕西中草药》)，五香血藤、滑藤、爬岩香、满山香、香血藤(《昆明民间常用草药》)。","s":"辛，温。\n\n①《草木便方》：\"热。\"\n\n②《重庆草药》：\"辛，温，无毒。\"\n\n③《陕西中草药》：\"味甘酸，性温。\"","f":"行气，止痛，活血，散瘀。治跌打损伤，风湿麻木；筋骨疼痛，痨伤吐血，经闭，腹胀，痈肿。\n\n①《草木便方》：\"生心血，散瘀活血，透关节。治跌打损伤血胀，四肢筋骨风毒。\"\n\n②《分类草药性》：\"治风湿麻木，筋骨疼痛。涂鱼口肿毒。\"\n\n③《重庆草药》：\"行气，活血。治跌打损伤，劳伤吐血，经闭。\"\n\n④《陕西中草药》：\"活血调经，散瘀消肿，理气止痛。治月经不调，白带，劳伤，跌打损伤，疮疖疝气，肺脓疡。\"","y":"内服：煎汤，3～5钱；或浸酒。外用：捣敷或煎水洗。","d":"性状鉴别（1)藤茎细长圆柱形，直径0．2-0．6cm，有的略弯曲。表\n面红棕色或棕褐色，有纵皱纹及红棕色皮孔。分枝断痕较硬。质坚\n韧，难折断，折断面呈刺片状，皮部易与木部分离，皮部棕褐色，木部粉白色，髓部中央有空心。气香，味微辛凉，嚼之有粘性。\n（2)根圆柱形，常弯曲，长20-40cm，直径0．3-1．2cm。表面\n红褐色或棕红色，常有环状裂缝，多露出木部而呈节节状。质坚，难\n折断。断面皮部厚，整齐，显灰绿色；木部呈刺片状，黄白色。气香，味辛凉，微苦涩，嚼之有粘性。\n（3)根茎圆柱形，直径0.4-1.2cm。表面有细长须根和须根痕。皮部薄，断面棕色；髓中空。\n显微鉴别 藤茎及根茎横切面：木栓层较发达。皮层及韧皮部有小型的嵌晶纤维束散在，纤维木化；并有粘液细胞分布。木质部导管1-2列，导管圆多角形，切向径达85μm；木薄壁细胞全部木化。射线宽1-2列细胞，木化。髓部细胞较大，排列较松。本品薄壁细胞含有淀粉粒及棕色物。\n根横切面与藤茎及根茎相似，但不具髓。"},"大麦":{"a":"麰、稞麦、麰麦、牟麦、饭麦、赤膊麦。","s":"甘咸，凉。\n\n①《别录》：\"味咸，微寒，无毒。\"\n\n②《本草衍义》：\"性平，凉。\"","f":"和胃，宽肠，利水。治食滞泄泻，小便淋痛，水肿，汤火伤。\n\n①《别录》：\"主消渴，除热，益气，调中。\"\n\n②《唐本草》：\"大麦面平胃，止渴，消食，疗胀。\"\n\n③《崔禹锡食经》：\"主水痮。\"\n\n④《本草拾遗》：\"调中止泄。\"\n\n⑤《纲目》：\"宽胸下气，凉血，消积，进食。\"","y":"内服：煎汤，1～2两；或研末。外用：炒研调敷或煎水洗。","d":"?"},"肺形草":{"a":"穿藤金兰花、铁交杯、蝴蝶草、山蝴蝶、金丝蝴蝶、石板肯、铜交杯、金交杯、大叶竹叶青、四脚喜、花蝴蝶、铁板青(《浙江民间常用草药》)，胡地莲(江西《草药手册》)。","s":"《浙江民间草药》：\"味辛，性寒。\"","f":"清肺止咳，解毒消肿。治肺热咳嗽，肺痨咯血，肺痈，肾炎，疮痈疖肿。\n\n①《植物名实图考》：\"捣敷诸毒。\"\n\n②《药用植物图说》：\"治咯血。\"\n\n③《浙江民间草药》：\"除寒热，治肺痨、肺痈。\"\n\n④《江西植物志》：\"止刀伤血。\"\n\n⑤《广西药植名录》：\"治乳疮、久痢，月经不调。\"","y":"内服：煎汤，2～4钱(鲜者1～2两)。外用：捣敷。","d":"?"},"老鼠耳":{"a":"狗脚刺、提云萆、小桃花(《岭南采药录》)，老鼠乌、鼠乳头、乌金藤((福建民间草药》)，老鼠乳、鼠米、乌痧头、乌李楝(《福建中草药》)。","s":"《闽南民间草药》：\"微苦，平，无毒。\"","f":"治疔疮，睾丸脓肿，痔疮，烫伤。","y":"内服：煎汤，鲜者0.5～1两。外用：捣敷。","d":"?"},"大麻药":{"a":"麻里麻、麻三段、豆叶百步还阳(《云南中草药》)，大豆荚、大九荚(《文山中草药》)。","s":"《云南中草药》：\"辛麻，温，有毒。\"","f":"镇痛，消肿，止血。治风湿痛，跌打损伤，骨折，外伤出血，吐血，衄血，便血。\n\n①《云南中草药》：\"止血生肌，消炎镇痛，接骨。\"\n\n②《文山中草药》：\"行血散瘀，止痛消肿。\"","y":"内服：煎汤，1～3钱(鲜者0.5～1两)；或浸酒。外用：研末撒或调敷。","d":"?"},"藤三七":{"a":"藤子三七。","s":"微苦，温。","f":"滋补，壮腰膝，消肿散瘀。治腰膝痹痛，病后体弱，跌打损伤，骨折。","y":"内服：炖鸡或炖猪肉，1～2两。外用：捣敷。","d":"?"},"鹌鹑":{"a":"鹑鸟,循,宛鹑,赤喉鹑,红面鹌鹑","s":"甘，平。\n\n①《七卷经》：\"味辛，平。\"\n\n②《品汇精要》：\"味甘，性温平，无毒。\"\n\n入大肠、心、肝、脾、肺、肾经","f":"治泻痢，疳积，湿痹。\n\n①孟诜：\"补五脏，益中续气，实筋骨，耐寒暑，消结热。\"\"患痢人和生姜煮食之。\"\n\n②崔禹锡《食经》：\"主赤白下痢，漏下血，暴风湿痹，养肝肺气，利九窍。\"\n\n③《嘉祐本草》：\"和小豆、生姜煮食，止泄痢。\"\n\n④《本草衍义》：\"小儿患疳及下痢五色，旦旦食之。\"\n\n⑤《本草求原》：\"补土续气，调肺利水湿。治腹大如鼓，泻痢，疳积。\"","y":"内服：煮食、煎汤或烧存性研末。","d":"?"},"金腰带":{"a":"金丝带","s":"味甘、苦，性平；归肝、肾经。","f":"","y":"","d":""},"赤瓟":{"a":"气包(《东北药植志》)，赤包、山屎瓜(《东北常用中草药手册》)。","s":"《东北常用中草药手册》：\"酸苦，平。\"","f":"降逆，理湿，和瘀。治黄疸，痢疾，反胃吐酸，咳血胸痛，腰部扭伤。\n\n①《东北药植志》：\"顺气，调气。\"\n\n②《黑龙江中药》：\"治扭腰岔气，胸胁疼痛。\"\n\n③《东北常用中草药手册》：\"祛痰，止呕。\"","y":"内服：煎汤或研末服。","d":"干燥果实呈卵圆形、椭圆形至长圆形，常压扁，长纣3～5厘米，直径约1.5～3厘米。橙黄色、橙红色、红色至红棕色。表面皱缩，有极稀的白色茸毛及纵沟坟，顶端有残留柱基，基部有细而弯曲的果柄。果皮厚1毫米左右，内表面粘连多数黄色长圆形的小颗粒，系不发育的种子，中心有多数扁卵形、棕黑色的成热种子，新鲜时质软而粘。气特异。味甜。"},"獾油":{"a":"獾子油(《黑龙江中药》)。","s":"甘、酸，平。","f":"治中气不足，子宫脱垂，咳血，痔疮，疳疮，疥癣，白秃，烫伤，冻疮。\n\n①《纲目拾遗》：\"治头止白秃。\"\n\n②《山东中药》：\"外敷治汤火伤。\"\n\n③《黑龙江中药》：\"内服可补中益气，杀虫润肠，止咳血，胸腹胀；外用治内外痔疮，火烧水烫，小儿疳疮。\"","y":"内服：溶化入汤剂。外用：涂擦。","d":"?"},"水飞蓟":{"a":"水飞雉,奶蓟,老鼠勒。","s":"性寒，味苦。归肝、胆经。","f":"?","y":"内服：煎汤，，6-15g；或制成冲剂、胶囊、丸剂。","d":"?"},"猫爪草":{"a":"猫爪儿草、三散草","s":"甘辛，温。\n\n①《中药材手册》：\"味微甘。\"\n\n②《广西中药志》：\"味酸甘，性平，无毒。\"\n\n③《河南中草药手册》：\"味辛，性温。\"\n\n归肝；肺经 \n\n《广西中药志》：\"入肝、肺二经。\"","f":"治瘰疬，肺结核，疟疾。\n\n①《中药材手册》：\"治颈上瘰疬结核。\"\n\n②《河南中草药手册》：\"消肿，截疟。治瘰疬，肺结核。\"","y":"内服：煎汤，0.5～1两。外用：研末撒。","d":"干燥的块根呈纺锤形，常数个簇生一起，形似猫爪，全长约1厘米余。表面黄褐色或灰褐色，有点状须根痕，有的尚有须根残留；上端有黄棕色残茎或茎痕，质坚实，断面黄白色或黄棕色，实心或空心。气无，味微甘。以色黄褐、质坚实饱满者为佳。\n产河南、江苏、浙江、广西等地。"},"硫黄":{"a":"石流黄(《范子计然》)，石留黄、硫黄(《吴普本草》)，昆仑黄(陶弘景)，黄牙(《丹房鉴源》)，黄硇砂(《海药本草》)。","s":"酸，热，有毒。\n\n①《本经》：\"味酸，温。\"\n\n②《吴普本草》：\"神农、黄帝、雷公：咸，有毒。医和、扁鹊：无毒。\"\n\n③《别录》；\"大热，有毒。\"\n\n④《药性论》：\"味甘，有大毒。\"","f":"壮阳，杀虫。治阳痿，虚寒泻痢，大便冷秘；外用治疥癣，湿疹，癞疮。\n\n①《本经》：\"主妇人阴蚀，疽痔恶血，坚筋骨，除头秃。\"\n\n②《别录》：\"疗心腹积聚，邪气，冷癣在胁，咳逆上气，脚冷疼弱无力，及鼻衄恶疮，下部匿疮，止血，杀疥虫。\"\n\n③《药性论》：\"除冷风，顽痹。生用治疥癣及疗寒热咳逆，炼服主虚损泄精。\"\n\n④《海药本草》：\"主遗精痔漏，老人风秘等。\"\n\n⑤《日华子本草》：\"杀腹脏虫。\"\n\n⑥《纲目》：\"主虚寒久痢滑泄，霍乱，补命门不足，阳气暴绝，阴毒伤寒，小儿慢惊。\"\n\n⑦《纲目拾遗》：\"天生磺，治膈症。\"\"舶上硫黄，灭斑，杀虫，治疮通血，止泻痢。\"","y":"内服：研末，0.5～1钱，或入丸、散。外用：研末撒，调敷或磨汁涂。","d":"为不规则的块状，大小不一。呈黄色，或带浅绿色或浅棕黄色。表面不平坦，常有麻纹及细砂孔；有光泽，半透明。体轻，质脆易碎。断面常呈粗针状结晶形。有特异之臭气，味淡。以色黄，光亮、松脆、无杂质者为佳。燃之易熔融，发蓝色火焰，并放出刺激性的二氧化硫臭气。不溶于水及盐酸、硫酸；遇硝酸或王水被氧化成硫酸；溶于二硫化碳、煤袖及松节油中。\n产山西、陕西、河南、山东、湖北、湖南、江苏、四川、广东、台湾等地。\n\n此外，尚有天生碘和舶上硫黄二种商品：\n\n①天生磺(《纲目拾遗》)\n系含硫温泉处升华凝结于岩石上者，收集后，先用冷水洗去泥土，再用热水烫7～10余次，然后放在香油内，捞取浮于表面者。本品为浅黄色粉末，少有呈碎片状，闪烁发光，有臭气。\n\n②舶上硫黄(《博济方》)\n又名：舶硫(《遵生八笺》)，白硫黄(《百草镜》)。系将硫黄提炼而成。商品为不规则的块状，全体鲜黄色，半透明，有玻璃样光泽。体轻而脆，易碎，断面不平坦。有臭气，味淡。"},"黄耆":{"a":"戴糁(《本经》)，戴椹、独椹、蜀脂、百本(《别录》)，王孙(《药性论》)，百药绵(侯宁极《药谱》)，绵黄耆(《本草图经》)，黄芪(《纲目》)，箭芪(刘仕廉《医学集成》)，土山爆张根(《新疆药材》)，独根(《甘肃中药手册》)，二人抬(《辽宁经济植物志》)。","s":"甘，微温。\n\n①《本经》：\"味甘，微温。\"\n\n②《别录》：\"无毒。生白水者，冷。\"\n\n③《药性论》：\"白水赤皮者，微寒。\"\n\n④《医学启源》：\"气温，味甘，平。\"\n入肺、脾经。\n\n①《汤液本草》：\"入手少阳、足太阴经、足少阴命门。\"\n\n②《本草蒙筌》：\"入手少阳，手足太阴。\"\n\n⑧《本草经疏》：\"手阳明、太阴经。\"\n\n④《本革新编》：\"入手太阴、足太阴、手少阴经。\"","f":"生用：益卫固表，利水消肿，托毒，生肌。治自汗，盗汗，血痹，浮肿，痈疽不溃或溃久不敛。炙用：补中益气。治内伤劳倦，脾虚泄泻，脱肛，气虎血脱，崩带，及一切气衰血虚之证。\n\n①《本经》：\"主痈疽，久败疮，排脓止痛，大风癞疾，五痔，鼠瘘。补虚。小儿百病。\"\n\n②《别录》：\"主妇人子脏风邪气，逐五脏间恶血。补丈夫虚损，五劳羸瘦。止渴，腹痛，泄痢，益气，利阴气。\"\n\n③《药性论》：\"治发背。内补，主虚喘，肾衰，耳聋，疗寒热。生陇西者下补五脏。蜀白水赤皮者，治客热。\"\n\n④《日华子本草》：\"黄耆助气壮筋骨，长肉补血，破癥癣，治瘰疬，瘿赘，肠风，血崩，带下，赤白痢，产前后一切病，月候不匀，消渴，痰嗽；并治头风，热毒，赤目等。\"\"白水耆，排脓治血，及烦闷，热毒，骨蒸劳，功次黄耆；赤水耆，治血，退热毒，余功用并同上；木耆治烦，排脓力微宁黄耆，遇缺即倍用之。\"\n\n⑤《医学启源》：\"治虚劳自寒(\"寒\"一作\"汗\")，补肺气，实皮毛，泻肺中火，脉弦自汗，善治脾胃虚弱，内托阴证疮疡必用之药。\"\n\n⑥王?古：\"主太阴疟疾。\"\n\n⑦《本草备要》：\"生用固表，无汗能发，有汗能止，温分肉，实腠理，泻阴火，解肌热；炙用补中，益元气，温三焦，壮脾胃。生血，生肌，排脓内托，疮痈圣药。痘症不起，阳虚无热者宜之。\"","y":"内服：煎汤，3～5钱(大剂1～2两)；入丸、散，或熬膏。","d":"干燥的根呈圆柱形，极少有分枝，上端较粗，下端较细，两端平坦，长20～70厘米，粗1～3厘米。一般在顶端常带有较粗大的根头，并有茎基残留。表面灰黄色或淡棕褐色，全体有不整齐的纵皱纹或纵沟。皮孔横向，细长，略突起。质硬略韧，坚实有粉性，折断面纤维性甚强，呈毛状；皮部黄白色，有放射状弯曲的裂隙，较疏松；木质部淡黄色至棕黄色，有多少不等的放射状弯曲的裂隙；老根断面木质部有时枯朽而呈黑褐色，甚至脱落而成空洞。气微弱而特异，味微甜，嚼之有豆腥气。以根条粗长、皱纹少、质坚而绵、粉性足、味甜者为佳。根条细小、质较松、粉性小及顶端空心大者质次。\n主产山西、甘肃、黑龙江、内蒙古、辽宁、吉林、河北等地亦产。\n\n甘肃、河北、青海所产的小白耆(又称小黄耆)，为植物金翼黄耆的根；甘肃、青海所产的白大耆，为植物塘谷耳黄耆的根；四川所产的川耆，主要为塘谷耳黄耆及多花黄耆的根。此等商品外形与上述相近，但较细小，质量亦较差，产量也少。\n\n黄耆除上述品种外，尚有一种红耆。为豆科植物多序岩黄耆的根，产量较大。药材呈长圆柱形，少分枝，上粗下细，长10～50厘米，粗6～20毫米。表面棕黄色或近于棕红色，有纵皱及少数支根痕；皮孔横向，浅黄色或暗黄色，略凸出；栓皮易剥落。质柔韧，断面纤维性且富粉质，皮部棕白色，形成层成棕色的环，木质部淡黄棕色，中心颜色较浅，有细致的类白色放射状纹理。气微弱而特异，味微甜。\n产甘肃南部。"},"猪蹄甲":{"a":"猪悬蹄(《本经》)，猪悬蹄甲(《千金·食治》)，猪蹄合子(《圣济总录》)，猪爪甲(《普济方》)，猪退(《纲目》)。","s":"咸，平。\n\n①《本经》：\"平。\"\n\n②《药对》：\"微寒。\"\n\n③《纲目》：\"咸，平，无毒。\"","f":"治咳嗽喘息，痔疮；白秃，冻疮。\n\n①《本经》：\"主五痔，伏热在肠，肠痈内蚀。\"\n\n②《本经逢原》：\"治目疾外障。\"","y":"内服：烧灰研末。外用：研末调敷。","d":"理比鉴别薄层色谱取本品米粉0.1g,加CH2Cl25ml，温水浴浸渍15min，过滤，滤液作供试品溶液。另取胆固醇约102g，加5mlCH2Cl2，振摇使溶解，作对照品溶液。吸取上述溶液各2μl，分别点于同一硅胶G－CMCNa薄层板上，用CH2CI2-CHCl3（1：1）为展汗剂，展开两次，挥干，喷以10%硫酸乙醇液，于110℃加热5min，结果供试品色谱在与对照品相同的位置上呈相同颜色的紫红色斑点。"},"无患子":{"a":"穗子(《多能鄙事》)，木患子、肥珠子、油珠子、菩提子(《纲目》)，木挽子、油患子(《中国树木分类学》)，圆肥皂、桂圆肥皂(《现代实用中药》)，洗手果、苦枝子(《广西中兽医药植》)。","s":"苦，平，有毒。\n\n①《本经逢原》：\"苦，平，无毒。\"\n\n②《南宁市药物志》：\"苦涩，有小毒。\"","f":"清热，祛痰，消积，杀虫。治喉痹肿痛，咳喘，食滞，白带，疳积，疮痹，肿毒。用于白喉症，精囊病，淋浊尿频。清热，祛痰，消积，杀虫。喉痹肿痛、咳喘、食滞、白带、疳积、疮癣、肿毒。\n\n①《生草药性备要》：\"止血；煨食杀虫，去腻；煮膏药祛风、消肿、拔毒。\"\n\n②《广西中药志》：\"烧灰研末吹喉治声哑。\"\n\n③《浙江天目山药植志》：\"治各种喉症，感冒发热，百日咳，白浊，白带，小儿疳积。\"","y":"内服：煎汤，1～2钱；研末或煨食。外用：研末吹喉、擦牙，或煎汤洗、熬膏涂。","d":"干燥的种子呈球形，径长14毫米。外表黑色，光滑。种脐线形，周围附有白色绒毛。种皮骨质，坚硬。无胚乳，子叶肥厚，黄色，胚粗壮稍弯曲。\n产广东、广西等地。"},"狼毒":{"a":"续毒(《本经》)，川狼毒(《集效方》)。","s":"苦辛，平，有毒。\n\n①《本经》：\"味辛，平。\"\n\n②《别录》：\"有大毒。\"\n\n③《药性论》：\"味苦辛，有毒。\"\n\n④《本经逢原》：\"苦辛，寒，大毒。\"","f":"逐水祛痰，破积杀虫。治水肿腹胀，痰、食、虫积，心腹疼痛，慢性气管炎，咳嗽，气喘，淋巴结、皮肤、骨、副睾等结核，疥癣，痔瘘。\n\n①《本经》：\"主咳逆上气，破积聚，饮食，寒热，水气，恶疮，鼠瘘疽蚀，蛊毒。\"\n\n②《别录》：\"疗胁下积癖。\"\n\n③《药性论》：\"治痰饮，癥瘕。\"\n\n④《滇南本草》：\"治胃中年深日久饮食结住，积久稠痰，状粘如胶。攻虫积，利水道，下气，消水肿，吐痰涎。\"\n\n⑤《本草通玄》：\"主咳逆，治虫疽，瘰疬，结痰，驱心痛。\"\n\n⑥《高原中草药治疗手册》：\"下气杀虫。治痰饮停留，骨膜发炎，结核顽疮，酒齄鼻。\"","y":"内服：煎汤，3～8分；或入丸、散。外用：磨汁涂或研末调敷。","d":"①狼毒\n又名：绵大戟、山萝卜(《滇南本草》)，大将军、红狼毒、西北狼毒。为瑞香狼毒的干燥根，呈圆锥形至长圆柱形，稍扭曲，长7～30厘米，直径2～7厘米；根头部留有地上茎残基；外表棕色至棕褐色，有纵皱及横生的细长皮孔，有时残留细根。栓皮剥落后，露出柔软的纤维。体轻，质韧，不易折断，断面中心木质部黄白色，外圈韧皮部白色，呈纤维状。气微，味微甘、微苦而辣。\n产内蒙古、山西、河南、青海、甘肃、陕西、四川等地。\n\n②白狼毒\n为狼毒大戟、月腺大戟的干燥根，都切成类圆形的块片。\n\n狼毒大戟\n又名：猫眼花根、东北狼毒。直径约4～7厘米，厚0.5～3厘米，偶有厚达7厘米者。表面黄棕色或淡棕色。栓皮成重叠的薄片状，易剥落。切面不平坦，有暗棕色与黄白色相间的明显同心环，偶有环纹不显著者。质轻，易折断，断面粉性，水湿之有粘性，撕开时可见粘丝。气微，味甘，并有刺激性辣味。\n产辽宁、吉林、黑龙江、内蒙古、河北。\n\n月腺大戟的根性状与上种相似，唯切面的同心环纹颜色较浅，不如狼毒大戟根的明显。以水湿之不显粘性。\n产河南、山东、江苏、安徽、湖北等地。\n\n《本草》所载的狼毒，系瑞香科瑞香狼毒，故应以此为正品，但目前多数地区所用的狼毒，为大戟科的白狼毒。"},"杏子":{"a":"杏实","s":"酸甘，温。\n\n①《千金·食治》：\"味极酸。\"\n\n②崔禹锡《食经》：\"味酸，大热。\"\n\n③《日华子本草》：\"热，有毒。\"\n\n④《本草图经》：\"杏之类梅者味酢，类桃者味甘。\"\n\n归肺；心经","f":"润肺定喘，生津止渴。\n\n①《千金·食治》：\"其中核犹未鞕者，采之暴干食之，甚止渴，去冷热毒。\"\n\n②《滇南本草》：\"治心中冷热，止渴定喘，解瘟疫。\"\n\n③《随息居饮食谱》：\"润肺生津。\"","y":"内服：煎汤，6-12g，或生食，或晒干为脯，适量。","d":"?"},"十大功劳叶":{"a":"功劳叶","s":"《饮片新参》：\"苦，凉。\"","f":"清热补虚，止咳化痰。治肺痨咳血，骨蒸潮热，头晕耳鸣，腰酸腿软，心烦，目赤。\n\n①《本草再新》：\"治虚劳咳嗽。\"\n\n②《植物名实图考》：\"治吐血。\"\n\n③《饮片新参》：\"治肺劳，止咳化痰，退虚热，杀虫。\"\n\n④《现代实用中药》：\"清凉性滋养强壮药。功效与女贞子相似，适用于潮热、骨蒸、腰酸、膝软、头晕、耳鸣等证。\"\n\n⑤《陆川本草》：\"泻火退热。治温病发热，心烦，下利，赤眼。\"\n\n⑥《西藏常用中草药》：\"治湿热痢疾，目赤肿痛，痈肿疮毒。\"","y":"内服：煎汤，2～3钱。","d":"①阔叶十大功劳叶，呈卵状椭圆形，先端渐尖而有锐刺，基部心形或近截形而歪斜，边缘两侧各具2～8个刺状齿，齿尖向叶背微弯，上面紫绿色有光泽，下面黄绿色。质硬而脆。气微弱，味淡。\n\n②细叶十大功劳叶，呈狭披针形，边缘两侧各具6～13个刺状齿，其他与上种相同。\n\n以上药材产浙江、安徽、江西等地。\n\n⑧华南十大功劳叶，药材性状同阔叶十大功劳叶。使用于福建、云南。\n\n据《植物名实图考》所载十大功劳，即为上述小檗科植物。但目前仅浙江、江西等少数地区有药材，福建、广东、广西等地民间亦使用之。西藏地区所用的十大功劳叶，为西藏十大功劳的叶。至于市场上广泛使用的功劳叶，则为冬青种植物枸骨的叶。参见\"枸骨叶\"条。"},"鸡屎白":{"a":"鸡矢(《素问》)，鸡子粪(《本草经集注》)，鸡粪(《千金方》)。","s":"苦咸，凉。\n\n①《别录》：\"微寒。\"\n\n②《纲目》：\"微寒，无毒。\"\n\n③《医林纂要》：\"苦咸，寒。\"","f":"利水，泄热，祛风，解毒。治臌胀积聚，黄疸，淋病，风痹，破伤中风，筋脉挛急。\n\n①《本经》：\"主消渴，伤寒，寒热。\"\n\n②《别录》：\"破石淋及转筋，利小便，止遗溺，灭瘢痕。\"\n\n③《本草拾遗》：\"和黑豆炒浸酒，主贼风、风痹，破血。\"又：\"炒服之，主虫咬毒。\"\n\n④《日华子本草》：\"治中风失音，淡(痰)逆，消渴，破石淋，利小肠余沥，敷疮痍，灭瘢痕。炒服，治小儿客忤。朱雄鸡粪治白虎风，并敷痛风。\"\n\n⑤《品汇精要》：\"丹雄鸡屎白敷蛐蟮咬良，又烧研水服方寸匕，疗食药中毒，发狂、闷、吐下欲死，及疗妒乳并乳头破裂及痈肿。\"\n\n⑥《纲目》：\"下气，通利大小便，治心腹鼓胀，消癥瘕。以水淋汁服，解金银毒。以醋和涂蜈蚣、蚯蚓咬毒。\"","y":"内服：晒干，文火焙炒，炒时洒入白酒少许，研末为丸散，1～2钱，或浸酒。","d":"?"},"枇杷核":{"a":"?","s":"苦，平。\n\n①《本经逢原》：\"大寒。\"\n\n②《现代实用中药》：\"苦，平。\"\n\n③《四川中药志》：\"性微寒，味苦，无毒。\"","f":"化痰止咳，疏肝理气。治咳嗽，疝气，水肿，瘰疬。\n\n①《纲目拾遗》：\"治肝有余诸症，气实者可用。\"\n\n②《本草再新》：\"治疝气，消水肿，利关节，治瘰疬。\"\n\n③《现代实用中药》：\"镇咳祛痰。\"\n\n④《四川中药志》：\"疏肝理气。\"","y":"内服：煎汤，2～3钱。外用：研末调敷。","d":"性状鉴别 种子呈圆形或偏圆形，直径1-1.5cm，表面棕褐色，有光泽。种皮纸质，子叶2片，外表为淡绿色或类白色，内面为白色，富油性。气微香，味涩。"},"风藤":{"a":"小叶风绳(《浙江中药资源名录》)，小木莲(《浙江天目山药植志》)。","s":"?","f":"《浙江中药资源名录》：\"治风湿。\"","y":"内服：煎汤，鲜者2～3两。","d":"?"},"瓦松":{"a":"昨叶荷草(《唐本草》)，屋上无根草(《经验良方》)，向天草(《庚辛玉册》)，瓦花(《摘元方》)，石莲花、厝莲(《福建民间草药》)，干滴落(《东北药植志》)，猫头草、瓦塔(《河北药材》)，天蓬草(《中药材手册》)，瓦霜、瓦葱(《四川中药志》)，酸塔、塔松、兔子拐杖、干吊鳖、石塔花、狼爪子、酸溜溜(《辽宁经济植物志》)，瓦宝塔、瓦莲花、岩松、屋松、岩笋、瓦玉(《浙江民间常用草药》)。","s":"酸苦，凉，有毒。\n\n①《唐本草》：\"味酸，性平，无毒。\"\n\n②《本草再新》：\"味苦，性寒，有毒。\"\n\n③《四川中药志》：\"性凉，味淡，无毒。\"","f":"清热解毒，止血，利湿，消肿。治吐血，鼻衄，血痢，肝炎，疟疾，热淋，痔疮，湿疹，痈毒，疔疮，汤火灼伤。\n\n①《唐本草》：\"主口中干痛，水谷血痢，止血。\"\n\n②《本草图经》：\"行女子经络。\"\n\n③《纲目》：\"大肠下血，烧灰，水服一钱，又涂诸疮不敛。\"\n\n④《本草再新》：\"治百毒，疗火疮，消肿杀虫。\"\n\n⑤《分类草药性》：\"治一切痔疮肿痛出血，煎水熏洗。\"\n\n⑥《科学的民间药草》：\"通便。\"\n\n⑦《河北药材》：\"治水臌。\"\n\n⑧《泉州本草》：\"清热，解毒，利小便。\"","y":"内服：煎汤，1～3钱；捣汁或入丸剂。外用：捣敷、煎水熏冼或烧存性研末调敷。","d":"干燥的全草，茎呈黄褐色或暗棕褐色，长12～20厘米，上有多数叶脱落后的疤痕，交互连接成棱形花纹。叶灰绿色或黄褐色，皱缩卷曲，多巳脱落，长12～15毫米，宽约3毫米，茎上部叶间带有小花，呈红褐色，小花柄长短不一。质轻脆，易碎。气微，味酸。以花穗带红色、老者为佳。全国大部分地区均产。\n\n此外，同属植物黄花瓦松的全草亦同供药用，分布西藏、新疆、内蒙古、吉林等地。"},"狗尾草":{"a":"莠(《诗经》)，光明草、阿罗汉草(《纲目》)，狗尾半支(《纲目拾遗》)，谷莠子(《植物名汇》)，洗草(《贵州民间方药集》)，犬尾草、犬尾曲(《福建民间草药》)。","s":"①《陆川本草》：\"凉，淡。\"\n\n②《四川中药志》：\"性平，味淡，无毒。\"","f":"除热，去湿，消肿。治痈肿，疮癣，赤眼。\n\n①《纲目》：\"治疣目，贯发，穿之即干灭也。凡赤眼拳毛倒睫者，翻转目险，以一、二茎蘸水戛去恶血。\"\n\n②《纲目拾遗》：\"治疔痈癣。面上生癣，取草效茎揉软，不时搓之。\"\n\n③《贵州民间方药集》：\"解热，治目疾。又用治麻(疣)子。\"\n\n④《陆川本草》：\"去湿，消肿。治黄水疮。\"\n\n⑤《重庆草药》：\"治目疾流泪起雾。\"","y":"内服：煎汤，2～4钱(鲜者1～2两)。外用：煎水洗或捣敷。","d":"?"},"紫金牛":{"a":"平地木、叶下红(《李氏草秘》)，叶底红、矮脚樟(《杨春涯经验方》)，矮茶、雪里珠、矮脚草、地茶(《植物名实图考长编》)，矮茶荷(《草木便方》)，矮茶风、地青杠(《分类草药性》)，矮茶子(《天宝本草》)，千年不大(《中国药植志》)，叶下珍珠(《江西民间草药》)，老不大(《浙江民间草药》)，铺地凉伞、矮郎伞(《广西药植名录》)，矮脚茶、阴山红、映山红、野枇杷叶(《上海常用中草药》)，矮地茶(《湖南药物志》)。","s":"苦，平。\n\n①《植物名实图考》：\"性寒。\"\n\n②《现代实用中药》：\"苦，平。\"","f":"镇咳，祛痰，活血，利尿，解毒。治慢性气管炎，肺结核咳嗽咯血，吐血，脱力劳伤，筋骨酸痛，肝炎，立即，急慢性肾炎，高血压，疝气，肿毒。\n\n①《李氏草秘》：\"治偏坠疝气，捣汁冲酒服半碗。\"\n\n②《植物名实图考》：\"治肿毒，血痢，解蛇毒，救中暑。\"\n\n③《草木便方》：\"治风湿顽痹，肺痿久嗽。涂寒毒肿痛。\"\n\n④《分类草药性》：\"治吐血，咳嗽，气痛。\"\n\n⑤《现代实用中药》：\"为强壮剂，有止血作用。治肺结核咳嗽吐血；酒服，治跌打损伤，睾丸肿痛。\"\n\n⑥《上海常用中草药》：\"活血止痛，利尿，健胃，止血。治湿热黄疸，肝炎，急性肾炎，膀胱炎，肺结核盗汗、咯血，脱力劳伤，筋骨酸痛，月经不调，副鼻窦炎。\"\n\n⑦金华《常用中草药单方验方选编》：\"通经活血，凉血解毒。治肺痨咳血，刀伤出血，无名肿毒，月经不调，小儿疳积，痢疾，脱肛，习惯性流产，少乳，慢性肾炎，高血压。\"","y":"内服：煎汤，3～4钱，大剂1～2两；或捣汁。外用：捣敷。","d":"?"},"红毛鸡":{"a":"茅笼中鸟、绿结鸡(《陆川本草》)，毛鸡、落谷(《广西中药志》)。","s":"《广西中药志》：\"味甘，性温，无毒。\"","f":"《广西中药志》：\"妇科用以调经、补血。外用治跌打、风湿。\"","y":"内服：，浸酒。外用：浸酒涂敷。","d":"?"},"肺心草":{"a":"梅花草、白侧耳。","s":"甘，寒。","f":"清热润肺，消肿止痛。治肺结核，腮腺炎，淋巴腺炎，喉炎，白带，热毒疮肿，跌打损伤。","y":"内服：煎汤，3～5钱；或研末。外用：捣敷。","d":"?"},"洋金花":{"a":"曼罗花、蔓陀罗花、千叶蔓陀罗花、层台蔓陀罗花、山茄花、押不芦、胡茄花、大闹杨花、马兰花、风茄花、佛花、天茄弥陀花、洋大麻子花、关东大麻子花、虎茄花、风麻花、酒醉花、羊惊花、枫茄花、广东闹羊花、大嗽叭花","s":"味辛，性温，有毒。归肺，肝经。\n①《纲目》：\"辛，温，有毒。\"\n\n②《生草药性备要》：\"味甘，性温，有毒。\"\n\n③《本草便读》：\"辛，温，大毒。\"","f":"定喘，止咳，祛风，麻醉止痛，解痉止搐。治哮喘，惊痫，风湿痹痛，脚气，疮疡疼痛。并作外科手术麻醉剂。\n\n①《纲目》：\"诸风及寒湿脚气，煎汤洗之。又主惊痫及脱肛，并入麻药。\"\n\n②《生草药性备要》：\"少服止痛，通关利窍，去头风。\"\n\n③《本草便读》：\"止疮疡疼痛，宣痹着寒哮。\"\n\n④《陆川本草》：\"治咳嗽，跌打疼痛。\"","y":"内服：煎汤(或泡水)，1～1.5分；入散剂，3～5厘；煎酒或作卷烟吸。外用：煎水洗或研末调敷。","d":"①南洋金花：为白曼陀罗的干燥花朵。多为数十朵捆成一把。花萼一般已除去。花冠漏斗状，长10～15厘米，黄棕色至淡棕色，皱褶，筒状部具纵皱纹，上部5裂，多已破碎，完整者裂片尖端呈丝状，两者之间呈凹陷，雄蕊5，多包于花冠筒内。雌蕊1。花纸质，易碎。气微，味苦而涩。以去萼、朵大、质厚、整齐、黄棕色、有香气者为佳。\n主产江苏、福建、广东等地。\n\n②北洋金花：为毛曼陀罗的干燥花朵。多分散，或捆成小把。花形状与南洋金花类似而较短，但带有黄绿色至灰绿色的萼筒，萼筒上有5个棱角，长3～5厘米，灰绿色，外被灰白色柔毛。气味同南洋金花。以朵大、黄棕色、完整、无杂质者为佳。\n主产河北、山东、河南等地。\n\n除上述两种外，尚有几种同属植物的干燥花，亦同等入药：①欧曼陀罗，茎淡绿色。花白色。蒴果卵球形，先端具较长的坚硬针刺，成熟时规则的4瓣裂(分布长江流域各省)。\n\n②紫花曼陀罗，茎淡紫红色。花淡紫色；花萼上部亦略具淡紫点。蒴果卵球形，具近于等长的坚硬针刺；成熟时规则的4瓣裂(分布长江流域各省)。\n\n③无刺曼陀罗，花白色，蒴果平滑无刺。\n\n④重瓣曼陀罗，花冠2～3层，外面紫色，内白色。"},"野木瓜":{"a":"那蘑、牛藤(《广西植物名录》)。","s":"性味：甘；性温\n性状：性状鉴别 茎圆柱形，长3-5cm，直径0.3-2.5cm。表面灰棕色至棕色，有粗纵纹，栓皮常块状脱落而显露内部纤维束；细茎具光泽，纵纹明显，有小枝痕与叶痕。质坚硬，稍带韧性。切断面皮部常与木部分离，皮部狭窄，深棕色，可见灰白色波环状中柱鞘，木部宽广，浅棕黄色，射线致密，导管孔明显。叶片完整或破碎，背面网脉间有白色斑点。气微、味淡、稍苦涩。显微鉴别 茎横切面：木栓层有时夹有石细胞，与爆壁细胞形成落皮层。皮层散有石细胞群，近木栓怪处几连成环状。中柱鞘纤维壁厚，木化，在紧接韧皮部多排列成新月形，髓射线处的石细胞群连成环状。韧皮部较窄。束内形成层可见。髓射线数至约20列细胞，木化，壁孔明显，近形成层处均有石细胞群，木质部细胞均木桦，导管直径60-120μm。髓细胞类圆形，壁稍层，木化，壁孔明显。本品薄壁细胞含有众多细小淀粉粒；皮层薄细胞含草酸钙方晶。叶表面观：上表皮细胞壁厚，垂周壁波状弯曲，并略呈串珠状增厚。下表皮细胞有众多不定式气孔，副卫细胞壁稍平直。在扫描电子显微镜下观察叶下表皮，可见气孔与白斑处的圆形凸起物，并有光学显微镜下不可见的刺球体。","f":"①《国药的药理学》：\"为强心、利尿药。\"\n\n②《广西植物名录》：\"藤，止痛；藤及根，利尿。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"柏树叶":{"a":"?","s":"苦；涩；性平\n\n①《分类草药性》:\"苦涩。\"\n\n②《重庆草药》:\"味苦辛，性温，无毒。\"","f":"凉血止血；敛疮生肌。主吐血；血痢；痔疮；癞疮；烫伤；刀伤；毒蛇咬伤\n①《分类草药性》:\"和血。治肠风痔肿，痢疾，吐血；兼涂小儿肥疮。\"\n\n②《重庆草药》:\"止血生肌，治刀伤。\"\n\n③《广西药植名录》:\"治咳血，心气痛，筋缩症。\"","y":"内服:煎汤，3～4钱；或研末。外用:捣敷或研末调敷。","d":"1.性状鉴别：枝叶呈树枝状。叶细小鳞片形，先端锐尖，紧密贴生于小枝上，但在较大的枝上，叶尖不紧贴而成刺状突出；叶面黄绿色或灰绿色；小枝棕褐色。质脆，易断。气淡，味涩。\n2.显微鉴别：柏树叶与侧柏叶主要区别为，表皮和皮层有较多的含棕色物质的细胞，转输管胞的具缘孔少、草酸钙结晶主要少砂晶，偶见片状或柱状结晶。 　　\n3.理化鉴别：取本品粗粉3g，加甲醇30ml，置水浴上回流30min。滤过，滤液蒸干，残渣加5%碳酸钠15ml溶解，用水饱和正丁醇提取2次，每次10ml，再用稀盐酸调节Ph至3-4，用乙醚提取2次，每次10ml，合并醚液挥干，残渣用甲醇2ml溶解，作供试液。另取槲皮素适量，以甲醇溶解作对照液用。分别取上液10μl，点于同一硅胶GF/254薄层板上，以甲苯：乙酸乙酯：甲酸（5：4：1）展开，置紫外灯下检视，供试品色谱中，在与对照品色谱相应的位置上，显相同色斑。"},"矮地茶":{"a":"平地木,老勿大,不出林,叶底珠","s":"性平，味辛、微苦。\n\n⑴《植物名实图考》：“性寒。”\n\n⑴《现代实用中药》：“苦，平。”\n\n归肺、肝经。","f":"化痰止咳，利湿，活血。用于咳嗽、痰中带血、慢性支气管炎、湿热黄疸、跌扑损伤。","y":"用量15～30g。","d":"该品根茎呈圆柱形，疏生须根。茎略呈扁圆柱形，稍扭曲，长10~30cm，直径0.2~0.5cm；表面红棕色，有细纵纹、叶痕及节；质硬，易折断。叶互生，集生于茎梢；叶片略卷曲或破碎，完整者展平后呈椭圆形，长3~7cm，宽1.5~3cm；灰绿色、棕褐色或浅红棕色；先端尖，基部楔形，边缘具细锯齿；近革质。茎顶偶有红色球形核果。气微，味微涩。"},"栗子":{"a":"板栗(《唐本草》)，栗果(《滇南本草》)，大栗(《浙江天目山药植志》)。","s":"甘，温。\n\n①《别录)：\"味咸，温，无毒。\"\n\n②陶弘景：\"甜。\"\n\n③《滇南本草》：\"味甘，平。\"","f":"养胃健脾，补肾强筋，活血止血。治反胃，泄泻，腰脚软弱，吐、衄、便血，金疮、折伤肿痛，瘰疬。\n\n①《别录》：\"主益气，厚肠胃，补肾气，令人忍饥。\"\n\n②《千金·食治》：\"生食之，甚治腰脚不遂。\"\n\n③《唐本草》：\"嚼生者涂病上，疗筋骨断碎、疼痛、肿瘀。\"\n\n④《食性本草》：\"理筋骨风痛。\"\n\n⑤《日华子本草》：\"生食破冷痃癖，日生吃七个。生嚼罯恶刺，并敷瘰疬肿毒痛。\"\n\n⑥《本草图经》：\"活血。\"\n\n⑦《滇南本草》：\"治山岚嶂气，疟疾，或水泻不止，或红白痢疾。用火煅为末。每服三钱姜汤下。\"\"生吃止吐血、衄血、便血，一切血症俱可用。\"\n\n⑧《滇南本草图说》：\"治反胃。\"","y":"内服：生食、煮食或炒存性研末服。外用：捣敷。","d":"?"},"茯苓皮":{"a":"苓皮(《四川中药志》)。","s":"甘淡，平。\n\n《四川中药志》:\"性平，味甘淡，无毒。\"","f":"利水，消肿。治水肿肤胀。\n\n①《纲目》:\"主水肿肤胀，开水道，开腠理。\"\n\n②《医林纂要》:\"行皮肤之水。\"","y":"内服:煎汤，3～5钱。","d":"茯苓皮多为长条状，大小不一，外面黑褐色或棕褐色，有疣状突起，内部白色或灰棕色。体软质松，具有弹性。"},"筋骨草":{"a":"白毛夏枯草,散血草,破血丹。","s":"苦，寒，无毒。","f":"清热凉血，退热消肿。","y":"内服：煎汤，15-30g。外用：适量，捣蛋烂敷。","d":"?"},"狗骨":{"a":"龙沙，卑相，卑监，狗骨，色道麻，结力根，麻黄草，草麻黄，中麻黄，木贼廓黄，山麻黄，川麻黄，田麻黄，华麻黄，木麻黄，西麻黄，朱芯麻","s":"甘，温。\n\n①《纲目》：\"甘，平，无毒。\"\n\n②《四川中药志》：\"性温，味辛咸，无毒。\"\n归肺、膀胱经。","f":"健脾和络，活血生肌。治风湿痛，腰腿无力，四肢麻木，久痢，疮瘘，冻疮。\n\n①《别录》：\"烧灰疗下利，生肌。\"\n\n②陶弘景：\"烧屑疗诸疮瘘及妒乳痈肿。\"\n\n③《本草拾遗》：\"煎为粥，热补，令妇人有子。\"\n\n④《蜀本草》：\"主补虚，小儿惊痫，止下利。\"\n\n⑤《纲目》：\"烧灰，米饮日服，治休息久痢；猪脂调，敷鼻中疮。\"\n\n⑥《四川中药志》：\"治风湿关节痛，冷骨风痛，腰腿无力及四肢麻木。\"","y":"内服：浸酒或烧存性研末，3～5钱。外用：烧灰研末调敷。","d":"骨质坚实，不甚沉重，白色或微黄色，断面不平正，内心网状髓质不明显。以四肢骨为佳。"},"甜杏仁":{"a":"南杏、南杏仁","s":"①《本萆便读》：\"味甘，性平。\"\n\n②《四川中药志》：\"性平，味甘，无毒。\"","f":"润肺，平喘。治虚劳咳喘，肠燥便秘。\n\n①《现代实用中药》：\"有滋润性，内服具轻泻作用，并有滋补之效。外用常用于表皮剥脱时作敷料，呈保护作用。\"\n\n②《四川中药志》：\"能润肺宽胃，祛痰止咳。治虚劳咳嗽气喘，心腹逆闷，尤以治干性、虚性之咳嗽最宜。\"","y":"内服：煎汤，2～3钱；或入丸剂。外用：捣敷。","d":"干燥种子，呈扁心脏形，长1.6～2.1厘米，宽1.2～1.6厘米，顶端尖，基部圆，左右对称，种脊明显，种皮较苦杏仁为厚，淡黄棕色，自合点处分散出许多深棕色脉纹，形成纵向凹纹。断面白色。子叶接合面常见空隙。气微，味微甜。以颗粒均匀而大、饱满肥厚、不发油者为佳。\n主产河北、北京、山东等地；此外，陕西、四川、内蒙古、甘肃、新疆、山西、东北等地亦产。\n\n本品在江苏、山东、河南、四川、陕西等地有时作巴旦杏仁使用。"},"苎麻叶":{"a":"?","s":"味甘，性寒，无毒。入肺、脾、肾三经。","f":"凉血止血；散瘀消肿；解毒。主咯血；吐血；血淋；尿血；月经过多；外伤出血；跌仆肿痛；脱肛不收；丹毒；疮肿；乳痈；湿疹；蛇虫咬伤。","y":"","d":""},"倒水莲":{"a":"金鸡尾","s":"性寒，味苦涩，无毒。","f":"治疟疾寒热，湿热发黄，头晕，目疼及腹痛泻痢。","y":"内服：煎汤，4～8钱；或炖肉。","d":"?"},"岩白菜":{"a":"呆白菜、矮白菜(《植物名实图考》)，岩壁菜(《中国药植志》)","s":"《四川中药志》：\"性平，味甘，无毒。\"\n《四川中药志》：\"入肝、脾二经。\"","f":"治虚弱头晕，劳伤咳嗽，吐血，咯血，淋浊，白带，肿毒。\n\n①《植物名实图考》：\"治吐血。\"\n\n②《分类草药性》：\"化痰止咳。治一切内伤吐血，气喘，淋症。\"\n\n③《峨嵋药植》：\"治头晕虚弱，为治痨要药。\"\n\n④《四川中药志》：\"滋补强壮，止血，止咳。治肝脾虚弱，劳伤吐血，内伤咯血，肺病咳喘，妇女白带及男子淋浊；外敷无名肿毒。\"","y":"内服：煎汤，鲜者2～4两。","d":"岩白菜干燥全草长25～30厘米。根茎粗直，圆柱形，长约10厘米，粗1～1.5厘米，外表粗糙，有大型的环节状纹理，根皮棕褐色，多成片脱落。质脆，断面内心棕红色。叶片大，长椭圆形，厚实无毛，枯绿黄色，背面色淡，微带粉红；叶柄粉红色，易破碎。以片大、根茎粗壮为佳。\n产于四川。"},"金果榄":{"a":"金楛榄(《药性考》)，金苦榄(《柑园小识》)，地胆、天鹅蛋(《分类草药性》)，九牛胆、铜秤锤、金银袋(《广西野生资源植物》)，金榄(《陆川本草》)，地苦胆(《四川中药志》)，地蛋、破石珠(《湖南药物志》)，金牛胆(广州部队《常用中草药手册》)，山茨菇、九牛子(《江西草药》)","s":"苦，寒。\n\n①《药性考》：\"苦，大寒。\"\n\n②《纲目拾遗》：\"性凉。\"\n\n③《本草再新》：\"味甘酸，性寒，无毒。\"","f":"清热解毒。治急慢性扁桃体炎，急性咽喉炎，口腔炎，腮腺炎，乳腺炎，阑尾炎，痈疽疔疮，急慢性肠炎，菌痢，胃痛，热嗽失音。\n\n①《药性考》：\"解毒。咽喉痹急，口烂宜服。疽痈发背，焮赤疔瘯，蛇蝎虫伤，磨涂。治目痛，耳胀，热嗽，岚瘴，吐衄，一切外症。\"\n\n②《柑园小识》：\"祛内外结热，遍身恶毒，消瘴疠，双单喉蛾及齿痛，切薄片含；磨涂疔疮肿毒。\"\n\n③《本草再新》：\"滋阴降火，止渴生津。\"\n\n④《陆川本草》：\"治小儿胎毒。\"\n\n⑤广州部队《常用中草药手册》：\"清热解毒，利咽止痛。治白喉，急性咽喉炎，扁桃体炎，热咳失音，菌痢，跌打，蛇伤。\"\n\n⑥《广西中草药》：\"治急性胃肠炎，口腔炎。\"\n\n⑦《广西实用中草药新选》：\"治胃痛，外感高热症，接触性皮炎等。\"","y":"内服：煎汤，1～3钱；研末或磨汁。外用：捣敷、研末吹喉或切片含。","d":"干燥块根呈不规则圆块状，或切成半圆球形，大小不一，长约7厘米，直径约1.5～4厘米。表面灰棕色，略带黄绿色，皱缩，凹、凸不平，块根两端有小根的残基。质坚实，不能折断。切面淡黄白色，有淡棕色细车轮纹，显粉性，气淡。味苦。以表面微黄绿色、断面淡黄色、个大、坚实者佳。\n主产广西、湖南、贵州。此外，广东、四川亦产。\n\n湖南、贵州等地，有将本品作\"山慈姑\"使用。"},"野葡萄藤":{"a":"大风藤","s":"味甘，性平。","f":"止血，清热利湿，安胎，解热，消肿解毒。治麻疹，痢疾，疮疡肿毒.\n\n①《广西药植名录》：\"全株：止血，祛风湿，安胎，解热。治麻疹。\"\n\n②《广西植物名录》：\"叶：清热利湿，消肿解毒。治痢疾，疮疡肿毒。\"","y":"内服：煎汤，2～3钱。外用：研粉撒。","d":"?"},"一枝黄花":{"a":"土泽兰","s":"辛苦，凉。\n\n①《闽南民间草药》：\"苦，寒。\"\n\n②《上海常用中草药》：\"辛苦，凉.\"","f":"疏风清热，消肿解毒。治感冒头痛，咽喉肿痛，黄疸。百日咳，小儿惊风，跌打损伤，痈肿发背，鹅掌风。\n\n①《植物名实图考》：\"洗肿毒。\"\n\n②《南宁市药物志》：\"清热解毒。治蛇伤，痧气，疮肿。\"\n\n③《湖南药物志》：\"疏风解毒，退热行血，消肿止痛。\"\n\n④《闽东本草》：\"发汗解表。治寒热往来，外感风寒，头身疼痛。\"\n\n⑤《广东中药》：\"破血，通关窍。治跌打损伤，皮肤瘙痒，缠身疮。\"","y":"内服：煎汤，3～6钱(鲜者o.7～1两)。外用：捣敷或煎水洗。","d":"理化鉴别 （1）取本品粉末1g，加水适量煮沸，制成1%水浸液，经剧烈振摇后，有持久性泡沫。（检查皂甙）（2）取本品粉末5g，加甲醇25ml回流20min，滤过。滤液1ml，加盐酸数滴及镁粉少许，渐显红色反应。（检查黄酮）（3）薄层色谱 将上述甲醇提取液浓缩成1：1作为供试品溶液。另以芦丁的甲醇深液作为对照品溶液。取供试品溶液和对照品溶液分别点样于同一聚酰胺薄膜（浙江黄岩）上。用丙酮-甲醇-水（2：1：1）展开，展距10cm。先在紫外光灯（254nm）下观察，供试品溶液色谱在与对照品溶液色谱的相应位置上显相同的红棕色荧光斑点；再喷以1%三氯化铝剂后烤干，斑点转亮黄色。"},"刺梨根":{"a":"茨藜子根(《天宝本草》)，茨藜根(《贵阳民间药草》)。","s":"甘酸，平。\n\n①《草木便方》：\"甘酸，涩。\"\n\n②《分类草药性》：\"味苦。\"\n\n③《贵阳民间药草》：\"酸涩，平，无毒。\"","f":"健胃，消食，止泻，涩精。治胃痛，泄泻，痢疾，遗精，崩漏，带下，久咳。\n\n①《草木便方》：\"止痢，治牙痛，崩带。\"\n\n②《分类草药性》：\"止泻。治喉痛，吐血，红崩，白带。\"\n\n③《贵阳民间药草》：\"健胃止痛，消食去胀。治久咳，久痢。\"\n\n④《四川中药志》：\"治痔疮，牙龈肿痛。并能发乳，止遗精。\"","y":"内服：煎汤，0.5～2两。","d":"?"},"排钱草":{"a":"龙鳞草、午时合(《生草药性备要》)，金钱草、午时灵(《岭南采药录》)，叠钱草、钱排草(《广西野生资源植物》)，双排钱(《福建民间草药》)，金钱豹、四季春(《泉州本草》)，钱串草(江西《草药手册》)，双金钱、纸钱剑、猎狸尾草(《福建中草药》)。","s":"《生草药性备要》：\"味淡苦，性平。\"","f":"祛风利水，散瘀消肿。治感冒，风湿痹痛，水肿臌胀，喉风，牙痛，跌打肿痛。\n\n①《生草药性备要》：\"消风热，浸酒去瘀生新，治小儿马牙疳，又治跌打。\"\n\n②《岭南采药录》：\"治月内锁喉病，牙痛，以之浸酒能去瘀生新，又能去湿消滞。\"","y":"内服：煎汤，2～5钱(鲜者2～4两)；或浸酒。外用：捣敷。","d":"?"},"铁马鞭":{"a":"金钱藤、野花草(《浙江天目山药植志》)。","s":"苦、辛，平。","f":"治体虚久热不退，痧症腹部胀痛，水肿，痈疽，指疔。\n\n《植物名实图考》：\"散血。\"","y":"内服：煎汤，5～6钱。外用：酒浸后捣敷。","d":"?"},"沙枣":{"a":"银柳、红豆(《中国高等植物图鉴》)。","s":"《内蒙古中草药》：\"味甘酸涩，性平。\"","f":"《新疆中草药手册》：\"强壮，镇静，固精，健胃，止泻，调经，利尿。治胃痛，腹泻，身体虚弱，肺热咳嗽。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"尖尾风":{"a":"尖尾峰、起疯晒(《生草药性备要》)，赶风晒、赶风帅(《本草求原》)，赤药子(《植物名实图考》)，赶风柴(《岭南采药录》)，大风药(《广西中兽医药植》)，尖尾枫(《中国经济植物志》)，雪突、牛舌癀(《福建中草药》)。","s":"辛，温。\n\n①广州部队《常用中草药手册》：\"辛，温。\"\n\n②《福建中草药》：\"苦辛，温。\"","f":"祛风散寒，活血消毒。治风湿骨痛，风寒咳嗽，寒积腹痛，无名肿毒，跌打损伤。\n\n广州部队《常用中草药手册》：\"行气活血，祛风消肿。治跌打损伤，骨折，风湿性腰腿痛，毒蛇咬伤。\"","y":"内服：煎汤，5～8钱。外用：研末调敷或鲜品捣敷。","d":"茎枝呈方柱形，表面棕褐色，有点状凸起的灰白色皮孔，节上有一圈黄棕色柔毛。叶皱缩破碎，完整者展平后呈披针形至狭椭圆形，长10-20cm或更长，宽2-5cm，先端锐尖，基部楔形，全缘或有不明显小齿，上面暗绿色，下面暗黄绿色，有细小的黄色腺点;叶柄长1-1.5cm。叶腑有残留小花。揉搓后有芳香气，味微辛、辣。以枝幼嫩、叶多而绿者为佳。"},"泥鳅":{"a":"鳛、鳅(《尔雅》)，鳅鱼(《本草拾遗》)，和鳅(《泉州本草》)。","s":"甘，平。\n\n①《滇南本草》：\"味酸甘。\"\n\n②《医学入门》：\"甘，温，无毒。\"\n\n③《纲目》：\"甘，平，无毒。\"","f":"补中气，祛湿邪。治消渴，阳痿，传染性肝炎，痔疾，疥癣。\n\n①《滇南本草》：\"煮食治疮癣，通血脉而大补阴分。\"\n\n②《医学入门》：\"补中，止泄。\"\n\n③《纲目》：\"暖中益气，醒酒，解消渴。\"\n\n④《随息居饮食谱》：\"杀虫。\"\n\n⑤《四川中药志》：\"利小便。治皮肤瘙庠，疥疮发痒。\"","y":"内服：煮食或烧存性入散剂。外用：烧存性研末调敷。","d":"?"},"祖师麻":{"a":"祖司麻、走司马、走丝麻、大救驾、黄杨皮、爬岩香、金腰带","s":"《陕西中药志》：\"辛苦，温，有小毒。\"","f":"祛风除湿，止痛散瘀。治风湿痹痛，四肢麻木，头痛，胃痛，跌打损伤。\n\n①《陕西中药志》：\"止痛，散血，补血，有麻醉性。用于跌打损伤，周身疼痛，头痛，心胃痛，腰腿痛。又治四肢麻木。\"\n\n②《陕西中草药》：\"祛风除湿，温中散寒。治感冒，风湿疼痛，中风麻木，半身不遂，皮肤痒疹。\"","y":"内服：煎汤，1～2钱；或煅研为散。","d":"干燥根皮，呈带状，宽1～2厘米，边缘内卷成筒状，外表灰棕色至紫棕色，有纵皱及横纹，栓皮易开裂脱落。内表面浅黄色至淡棕色，光滑，有纵纹理。质坚韧，不易折断，断面富纤维性。气微，味微酸苦。\n\n同科植物结香(参见\"梦花\"条)和陕西瑞香的根皮及茎皮亦同等入药。"},"了哥王":{"a":"地棉皮、山豆了、九信草。","s":"苦辛，寒。有毒。\n\n①《生草药性备要》：\"味辛，性子，有毒。\"\n\n②《南宁市药物志》：\"苦，寒，有毒。\"","f":"清热解毒，消肿散结，止痛。治瘰疬，痈肿，风湿痛，百日咳，跌打损伤。\n1、《生草药性备要》：消热毒疮，手指生狗皮头。可撕皮扎之。\n2、《岭南采药录》：叶和盐捣烂外敷。能去皮肤红黑瘀血，拔毒消肿。\n3、《南宁市药物志》：杀虫解毒，消肿，止痛，清热，泻下。治麻风，梅毒，痈疮，无名肿毒，风湿痛，肺痨，痧气，百日咳，痢症。","y":"内服：煎汤(宜久煎4小时以上)，2～3钱。外用：捣敷，研末调敷或煎水洗。","d":"?"},"松花粉":{"a":"松花、松黄(《唐本草》)。","s":"甘，温。\n\n\n①《本草衍义》：\"味淡。\"\n\n\n②《纲目》：\"甘，温，无毒。\"\n\n\n入足厥阴肝经、足太阴脾经","f":"祛风益气，收湿，止血。治头旋眩晕，中虚胃疼，久痢，诸疮湿烂，创伤出血。\n\n\n①《纲目》：\"润心肺，益气，除风，止血。亦可酿酒。\"\n\n\n②《本草汇言》：\"疗久痢，解酒毒，清血热。\"\n\n\n③《本经逢原》：\"除风湿，治痘疮湿烂。\"\n\n\n④《随息居饮食谱》：\"酿酒主养血息风。\"\n\n\n⑤《江苏植药志》：\"预防汗疹。外用作创伤止血剂。\"\n\n\n⑥《四川中药志》：\"收敛止血。治皮肤湿疹，黄水疮湿烂不结痂。\"","y":"内服：煎汤，1～2钱；浸酒或调服。外用：干掺或调敷。","d":"干燥松花粉为淡黄色的细粉末，用扩大镜观察，呈均匀的小圆粒。体质轻飘，易飞扬，手捻有滑润感，不沉于水。气微香，味有油腻感。以黄色、细腻、无杂质、流动性较强者为佳。\n\n\n主产浙扛、江苏、辽宁、吉林、湖北等地。"},"罗汉果":{"a":"拉汗果、假苦瓜、光果木鳖、金不换、罗汉表、裸龟巴","s":"味甘;性凉\n\n\n①《岭南采药录》：“味甘。”\n\n\n②《广西中药志》：“味甘，性凉，无毒。”\n\n\n入肺、脾二经\n\n\n《广西中药志》：\"入肺、脾二经。\"","f":"清肺润肠。治百日咳、痰火咳嗽，血燥便秘。\n\n\n①《岭南采药录》：\"理痰火咳嗽，和猪精肉煎汤服之。\"\n\n\n②《广西中药志》：\"止咳清热，凉血润肠。治咳嗽，血燥胃热便秘等。\"","y":"内服：煎汤，3～5钱。","d":"干燥果实，圆形至长圆形，径5～8厘米，外表黄褐色至深棕色，较光泽，微具残留毛茸，少数有较深色的纵条纹。顶端膨大，中央有一圆形的花柱基痕，基部略狭，有果柄痕。质脆易碎，破碎后内表面黄白色，疏松似海绵状。除去中果皮，可见明显的纵脊纹10条。种子扁平，矩圆形或类圆形，棕色，边缘较厚，中央微凹，内有子叶2枚。味甜。以形圆、个大、坚实、摇之不响、色黄褐者为佳。\n\n\n主产广西。"},"木姜子":{"a":"山胡椒、木香子、木樟子、山姜子、木椒子、腊梅柴、大木姜、香桂子、猴香子、生姜材、黄花子、辣姜子","s":"味辛，苦；性温。归脾、胃经。","f":"健脾，燥湿，调气，消食，止痛，解毒消肿。主胃寒腹痛；暑湿吐泻；食滞饱胀；痛经；疝痛；疟疾；疮疡肿痛\n。\n\n①《贵州民间药物》：\"健脾燥湿，助消化，外治疮毒。\"\n\n②《重庆草药》：\"逐寒、镇痛，健胃、消饱胀。治心胃冷气痛，冷骨风，寒食摆子，痛经。\"\n\n③《湖南药物志》：\"祛风，散寒。\"","y":"内服：煎汤，3～5钱；或入散剂。外用：捣烂敷或研粉调敷。","d":"性状鉴别 果实类圆球形，直径4-5mm。外表面黑褐色或棕褐色，有网状皱纹，先端钝圆，基部可见果柄脱落的圆形疤痕，少数残留宿萼及折断提醒柄。除去果皮，可见硬脆的果核，表面暗棕褐色。质坚脆，有光泽，外有一隆起纵横纹。破开后，内含种子1粒，胚具子叶2片，黄色，富油性。气蓄谋香，味辛辣，微苦而麻。"},"香茅":{"a":"大风茅(《岭南采药录》)，柠檬茅(《种子植物名称》)，柠檬草(《广州植物志》)，茅草茶、姜巴茅(《贵州民间药物》)，姜草、香巴茅(《四川中药志》)，香茅草、风茅草(《广东中药》Ⅱ)，姜巴草(《贵州草药》)。","s":"辛，温。\n\n①《岭南采药录》：\"味辛。\"\n\n②《陆川本草》：\"辛，温。\"\n\n③《四川中药志》：\"性温，味辛辣，无毒。\"","f":"疏风解表，祛瘀通络。治感冒头痛，胃痛，泄泻，风湿痹痛，跌打损伤。\n\n①《岭南采药录》：\"散跌打伤瘀血，通经络。头风痛，以之煎水洗。将香茅与米同炒，加水煎饮，止水泻。煎水洗身，可祛风消肿，解腥臭。提取其油，可止腹痛。\"\n\n②《陆川本草》：\"发表退热，消肿止痛。主治风湿骨痛，跌打损伤，感冒身热。\"\n\n③《四川中药志》：\"祛风湿，散凉寒。治筋骨疼痛及半身麻木。\"\n\n④《广东中药》Ⅱ：\"治头晕，头风，风痰，鹤膝症；煎水饮可以止心痛。\"\n\n⑤《贵州草药》；\"补虚，止咳，镇痛，宁心。\"","y":"内服：煎汤，1～2钱；或浸酒。外用：煎水洗或研末调敷。","d":"?"},"紫草—新疆紫草":{"a":"软紫草、硬紫草、大紫草、红条紫草","s":"根呈不规则的长圆柱形，多扭曲，长7～20cm，直径1～2·5cm。\n\n\n　　表面紫红色或紫褐色，皮部疏松，呈条片状，常10余层重叠，易剥落。\n\n\n　　顶端有的可见分歧的茎残基。\n\n\n　　体轻，质松软，易折断，断面不整齐，黄白色或黄色。\n\n\n　　气特异，味微苦、涩。","f":"凉血，活血，解毒透疹。用于血热毒盛、斑疹紫黑、麻疹不透、疮疡、湿疹、水火烫伤。","y":"?","d":"?"},"金箔":{"a":"金薄(《药性论》)。","s":"辛苦，平。\n\n①《本草汇言》：\"味辛，气寒，有毒。\"\n\n②《本经逢原》：\"无毒。\"\n\n③《本草求真》：\"辛，平。\"","f":"镇心，安神，解毒。治惊痫，癫狂，心悸，疮毒。\n\n①《药性论》：\"主小儿惊伤，五藏风痫，失志，镇心，安魂魄。\"\n\n②《海药本草》：\"主癫痫风热，上气咳嗽，伤寒肺损吐血，骨蒸劳极作渴.主利五藏邪气，补心，并入薄于丸、散服。\"\n\n③《本草蒙筌》：\"除邪杀毒，却热驱烦，安魂魄，养精神，坚骨髓，和血脉，禁癫狂疾走，止惊悸风痫。幼科药作锭丸，必资此以为衣饰。\"\n\n④《本草经疏》：\"磨细屑，挑开疔疮头上，没入，能拔疔根。\"\n\n⑤《本草再新》：\"舒肝气，定心智，安魂魄，滋肾水，行经络，利关节，破积消疽，治小儿惊痫、痘疮诸毒。\"","y":"内服：入丸、散。一般多作丸药挂衣。外用：研末撒。","d":"(1)取本品少许，加王水，振摇，溶解后，溶液呈鲜黄色透明液体。（检查金）若有白色沉淀，表明本品含有银。(2)取本品少量，加王 水，溶解后，溶液加热浓缩成稠厚液，再用水冲淡，加热，加氯化亚锡试液，溶液变为紫色，并有紫色沉淀。（检查金）"},"黄蜀葵花":{"a":"黄蜀葵、棉花葵、水棉花、野芙蓉、侧金盏","s":"①《品汇精要》：\"无毒。\"\n\n②《纲目》：\"甘，寒，滑，无毒。\"","f":"通淋，消肿，解毒。治淋病，痈疽肿毒，汤火烫伤。\n\n①《嘉祐本草》：\"治小便淋及催生，又主诸恶疮脓水久不瘥者，作末敷。\"\n\n②《纲目》：\"消痈肿，浸油涂汤火伤。\"","y":"内服：研末，1～2钱。外用：研束调敷或油浸涂。","d":"?"},"楮实子":{"a":"彀实","s":"味甘；性寒","f":"?","y":"6～12g。","d":"本品粉末红棕色。果皮栅状细胞壁黏液化，残存具细齿状的条纹增厚部分，形似细芒。含晶厚壁细胞成片，棕黄色，表面观类多角形，内含草酸钙簇晶；断面观类长方形，内壁极厚，胞腔偏靠外侧，簇晶矩圆形。内果皮厚壁细胞甚扁平，常多层重叠，界限不清。种皮表皮细胞表面观多角形，壁略呈连珠状增厚，非木化，胞腔内含黄棕色物。"},"老鼠瓜":{"a":"槌果藤(《新疆中草药手册》)，菠里克果(维名)。","s":"味辛苦，性温。\n\n入肺经。","f":"祛风，散寒，除湿。","y":"外用适量，捣烂外敷。","d":"?"},"胡萝卜":{"a":"黄萝卜(《本草求原》)，胡芦菔、红芦菔(《随息居饮食谱》)，丁香萝卜(《现代实用中药》)，金笋(《广州植物志》)，红萝卜(《岭南草药志》)。","s":"甘，平。\n\n①《日用本草》:\"味甘辛，无毒。\"\n\n②《饮膳正要》:\"味甘，平，无毒。\"\n\n③《医林纂要》:\"生微辛苦，熟则纯甘。\"","f":"健脾，化滞。治消化不良，久痢，咳嗽。\n\n①《日用本草》:\"宽中下气，散胃中邪滞。\"\n\n②《纲目》:\"下气补中，利胸膈肠胃，安五脏，令人健食。\"\n\n③《医林纂要》:\"润肾命，壮元阳，暖下部，除寒湿。\"\n\n④《岭南采药录》:\"凡出麻痘，始终以此煎水饮，能消热解毒，鲜用及晒干用均可。\"\n\n⑤《现代实用中药》:\"治久痢。\"","y":"内服:煎汤、生食或捣汁。外用:捣汁涂。","d":"?"},"鹿血":{"a":"?","s":"①《日用本草》：\"味甘。\"\n\n②《医林纂要》：\"咸，热。\"","f":"补虚，和血。治虚损腰痛，心悸，失眠，肺痿吐血；崩中，带下。\n\n①《千金·食治》：\"生血，治痈肿。\"\n\n②《唐本草》：\"主狂犬伤。鼻衄，折伤，阴痿，补虚，止腰痛。\"\n\n③《日华子本草》：\"治肺痿吐血及崩中，带下，和酒服之良。\"\n\n④《日用本草》：\"补阴，益营气。\"\n\n⑤汪颖《食物本草》：\"诸气痛欲危者，饮之。\"\n\n⑥《纲目》：\"大补虚损，益精血，解痘毒、药毒。\"\n\n⑦《医林纂要》：\"行血祛瘀，续绝除伤，与山羊血同而性较中和。\"","y":"内服：入丸、散，1～2钱。","d":"?"},"铁树叶":{"a":"?","s":"甘淡，凉。\n\n\n①《本草求原》：\"淡，微寒。\"\n\n\n②《陆川本草》：\"苦，寒。\"\n\n\n③《广西中草药》：\"味甘，性平，无毒。\"","f":"清热，止血，散瘀。治痢疾，吐血，便血，胃痛，尿血，月经过多，跌打肿痛。\n\n\n①《纲目拾遗》：\"治一切心胃及气痛。\"\n\n\n②《本草求原》：\"散瘀止血，活筋骨中血。治下血、吐血，煎肉食。跌打肿痛，同原酒糟敷之;加葱头、醋敷之，拔一切毒风、酒风。\"\n\n\n③《植物名实图考》：\"治痢证。\"\n\n\n④《陆川本草》：\"解热毒，凉血，止血。治痢疾，肠出血，尿血。\"\n\n\n⑤广州部队《常用中草药手册》：\"治肺结核咯血，先兆流产，月经过多，尿血，痔疮出血。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"韭菜子":{"a":"韭菜仁,韭子","s":"味辛；甘；性温 \n\n归肝；肾经","f":"补肝肾，暖腰膝，助阳，固精。用于阳痿、遗精、遗尿小便频数、腰膝酸软、冷痛、白带过多。","y":"内服：煎汤，6-12g；或入丸、散。","d":"性状鉴别 种子扁卵形，一面微凹，另面隆起，先端钝，基部稍尖，长3-4mm，宽2-3mm。表面黑色，隆起面有明显的网状皱纹，凹入面皱纹不甚明显，基部有两个小突起，较短的突起顶端灰棕色或灰白色，为种脐，较长的突起顶端为珠孔。纵切面可见种皮菲薄，胚乳灰白色，弯曲，子叶1枚。质坚硬。气特异，嚼之有韭菜味。以粒饱满、色黑、无杂质者为佳。显微鉴别 处子横切面：种皮表皮细胞较平整，细胞壁厚，外壁被有薄角质层，细胞腔含暗褐色物质，其下为数列棕黄色薄壁细胞。胚乳细胞形大，壁甚厚，有大形纹孔，胞腔内含有糊粉粒及脂肪油。粉末特征：灰黑色。①种皮表皮细胞黑色或棕黑色，长条形、类圆形、多角形或不规则形，直径（37-)74-139（200-)μm，表面具网状纹理。②胚乳细胞众多，多破碎，有较多大的类圆形或长圆形纹孔。"},"辣蓼草":{"a":"辣蓼、酸模叶蓼、旱苗蓼、苦蓼大马蓼、白辣蓼","s":"辛，温。","f":"消肿止痛。治肿疡，痢疾腹痛。","y":"内服：煎汤，1～3钱。外用：捣敷。","d":"?"},"冬青叶":{"a":"四季青叶(江苏)。","s":"《江西草药》：\"苦涩，寒。\"","f":"治烫伤，溃疡久不愈合，闭塞性脉管炎，急、慢性支气管炎，肺炎，尿路感染，菌痢，外伤出血，冻瘃，皲裂。\n\n①《本草图经》：\"烧灰，面膏涂之，治皲瘃殊效，兼灭瘢疵。\"\n\n②《江西草药》：\"凉血止血。治外伤出血，鲜叶捣敷。\"","y":"外用：制成乳剂、膏剂涂搽。内服：浓煎成流浸膏服用。","d":"?"},"金线草":{"a":"重阳柳、蟹壳草(《花镜》)，毛蓼、白马鞭(《植物名实图考》)，人字草、九盘龙(《广西中药志》)，野蓼、一串红(江西《草药手册》)。","s":"辛，温。\n\n①《广西中药志》：\"辛涩，温，有小毒。\"\n\n②《陕西草药》：\"味辛微苦，性温。\"","f":"祛风除湿，理气止痛，止血，散瘀。治风湿骨痛，胃痛，咳血，吐血，便血，血崩，经期腹痛，产后血瘀腹痛，跌打损伤。\n\n①《广西中药志》：\"祛风止痛，健脾燥湿，散瘀消肿。治霍乱吐泻，风湿痛，痈肿瘰疬。\"\n\n②江西《草药手册》：\"散瘀止血，解毒利气。治吐血，咳血，下血，血崩。\"\n\n③《陕西草药》：\"收敛，止血，止痛。治跌打损伤。\"","y":"内服：煎汤，0.3～1两。外用：煎水洗。","d":"?"},"刺梨":{"a":"茨梨(《分类草药性》)，文先果(《四川中药志》)，团糖二(《四川常用中草药》)。","s":"《宦游笔记》：\"味甘而酸涩。\"","f":"健胃，消食。治食积饱胀。\n\n①《贵州民间方药集》：\"健胃，消食积饱胀，并滋补强壮。\"\n\n②《四川中药志》：\"解暑，消食。\"","y":"内服：生食或煎汤。","d":"?"},"三七叶":{"a":"田七叶、山漆叶、金不换叶","s":"味辛；性温 \n\n《生草药性备要》：“味辛。”\n\n入肝、胃二经","f":"止血，消肿，定痛。治吐血，衄血，便血，外伤出血，痈肿毒疮。\n\n①《纲目》：\"治折伤跌扑出血，敷之即止，青肿经夜即散。余功同根。\"\n\n②《生草药性备要》：\"治跌打，消察散血，敷毒疮，治痰火，又能止血。\"","y":"内服：煎汤，1～3钱；或入丸，散。外用：研末撤或调敷。","d":"?"},"山海螺":{"a":"地黄(《别录》，白河车(王安卿《采药志》)，牛奶子(《植物名实图考》)，四叶参(《苏南种子植物》)，白蟒肉、山胡萝卜(《东北药植志》)，乳薯(《江西民间草药》)，奶参、土党参(《广西中药志》)，通乳草、奶奶头(《南京地区常用中草药》)。","s":"甘辛，平。\n\n①《别录》：\"味甘，温，无毒。\"\n\n②《浙江民间草药》：\"味辛，性凉。\"\n\n③《广西中药志》：\"味甘，性平，无毒。\"","f":"消肿，解毒，排脓，祛痰，催乳。治肺痈，乳痈，肠痈，肿毒，瘰疬，喉蛾，乳少，白带。\n\n①《别录》：\"主头眩痛，益气，长肌肉。\"\n\n②汪连仕《采药书》：\"治杨梅恶疮。\"\n\n③《纲目拾遗》：\"治肿毒瘰疬，取汁和酒服，渣敷患处。\"\n\n④《植物名实图考》：\"发乳汁，壮阳道。\"\n\n⑤广州部队《常用中草药手册》：\"滋补强壮，祛痰润肺，排脓解毒。治肺脓肿，乳腺炎，痈疮肿毒，蛇咬伤。\"","y":"内服：煎汤，O.5～1.5两(鲜者1.5～4两)。外用：捣敷。","d":"干燥根略呈纺锤形或圆锥形，大小不等，一般长6～12厘米，直径1～3厘米，有时有分枝。上部较粗，有众多的横皱纹，下部稍细；有纵皱及细根痕迹。外表灰棕色至土黄色，粗糙；除去栓皮的呈灰白色或淡黄白色。质疏松而轻，易折断，断面类白色，多裂隙。味苦微辣。\n\n产黑龙江、广西、浙江、江西、福建等地。"},"水翁花":{"a":"水雍花(《广东中药》)，大蛇药(《广西药植名录》)。","s":"《岭南采药录》：\"味苦，性寒。\"","f":"治外感恶寒发热头痛，食滞不化。\n\n①《岭南采药录》：\"清热，散毒，消食化滞。\"\n\n②《广东中药》：\"治外感发热头痛，感冒恶寒发热。\"\n\n③《广西药植名录》：\"治头痛，跌打，蛇伤。\"","y":"内服：煎汤，0.5～1两。","d":"干燥花蕾呈卵形或球形而两端尖，长约4～6毫米，径约2～3毫米，皱缩，下半部为棕黑色的倒钟形或杯形的萼简，上半部帽状，为5枚合生的花瓣，浅棕黄色。除去帽状体，可见重叠的雄蕊，花丝棕黑色，中央有1锥形花柱。质干硬。气微香，味苦。以黄黑色，无枝梗者为好。\n产广东、广西等地，"},"八角莲":{"a":"山荷叶、金魁莲、旱八角","s":"苦辛，平，有毒。\n\n①《分类草药性》：\"味苦，无毒。\"\n\n②《福建民间草药》：\"甘微辛，温，有毒。\"\n\n③《贵阳民间药草》：\"辛微苦，平，无毒。\"\n\n④《广西中药志》：\"甘苦微辛，性凉，无毒。\"","f":"清热解毒，化痰散结，祛瘀消肿。治痈肿，疔疮，瘰疬，喉蛾，跌打损伤，蛇咬伤。\n\n①《纲目拾遗》：\"治一切毒蛇伤。\"\n\n②《贵州民间方药集》：\"治虚弱脱肛；外用消伤肿，并治蛇咬伤，疔疮。\"\n\n③《福建民间草药》：\"散结活瘀，消瘿解毒。\"\n\n④《广西中药志》：\"清热化痰，解蛇虫毒。治肺热痰咳，虫蛇咬伤，单双蛾喉痛，疮疖。\"\n\n⑤《四川中药志》：\"治劳伤吐血、腰痛，疥癣白秃。\"\n\n⑥广州部队《常用中草药手册》：\"清热解毒，燥湿泻火。治淋巴结炎，腮腺炎，痈疮。\"\n\n⑦《江西草药》：\"治肾虚，劳伤，中暑，胃痛。\"","y":"内服：煎汤，2～4钱；或研末。外用：研末调敷、捣敷或浸酒涂敷。","d":"根茎呈结节状，长约6～10厘米，径约0.7～1.5厘米，鲜时浅黄色，干后呈棕黑色；表面平坦或微凹，上有几个小的凹点，下面具环纹。须根多数，长达20厘米，径约1毫米，有毛，鲜时浅黄色，干后棕黄色。质硬而脆，易折断。根茎断面黄绿色，角质；根的断面黄色，中央有圆点状中柱。气微，味苦。\n产广西、四川、贵州等地。"},"马蹬草":{"a":"过桥草、还阳草、小石韦","s":"淡，平。心经","f":"活血化瘀；止血；解毒。主血栓闭塞性脉管炎；偏瘫；子宫出血；外伤出血；神经性皮炎；下肢溃疡","y":"内服：煎汤，0.5～1.5钱；或研末。外用：研末撒敷。","d":"?"},"鸡眼草":{"a":"掐不齐、人字草、小蓄片、妹子草、红花草、地兰花、土文花、满路金鸡、细花草、鸳鸯草、夜关门、老鸦须、铺地龙、蚂蚁草、莲子草、花花草、夏闭草、花生草、白扁蓄、小关门、瞎眼草、小号苍蝇草、红骨丹","s":"甘、辛，平。\n\n①《本草求原》：\"甘辛，平。\"\n\n②《四川中药志》：\"性寒，味辛，无毒。\"\n\n归肝；脾；肺；肾经","f":"清热解毒，健脾利湿。治感冒发热，暑湿吐泻，疟疾，痢疾，传染性肝炎，热淋，白浊。\n\n①《本草求原》：\"治跌打扑肿，解毒。\"\n\n②《植物名实图考》：\"除火毒。中暑捣取汁，(和)凉水饮之。\"\n\n③《南京民间药草》：\"利小便。\"\n\n④《福州草药》：\"治蛇咬伤。\"\n\n⑤《中医药实验研究》：\"治妇人白带，湿热黄疸，暑泻，肠风便血，红白痢疾。\"\n\n⑥《民间常用草药汇编》：\"治吐血，泻痢及小儿疳疾。\"\n\n⑦《贵州民间药物》：\"止血。治腹痛。\"\n\n⑧《四川中药志》：\"解热、散痧。治腰痛腹泻，发痧，白痢。\"\n\n⑨《浙江民间常用草药》：\"利湿健脾，解热止痢。\"\n\n⑩《上海常用中草药》：\"治感冒发热，咳嗽胸痛，尿路感染，肠炎，痢疾。\"\n\n⑾《福建中草药》：\"利水消积。治消化不良腹泻。\"\n\n⑿《陕西中草药》：\"收敛，固脱。治子宫脱垂，脱肛。\"","y":"内服：煎汤，3～5钱。外用：捣敷或捣汁涂。","d":"性状鉴别 （1)鸡眼草茎枝圆柱形，多分枝，长5-30cm，被白色向下的细毛。三出复叶互生，叶多皱缩，完整小叶长椭圆形或倒卵状长椭圆形，长5-15mm；叶端钝圆，有小突刺，叶基楔形；沿中脉及叶缘疏生白色长毛；托叶2片。花腋生，花萼钟状，深紫褐色；蝶形花冠浅玫瑰色，效萼长2-3倍。荚果卵状矩圆形，顶端稍急尖，有小喙，长达4mm。种子1粒，黑色，具不规则褐色斑点，气微，味淡。\n（2)竖毛鸡眼草 茎多枝，较粗壮，长10-25cm，疏被向上生长的硬毛。三小叶，完整小叶倒卵形或椭圆形，长7-20mm，宽3-12mm；叶端圆或微凹，具短尖，叶基楔形；上面无毛，下面中脉及叶缘有白色长硬毛。花簇生于叶腋，花梗有白色硬毛，花萼钟状，花冠暗紫色。荚果卵形，长约3mm。种子黑色，平滑。气微，味淡。\n显微鉴别 鸡眼草茎横切面：表皮细胞1列，细胞多为椭圆形，外被角质层，尚有非腺毛或其残基。表皮下可见1-3列细胞组成的厚角组织，常边续成环。韧皮部外侧具帽状纤维束，其周围可见草酸钙方晶，纤维壁微木化。形成层成波状环。髓部宽大。\n叶表面制片：上表皮细胞垂周壁浅状弯曲。下表皮细胞垂周壁波状弯曲。上下表皮均有平轴式气孔。非腺毛常为2（1-3)个细胞，基部细胞甚短，顶细胞长，先端渐尖，壁密生壁疣。"},"木棉花":{"a":"木棉,斑枝花,琼枝","s":"广州部队《常用中草药手册》：\"甘，凉。\"","f":"清热，利湿，解毒，止血。治泄泻，痢疾，血崩，疮毒，金创出血。\n\n①《生草药性备要》：\"治痢症，白者更妙。\"\n\n②《本草求原》：\"红者去赤痢，白者治白痢，同武彝茶煎常饮。\"\n\n③《岭南采药录》：\"消暑。\"\n\n④《中药新编》：\"利尿及健胃。\"\n\n⑤《南宁市药物志》：\"去湿热。治血崩，金创。\"\n\n⑥《广西中药志》：\"去湿毒，治恶疮。\"\n\n⑦广州部队《常用中草药手册》：\"清热利湿，治肠炎，菌痢。\"","y":"内服：煎汤，2～3钱。","d":"干燥花多皱缩，不具子房和花柄。花萼杯状，顶端3～5裂，厚革质而脆，外表棕黑色，具不规则纵皱，内面被灰黄色短绒毛；花瓣5片，分离，皱缩戌破碎，外面棕黄色或深棕色，具纵纹，被星状毛，内面红棕色，被少数星状毛；雄蕊多数，花丝红棕色，扭曲，具粗纵纹，花药大部脱落。味淡微甘。\n产广东、广西等地。\n\n古书所载的木棉，常与锦葵科棉属植物混淆不分。《纲目》木棉条集解中即包括锦葵科棉属植物在内，而所述\"交广木棉\"，乃为木棉科植物。"},"急性子":{"a":"金凤花子(《摘元方》)，凤仙子(《纲目》)。","s":"苦辛，温，有毒。\n\n①《纲目》：\"微苦，温，有小毒。\"\n\n②《医林纂要》：\"辛，平。\"\n\n③《本草再新》：\"味苦辛，性凉，有毒。\"","f":"破血，消积，软坚。治经闭，积块，噎膈，外疡坚肿，骨鲠不下。\n\n①《纲目》：\"治产难，积块，噎膈，下骨鲠，透骨通窍。\"\n\n②《本经逢原》：\"软坚，搜顽痰，下死胎。\"\n\n③《玉楸药解》：\"软坚，化骨，消癖，落牙。\"\n\n④《医林纂要》：\"解蛇虫毒。\"\n\n⑤《本草再新》：\"治诸恶疮，败一切火毒。\"\n\n⑥《本草正义》：\"治外疡坚块，酸肿麻木，阴发大症。研末熬膏贴患处，极能软坚消肿。\"","y":"内服：煎汤，0.8～1.5钱；或入丸、散。外用：研末吹喉、点牙，调敷或熬膏贴。","d":"性状鉴别 种子扁圆形或扁卵圆形，长2-3.5mm，宽2-3mm。表面棕褐色，粗糙，有细密疣状突起及短条纹，一端有突出的种脐。质坚硬，剖开后，种皮薄;子叶2枚，肥厚，半透明，油质。气微，味淡，微苦。以颗粒饱满者为佳。\n\n\n　　显微鉴别 种子横切面：外种皮外被腺毛及非腺毛。下皮层1列细胞。色素层细胞含棕红色物质，外侧近下皮层分布有大形薄壁细胞，内含草酸钙针晶束。内种皮1列细胞，壁稍增厚。子叶薄壁细胞含症粉粒及糊粉粒。\n\n\n　　粉末特征：浅棕色。①外种皮细胞垂周壁波状弯曲，有腺毛或非腺毛。③腺毛头部单细胞或2-8细胞，直径20-60μm;柄为单细胞。③非腺毛为单细胞，与腺毛同含黄棕色物质。④含草酸钙针晶细胞椭圆形，针晶长约50μm。⑤内种皮细胞长方形或多角形，壁稍增厚。"},"响铃草":{"a":"野花生(《中国植物志》)，荷猪草、黄花野百合(《中国主要植物图说·豆科》)，马响铃(《滇南本草整理本》)，铃铃草、肾气草(《四川中药志》)，响铃子(《中国药植图鉴》)，小狗响铃、假地豆、地响铃、野豌豆、马小莲、野毛豆(《云南中草药选》)，马铃草、响亮草、荷承草(江西《草药手册》)。","s":"苦微酸，寒。\n\n①《滇南本草》：\"性寒，味苦微酸。\"\n\n②《滇南本草图说》：\"气味辛酸苦。\"","f":"敛肺气，补脾肾，利小便，消肿毒。治久咳痰血，耳鸣，耳聋，梦遗，慢性肾炎，膀胱炎，肾结石，扁桃腺炎，淋巴腺炎，疔毒，恶疮。\n\n①《滇南本草》：\"敛肺气，止咳，消痰，定喘。\"\n\n②《滇南本草图说》：\"治石淋内结；捣烂敷疮。\"\n\n③《草木便方》：\"补中益气，疗耳鸣，头目昏眩，崩淋。又泻火清热，平肝风，消肿痛。\"\n\n④《分类草药性》：\"大补脾肾，治耳聋，气虚。\"\n\n⑤《四川中药志》：\"补中益气，治耳鸣耳聋，头目眩晕，肾亏遗精，及妇女干血劳。\"\n\n⑥《云南中草药选》：\"利水，消炎，平喘，止咳。治慢性肾炎，膀胱炎，慢性支气管炎，扁桃腺炎，淋巴腺炎，肾结石；月经不调，痛经。\"\n\n⑦江西《草药手册》：\"解毒透疹。\"","y":"内服：煎汤，0.5～1两；或炖肉。外用：捣敷。","d":"干燥全草，茎圆形，全体有黄棕色茸毛。叶片卷曲，多脱落，呈椭圆形或卵形，黄绿色。枝端尚带荚果，种子大多脱落。带根者，根婉蜒而长，圆形，少分枝，须根细长，表面土黄色。\n产于云南、四川、贵州等地。\n\n在四川地区，同属植物猪屎豆、野百合(参见\"野百合\"条)及条叶猪屎豆等的全草，与本品同等入药。"},"脆蛇":{"a":"金蛇(《本草拾遗》)，地鲜、蝎蛇(《岭表录异》)，银蛇(《开宝本草》)，金星地鳝(《本草图经》)，金星鳝(《圣济总录》)，片蛇(《滇略》)，蛇蜥、无脚蜥(《动物学大辞典》)，碎蛇(《中药形性经验鉴别法》)。","s":"咸，平。\n\n①《本草拾遗》：\"味咸，半。\"\n\n②《开宝本草》：\"无毒。\"\n\n③《四川中药志》：\"性平，味辛咸，有小毒。\"","f":"散瘀，祛风，消肿，解毒。治跌损折伤，大麻风，痈疽肿毒。\n\n①《开宝本草》：\"解生金毒。人中金药毒者，取金蛇四寸，炙令黄，煮汁饮，频服之，以瘥为度。银蛇解银药毒。\"\n\n②《本草图经》；\"能解众毒，止泻泄及邪热。\"\n\n③《纲目》：\"疗久痢。\"\n\n④《滇略》：\"治恶疽，腰以上用首，腰以下用尾；又治大麻风及痢。\"\n\n⑤《滇黔记游》：\"接断骨。\"\n\n⑥《纲目拾遗》：\"肉熬膏，箍痈疽，去风疠。其骨醋磨，围肿毒。\"\n\n⑦《中药形性经验鉴别法》：\"治关节痛，神经痛，恶疮肿疡。\"","y":"内服：煎汤，1～3钱；浸酒或入散剂。外用：熬膏涂。","d":"干燥的脆蛇多已盘成圈状，直径约6～10厘米。蛇的背面棕黄色或缉褐色，有光泽；鳞片不太明显。具有方格形的网纹，并有黑色横纹：腹面黄白色，带有篾片夹持时遗留下的痕迹，腹侧面各有1条凹沟。头部呈三角形，尾部细尖，或短促。体轻、干脆、气微腥。大者身短粗壮，色泽较深：小者瘦长，尾部尖，背面色泽较淡。以条匀、无碎断、气腥不臭、有光泽者为佳。\n产四川、云南等地。"},"拔毒散":{"a":"王不留行(《滇南本草》)，小黄药、小迷马桩、迷马桩棵、小克麻(《云南中草药》)，小拔毒、尼马庄柯(《云南中草药选》)。","s":"①《滇南本草》：\"性寒，味苦。\"\n\n②《云南中草药》：\"苦，平。\"","f":"清热解毒，活血祛瘀。治急性乳腺炎，急性扁桃体炎，疔疮，肿毒，肠炎，菌痢，妇女经闭，跌打损伤。\n\n①《滇南本草》：\"治妇人乳汁不通，乳痈、乳结、红肿，消诸疮肿毒；治小儿尿血，血淋，祛皮肤瘙痒，消风解热。梗叶细末，醋调敷痈疽疮毒溃散。\"\n\n②《云南中草药》：\"活血祛瘀，拔毒，接骨，通乳。治经闭，疔疮，枪伤，骨折。\"\n\n③《云南中草药选》：\"消炎，拔毒生肌。治急性乳腺炎，急性扁桃体炎，肠炎，菌痢。\"","y":"内服：煎汤，3～5钱。外用：捣敷。","d":"?"},"松香":{"a":"松脂、松膏、松肪(《本经》)，松胶香(《刘涓子鬼遗方》)，沥青(《卫生宝鉴》)，白松香(《滇南本草》)，松胶(《纲目》)，黄香(《本草原始》)，松脂香(《草木便方》)。","s":"苦甘，温。\n\n①《本经》：\"味苦，温。\"\n\n②《别录》：\"甘，无毒。\"\n\n③《药性论》：\"味甘，平。\"\n\n④《本草正》：\"味苦辛；温。\"\n\n肝；脾经","f":"祛风，燥湿，排脓，拔毒，生肌，止痛。治痈疽，疔毒，痔瘘，恶疮。疥癣，白秃，金疮，扭伤，风湿痹痛，疠风瘙痒。\n\n①《本经》：\"主痈疽恶疮，头疡白秃，疥瘙风气，安五脏，除热。\"\n\n②《别录》：\"主胃中伏热，咽干消渴，及风痹死肌，炼之令白；其赤者主恶痹。\"\n\n③《药性论》：\"杀虫，用之主耳聋；牙有蛀孔，少许咬之不落；能贴诸疮脓血，煎膏生肌止痛，祛风。\"\n\n④《日华子本草》：\"润心肺，下气除邪；煎膏主瘘烂，排脓。\"\n\n⑤《滇南本草》：\"疗赤白癜风，厉风。\"\n\n⑥《医学入门》：\"治历节酸痛，生津止渴，固齿，聪耳明目；入滋补药和服，壮阳，实阴茎，令人有子。\"\n\n⑦《纲目》：\"强筋骨，利耳目。治崩带。\"\n\n⑧《本草备要》：\"祛风去湿，化毒杀虫。\"","y":"外用：研末撒或调敷。内服：入丸、散或浸酒。","d":"松香为不规则半透明的块状，大小不等。表面黄色，常有一层黄白色的霜粉。常温时质坚而脆，易碎，断面光亮，似玻璃状。有松节油臭气，味苦。加热则软化，然后溶化，燃烧时产生棕色浓烟。以块整齐、半透明、油性大、气味浓厚者为佳。\n产广东、广西、福建、湖南、江西、浙江、安徽等地。"},"藕粉":{"a":"藕澄粉(《本草求原》)。","s":"《医林纂要》：\"甘咸，平。\"","f":"益血，止血，调中，开胃。治虚损失血，泻痢食少。\n\n①《本草通玄》：\"安神，开胃。\"\n\n②《本经逢原》：\"治虚损失血，吐利下血。又血痢口噤不能食，频服则结粪自下，胃气自开，便能进食。\"\n\n③《纲目拾遗》：\"调中开胃，补髓益血，通气分，清表热，常食安神生智慧，解暑生津，消食止泻。\"","y":"内服：沸水冲，和糖服。","d":"?"},"苦瓜":{"a":"锦荔枝、癞葡萄(《救荒本草》)，红姑娘(《群芳谱》)，菩达(《广东新语》)，凉瓜(《广州植物志》)，癞瓜(《民间常用草药汇编》)，红羊(《泉州本草》)。","s":"苦，寒。\n\n①《滇南本草》：\"苦，寒，平。\"\n\n②《纲目》：\"苦，寒，无毒。\"\n\n③《本经逢原》：\"生则性寒，熟则性温。\"","f":"清暑涤热，明目，解毒。治热病烦渴引饮，中暑，痢疾，赤眼疼痛，痈肿丹毒，恶疮。\n\n①《滇南本草》：\"治丹火毒气，疗恶疮结毒，或遍身已成芝麻疔疮疼难忍。\"\"泻六经实火，清暑，益气，止渴。\"\n\n②《生生编》：\"除邪热，解劳乏，清心明目。\"\n\n③《本草求真》：\"除热解烦。\"\n\n④《随息居饮食谱》：\"青则涤热，明目清心。熟则养血滋肝，润脾补肾。\"\n\n⑤《泉州本草》：\"主治烦热消渴引饮，风热赤眼，中暑下痢。\"","y":"内服：煎汤，2～5钱；或煅存性研末。外用：捣敷。","d":"干燥的苦瓜片，呈椭圆形或矩圆形，厚约2～8毫米，长3～15厘米，宽0.4～2厘米，全体皱缩，弯曲，果皮浅灰棕色，粗糙，有纵皱或瘤状突起。中间有时夹有种子或种子脱落后留下的孔洞。质脆，易断。气微味苦。以青边、肉白、片薄、子少者为佳。\n产于广西、广东、云南、福建等地。"},"飞龙掌血":{"a":"黄椒、三百棒、飞龙斩血、见血飞、黄大金根、血棒头、飞见血，血见愁，大救驾、下山虎、簕钩","s":"《贵阳民间药草》：\"辛苦，温，无毒。\"","f":"祛风，止痛，散瘀，止血。治风湿疼痛，胃痛，跌打损伤，吐血，衄血，子官出血，刀伤出血，经闭，痛经，肋间神经痛，疮疖肿毒。\n\n①《分类草药性》：\"散血破气，治风湿筋骨疼痛，吐血不止。\"\n\n②《贵州民间药物》：\"散瘀，解表。治伤风咳嗽，腹绞痛。\"\n\n③《广西药植名录》：\"治眼红肿、翳膜。\"\n\n④《四川常用中草药》：\"治痛经，经闭，血块，劳伤吐血，风湿麻木，筋骨疼痛。\"","y":"根皮3～5钱，水煎或浸酒服；外用适量，捣烂或研末敷患处。鲜叶适量，捣烂外敷。","d":"干燥根呈棒状，径约2～3厘米.表面灰棕色，有细纵纹及多数疣状突起；突起处栓皮多脱落，露出鲜黄色或红黄色皮层，质粗糙；剥去皮层，可见木质中柱，纹理平直细密。质硬，不易折断，断面平坦。气微，味淡。\n\n产陕西、四川、贵州、湖南、广西等地。"},"黄花地丁":{"a":"野豌豆、马口铃、猴丝草(《广西药植名录》)，小响铃、狗响铃(《云南思茅中草药选》)。","s":"①《滇南本草》：\"性寒，味苦。\"\n\n②《昆明民间常用草药》：\"凉，苦涩。\"","f":"清热，解毒，利尿。治久咳痰喘，尿道炎，膀胱炎，痈疽疔疮。\n\n①《滇南本草》：\"治痈疽疮肿，消痰、定喘、止咳嗽。\"\n\n②《广西药植名录》：\"叶：治黄疸，乳疮，疳积。\"\n\n③《昆明民间常用草药》：\"撵疮毒。\"","y":"内服：煎汤，3～5钱。外用：捣敷。","d":"?"},"含羞草":{"a":"知羞草、怕羞草、喝呼草、怕丑草、望江南、惧内草、感应草","s":"甘，寒，有毒。\n\n①《生草药性备要》：\"味甘，性寒。\"\n\n②《南宁市药物志》：\"甘，寒，有小毒。\"\n\n③《实用中草药》：\"性微寒，味微苦。\"\n\n归心；肝；胃；大肠经","f":"清热，安神，消积，解毒。治肠炎，胃炎，失眠，小儿疳积，目热肿痛，深部脓肿，带状疱疹。\n\n①《生草药性备要》：\"止痛消肿。\"\n\n②《本草求原》：\"敷疮，\"\n\n③《岭南采药录》：\"治眼热作痛。\"\n\n④《南宁市药物志》：\"清肝火，治小儿疳积，肝火上亢，外治疮疡作痛。\"\n\n⑤广州部队《常用中草药手册》：\"安神镇静。\"\n\n⑥《实用中草药》：\"清热利湿。治深部脓肿，肠炎，胃炎，疝气，小儿疳积。\"","y":"内服：煎汤，0.5～1两；或炖肉。外用：捣敷。","d":"?"},"驳骨草":{"a":"小功劳(《云南中草药选》)。","s":"《云南中草药选》：\"苦，凉。\"","f":"清热解毒，祛风止痛。治感冒，肠炎，痢疾，风湿骨痛，跌打伤折。\n\n①《广西药植名录》：\"根：止血，止咳，治跌打。叶：消肿，驱风。\"\n\n②《云南中草药选》：\"清热解毒，止痛。\"","y":"内服：煎汤，3～5钱。外用：研末包敷。","d":"?"},"鼻烟":{"a":"?","s":"?","f":"《纲目拾遗》：\"通关窍，治惊风，明目，定头痛，辟疫。\"\"能追风发汗。\"","y":"外用：搐鼻。","d":"?"},"羊角藤":{"a":"白面麻、红头根、山八角(《广西药植名录》)，穿骨虫、放筋藤、牛的藤(《福建中草药》)。","s":"《福建中草药》：\"根：辛微甘，温。\"","f":"祛风湿。治关节肿痛，肾虚腰痛。\n\n①《广西药植名录》：\"根：祛风湿，消肿，去毒。\"\n\n②《福建中草药》：\"根皮：祛风湿，暖肾气。\"","y":"内服：水酒煎，1～2两。","d":"?"},"胡枝子":{"a":"随军茶(《救荒本草》)，牡荆、荆条、楚子(《盛京通志》)，扫皮、胡枝条(《青岛木本植物名录》)，杭子梢(《中国树木分类学》)，虾夷山蔌、胡枝花、鹿鸡花、扫条(《国产牧草植物》)，野花生(《福建民间草药》)，过山龙、羊角梢、豆叶柴(《江西民间草药》)，夜合草、假花生(《闽东本草》)。","s":"甘，平。\n\n①《福建民间草药》:\"甘，平，无毒。\"\n\n②《闽东本草》:\"味微苦，性平。\"","f":"润肺清热，利水通淋。治肺热咳嗽，百日咳，鼻衄，淋病。\n\n①《福建民间草药》:\"润肺解热，利水通淋。\"\n\n②《闽东本草》:\"筋益肾，健脾祛湿。治头晕，脱力，蛇伤。\"","y":"内服:煎汤，3～5钱(鲜者1～2两)。","d":"?"},"仙人球":{"a":"仙人拳(《中国植物图鉴》)，刺球、翅翅球、雪球(《福建民间草药》)。","s":"甘淡，平。\n\n①《福建民间草药》：\"甘，寒。\"\n\n②《陆川本草》：\"性寒，微酸。\"\n\n③《湖南药物志》：\"淡，平。\"\n\n入肺经。","f":"治肺热咳嗽，痰中带血，痈肿，汤火伤。\n\n①《福建民间草药》：\"滑肠，泻火，消痈。\"\n\n②《陆川本草》：\"清心肺，止血。治肺热咳嗽，痰中带血。\"\n\n③《湖南药物志》：\"消肿止痛，行气活血，祛湿退热，生肌。\"","y":"内服：煎汤，3～5钱(鲜者2～3两)。外用：捣敷或捣汁涂。","d":"?"},"葎草":{"a":"勒草、黑草(《别录》)，葛葎蔓(《唐本草》)，葛勒蔓(《蜀本草》)，来莓草(《开宝本草》)，葛葎草(《圣济总录》)，葛勒子、涩萝蔓(《救荒本草》)，割人藤(《本经逢原》)，假苦瓜、苦瓜蘑(《广州植物志》)，锯锯藤(《贵州民间方药集》)，五爪龙、牛跤迹(《福建民间草药》)，老虎藤(《安徽药材》)，拉拉藤(《江苏野生植物志》)，穿肠草、拉拉秧(《东北药植志》)，拉拉蔓(《河北药材》)，过沟龙(《江西草药》)。","s":"①《别录》：\"味甘，无毒。\"\n\n②《唐本草》：\"味甘苦，寒，无毒。\"","f":"清热，利尿，消淤，解毒。治淋病，小便不利，疟疾，腹泻，痢疾，肺结核，肺脓疡，肺炎，癞疮，痔疮，痈毒，瘰疬。\n\n①《别录》：\"主瘀血，止精溢盛气。\"\n\n②《唐本草》：\"主五淋，利小便，止水痢，除疟，虚热渴，煮汁及生汁服之。\"\n\n③《本草衍义》：\"治伤寒汗后虚热，锉研，取生汁饮一合。\"\n\n④《纲目》：\"润三焦，消五谷，益五脏，除九虫，辟温疫，敷蛇、蝎伤。\"\n\n⑤《安徽药材》：\"治失眠；洗痔疮。\"","y":"内服：煎汤，3～6钱(鲜者2～4两)；或捣汁。外用：捣敷或煎水熏洗。","d":"?"},"天麻子":{"a":"还筒子(《卫生杂兴》)。","s":"?","f":"①《本草拾遗》：\"取子，作饮，去热气。\"\n\n②《纲目》：\"定风补虚，功同天麻。\"","y":"?","d":"?"},"玳玳花":{"a":"枳壳花(《草花谱》)，代代花(《饮片新参》)，酸橙花(《药材学》)。","s":"《药材学》:\"甘微苦。\"","f":"疏肝，和胃，理气。治胸中痞闷，脘腹胀痛，呕吐、少食。\n\n①《饮片新参》:\"理气宽胸，开胃止呕。\"\n\n②《动植物民间药》:\"治腹痛，胃痛。\"\n\n③《浙江中药手册》:\"调气疏肝。治胸膈及脘宇痞痛。\"","y":"内服:煎汤，5～8分；或泡茶。","d":"干燥花蕾略呈长卵圆形，长1.5～2厘米，直径6～8毫米。上部较膨大，基部具花柄；花萼绿色，皱缩不平，基部连合，裂片5；花瓣5片，淡黄白色或灰黄色，顶端覆盖成覆瓦状，表面有纵纹；内有雄蕊数束，黄色；中心有雌蕊，呈棒状，子房倒卵形，暗绿色。质脆易碎。气香，味微苦。以干燥、色黄白、香气浓郁、无破碎者为佳。\n主产江苏、浙江。"},"双肾草":{"a":"一根葱、秤砣草、坠桃草。","s":"淡，温。","f":"滋阴益肾。治膀胱疝气，白带。","y":"内服：煎汤，0.5～1两(鲜者2两)。","d":"?"},"赤茯苓":{"a":"赤苓(《本草再新》)，赤茯(《本草便读》)。","s":"甘淡，平。\n\n①《本草择要纲目》：\"甘，平，无毒。\"\n\n②《得配本草》：\"甘淡，平。\"\n\n③《本草再新》：\"味辛，性温，无毒。\"","f":"行水，利湿热。治小便不利，淋浊，泻痢。\n\n①《药性论》：\"破结气。\"\n\n②《纲目》：\"泻心小肠膀胱湿热，利窍行水。\"\n\n③《本草再新》：\"益心气，健中和脾，润肺，燥湿。治泻痢。\"","y":"内服：煎汤，2～4钱；或入丸、散。","d":"为大小不一的方块或碎块，均为淡红色或淡棕色。质松，略具弹性。\n产地同茯苓。"},"阳雀花":{"a":"渣玛兴(藏名)。","s":"性平，味甘微苦。","f":"补气益肾。治头晕头痛，耳鸣眼花，肺痨咳嗽，小儿疳积。","y":"内服：煎汤，1～3钱。","d":"?"},"猪牙皂":{"a":"皂荚(《本经》)，鸡栖子(《广志》)，皂角(《肘后方》)，猪牙皂角(《海上集验方》)，牙皂(《本事方》)，乌犀(《纲目》)，小皂(《本经逢原》)，眉皂、小皂荚(《中药志》)。","s":"辛咸，温，有毒。\n\n①《本经》：\"味辛咸，温。\"\n\n②《别录》：\"有小毒。\"\n\n③《药品化义》：\"味大辛，性热。\"\n\n④《长沙药解》：\"味辛苦涩。\"","f":"?","y":"内服：煎汤，0.5～1钱；或入丸、散。外用：煎水冼，研末掺或调敷，吹鼻，熬膏涂，烧烟熏。","d":"干燥荚果呈圆柱形，略扁，弯曲作镰形，长5～10厘米，宽5～12毫米。表面紫棕色或紫黑色，被灰白色粉霜，擦去后有光泽，并有细小的疣状突起及线状裂纹，腹缝线突起呈棱脊状，背缝线突起不显著而有棕黄色纵纹。先端有喙状的花柱残基，基部有果柄残痕。质硬而脆，易折断，断面外层棕黄色，中间黄白色，中心较软，有淡绿或淡棕黄色的丝状物与斜向网纹，纵向剖开可见排列整齐的凹窝，很少见种子。臭微，有刺激性，嗅其粉末则作喷嚏，味先甜后辣。以个小饱满、色紫黑、有光泽、无果柄、质坚硬、肉多而粘、断面淡绿色者为佳。\n主产四川、贵州、云南、山东。此外，陕西、湖北、河北、山西、安徽、河南、江苏等地亦产。"},"蜈蚣草":{"a":"蜈蚣蕨(《湖南药物志》)，小贯仲(《云南中草药选》)。","s":"《贵州民间药物》：\"性平，味淡。\"","f":"①《贵州民间药物》：\"治疥疮。\"\n\n②《湖南药物志》：\"辟疫，消肿，退热。治腹痛，痢疾，蜈蚣咬伤，无名肿毒。\"","y":"内服：煎汤，2～4钱。外用：煎水洗或捣敷。","d":"?"},"南瓜藤":{"a":"番瓜藤,盘肠草","s":"《本草再新》:\"味甘苦，性微寒，无毒。\"\n\n《本草再新》:\"入肝、脾二经。\"","f":"清肺，和胃，通络。治肺结核低热，胃痛，月经不调，烫伤。\n\n①《本草再新》:\"平肝和胃，通经络，利血脉，滋肾水。治肝风，和血养血，调经理气，兼去诸风。\"\n\n②《上海常用中草药》:\"清热。治肺结核低热。\"","y":"内服:煎汤，0.5～1两；或切断滴汁。外用:捣汁涂。","d":"?"},"闹羊花":{"a":"踯躅花(《本草图经》)，惊羊花、老虎花(《纲目》)，石棠花(《纲目拾遗》)，黄喇叭花(《浙江中药手册》)，水兰花、老鸦花、豹狗花(《湖南药物志》)，黄蛇豹花(《闽东本草》)，三钱三、一杯倒、一杯醉(《广西中草药》)，黄牯牛花、石菊花、黄杜鹃花、石棠花、闷头花(《浙江民间常用草药》)。","s":"辛，温，有毒。\n\n①《本经》：\"味辛，温。\"\n\n②《别录》：\"有大毒。\"","f":"驱风，除湿，定痛。治风湿顽痹，伤折疼痛，皮肤顽癣。并用作手术麻醉。\n\n①本经》：\"主贼风在皮肤中淫淫痛，温疟，恶毒诸痹。\"\n\n②《本草拾遗》：\"主一切风血。煮之，亦浸酒。\"\n\n③《本草蒙筌》：\"主风湿藏肌肉里，濈濈麻痹。\"\n\n④《本草新编》：\"主折伤。\"\n\n⑤《本草求原》：\"劫顽痰。\"\n\n⑥《科学的民间药草》：\"是麻醉药，能镇痉镇痛。治气喘。\"","y":"内服：煎汤，1～2分；浸酒或入丸、散。外用：捣擦。","d":"干燥的花序多皱缩，由6～12朵花组成，簇生在一总柄上，黄灰色至黄褐色；花冠钟状，顶端卷折，表面疏生短柔毛；雄蕊较长，花丝弯曲并露于花冠外面，有的脱落，花药卵黄色。以干燥、黄灰色、无杂质者为佳。\n主产江苏、浙江、安徽、湖南等地。"},"桂子":{"a":"天竺桂实(《中国医学大辞典》)。","s":"辛甘，温。\n\n①《药性考》：\"甘辛。\"\n\n②《纲目拾遗》：\"性温，味辛。\"","f":"①《药性考》：\"温中，暖胃，平肝，益肾，散寒，止哕。\"\n\n②《纲目拾遗》：\"胃脘寒痛。\"","y":"内服：煎汤，1～2钱。","d":"?"},"萝藦":{"a":"芄兰(《诗经》)，藋(《尔雅》)，雀瓢(陆玑《诗疏》)，苦丸(陶弘景)，白环藤、熏桑、鸡肠(《本草拾遗》)，羊角菜、羊奶科、细丝藤、过路黄、合钵儿、婆婆针扎儿(《救荒本草》)，婆婆针袋儿(《袖珍方》)，羊婆奶、婆婆针线包(《纲目》)，奶浆藤、奶浆草(《民间常用草药汇编》)。","s":"甘辛，平。\n\n①《品汇精要》：\"味甘辛，性温，无毒。\"\n\n②《纲目》：\"甘，微辛。\"\n\n③《四川冲药志》：\"性平，味淡，无毒。\"","f":"补益精气，通乳，解毒。治虚损劳伤，阳萎，带下，乳汁不通，丹毒疮肿。\n\n①陶弘景：\"补益精气，强盛阴道。\"\n\n②《本草抬遗》：\"主蜘蛛、蚕咬，折取汁，点疮上，此汁烂丝，煮食补益。叶：主目热赤，挼碎滴目中。\"\n\n③《纲目》：\"取汁敷丹毒赤肿及蛇虫毒。蜘蛛伤，频治不愈者，捣封三度，能烂丝毒，即化作脓也。\"\n\n④《江苏植药志》：\"水煎服，治温毒，解热。\"\n\n⑤《四川中药志》：\"能补血行气。治虚损痨伤，下乳汁。\"\n\n⑥《重庆草药》：\"治虚弱白带。\"","y":"内服：煎汤，0.5～2两。外用：捣敷。","d":"?"},"九龙藤":{"a":"过岗龙、过江龙、邬郎藤、乌藤、串鼻藤、飞扬藤、山道藤、九龙根、羊蹄风、黄开口、子燕藤、五里藤、双木蟹、九牛燥、五花血藤、马脚藤、马蹄叶根","s":"《南宁市药物志》；\"苦辛，平，无毒。\"","f":"《南宁市药物志》：\"祛风，去瘀，止痛。治风湿骨痛，跌打接骨。\"","y":"内服：煎汤，2～5钱(鲜用1～2两)。","d":"本品呈圆柱形，稍扭曲。表面粗糙，灰棕色或灰褐色，具不规则皱沟纹。质坚实，难折断，切断面皮部棕红色，木部浅棕色，有2-4圈深棕红色环纹，习称“鸡眼圈纹”，针孔状导管细而密。气无，味微涩。\n以藤茎粗，断面“鸡眼圈纹”明显者为佳。"},"稻草":{"a":"稻穰(《广雅》)，稻藁(《崔氏纂要方》)，稻杆(刘禹锡《传信方》)，禾秆(《纲目》)。","s":"甘，平。\n\n①《滇南本草》：\"性温，味甘平。\"\n\n②《纲目》：\"辛甘，热，无毒。\"\n\n③《本草再新》：\"味辛，性温，无毒。\"","f":"宽中，下气，消食积。治噎膈，反胃，食滞，泄泻，腹痛，消渴，黄疸，白浊，痔疮，烫伤。\n\n①《本草拾遗》：\"主黄病身作金色，煮汁浸之。\"\n\n②《滇南本草》：\"宽中，下气，温中，止泻，消牛马肉积宿食，小儿乳食结滞，肚腹疼痛。稻草节，走周身经络，治痰火疼痛。\"\n\n③《本草再新》：\"走经络，利肠分，宽中益气。\"","y":"内服：煎汤，1.5～3两；或烧灰淋汁澄清。外用：煎水浸洗。","d":"?"},"鹿胎":{"a":"?","s":"甘咸，温。\n\n①《本经逢原》：\"甘，温，无毒。\"\n\n②《四川中药志》：\"性温，味咸，无毒。\"","f":"益肾壮阳，补虚生精。治虚损劳瘵，精血不足，妇女虚寒，崩漏带下。\n\n①《本草新编》：\"健脾生精，兴阳补火。\"\n\n②《青海药材》：\"治妇女月经不调，血虚、血寒，久不生育。\"\n\n③《四川中药志》：\"能补下元，调经种子。治血虚精亏及崩带。\"","y":"内服：入丸散，2～5钱；鲜胎可煮汁熬膏。","d":"干燥的鹿胎，大小不一，全体弯曲，头大，嘴尖，下唇较长，四肢细长，有2蹄，尾短，脊背皮毛有小白色点，鲜时色淡，干燥后呈棕红色。质坚硬，不易折断。气微腥。以幼小、无毛、胎胞完整、无臭味者为佳。\n主产黑龙江、吉林、河北、青海、甘肃、云南等地。\n\n四川所产的鹿胎，为水鹿、白唇鹿、白鹿的胎兽及胎盘。用木板夹扁后加工干燥，商品呈扁圆形，棕褐色，外面包裹一层胎盘。"},"西瓜霜":{"a":"西瓜硝(《本草再新》)。","s":"咸，寒。\n\n《本草再新》：\"味辛，性平，有小毒。\"","f":"治喉风，喉痹，口疮，牙疳，久嗽咽痛。\n\n①《疡医大全》：\"治咽喉口齿，双蛾喉痹。\"\n\n②《本草再新》：\"治喉痹久嗽。\"","y":"外用：研末吹喉。内服：冲入汤药。","d":"为白色粉粒状结晶，形似粗盐，遇热即化。以洁白、纯净、无泥屑、杂质者为佳。"},"硫磺":{"a":"硫块、粉末硫磺、磺粉、硫磺块、硫磺粉","s":"?","f":"?","y":"?","d":"?"},"葱白":{"a":"葱茎白(《纲目》)，葱白头(《药品化义》)。","s":"辛，温。\n\n①《素问》：\"辛。\"\n\n②《别录》：\"平。\"\n\n③张元素：\"味辛而甘，平。\"\n\n④《本草蒙筌》：\"味辛，气温。\"","f":"发表，通阳，解毒。治伤寒寒热头痛，阴寒腹痛，虫积内阻，二便不通，痢疾，痈肿。\n\n①《本经》：\"主伤寒寒热，出汗中风，面目肿。\"\n\n②《别录》：治\"伤寒骨肉痛，喉痹不通，安胎。\"\n\n③孟诜：\"通关节，止衄血，利大小便。\"\n\n④《日华子本草》：\"治天行时疾，头痛热狂，通大小肠，霍乱转筋及责豚气，脚气，心腹痛，目眩及止心迷闷。\"\n\n⑤《用药心法》：\"通阳气，发散风邪。\"\n\n⑥李杲：\"治阳明下痢下血。\"\n\n⑦《日用本草》：\"能达表和里，安胎止血。\"\n\n⑧《本草蒙筌》：\"蛇伤、蚯蚓伤，和盐罯即解。\"\n\n⑨《纲目》：\"除风湿，身痛麻痹，虫积心痛，止大人阳脱，阴毒腹痛，小儿盘肠内钓，妇人妊娠溺血，通奶汁，散乳痈，利耳鸣，涂猘犬毒。\"","y":"内服：煎汤，3～5钱，或煮酒。外用：捣敷、炒熨、煎水洗或塞耳、鼻窍中。","d":"?"},"蜘蛛香":{"a":"豆鼓菜根、九转香、雷公七(《贵州民间方药集》)，马蹄香(《广西中药志》)，鬼见愁，臭狗药、磨脚花(《云南中草药》)，连香草、香草子(《陕西中草药》)，养血莲、臭药、乌参(成都《常用草药治疗手册》)。","s":"①《纲目》：\"辛，温，无毒。\"\n\n②《贵阳民间药草》：\"辛苦，温，无毒。\"","f":"行气，散寒，活血，调经。治发痧脘腹胀痛，呕吐泄泻，肺气水肿，风寒感冒，月经不调，痨伤咳嗽。\n\n①《纲目》：\"辟瘟疫、中恶。\"\n\n②《贵州民间方药集》：\"镇静，顺气，消食。治腹胀痛，胃气痛。又治惊风。\"\n\n③《贵阳民间药草》：\"治气胀，发痧，腹痛，止水泻。\"\n\n④《广西中药志》：\"除湿散寒，治脚气水肿，脾胃食滞，外敷疮疖。\"\n\n⑤《陕西中草药》：\"活血，调经。治头痛，关节痛，月经不调，跌打损伤，疖疮。\"\n\n⑥《云南中草药》：\"治消化不良，小儿咳嗽，疳积，流感，疟疾。\"","y":"内服：煎汤，1～1.5钱；或浸酒。外用：磨汁涂。","d":"干燥根茎结节状，圆形或扁圆形，微弯曲，不分叉，长3～5厘米，径0.7～1.3厘米，棕褐色或茶褐色。表面有较绸密的环形突起，不甚规则，底面有多数须根痕。芦头平截，可见茎、叶残基。质坚实，断面黄褐色。有缬草样特异香气。以粗壮、坚实、黄色者为佳。\n产四川、贵州等地。"},"荔枝草":{"a":"水羊耳(《生草药性备要》)，过冬青、夭明精(《经验广集》)，风眼草、赖师草、隔冬青(汪连仕《采药书》)，雪里青(《慈航活人书》)，皱皮葱(《纲目拾遗》)，癞子草、野芝麻、野薄荷、癞客蚂草(《草木便方》)，癞虾蟆(《分类草药性》)，虾蟆草(《药物图考》)，小活血、麻鸡婆、野芥菜、皱皮草、内红消(《江西中医药》(6):57，1957)，臌胀草，沟香薷(《中国药植图鉴》)，麻麻草、青蛙草(《民间常用草药汇编》)，落地红、朴地捎、根下红(《江西民间草药验方》)，野猪菜(《上海常用中草药》)。","s":"辛，凉。\n\n①《纲目拾遗》:\"性凉。\"\n\n②《草木便方》:\"苦，寒。\"\n\n③《四川中药志》:\"性平，味辛，无毒。\"","f":"凉血，利水，解毒，杀虫。治咳血，吐血，尿血，崩漏，腹水，白浊，咽喉肿痛，痈肿，痔疮。\n\n①《生草药性备要》:\"治跌打伤，去瘀，洗痔疮。\"\n\n②汪连仕《采药书》:\"凉血，止崩漏，散一切痈毒。\"\n\n③《纲目拾遗》；\"《葛祖遗方》，治咽喉十八症，消痈肿，杨梅、痔疮。\"\n\n④《草木便方》:\"解毒。治白秃，疥癞，风癣；除脚胫疮痒黄水，杀虫，调油涂。\"\n\n⑤《分类草药性》:\"治一切久年癍疮，洗痔疮，痒疮。\"\n\n⑥《药物图考》:\"治湿热风疹，阴痒、肾囊风，消肿利水。\"\n\n⑦《江苏植药志》:\"水煎服，治腹胀。\"\n\n⑧《中国药植图鉴》:\"捣烂敷肚脐上，除臌胀病腹水。\"\n\n⑨《四川中药志》:\"清肺热，除风湿。治咳嗽，痢疾，牙痛及痒疹，疮毒。\"","y":"内服:煎汤，0.3～1两(鲜者0.5～2两)或入丸、散。外用:捣敷，捣汁含漱、滴耳或煎水洗。","d":"理化鉴别 （1）取本品粉末2g，加乙醇适量，热提10min，滤过。滤液蒸干，残渣加水5ml，煮沸，趁热滤过，。取滤液1ml，加镁粉少许，盐酸数滴，溶液显樱红色。（检查黄酮类）（2）另取上述滤液，加1%三氯化铝乙醇溶液，呈鲜黄色。（检查黄酮类）"},"虎尾轮根":{"a":"石参","s":"甘，温。\n\n①《广西中药志》：\"味甘，性温，无毒。\"\n\n②《泉州本草》：\"味苦微辛，性涩而平。\"\n\n入肺、胃、肾三经。\n\n①《广西中药志》：\"入肺、胃二经。\"\n\n②《泉州本草》：\"入肝、肾、心、肺诸经。\"","f":"理气，化痰，益肾。治心胃气痛，痰饮咳嗽，肾虚遗精。\n\n①《广西中药志》：\"行气止痛，逐痰化饮。治心胃气痛，痰饮咳嗽。\"\n\n②《泉州本草》：\"益肾滋肝。治肾虚遗精。\"","y":"内服：煎汤，3～5钱，或研末。","d":"性状鉴别 根细长，圆柱形，有分枝，表面棕黄色，具细皱纹，支根纤细，皮部易剥离。质稍硬，折断面不平整，断面皮部棕黄色，木部淡黄色，于放大镜下观察，木部具众多小孔（导管)，射线明显，呈放射状。气微，味淡。"},"硇砂":{"a":"北庭砂(《四声本草》)，亦砂、黄砂(《石药尔雅》)，狄盐(《日华子本草》)，气砂(《本草图经》)，白硇砂(《中药志》)。","s":"咸苦辛，温，有毒。\n\n①《药性论》：\"味酸咸，有大毒。\"\n\n②《唐本草》：\"味咸苦辛，温，有毒。\"\n\n③《日华子本草》：\"味辛酸，暖，无毒。\"","f":"消积软坚，破瘀散结。治癥瘕痃癣，噎膈反胃，痰饮，喉痹，积痢，经闭，目翳，息肉，疣赘，疔疮，瘰疬，痈肿，恶疮。\n\n①《唐本草》：\"主积聚，破结血，烂眙，止痛下气，疗咳嗽，宿冷，去恶肉，生好肌。\"\n\n②《本草拾遗》：\"主妇人丈夫羸瘦积病，血气不调，肠鸣，食次不消，腰脚疼冷，痃癖，痰饮，喉中结气，反胃吐水，令人能食，肥健。\"\n\n③《日华子本草》：\"补水藏，暖子宫，消冷癖瘀血，宿食不消，气块痃癖及血崩带下，恶疮息肉，食肉饱胀，夜多小便，女人血气心疼，丈夫腰胯酸重，四肢不任。\"\n\n④《本草衍义》：\"合他药，治目中翳。\"\n\n⑤王好古：\"消肉积。\"\n\n⑥《纲目》：\"治噎膈，癥瘕，积痢，骨哽，除痣黡疣赞。\"","y":"内服：入丸、散，1～3分。外用：研末点、撒或调敷，或入膏药中贴，或化水点涂。","d":"为白色结晶体，呈不规则的块状或粒状，大小不一。全体白色，有的稍带淡黄色。质较脆，易碎，用指甲即可刮下白色粉末，断面显束针状纹理，有光泽。臭微，用舌舔之，味咸苦而刺舌。以块整，色白、有光泽、无杂质者为佳。热之不熔融而挥散。可溶于水，水溶液显铵盐与氯化物之各种反应。\n产青海、甘肃、新疆等地。\n\n硇砂药材，除上述正品外，市场上使用较广、较久的，尚有一种紫硇砂，又称红硇砂，为含有少量硫和锂的石盐晶体。多呈立方形，有棱角或凹凸不平，表面暗红色或紫红色，质重。臭气浓，昧咸。热之不挥散而残留。"},"石仙桃":{"a":"石山莲、石橄榄、果上叶、千年矮、麦斛、小扣子兰、大吊兰、浮石斛、上石仙桃、川甲草、马榴根、上石蒜、麦斛兰、石萸肉、箴兰、上树蛤蟆、石川盘","s":"甘，凉。\n\n①《广东中药》Ⅱ：\"甘淡，平。\"\n\n②《福建中草药》：\"苦微酸，凉。\"\n\n归肺；肾经","f":"养阴，清肺，利湿，消瘀。治眩晕，头痛，咳嗽，吐血，梦遗，痢疾，白带，疳积。\n\n①《生草药性备要》：\"治内伤，化痰止咳。\"\n\n②《岭南采药录》：\"治内伤吐血，和猪精肉煎服；治哮喘咳嗽，和陈皮、猪肉煎服；治心气痛，水煎，冲酒服；治风湿骨痛，浸酒服；治办白痢，水煎，蜜糖调服；风火牙痛，水煎，冲酒服。\"\n\n③《广东中药》Ⅱ：\"清肺郁热，养肺阴，化痰止咳。治内伤咳嗽，小儿热积。\"","y":"内服：煎汤，3～5钱(鲜品1～2两)。","d":"根茎短粗，被膜质鳞片，每隔1～2厘米有一假鳞茎，下侧有须根。假鳞茎短圆柱形或长卵形，长2～4厘米，径3～8毫米，外表皱缩，污黄色或黄棕色，光滑，顶端有叶痕中央常有锥尖状干枯的芽，基部有鞘状鳞叶。质坚稍韧，断面白色。气微，味甘淡。以须根少、假鳞茎大者为佳。\n产广东、福建等地。"},"蜥蜴":{"a":"马蛇子、麻蛇子","s":"咸，寒。","f":"消瘿散瘰。治淋巴结结核。","y":"内服：研末，1个。外用：研末调敷，适量。","d":"?"},"百合花":{"a":"强瞿、番韭、山丹、倒仙","s":"《滇南本草》：性微寒平，味甘微苦。","f":"润肺，清火，安神。治咳嗽，眩晕，夜寐不安，天疱湿疮。\n1．《滇南本草》：止咳嗽，利小便，安神宁心定志。\n２．《纲目》：治小儿天疱湿疮，暴干研末，菜子油涂。\n３．《要药分剂》：润肺清火。","y":"内服：煎汤，2～4钱。外用：研末调敷。","d":"?"},"麻根":{"a":"麻青根 大麻根","s":"","f":"去瘀，止血。治淋病，血崩，带下，难产，胞衣不下，跌打损伤。利尿\n\n①陶弘景：\"麻根汁煮饮之，主瘀血、石淋。\"\n\n②《唐本草》：\"主产难，胞衣不出，破血壅胀。带下崩中不止者，以水煮服之。\"\n③《本经逢原》：麻根捣什,治产难胞衣不下,煮服治崩中不止,生走熟守也。并治淋下血不止。","y":"","d":"?"},"皂荚子":{"a":"皂角子(《千金方》)，皂子、皂儿(《博济方》)，皂角核(《妇人良方》)。","s":"辛，温，有毒。\n\n①《纲目》：\"辛，温，无毒。\"\n\n②《本草经疏》：\"味辛咸，温，有小毒。\"\n\n③《本草汇言》：\"味辛甘，气温，无毒。\"","f":"润燥通便，祛风消肿。治大便爆结，肠风下血，下痢里急后重，疝气，瘰疬，肿毒，疮癣。\n\n①《本草图经》：\"核中白肉，入治肺药。又炮核取中黄心，嚼饵之，治膈痰吞酸。\"\n\n②李杲：\"和血润肠。\"\n\n③《纲目》：\"治风热大肠虚秘，瘰疬、肿毒、疮癣。\"\n\n④《本草崇原》：\"治疝气并睾丸肿痛。\"\n\n⑤《医林纂要》：\"杀疳虫。\"\n\n⑥《本草求原》：\"疏风热，去麻痹。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。","d":"干燥种子呈长椭圆形，一端略狭尖，长11～13毫米，宽7～8毫米，厚约7毫米。表面棕褐色，平滑而带有光泽，较狭尖的一端有微凹的点状种脐，有时不甚明显，种皮剥落后，可见2片大形鲜黄色的子叶。质极坚硬，气微，味淡，以颗粒饱满、坚实、无杂质、无虫蛀者为佳。"},"酒糟":{"a":"甜糟(《本草拾遗》)，糟(《日华子本草》)，红糟(《养生必用方》)，酒醅糟、粕(《纲目》)。","s":"甘辛，温。\n\n①《纲目》：\"甘辛，无毒。\"\n\n②《本草求原》：\"辛，热。\"","f":"温中，消食，散瘀，止痛。治伤折瘀滞疼痛，冻疮，风寒湿痹。\n\n①《本草拾遗》：\"主温中冷气，消食杀腥，去草菜毒，润皮肤，调脏腑。\"\n\n②《日华子本草》：\"罯扑瘀血，浸洗冻疮，敷蛇、蜂叮毒。\"\n\n③《纲目》：\"能活血行经止痛，故治伤折有功。\"","y":"内服：炖温。外用：罨敷。","d":"?"},"桂皮":{"a":"柴桂、山肉桂、土桂","s":"辛，温。\n\n①《开宝本草》：\"味辛，温，无毒。\"\n\n②《四川中药志》：\"性大热，味辛甘，有小毒。\"","f":"暖脾胃，散风寒，通血脉。治腹冷胸满，呕吐噎膈，风湿痹痛，跌损瘀滞，血痢肠风。\n\n①《本草拾遗》：\"治腹内诸冷，血气胀痛。\"\n\n②《海药本草》：\"补暖腰脚，破产后恶血，治血痢肠风，功力与桂心同。\"\n\n③《四川中药志》：\"益肝肾，通经脉，散风寒，除湿痹，暖腰膝，止呕吐。治筋骨疼痛，寒泄腹痛，霍乱呕吐，噎膈胸满，膀胱寒疝，腰膝现冷，风湿痹痛及跌损瘀滞等症。\"","y":"内服：煎汤，1～2钱；或入丸、散。","d":"干燥的树皮，呈弯曲状或半筒状，或不整齐的块片，长约30～60厘米，宽达9厘米，厚约1～9毫米。外皮黑棕色至黑褐色，有灰白色花斑，表面栓皮或呈鱼鳞状脱落而显龟纹状凹斑。内表面暗红棕色至黑棕色。断面外层灰褐色，内层红棕色，间有黄棕色射线。气清香而凉，似樟脑，味微甜辛。以皮薄、呈卷筒状、香气浓厚者为佳。\n主产福建、广东、广西、湖北、江西、浙江等地。此外云南、安徽亦产。\n\n陕西、四川、云南尚以柴樟的干皮作桂皮。"},"黄脚鸡":{"a":"玉竹、十样错(《贵州草药》)，竹节参(《贵州药植目录》)。","s":"《贵州草药》：\"甘，平。\"","f":"①《贵州草药》：\"养阴润肺，生津止渴。\"\n\n②《贵州药植目录》：\"治月经不调。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"地菍":{"a":"山地菍(《生草药性备要》)，地茄(《植物名实图考》)，铺地锦(《岭南采药录》)，地吉桃、地葡萄、地红花(《广西中兽医药植》)，古柑、苦含(《闽南民间草药》)，倒藤王不留、金头石榴(《泉州本草》)，地石榴、毛冬瓜、水汤泡、提脚龙、猫儿眼睛草(《湖南药物志》)，铺地稔(广州部队《常用中草药手册》)，野落苏、红地茄(《浙江民间常用草药》)，落地稔、地稔藤(《南方主要有毒植物》)，矮脚埔梨、埔淡，波罗罂子(《福建中草药》)。","s":"《陆川本草》：\"味甘微涩，性稍凉。\"","f":"活血止血，清热解毒。治痛经，产后腹痛，血崩，带下，便血，痢疾，痈肿，疔疮。\n\n①《生草药性备要》：\"叶，煎水，洗疳痔热毒、麻疥烂脚，蛇伤。\"\n\n②《陆川本草》：\"止血，解毒，消炎。治子宫出血，痢疾，疮痈溃烂红肿。\"\n\n③《闽南民间草药》：\"清热解毒，活血消疝。治赤白痢，产后腹痛。\"\n\n④《闽东本草》：\"治痛经，崩带，血痢，痔瘘，风疹，疝气。\"","y":"内服：煎汤，3～5钱(鲜者1～2两)。外用：煎水洗或捣敷。","d":"?"},"竹根七":{"a":"竹根参、竹节七、牛尾七(《陕西中草药》)。","s":"《陕西中草药》：\"味甘微苦，性寒。\"","f":"滋阴泻火，活血调经。治劳热咳嗽，风湿痹痛，月经不调，跌打损伤。\n\n①《陕西中草药》：\"除风湿，清热泻火，镇痛止血，调经活血，滋阴补虚。治风湿性关节炎，腰腿疼痛，跌打损伤，劳伤，月经不调，骨蒸劳热。\"\n\n②《成都中草药》：\"益气活血，清肺，解毒。\"","y":"内服：煎汤，1～3钱；或研粉冲服，0.5～1钱；或浸酒。外用：捣敷。","d":"根茎扁圆柱形，略扭曲，长10～15厘米，径约1厘米，节明显，略膨大，节处有芽及膜质鳞片状叶，节间短。表面黄棕色或黄绿色，有皱纹。断面淡黄白色，细颗粒状。气无，味苦涩。\n产于陕西、四川。"},"松萝":{"a":"女萝,松上寄生,松落,天棚草,雪风藤,山挂面,龙须草,金钱草,关公须,天蓬草,树挂,飞天蜈蚣,松毛,海风藤,石丝线,飞山翅,仙人头发,金丝藤,云雾草,老君须,胡须草,荼须,过山龙,石须","s":"苦甘，平。\n\n①《本经》：\"味苦，平。\"\n\n②《别录》：\"甘，无毒。\"\n\n③《陕西中草药》：\"味淡微苦，性凉。\"\n\n归心；肾；肺经","f":"清肝，化痰，止血，解毒。治头痛，目赤，咳嗽痰多，疟疾，瘰疬，白带，崩漏，外伤出血，痈肿，毒蛇咬伤。\n\n①《本经》：\"主嗔怒邪气，止虚汗，头风，女子阴寒肿痛。\"\n\n②《别录》：\"疗痰热温疟，可为吐汤，利水道。\"\n\n③《药性论》：\"治寒热，吐胸中客痰涎，去头疮，主项上瘤瘿。\"\n\n④《日华子本草》：\"令人得眠。\"\n\n⑤《纲目拾遗》：\"治蛇虎伤、汤火烙伤及顽疮等症。\"\n\n⑥《陕西中草药》：\"止血生肌，止痛，清肝明目，退云翳，降血压，调经。治外伤出血，大便下血，急性结膜炎，角膜云翳，头痛，高血压症，月经不调，崩漏，白带，痈肿，无名肿毒。\"\n\n⑦《西藏常用中草药》：\"清热解毒，止咳化痰。治外伤感染，化脓性感染，毒蛇咬伤，肺结核咳嗽痰多，颈淋巴腺炎，乳腺炎。\"","y":"内服：煎汤，2～3钱。外用：煎水洗或研末调敷。","d":"性状鉴别 （1)地衣体丝状，柔软，浅黄绿色。主枝短，具皮层，有环裂；次生分枝极长，无皮层，有稠密的小纤毛，表面常有颗粒状小疣。\n（2)地衣体丝状，较粗壮，淡灰绿色或淡黄棕色。枝体表面有多数环状裂沟。横断面可见中央有线状强韧性的中轴，具弹性，由菌丝组成；其外为藻环，常由环状沟纹分离成短筒状。"},"野烟叶":{"a":"大王叶(《生草药性备要》)，大黄叶(《岭南采药录》)，土烟叶(《中国树木分类学》)，假烟叶(《广州植物志》)，石烟(《陆川本草》)，臭烟(《闽南民间草药》)。","s":"辛，平。\n\n①《生草药性备要》：\"味辛，性平。\"\n\n②《陆川本草》：\"辛，温。\"\n\n③《南宁市药物志》：\"苦辛。\"","f":"治黄肿，痛风，血崩，跌打肿痛，牙痛，瘰疬，痈疮，湿疹，皮炎。\n\n①《生草药性备要》：\"消黄肿，擂粥食。\"\n\n②《岭南采药录》：\"治风湿脚痛，煎水洗。\"\n\n③《陆川本草》：\"消肿止痛，治跌打肿痛，浸酒服或捣烂酒炒敷。\"\n\n④《南宁市药物志》：\"杀虫，消肿，止血。内服治妇女血崩，化痰止咳，牙痛(煲水含)。外用洗烂疮；捣烂加尿煮熟，外敷，治阴囊睾丸肿胀。\"","y":"内服：煎汤，1.5～3钱。外用：煎水洗、捣敷或捣碎酒炒热敷。","d":"?"},"赤胫散":{"a":"土竭力(《植物名实图考》)，花蝴蝶、花脸荞、荞子连、九龙盘、花扁担、土三七、散血连(《贵州民间方药集》)，小晕药、花脸晕药、红皂药(《民间常用草药汇编》)，苦茶头草(《中国药植图鉴》)，红泽兰(《贵州民间药物》)，荞黄连、广川草、甜荞莲、脚肿草、田枯七(《湖南药物志》)，蛇头草，南蛇头、蝴蝶草(《广西药植名录》)，草见血、血当归、黄泽兰(《云南中草药》)，花脸荞麦、亚腰山蓼(《常用中草药配方》)。","s":"酸苦微辛，寒。\n\n①《湖南药物志》：\"苦(一说辛)，寒，无毒。\"\n\n②《广西实用中草药新选》：\"味酸涩，性平。\"","f":"清热解毒，活血消肿。治痢疾，白带，血热头痛，崩漏，经闭，乳痈疮疖，跌打损伤。\n\n①《民间常用草药汇编》：\"清三焦热。治头昏晕。\"\n\n②《湖南药物志》：\"镇痛。\"\n\n③《广西实用中草药新选》：\"消肿解毒。治毒蛇咬伤，痈疖，无名肿毒，乳腺炎。\"\n\n④《四川常用中草药》：\"清热，活血。治内伤，血热头昏头痛，红崩，经闭，虚火咳嗽，赤白痢，痈毒恶疮。\"","y":"内服：煎汤，3～5钱(鲜者0.5～1两)。外用：捣敷。","d":"?"},"榛子":{"a":"棰子(《本草求原》)，平榛(《河北习见树木图说》)，山反栗(《中国树木分类学》)。","s":"甘，平。\n\n①《开宝本草》：\"味甘，平，无毒。\"\n\n②《医林纂要》：\"甘咸，平。\"","f":"调中，开胃，明目。\n\n①崔禹锡《食经》：\"食之明目，去三虫。\"\n\n②《日华子本草》：\"肥白人，止饥，调中，开胃。\"\n\n③《开宝本草》：，\"主益气力，宽肠胃，令人不饥，健行。\"","y":"内服：煎汤，1～2两；或研末。","d":"?"},"鸦葱":{"a":"土参、黄花地丁(《南京民间药草》)，人头发、老鹤咀子(《江苏药材志》)。","s":"①《江苏药材志》：\"味微苦涩。\"\n\n②《宁夏中草药手册》：\"微苦，寒。\"","f":"《江苏药材志》：\"消肿解毒。治五痨七伤，疔疮痈肿。\"","y":"内服：煎汤，3～5钱。外用：捣烂敷。","d":"干燥根呈长圆柱形，长可达20厘米以上，直径6～10毫米；表面棕黑色，有纵横皱纹，上部具密集的横皱纹，根头部残留众多棕色毛须(叶基纤维束与维管束)。质较疏松，断面黄白色。气微，味微苦涩。"},"山油麻":{"a":"榔树，山脚麻","s":"苦，凉。\n\n    入肝，肺二经。","f":"清热解毒，止痛，止血。主治疖毒。并治外伤出血\n①《浙江天目山药植志》：\"治疖毒，鲜叶捣烂，加白糖外敷患处，每天换一次。\"\n\n②《广西植物名录》：\"根、叶：清凉，止痛，止血。\"","y":"","d":"?"},"柠檬片":{"a":"黎檬子、黎檬子、宜母子、宜母子、里木子、黎檬干、药果、梦子、宜母果、柠果。","s":"","f":"","y":"适量，开水泡饮，如太酸可适当加少许白糖。","d":"?"},"干冬菜":{"a":"霉干菜、陈干菜","s":"咸苦，平。\n\n《本草再新》：\"味苦咸，性平，无毒。\"","f":"滋阴，开胃，化痰，利膈。治肺热痰嗽，喉痛，失音。\n\n①《纲目拾遗》：\"开胃下气，益血生津，补虚劳，已痰嗽。年久者，泡汤饮，治声音不出。和酒捣烂，涂汤火伤。\"\n\n②《本草再新》：\"治肺火咳嗽，化痰理气，治喉疼失音，益阴滋水。\"","y":"?","d":"?"},"蒟蒻":{"a":"蒻头,白蒟蒻,鬼芋,鬼头,磨芋,花杆莲,黑芋头,花梗莲,虎掌,花伞把,蛇头草根,蛇六谷,雷星,鬼蜡烛,蛇头子,独叶一枝花,花梗天南星,天六谷,星芋","s":"辛，温，有毒。\n\n①《医林纂要》：\"甘辛，温。\"\n\n②《江西草药》：\"苦辛，温，有毒。\"","f":"化痰散积，行瘀消肿。治痰嗽，积滞。疟疾，经闭，跌打损伤，痈肿，疔疮，丹毒，汤火伤。\n\n①《开宝本草》：\"主痈肿风毒。摩敷肿上。捣碎以灰汁煮成饼，五味调和为茹食，主消渴。\"\n\n②《本草会编》：\"治腮痈。\"\n\n③《医林纂要》：\"去肺寒。治痰嗽。\"\n\n④《草木便方》：\"化食，消陈积，癥聚，久疟。\"\n\n⑤《国药的药理学》：\"为利尿药。\"\n\n⑥《四川中药志》：\"烧熟捣绒，敷火疔疮。\"\n\n⑦《江西草药》：\"解毒消肿。\"","y":"内服：熬汤，3～5钱(须久煎2小时，取汁服)。外用：醋磨涂或煮熟捣敷。","d":"?"},"柏树果":{"a":"柏树子，香柏树子","s":"苦；甘；性平 。归心，肺经。\n①《分类草药性》:\"苦涩。\"\n\n②《重庆草药》:\"味甘辛微苦，性平，无毒。\"","f":"祛风，安神，凉血，止血。治感冒发热，胃痛呕吐，烦躁，失眠，劳伤吐血 \n①《分类草药性》：安神除烦。 \n②《四川中药志》:\"治风寒感冒、胃痛及虚弱吐血。\"\n\n③《重庆草药》:\"解风邪，安神，止血。治血热烦躁，小儿寒热高烧，吐血。\"","y":"内服:煎汤，3～5钱；或研末。","d":"性状鉴别 成熟干燥球果呈圆球形，直径8-12mm，暗褐色；种鳞4对，顶端为不规则五角形或方形，能育鳞有种子5-6粒。种子宽倒卵状菱形或近圆形，略扁，淡褐色，有光泽，长约2.5mm，边缘具窄翅。气微，味涩。"},"血藤":{"a":"大血藤(《草木便方》)，活血藤(《天宝本草》)，黄皮血藤(《四川中药志》)，紫金血藤(《重庆草药》)，气藤(《贵州草药》)，香石藤、铁骨散、小血藤(《云南中草药选》)。","s":"辛酸，温。\n\n①《草木便方》：\"温。\"\n\n②《四川中药志》：\"性温，味微麻酸涩苦，无毒。\"\n\n③《重庆草药》：\"辛，温，无毒。\"\n《四川中药志》：“入肝、大肠二经。”","f":"养血消瘀，理气化湿。治痨伤吐血，肢节酸疼，心胃气痛，脚气痿痹，月经不调，跌打损伤。\n\n①《草木便方》：\"入血分，破瘀生新。疗损伤积血，止痰血，鼻衄，臌胀，金疮。\"\n\n②《分类草药性》：\"治一切跌打损伤，筋骨疼痛，吐血；通气，又治恶毒。\"\n\n③《贵州民间方药集》：\"舒筋活络，通经破瘀。治跌打损伤，风湿麻木，调月经。\"\n\n④《贵州民间药物》：\"治心气痛。\"\n\n⑤《四川中药志》：\"通经活血，强筋壮骨。治五痨七伤，跌打损伤，风湿血痹，筋骨肢节酸痛及脚气，痿躄。\"\n\n⑥《贵州草药》：\"除湿，理气止痛。治胃气痛。\"","y":"内服：煎汤，0.5～1两；或浸酒。","d":"干燥藤茎呈圆柱形，粗壮；少有分枝。一般锯成长约30～60厘米的段落，径约2～6厘米不等。表面棕褐色微带黄色，皮质粗糙，但少里鳞片状者。质坚实，木质性强，切断面皮部呈棕红色或棕紫色，与木心紧密结合，木心坚硬，淡棕红色，有多数排列散乱的细孔。气味微弱。以条大、色红身干、无杂质者为佳。\n主产四川、贵州等地。"},"海风藤":{"a":"风藤、巴岩香(《中药志》)。","s":"辛苦，微温。《中药志》：\"辛，微温。\"","f":"祛风湿，通经络，理气。治风寒湿痹，关节疼痛，筋脉拘挛，跌打损伤，哮喘，久咳。\n\n①《本草再新》：\"行经络，和血脉，宽中理气，下湿除风，理腰脚气，治疝，安胎。\"\n\n②《浙江中药手册》：\"宣痹，化湿，通络舒筋。治腿膝痿痹，关节疼痛。\"","y":"内服：煎汤，2～5钱；或浸酒。","d":"干燥藤茎呈长圆柱形而扁，微弯曲，长15～60厘米，直径3～7毫米。表面粗糙，灰褐色或褐色，有纵向纹理。节膨大，节间长4.5～9厘米，节上不定根长短不等。横断面韧皮部窄，木质部与射线相间放射状排列，木部灰黄色，有许多小孔，射线灰白色，木质部与韧皮部交界处有小洞，故横切面边缘可见小洞成环状，中央有灰褐色髓。质轻而脆，折断时纤维状。气清香，味辛。以茎条粗壮、均匀、气香者为佳。\n主产福建、浙江及台湾等地。\n\n浙江、福建、湖南等地尚有以山蒟的藤茎作海风藤用。"},"小草乌":{"a":"云南飞燕草、倒捉壶(《贵州草药》)，鸡脚草乌(《中国高等植物图鉴》)，细草乌(《云南中草药》)。","s":"辛苦，温。有毒。\n\n①《滇南本草》：\"性温热，味苦。\"\n\n②《云南中草药》：\"微麻苦，温，有毒。\"","f":"驱风除湿，散寒止痛，通络散瘀。治风湿关节痛，胃寒疼痛，跌打损伤。\n\n①《滇南本草》：\"治胃气疼痛，开胃健脾，止面寒、背寒，胸膈噎食，痞满疳疾，左右胁窟，呕吐作酸。\"\n\n②《云南中草药》：\"祛风燥湿，止痛定惊。治风湿疼痛，小儿惊风，小儿肺炎，癫痫，蛔虫，胃痛。\"","y":"内服：煎汤，1～2钱；研末服1～2分；或浸酒。外用：研末调敷。","d":"?"},"野苋菜":{"a":"苋菜、光苋菜","s":"甘，凉。\n\n①《滇南本草》：\"性微温，味咸。\"\n\n②《福建中草药》：\"甘，凉。\"","f":"清热解毒。治痢疾，目赤，乳痈，痔疮。\n\n①苏轼《物类相感志》：\"蜂叮痛，以野苋菜捣敷之。\"\n\n②《滇南本草》：\"白者去肺中痰结，赤者破肠胃中血积。赤白同用，打肚腹毛发之积，消虫积，杀寸白虫，下气。洗皮肤瘙痒、皮肤游走之风。\"\n\n③《中国药植图鉴》：\"缓和止痛、收敛、利尿、解热；种子能利尿、明目。\"\n\n④《福建中草药》：\"清热解毒。\"","y":"内服：煎汤，0.5～4两。外用：捣敷。","d":"?"},"竹蜂":{"a":"笛师(《方言》郭璞解)，留师(《本草拾遗》)，竹蜜蜂(《白孔六帖》)，竹筛蜂(《陆川本草》)，乌蜂、熊蜂、象蜂(《广西中药志》)。","s":"《广西中药志》：\"味甘酸，性寒，无毒。\"\n\n胃；大肠经","f":"清热化痰，定惊。治小儿惊风，口疮，咽痛。\n\n①《陆川本草》：\"祛风化痰，行气消肿，治风痰闭窍，气喘腹胀，风水浮肿，小儿急惊。\"\n\n②《广西中药志》：\"清热泻火，祛风。治齿霞，口疮，咽痛，小儿惊风。\"","y":"内服：烘干研末，2～4个。","d":"性状鉴别，竹蜂体粗大，黑色，有光泽。雌虫胸前有浓密的黑色长毛，雄虫胸前方有一带状浓密的淡黄色绒毛，翅基部蓝紫色，向外缘顶部变铜色，有金属样光泽"},"小金钱草":{"a":"荷包草(《百草镜》)，肉馄饨草(《眼科要览》)，金锁匙(《纲目拾遗》)，黄疸草(《中国植物图鉴》)，小马蹄草(《贵州民间方药集》)，螺丕草(《福建民间草药》)，小铜钱草、酒杯窝(《广西中兽医药植》)，金挖耳、鸡眼草、小灯盏菜(《广西中药志》)，小迎风草、小碗碗草(《四川中药志》)，小元宝草(《上海常用中草药》)，落地金钱(《福建中草药》)，小蛤蟆碗(《浙江民间常用草药》)，九连环(《四川常用中草药》)。","s":"苦辛，凉。\n\n①《纲目拾遗》：\"性微寒。\"\n\n②《福建民间草药》：\"辛，平。\"\n\n③《广西中药志》：\"味淡微酸，性凉，无毒。\"","f":"清热，解毒，利水，活血。治黄疸，痢疾，砂石淋痛，白浊，水肿，疔疮肿毒，跌打损伤。\n\n①《百草镜》：\"利湿热。治黄疸，臌胀，白浊，经闭；捣汁点热眼；煎汤洗痔疮肿痛。\"②《贵州民间方药集》：\"治病后体虚，兴奋精神；又可利尿，治水肿。\"\n\n③《广西中药志》：\"利尿，散瘀，止痛。治五淋，白浊，痢疾；外治跌打刀伤，风火眼痛。\"\n\n④《四川中药志》：\"除风，理气。治风寒咳嗽。跌打损伤及黄疸病。\"","y":"内服：煎汤，2～5钱(鲜者1～2两)。外用：捣敷或捣汁滴眼。","d":"干燥全草多皱缩成团，根细，黄绿色，茎纤细，灰棕色，连同叶之下面，均被以稀疏白色或灰黄色毛茸。质脆，易折断。断面中有小孔。叶互生，多皱缩，圆形或肾形，灰绿色至棕色，上面稍粗糙，质脆易碎，生药中稀见花果。气微弱，味辛。\n\n产四川、浙江、福建、广西、湖南等地。"},"鸭儿芹":{"a":"三叶、起莫、三石、当田(《别录》)，赴鱼(《蜀本草》)，野蜀葵(《国药提要》)，三叶芹(《经济植物手册》)，水白芷、大鸭脚板(《贵州民间方药集》)，鸭脚板草(《四川中药志》)，野芹菜、红鸭脚板、水芹菜(《贵州草药》)。","s":"辛苦，平。\n\n①《别录》：\"味辛。\"\n\n②《陕西中草药》：\"苦微辛，平。\"\n\n③《常用中草药配方》：\"辛淡微苦，寒。\"","f":"消炎，解毒，活血，消肿。治肺炎，肺脓肿，淋病，疝气，风火牙痛，痈疽疔肿，带状疱疹，皮肤瘙痒。\n\n①《别录》：\"主寒热，蛇、蜂螫人。\"\n\n②《分类草药性》：\"治白淋，消肿毒，调经，退火。\"\n\n③《天宝本草》：\"火牙噙之即消。叶：捣敷耳根后，脱眼内翳。\"\n\n④《民间常用草药汇编》：\"外敷治臁疮。\"\n\n⑤《四川中药志》：\"消炎理气。治虚弱劳累，膀胱疝气，五淋尿闭及无名肿毒。\"\n\n⑥《陕西中草药》：\"活血祛瘀，镇痛止痒。治跌打损伤，皮肤瘙痒。\"\n\n⑦《常用中草药配方》：\"抗菌，消炎，解毒，止血，止痛。\"","y":"内服：煎汤，0.5～1两。外用：捣敷或研末撒。","d":"?"},"猪血":{"a":"猪红","s":"咸，平。\n\n①《千金·食治》：\"平，涩，无毒。\"\n\n②《纲目》：\"咸，平，无毒。\"\n\n归心；肝经","f":"治头风眩晕，中满腹胀，嘈杂，宫颈糜烂。\n\n①《别录》：\"主奔豚暴气，中风头眩，淋沥。\"\n\n②《千金·食治》：\"主卒下血不止，美清酒和炒服之。\"\n\n③《日华子本草》：\"生血，疗奔豚气。\"\n\n④《纲目》：\"清油炒食，治嘈杂有虫。\"\n\n⑤《医林纂要》：\"利大肠。\"","y":"内服：煮食或干燥为末。外用：生血涂敷，或干燥粉末喷撒。","d":"?"},"虎尾兰":{"a":"老虎尾(《陆川本草》)。","s":"《陆川本草》：\"性凉，味酸。\"","f":"清热解毒。治感冒，支气管炎，跌打，疮疡。\n\n①《陆川本草》：\"解毒，消炎。治跌打，疮疡，蛇咬伤。\"\n\n②《广西中草药》：\"清热解毒，去腐生肌。治感冒咳嗽，支气管炎，跌打损伤，痈疮肿毒，毒蛇咬伤。\"","y":"内服：煎汤，0.5～1两。外用：捣敷。","d":"?"},"棉花":{"a":"棉花。","s":"《纲目》：\"甘，温，无毒。\"","f":"止血。治吐血，下血，血崩，金疮出血。\n\n①《纲目》：\"治血崩，金疮，烧灰用。\"\n\n②《药性考》：\"烧灰止血，敷冻瘃。\"","y":"","d":"?"},"败酱草":{"a":"败酱、泽败、鹿酱、苦菜、取麻菜","s":"味辛、苦，性微寒。归肝、胃、大肠经。\n。①《本经》：“味苦，平。”\n②《别录》：“咸，微寒，无毒。”\n③《药性论》：“味辛苦，微寒。”\n④《纲目》：“微苦带甘。”入肝、胃、大肠经。\n归肝、胃、大肠经。\n①《汤液本草》：“入足少阴、手厥阴经。”\n②《纲目》：“手足阳明、厥阴。”","f":"清热解毒，消痈排脓，活血行瘀。用于肠痈、肺痈及疮痈肿毒，实热瘀滞所致的胸腹疼痛，产后瘀滞腹痛等症。","y":"内服：煎汤，10～15g（鲜品30～60g）。外用：鲜品适量，捣敷。","d":""},"寻骨风":{"a":"清骨风、猫耳朵(《南京民间药草》)，穿地节、毛香、白毛藤、地丁香、黄木香(《江苏植药志》)，白面风、兔子耳(《江西民间草药》)。","s":"《饮片新参》：\"苦，平。\"","f":"治风湿关节痛，腹痛，疟疾，痈肿。\n\n①《饮片新参》：\"散风痹，通络，治骨节痛。\"\n\n②《南京民间药草》：\"全草浸酒服，治筋骨痛及肚痛。\"\n\n③《江西民间草药》：\"治疟疾，风湿关节痛。\"","y":"内服：煎汤，3～5钱；或浸酒。","d":"①干燥的根茎呈细圆柱形，长40～50厘米，直径约2毫米，外表淡棕红色至黄赭色，有纵皱纹，节处有须根或残留的圆点状根痕。断面纤维性，类白色、淡棕色，纤维层和导管群极为显明。\n\n②干燥全草的茎细长，外被白绵毛；叶通常皱折或破裂，淡绿色，两面均密被白绵毛。气微香，味微苦。以根茎红棕色者为佳。\n产江苏、湖南、江西等地。"},"黄皮叶":{"a":"油皮、油梅","s":"《陆川本草》：\"辛，凉。\"\n\n肺经","f":"疏风解表，除痰行气。治温病身热，咳嗽哮喘，气胀腹痛，黄肿，疟疾，小便不利，热毒疥癞。\n\n①《本草求原》：\"解秽除垢，退黄肿。\"\n\n②《福建民间草药》：\"治痰咳哮喘。\"\n\n③《陆川本草》：\"疏郁行气，止痛退热。治气胀腹痛，温病身热。\"\n\n④广州部队《常用中草药手册》：\"疏风解表。\"","y":"内服：煎汤，0.5～1两(鲜者1～2两)。外用：煎水洗。","d":"性状鉴别 本品为单数羽状复叶，小叶5-13片，多皱缩，破碎，黄绿色至深绿色，完整者呈阔卵形或卵状椭圆形，密布细小半透明油点及疏柔毛，长4-13cm，宽2-5cm，先端急尖或短渐尖，基部楔形至圆形，两侧不对称，叶全缘或浅波状至浅圆齿状，略反卷，叶脉于叶面凹下，于背面凸起，小叶柄被短柔毛，长2-4mm，质脆。气香，味微苦辛。\n显微鉴别 叶横切面：上表皮细胞呈扁方形或长方形，被角质层；下表皮细胞较小，有多数气孔及非腺毛。栅栏组织为1-2列细胞；海绵组织合多数草酸钙簇晶及少数方晶。主脉纸管束周韧式，中柱鞘纤维束淡黄色。断续排列成环状。叶肉组织中有大型分泌细胞（直径40-200μm)散在。\n粉末特征：黄绿色。①草酸钙簇晶较多，棱角稍钝，直径15-35μm；亦有少数草酸钙方晶；②非腺毛指状至长圆锥形，直径30-50μm，长70-240μm；③表皮细胞表面观呈多角形，气孔多为不定式，少数为环式，副卫细胞4-6个；④中柱鞘纤维壁较厚，直径30-40μm，周围薄壁细胞有的含草酸簇晶；⑤木纤维外\n壁呈波状，胞腔稍大，直径40-70μm；⑥导管多为网纹及螺纹，直径60-100μm。"},"蝉花":{"a":"虫花(《四川中药志》)。","s":"《证类本草》：\"甘，寒，无毒。\"","f":"①《证类本草》：\"主小儿天吊，惊痫，瘈疭，夜啼，心悸。\"\n\n②《纲目》：\"功同蝉蜕。又止疟。\"","y":"内服：煎汤，3-9g。","d":"带菌的干燥虫体，虫体长椭圆形，微弯曲，长约3厘米，径约1～1.4厘米，形似蝉蜕，头部有数枚灰黑色或灰白色的孢梗束，长条形或卷曲，或有分枝，长约2～5厘米，质脆易断。虫体表面棕黄色，大部为灰白色菌丝所包被，折断后，可见虫体内充满粉白色或类白色松软物质。气微香。以具孢梗束、个大、完整、肉白、气香者为佳。\n产浙江、四川、云南、江苏等地。\n\n大蝉草子囊壳阶段的子座与寄主山蝉幼虫的干燥体亦入药用，称独角龙、乌角尖，常见于蝉花药材中。虫体同前种，头部具1～2枚棒状子座，或有分枝，长3～7厘米，径3～4毫米，黑褐色，顶端稍膨大，表面有多数细小点状突起。\n\n另有一种小蝉花，又名土蝉花，为小蝉草的子座或其分生孢子阶段的孢梗束与寄主蟪蛄幼虫的干燥体。形体较蝉花小。主产广东、福建。同作蝉花入药。"},"黄葵":{"a":"野芙蓉、假棉花(《广西中草药》)，假山稔、毛夹(《海南植物志》)。","s":"《广西中草药》：\"味微甘，性凉。\"","f":"《广西中草药》：\"解毒消肿，排脓止痛。治痈疮肿痛，无名肿毒，蛇头疮。\"","y":"外用：捣敷","d":"?"},"香椿子":{"a":"椿树子,椿芽树花,椿花,春尖花,香椿铃","s":"辛；苦；温 \n\n《四川中药志》：\"性温，味辛苦，无毒。\"\n\n入肝、肺经\n\n《四川中药志》：\"入肝、肺等经。\"","f":"祛风，散寒，止痛。治风寒外感，心胃气痛，风湿关节疼痛，疝气。\n\n①《民间常用草药汇编》：\"发汗，治心胃气痛。\"\n\n②《四川中药志》：\"除风寒，治冷骨风及风湿关节痛。\"","y":"内服：煎汤，1～3钱；或研末。","d":"干燥果实，长2.5～3.5厘米。果皮开裂为5瓣，深裂至全长2/3左右，裂片披针形，先端尖，外表黑褐色，有细纹理，内表黄棕色，光滑，厚约2.5毫米，质脆。果轴呈圆锥形，顶端钝尖，黄棕色，有5条棕褐色棱线。断面内心松泡色黄白。种子着生于果轴及果瓣之间，5列，种子有极薄的种翅，黄白色，半透明，基部斜口状，种仁细小不明显。气微弱。以完整、干燥者为佳。\n主产四川。"},"鸡矢藤":{"a":"鸡屎藤,臭藤,牛皮冻。","s":"：性平，味甘、微苦。","f":"?","y":"0.5～1两，外用适量，捣烂敷患处。","d":"?"},"水线草":{"a":"伞房花耳草","s":"?","f":"清热解毒。治疟疾，肠痈，肿毒，烫伤。\n\n①《植物名实图考》：\"洗无名肿毒。\"\n\n②《常见混淆中草药的识别》：\"治高热，疟疾，癌肿，阑尾炎。\"","y":"内服：煎汤，0.5～1两。外用：煎水洗。","d":"?"},"菊三七":{"a":"土三七，金不换，紫三七，血当归、血三七、血七、血格答，水三七，紫蓉三七、艾叶三七、铁罗汉、乌七，菊叶三七，狗头三七","s":"味甘、苦。性温。","f":"破血散瘀，止血，消肿。治跌打损伤，创伤出血，吐血，产后血气痛。\n\n①《滇南本草》：\"治跌打损伤。生用破血，炙用补血。\"\n\n②《纲目》：\"治金疮折伤出血及上下血病。\"\n\n③《简易草药》：\"能破血，祛瘀，散血，消肿。通治五劳七伤，跌打损伤。\"\n\n④《草木便方》：\"活血，续筋接骨。治内伤积血，痞块，心腹疼痛。\"\n\n⑤《天宝本草》：\"治包块癥瘕，妇女血滞，腰脚痛，男子遗精，痢症。\"\n\n⑥《国药的药理学》：\"治血痢，月经过多，分娩后的后期出血等。又遇虎咬、毒蛇咬，蜂刺伤时，取汁涂敷伤处。\"\n\n⑦《昆明药植调查报告》：\"治浮肿。\"","y":"内服：煎汤，2～3钱：研末，0.5～1钱。外用：捣敷。","d":"根呈拳形肥厚的圆块状，长3～6厘米，直径约3厘米，表面灰棕色或棕黄色，全体多有瘤状突起及断续的弧状沟纹，在突起物顶端常有茎基或芽痕，下部有须根或已折断。质坚实，不易折断，断面不平，新鲜时白色，干燥者呈淡黄色，有菊花心。气无，味甘淡后微苦。以干燥、整齐、质坚、无杂质、断面明亮者为佳。\n产四川、云南、广东、广西、江苏、江西、湖南、贵州等地。"},"山棯子":{"a":"豆棯干(《广西中药志》)。","s":"甘涩，平。\n\n①《本草求原》：\"甘，平。\"\n\n②《南宁市药物志》：\"甘涩。\"","f":"养血，止血，涩肠，固精。治血虚，吐血，鼻衄，便血，痢疾，脱肛，耳鸣，遗精，血崩，带下。\n\n①《生草药性备要》：\"健大肠，亦治蛇伤。\"\n\n②《纲目拾遗》：\"养血，明目。\"\n\n③《本草求原》：\"止痢、赤白带，生肌止血。\"\n\n④《南宁市药物志》：\"补血收敛。治腰肾酸痛，水泻，疗妇人血崩，痧麻夹经。果浸酒补血。\"\n\n⑤《广东中药》：\"治夜多小便，耳鸣遗精。炒黑治血崩。\"","y":"内服：煎汤，2～5钱(鲜者1～2两)；或浸酒。外用：烧存性研末调敷。","d":"干燥的果实呈长圆球形，一端稍尖，径约1厘米。外表土黄色或暗绿褐色。质较硬，顶端有宿存萼片5枚及花柱之残迹。内有种子多数，黄白色，扁平。味淡微甜，气微香。以个大、无虫蛀、干燥者为佳。\n\n产广东、广西、福建等地。"},"五爪龙":{"a":"五叶藤，五叶茹。","s":"《泉州本草》：\"甘，寒，无毒。\"","f":"清热，利水，解毒。治肺热咳嗽，小便不利，淋病，尿血，痈疽肿毒。\n\n①《南宁市药物志》：\"清热利尿。治肺热咳嗽。根、叶，捣烂外敷，治痈疮。\"\n\n②《泉州本草》：\"清热解毒，通淋利小便。治淋症，水肿，外敷痈疽肿毒。\"","y":"内服：煎汤，1.5～3钱(鲜者0.5～1两)。外用：捣敷。","d":"?"},"排草香":{"a":"排香、香排草、香草(《四川中药志》)，毛柄珍珠菜(《广西植物名录》)。","s":"《四川中药志》：\"味甘，性平，无毒。\"","f":"治感冒，咳喘，风湿痛，月经不调。\n\n①《中国药植志》：\"治虚弱。\"\n\n②《四川中药志》：\"祛风湿，理气，止气痛，醒脑除烦，搽雀斑。\"\n\n③《广西植物名录》：\"益气补虚，祛风活血。治虚弱，气管炎，哮喘，月经不调，感冒咳嗽。\"","y":"内服：煎汤，1～3钱。","d":"?"},"朝天罐":{"a":"张天刚(《植物名实图考》)，七孔莲、朝天瓮子、张天罐、紫金钟、赤红莲、痢症草、罐子草(《江西中医》)，向天葫芦、天葡萄、公石榴、大金钟(《广西中兽医药植》)，痢疾罐(《贵阳民间药草》)，罗浮金锦香(《中国药植图鉴》)，倒罐草、天罐子(《成都中草药》)，酒里坛(《云南中草药选》)","s":"《贵阳民间药草》：\"酸涩，微寒，无毒。\"","f":"补虚益肾，收敛止血。治痨伤咳嗽吐血，痢疾，下肢酸软，筋骨拘挛，小便失禁，白浊白带。\n\n①《植物名实图考》：\"治下部虚软，补阴分。\"\n\n②《民间常用草药汇编》：\"益肾止咳。\"\n\n③《贵阳民间药草》：\"清热收敛止血。治痢疾，虚咳，咯血。\"","y":"内服：煎汤，3～5钱。","d":"?"},"红景天":{"a":"扫罗玛尔布","s":"甘，苦，平。归肺、心经。","f":"活血止血，清肺止咳。治咳血，咯血，肺炎咳嗽，妇女白带。\n\n外用治跌打损伤，汤火伤。","y":"内服：煎汤，1～3钱，外用：捣敷或研末调敷。","d":"?"},"胖大海":{"a":"安南子、大洞果、胡大海、大发、通大海、大海子、大海、大海榄","s":"甘，寒;有小毒。归肺、大肠经。","f":"清热润肺，利咽解毒，润肠通便。用于肺热声哑，干咳无痰，咽喉干痛，热结便闭，头痛目赤。","y":"内服：煎汤，1.5～3钱；或泡茶。","d":"干燥种子呈椭圆形，状似橄榄，先端钝圆，基部略尖，长2～3厘米，直径l～1.5厘米。表面棕色至暗棕色，微有光泽，具细密的不规则皱纹，基部具浅色的圆形种脐。外种皮质轻而疏松，易剥落，遇水膨大成海绵状块。内种皮红棕色至棕黑色，先端有一黄白色的圆斑。剥去内种皮后，胚乳肥厚，成2片，暗棕色或灰棕色。子叶2片，紧贴于胚乳，菲薄而大。气无，久嚼有粘性。以个大、棕色、表面皱纹细、不碎裂者为佳。\n\n\n主产于越南、泰国、印度尼西亚、马来西亚等地。"},"黑芝麻":{"a":"胡麻、油麻、巨胜、脂麻","s":"甘，平。\n\n归肝、肾、大肠经。","f":"补肝肾，益精血，润肠燥。用于头晕眼花，耳鸣耳聋，须发早白，病后脱发，肠燥便秘。","y":"9～15g。","d":"(1) 取本品1g，研碎，加石油醚(60～90℃)10ml，浸泡1 小时，倾取上清液，置试管中，加含蔗糖0.1g的盐酸10ml，振摇半分钟，酸层显粉红色，静置后，渐变为红色。\n\n(2) 取本品0.5g，捣碎，加氯仿10ml，浸渍2 小时，滤过，滤液挥干，残渣加氯仿1ml 使溶解，作为供试品溶液。另取芝麻素及β-谷甾醇对照品，加氯仿分别制成每 1ml含2mg 的溶液，作为对照品溶液。照薄层色谱法(附录Ⅵ B)试验，吸取供试品溶液5μl、对照品溶液各2μl，分别点于同一硅胶G薄层板上，以环己烷-乙醚-醋酸乙酯(20:5.5:2.5)为展开剂，展开，取出，晾干，喷以10%硫酸乙醇溶液，加热至斑点显色清晰。供试品色谱中，在与对照品色谱相应的位置上，显相同颜色的斑点。"},"通天草":{"a":"荸荠梗(《饮片新参》)，地栗梗、荸荠苗(《苏州本产药材》)。","s":"①《饮片新参》：\"苦，平。\"\n\n②《苏州本产药材》：\"甘，寒。\"","f":"①《饮片新参》：\"化湿热，利小便，通淋。\"\n\n②苏医《中草药手册》：\"清热，利尿。治小便不利，呃逆。\"","y":"内服：煎汤，2～3钱。","d":"干燥的茎，呈压扁状，长60～90厘米，直径4～7毫米，顶端有穗状花序；上部淡黄色，不易拉断，下部淡绿色，则易拉断。全体皱缩，表面有纵纹，具光泽；节处稍隆起，质轻松软，中间空，折断面内有白色膜状间隔，用扩大镜观察之，呈蜂窝状。气微弱。以干燥、完整、带黄绿色、无泥土杂质者为佳。\n主产江苏、上海、浙江等地。"},"隔山消":{"a":"隔山撬(《分类草药性》)，隔山锹(《天宝本草》)。","s":"①《贵阳民间药草》：\"甘苦，平，无毒。\"\n\n②《陕西中草药》：\"甘微辛，平。\"","f":"养阴补虚，健脾消食。治虚损劳伤，痢疾，疳积，胃痛饱胀，白带，疮癣。\n\n①《纲目》：\"主腹胀积滞。\"\n\n②《草木便方》：\"醋磨涂癣。\"\n\n③《分类草药性》：\"消食积，下乳，补虚弱。\"\n\n④《贵州民间方药集》：\"外用治疮毒、鱼口。\"\n\n⑤《陕西中草药》：\"滋阴养血，健脾顺气，镇静止痛，催乳。治胃痛腹胀，虚劳，肾虚腰痛，阳萎，小儿痞块，白带，乳汁不足。\"\n\n⑥《南方主要有毒植物》：\"治肾炎水肿，胃及十二指肠溃疡。\"\n\n⑦《江西草药》：\"清热解毒，顺气止痢。\"","y":"内服：煎汤，2～3钱(鲜者0.5～1两)；或入丸、散。外用：捣敷或磨汁涂。","d":"干燥块根呈圆柱形，微弯曲，长约10～20厘米，直径约2～3厘米。外表黄褐色或红棕色，栓皮粗糙，有明显纵横皱纹，皮孔横长突起，栓皮破裂处露出黄白色的木质部。质坚硬，断面淡黄棕色，粉质，有辐射状花纹及鲜黄色孔点。气无，味先苦后甜。\n产四川、江苏、江西等地。本品在江苏作白首乌使用。"},"芋头花":{"a":"芋苗花(《生草药性备要》)。","s":"《四川中药志》：\"性平，味麻，有毒。\"","f":"治胃痛，吐血，子宫脱垂，痔疮，脱肛。\n\n①《生草药性备要》：\"治隔食，炒用。\"\n\n②《民间常用草药汇编》：\"治胃气痛，除湿。\"\n\n③《四川中药志》：\"治内外痔疮，吐血及小儿脱肛。\"","y":"内服：煎汤，0.5～1两。外用：捣敷。","d":"?"},"七叶胆":{"a":"绞股蓝,小苦药,公罗锅底,落地生,遍地生根","s":"味苦，性寒，无毒。","f":"消炎解毒，止咳祛痰，治慢性气管炎。","y":"内服：研末，每次0.7～1钱，每日3次，10天为一疗程。","d":"性状鉴别 本品为干燥皱缩的全草，茎纤细灰棕色或暗棕色，表面具纵沟纹，被稀疏毛茸，润湿展开后，叶为复叶，小叶膜质，通常5-7枚，少数9枚，叶柄长2-4cm被糙毛；侧生小叶卵状长圆形或长圆状披针形，中央1枚较大，长4-12cm，宽1-3.5cm；先端渐尖，基部楔形，两面被粗毛，叶缘有锯齿，齿尖具芒。常可见到果实，圆球形，直径约5mm，果梗长3-5mm。味苦，具草腥气。显微鉴别 叶横切面：叶的上下表皮由1层长方形细胞组成，外被角质层。叶肉组织异面型，栅栏组织由1-2层细胞组成，不通过主脉；海绵组织由3-4层细胞组成。主脉均向上下表皮突出，内侧有2-3层厚角细胞，维管束外韧型。 叶表面：上表皮垂周壁近平直，下表皮垂周壁微波状弯曲，气孔为不定式。上下表皮均有非腺毛和腺毛；非腺毛由5-14个细胞组成，表面有明显的线状角质纵纹，长120-360mm。茎横切面 呈多角形，表皮由1列扁平的细胞组成，外壁角质增厚，着生单细胞和多细胞非腺毛，角隅处有厚角组织，由4-6列细胞组成；皮层内方有围绕于韧皮部外缘的半月形纤维柬，内方有9-10个大小不等的双韧维管束，放射排列；两韧皮射线间有石细胞群；髓部薄壁细胞内含有直径12-28mm的淀粉粒。"},"蚂蝗七":{"a":"红蚂蝗七(《广西药植名录》)，石螃蟹(《广西实用中草药新选》)。","s":"《广西实用中草药新选》：\"微苦，凉，无毒。\"","f":"①《广西药植名录》：\"内用止咳，治胃痛，痢疾，小儿疳疾。外用消肿止痛，接骨，治跌打。\"\n\n②《广西实用中草药新选》：\"健脾消食，清热除湿。治小儿疳疾，肝炎。\"","y":"内服：煎汤，2～6钱。外用：捣敷。","d":"?"},"尿泡草":{"a":"羊卵泡。","s":"微苦，平。","f":"利尿。治肝硬化腹水，血管神经性水肿，慢性肝炎浮肿。","y":"内服：煎汤，20～30枚。","d":"?"},"母草":{"a":"四方草、小叶蛇针草、铺地莲(广州部队《常用中草药手册》)，四方拳草、蛇通管、气痛草(广州空军《常用中草药手册》)。","s":"广州部队《常用中草药手册》：\"微苦淡，凉。\"","f":"清热利湿，解毒。治感冒，急、慢性菌痢，肠炎，痈疖疔肿。\n\n①广州部队《常用中草药手册》：\"清热利湿。治细菌性痢疾，肠炎，腹泻，消化不良，蛇咬伤。\"\n\n②广州空军《常用中草药手册》：\"治感冒，肝炎，肾炎水肿，痈疮，疔毒。\"\n\n③《广西药植名录》：\"治跌打，乳痈，胃癌。\"","y":"内服：煎湎，1～3钱(鲜者1～2两)；研未或浸酒。外用：捣敷。","d":"?"},"旋复花":{"a":"蕧、盗庚，戴椹(《本经》)，飞天蕊金钱花(《本草图经》)，野油花，滴滴金、夏菊(《纲目》)，金钱菊(《花史》)，艾菊、迭罗黄(《群芳谱》)，满天星(《岭南采药录》)，六月菊(《铁岭县志》)，黄熟花(《南京民间药草》)，水葵花、金盏花，复花，小黄花，猫耳朵花、驴耳朵花，金沸花、伏花、全福花(《上海常用中草药》)。","s":"咸，温。","f":"消痰，下气，软坚，行水。治胸中痰结，胁下胀满，咳喘，呃逆，唾如胶漆，心下痞鞕，噫气不除，大腹水肿。\n\n①《本经》：“主结气，胁下满，惊悸。除水，去五脏间寒热，补中，下气。”\n\n②《别录》：“消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮，风气湿痹，皮间死肉，目中眵蔑，利大肠，通血脉，益色泽。”\n\n③《药性论》：“主肋胁气，下寒热水肿，主治膀胱宿水，去逐大腹，开胃，止呕逆不下食。”\n\n④《日华子本草》：“明目，治头风，通血脉。”\n\n⑤《汤液本草》：“发汗吐下后，心下痞，噫气不除者宜此。”\n\n⑥《滇南本草》：“祛头目诸风寒邪，止太阳、阳明头疼，行阳明乳汁不通。(治)乳岩、乳痈、红肿疼痛、暴赤火眼、目疾疼痛、祛风明目、隐涩羞明怕日，伤风寒热咳嗽、老痰如胶，走经络，止面寒腹疼，利小便，治单腹胀，风火牙根肿痛。”\n\n⑦《医学入门》：“逐水，消痰，止呕噎。”\n\n⑧《南京民间药草》：“花和苗，祛湿、拔毒、消肿，煎水洗患处。”","y":"内服：煎汤(包煎或滤去毛)，1.5～3钱；或入丸、散。外用：煎水洗，研末干撒或调敷。","d":"干燥头状花序呈扁球形，有时散落，直径8～15毫米(线叶旋复花较小，4～10毫米)。底部有4层(线叶旋复花3层)浅灰绿色、膜质的总苞片，有时残留花梗。外缘1层舌状花，黄色，长约1厘米，先端3齿裂，多卷曲；中央管状花密集，花冠5齿裂，子房顶端有多数白色冠毛，长约5毫米(线叶旋复花长约3毫米)，质柔软，手捻易散。气微弱，味微苦咸。以朵大、金黄色、有白绒毛，无枝梗者为佳。\n\n主产河南、江苏、河北，浙江、?徽和黑龙江、吉林、辽宁等地。\n\n\n\n除上述品种外，在部分地区尚有将旋复花属其它种植物的头状花序作旋复花用，如广东、广西、湖南、江西等地用的是齿叶旋复花，其干燥花序略呈球形，直径7～12毫米。总苞灰绿色，被白色茸毛。舌状花1层，黄色或淡棕色，有时脱落；管状花密集中央，子房上的冠毛多数退化，留下鳞片状残迹，质硬。云南、贵州有些地区用的是水朝阳花(参见\"水朝阳\"条)，其干燥花序的直径8～14毫米。子房上的冠毛15～20条，长约3毫米。湖北、贵州有些地区用的是湖北朝阳花，其干燥花序略呈半球形，不易散落，直径1～2厘米。总苞黄绿色或绿色，被白色短毛。舌状花1层，细长，长可达2厘米，黄色或淡棕色；中央为管状花，冠毛5～10条，长约2毫米。"},"荨麻根":{"a":"?","s":"《文山中草药》:\"苦辛，温，有毒。\"","f":"祛风，活血，止痛。治风湿疼痛，湿疹，麻风。\n\n①《贵州民间方药集》:\"治虚弱劳伤，舒筋活血，又可驱风。\"\n\n②《新疆中草药手册》:\"治高血压，手足发麻。\"\n\n③《文山中草药》:\"活血散风，止痛。\"","y":"内服:煎汤，1～3钱；或浸酒。外用:煎水洗。","d":"?"},"杨梅":{"a":"朹子(《北户录》)，圣生梅、白蒂梅(《品汇精要》)，朱红、树梅(《中国树木分类学》)。","s":"甘酸，温。\n\n\n①《食疗本草》：\"温。\"\n\n\n②《日华子本草》：\"热，微毒。\"\n\n\n③《开宝本草》：\"酸，温，无毒。\"\n\n\n④《日用本草》：\"昧酸甘，温，无毒。\"","f":"生津解渴，和胃消食。治烦渴，吐泻，痢疾，腹痛，涤肠胃，解酒。\n\n\n果实治心胃气痛，痢疾，吐泻;树皮能止血治痢，外用治刀伤出血，跌打伤，筋骨痛。\n\n\n①孟诜：\"和五藏，能涤肠胃，除烦愦恶气，亦能治痢。\"\n\n\n②《本草拾遗》：\"止渴。\"\n\n\n③《日华子本草》：\"疗呕逆吐酒。\"\n\n\n④《开宝本草》：\"主去痰，止呕哕，消食下酒。\"\n\n\n⑤《玉楸药解》：\"酸涩降敛，治心肺烦郁，疗痢疾损伤，止血衄。\"\n\n\n⑥《现代实用中药》：\"治口腔咽喉炎症。\"\n\n\n⑦《中国药植图鉴》：\"对心胃气痛及霍乱有效。\"","y":"内服：生啖、浸酒、腌食或烧存性研末。外用：捣敷、烧存性研末搐鼻或调敷。","d":"?"},"马蹄草":{"a":"连钱草、大叶金钱草、雷公根、蛐壳草、铜钱草、落得打、十八缺","s":"?","f":"治发痧，跌伤，扭伤。","y":"?","d":"?"},"苦竹笋":{"a":"苦笋(《食疗本草》)。","s":"①《纲目》：\"苦甘，寒。\"\n\n②《本草求原》：\"苦，寒，无毒。\"","f":"清热，除湿，利水，明目。治消渴，面目黄，脚气。\n\n①《本草拾遗》：\"主不睡，去面目并舌上热黄，消渴，明目，解酒毒，除热气，健人。\"\n\n②《食疗本草》：\"主逆气。\"\n\n③《食医心镜》：\"理心烦闷，益气力，止渴，主消渴，利水道，下气，理风热，脚气，蒸煮食之。\"\n\n④汪颖《食物木草》：\"治出汗，中风失音。\"\n\n⑤《纲目》：\"干者烧研入盐，擦牙疳。\"","y":"内服：煎汤，2～3两；或煮食。","d":"?"},"九仙草":{"a":"九龙草、珍珠草、酒仙草、小星宿草","s":"辛苦，凉。\n\n①《云南中草药》：\"甘、微苦，寒。\"\n\n②《云南中草药选》：\"微辛，凉。\"","f":"祛风清热，解痉。治感冒，中暑，小儿肺炎，咳嗽，惊风。\n\n①《云南中草药》：\"退热解痉，消炎杀虫。治小儿肺炎，咳嗽，肝炎，小儿惊风，血小板减少性紫癜，虫积，血吸虫病。\"\n\n②《云南中草药选》：\"解表，清热。治感冒，中暑，支气管炎。\"","y":"内服：煎汤，2～3钱；或蒸鸡蛋服。","d":"?"},"透骨香":{"a":"透骨草(《滇南本草》)，满山香(《分类草药性》)，煤炭子、煤炭果(《贵阳民间药草》)，万里香(《广西植物名录》)，九里香、洗澡叶、芳香草、满天香(《云南中草药》)，小遗骨草、透骨消(《昆明民间常用草药》)。","s":"辛，温。\n\n①《滇南本草》：\"性温，味辛辣，有小毒。\"\n\n②《贵阳民间药草》：\"辛，温，无毒。\"\n\n③《云南中草药》：\"辛，平。\"","f":"祛风除湿，活血通络。治风湿关节痛，水撒，跌打损伤，牙痛，湿疹。\n\n①《滇南本草》：\"治痰火，筋骨疼痛，泡酒用之良。其梗，洗风寒湿痹，筋骨疼痛，暖骨透热，熬水洗之。\"\n\n②《贵阳民间药草》：\"治风湿关节疼痛，跌打损伤。\"\n\n③《广西药植名录》：\"行气，消肿，止咳化痰。治牙痛，劳伤，蛇伤，风湿，痧气，皮肤痛痒。\"\n\n④《贵州草药》：\"祛风除湿，舒筋活血。\"\n\n⑤《昆明民间常用草药》：\"活络透骨。\"","y":"内服：煎汤，3～5钱(鲜者1两)；或浸酒。外用：煎水洗。","d":"茎长约35厘米，多分枝，径3～5毫米，表面黄棕色，具纵纹，有叶柄残痕。叶多数脱落。气微，味微苦，以新鲜、干燥，叶色绿者为佳。\n产云南、贵州。\n\n本品在云南、贵州地区作透骨草使用，参见\"透骨草\"条。"},"半边旗":{"a":"甘草蕨、甘草凤尾蕨、半边莲、半边蕨、半凤尾草、半边风药、凤凰尾巴草、单边旗、半边梳","s":"《陆川本草》：\"辛，凉。\"","f":"①《岭南采药录》：\"凡毒蛇咬伤，可将叶捣烂和片糖敷：治疮疖，煎水洗。\"\n\n②《南宁市药物志》：\"止血，生肌，消肿，止痛。治跌打，痢疾，发背，蛇伤。\"\n\n③《浙江天目山药植志》：\"根茎，煎服，治目赤肿痛。\"","y":"内服：煎汤，3～5钱。外用：捣敷、研末撒：或煎水洗。","d":"?"},"双参":{"a":"萝卜参、童子参、羊蹄参、山苦参、子母参(《云南中草药》)，合合参(《云南中草药选》)。","s":"甘苦，平。\n\n①《云南中草药》：\"苦微甘，平。\"\n\n②《云南中草药选》：\"甘微苦，温。\"","f":"益肾补气，活血调经。治肾虚腰痛，遗精，阳痿，月经不调，经闭。\n\n①《云南中草药》：\"调经活血，益肾。治闭经，月经不调，肾虚腰痛，遗精，阳痿，不孕症。\"\n\n②《云南中草药选》：\"补血，活血，补气。治久病体虚，慢性肝炎，月经不调，倒经，不孕症。\"","y":"内服：煎汤，0.5～1两；或炖肉服。","d":"?"},"雪茶":{"a":"地茶、太白茶(《陕西中草药》)。","s":"《四川中药志》：\"淡微苦，凉，无毒。\"","f":"清热解渴，醒脑安神。治虚劳骨蒸，肺炎咳嗽，癫痫狂躁，神经衰弱，高血压。\n\n①《纲目拾遗》：\"治胃气积痛，疗痢。\"\n\n②《中药形性经验鉴别法》：\"清热，解烦闷。\"\n\n③《四川中药志》：\"清热醒脑。治口干舌燥，眼昏头闷，精神疲倦。\"\n\n④《陕西中草药》：\"清热解渴，安神养心，明目。治心中烦热，虚劳骨蒸，肺炎咳嗽，癫痫狂躁，神经衰弱，目涩，中暑，高血压。\"","y":"内服：煎汤，3～5钱；或泡茶饮。","d":"全体呈细长管状，单枝或有2～3分枝，白色，长3～7厘米，直径1～2毫米，粗者呈扁带状，基部有断痕，先端渐尖细，外表细致，略有皱纹凹点。断面中空。质稍柔软。气无，味苦似茶。以粗壮、色白、味苦者为佳。\n产云南、四川。"},"穿心草":{"a":"穿钱草、顶心风(《广西中草药》)，穿心莲、狮子草(《广西实用中草药新选》)。","s":"①《广西中草药》：\"味微甘微苦，性平，无毒。\"\n\n②《广西实用中草药新选》：\"味微苦，性凉。。","f":"清热解毒，活血止痛。治肺热咳嗽，肝炎，钩端螺旋体病，黄疸，胸痛，胃痛，跌打内瘀，毒蛇咬伤。\n\n①《广西中草药》：\"理气，止痛，止咳。治肺热咳嗽，心胃气痛，毒蛇咬伤。\"\n\n②《广西实用中草药新选》：\"凉肝胆，活血止痛。治黄疸，肝炎，胸痛，胃痛，跌打内伤。\"\n\n③广州空军《常用中草药手册》：\"治急性支气管炎，肺炎，急性胃炎，十二指肠炎。\"","y":"内服：煎汤，3～5钱，治毒蛇咬伤用量加倍。外用：煎水洗。","d":"?"},"地牯牛":{"a":"砂挼子、倒行狗子、睡虫(《本草拾遗》)，沙谷牛(《生草药性备要》)，沙牛(《本草求原》)，蚁狮(《动物学大辞典》)，砂牛虫(《陆川本草》)，金沙牛(《生草药手册》)，地拱(《四川中药志》)。","s":"辛咸，温，有毒。\n\n①《本草拾遗》：\"有毒。\"\n\n②《陆川本草》：\"平，淡。\"\n\n③《四川中药志》：\"性温，味辛咸，有毒。\"","f":"治砂淋，疟疾，疔疮，瘰疬。\n\n①《生草药性备要》：\"治瘰窃，初起消散，破烂拔毒埋口。\"\n\n②《本草求原》：\"通窍利水。治淋，炒研同白糖汤下。\"\n\n③《民间常用草药汇编》：\"退疮管。\"\n\n④《陆川本草》：\"治小儿风痰，痉挛，砂淋，敷疔疮。\"\n\n⑤《四川中药志》：\"治瘴块，疟母，大便闭结不通，退竹木刺及铁沙入肉。\"","y":"内服：煎汤，0.5～1钱；或入散剂。外用：研末撒或捣烂敷。","d":"?"},"白首乌":{"a":"隔山消、白何乌、白何首乌、隔山撬、白木香、野蕃薯、一肿三消、和平参、山花旗、张果老","s":"味苦;性平\n\n\n《山东中药》：\"味苦甘涩，性微温，无毒。\"\n\n\n归肝;肾;脾胃经","f":"补肝肾;强筋骨;益精血;健脾消食;解毒疗疮\n\n\n主治腰膝酸软;阳痿遗精;头晕耳鸣;心悸失眠;食欲不振;小儿疳积;产后乳汁稀少;疮痈肿痛;毒蛇咬伤\n\n\n《山东中药》：\"为滋养、强壮、补血药，并能收敛精气，乌须黑发。治久病虚弱，贫血，须发早白，慢性风痹，腰膝酸软，性神经衰弱，痔疮，肠出血，阴虚久疟，溃疡久不收口。鲜的并有润肠通便的作用，适用于老人便秘。\"","y":"内服：煎汤，2～4钱；或入丸、散。","d":"干燥块根呈圆柱形或类球形，长5～10厘米，径约1.5～3.5厘米。表面黄褐色，多皱缩，栓皮易层层剥离。质坚硬，断面白色，粉性。气无，味苦甘涩。以粗大、粉足、断面白色者为佳。\n\n\n主产山东。\n\n\n白首乌的药材，除上述品种外，其同属植物耳叶牛皮消(参见\"飞来鹤\"条)，及隔山牛皮消的块根，有些地区亦作白首乌用。"},"人参芦":{"a":"参芦、竹节参","s":"甘苦，温。\n\n①《本草蒙筌》：\"甘。\"\n\n②《纲目》：\"苦，温，无毒。\"","f":"涌吐，升阳。治虚人痰壅胸膈，气陷泄泻。\n\n①《本草蒙筌》：\"发吐痰沫。虚羸老弱，痰壅，难服藜芦，用此可代。\"\n\n②《本经逢原》：\"盐哮用参芦涌吐最妙。\"","y":"内服：煎汤，1～2钱；或研末服。","d":"（1）取本品粉末0.5g，加已醇5ml，振摇5min，滤过。取滤液1ml，置蒸发皿中蒸干，滴加三氯化锑氯仿饱和溶液，再蒸干，显紫色。（检查人参皂甙）（2）取本品粉末1g，加氯仿40ml，置水浴上回波1h，弃氯仿液，药渣挥去溶剂，加水0.5ml拌匀湿润后，加水饱和的正丁醇10ml，超声处理30min，吸取上清液，加氨试液3倍量，摇匀，放置分层，取上层液蒸干，残潭加甲醇1ml振摇溶解，作为供试品溶液。另取人参皂甙Rb1、Re、Rb1对照品，加甲醇溶解制成每1ml各含2mg对照品的混合溶液，作为对照品溶液。在同一硅胶G薄层板上，将上述2种溶液分别点样，以氯仿-醋酸已酸-甲醇-水（15：40：22：10）在10℃硫酸已醇试液为显色剂，在105℃烘数分钟，分别在自然光及紫外光灯（365nm）下观察。样品溶液色谱，在与对照品溶液色谱的相应位置上，显相同颜色的斑点或荧光斑点。"},"景天三七":{"a":"费案、土三七、八仙草、血山草、马三七、白三七、胡椒七、晒不干、吐血草、见血散、活血丹、墙头三七、养心草回生草、九头三七","s":"x性平；味甘，微酸。入心；肝；脾经\n\n《浙江民间常用草药》：\"性平，味甘微酸。\"","f":"止血，化瘀。治吐血，衄血，便血，尿血，崩漏，跌打损伤。\n\n①《植物名实图考》：\"治吐血。\"\n\n②《山西中药志》：\"止血。治崩漏，便血。\"\n\n③《浙江中药资源名录》：\"治跌打损伤。\"\n\n④《浙江民间常用草药》：\"安神补血，止血化瘀。\"\n\n⑤《山西中草药》：\"止血散瘀，消肿止痛。\"","y":"内服：煎汤，3～5钱(鲜品2～3两)。外用：捣敷。","d":"性状鉴别 \n（l）费菜根茎短小，略呈块状；表面灰棕色，根数条，粗细不等；质硬，断面暗棕色或类灰白色。茎圆柱形，长15-40cm，直径2-5mm；表面暗棕色或紫棕色，有纵校；质脆，易折断，断面常中空。叶互生或近对生，几无柄；叶片皱缩，展平后呈长披针形至倒披针形，长3-8cm，宽l-2cm；灰绿色或棕褐色，先端渐尖，基部楔形，边缘上部有锯齿，下部全缘。聚伞花序顶生，花黄色。气微，味微涩。\n（2）横根费菜 根茎横走，木质，较细长。茎簇生。叶匙形至倒卵形。花橘黄色。\n显微鉴别 \n费菜根横切面：木栓层为10余列细胞，棕色。皮层较薄。韧皮部宽广。形成层成环。木质部导管类圆形，直径约至56μm，多单个散在，分布较密。本品薄壁细胞含草酸钙砂晶。\n\n干燥全草，茎呈青绿色，易折断，中间空心，叶皱缩，上、下面均灰绿色，但大多已脱落。气无，味微涩。亦有带根者。以色绿、身干、无杂质者为佳。"},"野酒花":{"a":"酒花、香蛇麻、啤酒花、蛇麻、忽布","s":"味苦，性平。","f":"健胃，镇静，抗结核。治消化不良，不思饮食，瘴病，失眠，结核病。","y":"内服：煎汤，3～6钱；或泡开水代茶饮。","d":"?"},"苦木":{"a":"黄楝瓣树,狗胆木,苦木霜,苦胆木,熊胆树,黄楝树。","s":"：性寒，味苦。","f":"?","y":"内服：煎汤，6-15g，大剂量30g；或入丸、散。外用：适量，煎水洗；研末撒或调敷；或浸酒搽。","d":"理化鉴别 取本品粗粉2g，加乙醇提取，蒸去乙醇后，加适量蒸馏水溶解，再以氯仿提取，蒸干，加蒸馏水2ml溶解。取1ml溶液置紫外光灯下观察，显天蓝色荧光，滴加氢氧化铵试液后，显淡黄绿色荧光。（检查内酯）（2）取上述溶液1ml，加异羟肟酸铁试液2-3滴，溶液呈紫红色。（检查内酯）薄层色谱 取本品粉末1g，加甲醇10ml冷浸过夜，滤过，滤液备用。以苦木碱B、C、D、F为对照品点于硅胶G薄层板上，用氯仿为展开剂，展距18cm。以改良Dra-gendorff-Wagner（1：1）试剂为显色剂显色，置紫外光灯（365nm）下观察，样品与对照品在相对应的位置处显相同颜色的荧光斑点。"},"黄莲花":{"a":"?","s":"酸、涩，微寒。","f":"可治高血压。对睡(失)眠有良好效果。","y":"内服；煎汤，3～5钱。","d":"?"},"蕨麻":{"a":"人参果(《西藏常用中草药》)，莲菜花(《中国高等植物图鉴》)，戳玛(藏名)。","s":"《西藏常用中草药》：\"甘，平。\"","f":"《西藏常用中草药》：\"健脾益胃，生津止渴，益气补血，治脾虚腹泻，病后贫血，营养不良。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"石吊兰":{"a":"黑乌骨(《植物名实图考》)，石豇豆(《草木便方》)，石泽兰、大姜豆、小泽兰(《分类草药性》)，岩豇豆、岩茶(《贵州民间方药集》)，岩泽兰(《贵阳民间药草》)，岩石兰、巴岩草，肺红草、蜂子花、瓜子草、石花(《湖南药物志》)，接骨生、山泽兰、千锤打、产后茶(《广西药植名录》)。","s":"甘苦，凉。\n\n①《草木便方》：\"甘。\"\n\n②《分类草药性》：\"苦，有毒。\"\n\n③《贵阳民间药草》：\"甘苦，平，无毒。\"\n\n④《文山中草药》：\"苦，凉。\"","f":"清肺消痰，凉血止血，祛湿化滞，通络止痛。治肺热咳嗽，吐血，崩带，菌痢，疳疾，风湿痹痛，跌打损伤。\n\n①《植物名实图考》：\"通肢节，治跌打，酒病。\"\n\n②《草木便方》：\"消痰，追毒，化食，养阴血。治风湿气肿，头闷眼花，诸虚。\"\n\n③《分类草药性》：\"治吐血，腰膝痛，去风除湿，跌打损伤。\"\n\n④《民间常用草药汇编》：\"清肺止咳，凉血止血。\"\n\n⑤《四川武隆药植图志》：\"治妇女血气病。\"\n\n⑥《四川中药志》：\"治妇女崩带，风湿痹痛，小儿疳疾及内伤喘咳。\"\n\n⑦《文山中草药》：\"清热燥湿，消肿止痛。治菌痢，风湿疼痛，皮肤化脓性感染。\"","y":"内服：煎汤，0.5～1两；或浸酒，外用：捣敷。","d":"理化鉴别 （1）取本品粗粉3g，加水50ml，煮沸30min，趁热滤过，滤液蒸干，残潭加乙醇2ml使溶解，滤过，滤液加镁粉少量与盐酸5-6滴，溶液显深红色。（检查黄酮类成分）（2）薄层色谱 取本品粗粉3g，加乙醇15ml，回流15min，趁热滤过，滤液浓缩至约10ml作为供试品溶液。取石吊兰素10mg，加乙醇10ml溶解作为对照品溶液。分别吸取对照品和供试品溶液点于同一硅胶G板上，以氯仿-丙酮（15：1）展开。日光下供试品在与对照品同一位置上显同样色斑。喷三氯化铝后颜色加深；在紫外光下照射10-15min，显紫红色荧光。"},"冬瓜叶":{"a":"?","s":"味苦；性凉","f":"治消渴，疟疾，泻痢，蜂螫，肿毒。\n\n①《日华子本草》：\"熁肿毒及蜂叮。\"\n\n②《纲目》：\"主消渴，疟疾寒热；又焙研敷多年恶疮。\"\n\n③《随息居饮食谱》：\"清暑。治疟、痢、泄泻，止渴。\"","y":"内服：煎汤.外用：研末调敷。","d":"?"},"小木通":{"a":"毛蕊铁线莲(《湖南药物志》)。","s":"淡，平，无毒。","f":"舒筋活血，去湿止痛，解毒利尿。","y":"内服：煎汤，0.5～1两。外用：煎水洗或捣烂塞鼻孔。","d":"?"},"猫人参":{"a":"猫气藤、痈草、沙梨藤(《浙江民间常用草药》)。","s":"苦、涩，凉。","f":"清热解毒。","y":"鲜根1～2两。本品亦用于试治癌症。","d":"理化鉴别 取本品粉末5g，置带塞锥形瓶中，加水50ml，置水浴（70-80℃）温浸2h（前1h内时时振摇），滤过。取滤液1ml，加碘化铋钾试液1-2滴，立即显橙黄色沉淀。改用碘-碘化钾试液，显棕红色沉淀。"},"扁豆":{"a":"藊豆(《唐本草》)，南扁豆(《滇南本草》)，沿篱豆、蛾眉豆(《纲目》)，凉衍豆(《本草乘雅半偈》)，羊眼豆(《药品化义》)，膨皮豆(《广州植物志》)，茶豆(《江苏植药志》)，南豆(《陆川本草》)，小刀豆、树豆(《四川中药志》)，藤豆(《中国药植图鉴》)。","s":"甘，平。\n\n①《别录》：\"味甘，微温。\"\n\n②《食疗本草》：\"微寒。\"\n\n③《日华子本草》：\"平，无毒。\"","f":"健脾和中，消暑化湿。治暑湿吐泻，脾虚呕逆，食少久泄，水停消渴，赤白带下，小儿疳积。\n\n①《别录》：\"主和中下气。\"\n\n②《药性论》：\"主解一切草木毒，生嚼及煎汤服。\"\n\n③孟诜：\"疗霍乱吐利不止，末，和醋服之。\"\n\n④《日华子本草》：\"补五脏。\"\n\n⑤《本草图经》：\"主行风气，女子带下，兼杀酒毒，亦解河豚毒。\"\n\n⑥《滇南本草》：\"治脾胃虚弱，反胃冷吐，久泻不止，食积痞块，小儿疳疾。\"\n\n⑦《品汇精要》：\"消暑和中。\"\n\n⑧《纲目》：\"止泄泻，消暑，暖脾胃，除湿热，止消渴。\"\n\n⑨《会约医镜》：\"生用清暑养胃，炒用健脾止泻。\"","y":"内服：煎汤，3～6钱；或入丸、散。","d":"干燥种子为扁椭圆形或扁卵圆形，长约8～12毫米，宽6～9毫米，厚4～7毫米。表面黄白色，平滑而光泽，一侧边缘有半月形白色隆起的种阜，约占周径的1/3～1/2，剥去后可见凹陷的种脐，紧接种阜的一端有1珠孔，另端有短的种脊。质坚硬，种皮薄而脆，内有子叶2枚，肥厚，黄白色，角质。嚼之有豆腥气。以饱满、色白者佳。\n全国大部分地区有产，主产于湖南、安徽、河南等地。\n\n扁豆的种子有白色、黑色、红褐色等数种，入药主要用白扁豆；黑色看古名\"鹊豆\"，不供药用；红褐色者在广西民间称\"红雪豆\"，用作清肝、消炎药，治眼生翳膜。"},"香叶":{"a":"香艾","s":"味辛；性温 \n\n《广西中药志》：\"味辛，气香，性温散。\"\n\n归肺；肝经","f":"主治 风湿痹痛；疝气；阴囊湿疹；疥癣 \n\n①《广西中药志》：\"治风湿，疝气。\"\n\n②《广西植物名录》：\"治阴囊湿疹，疥癣。\"","y":"内服：煎汤，3～5钱(鲜者1～1.5两)。外用：煎水洗或捣敷。","d":"?"},"野马追":{"a":"尖佩兰,佩兰,白头婆。","s":"苦，平。","f":"清热解毒，祛痰，定喘，降血压。治慢性气管炎，支气管炎，高血压病。","y":"内服：煎汤，1～2两。","d":"干燥全草，茎呈圆柱形，有纵棱，密被灰白色毛茸；下部褐色，上部略带紫褐色；质硬，易折断，断面纤维状，白色。叶对生，无柄，3全裂似轮生；湿润展平后，中间裂片较长，呈线状披针形，边缘疏锯齿，上面绿褐色，下面黄绿色，于放大镜下可见腺点，两面被毛。枝端常残留头状花序或果实。以身干、叶多、色绿、无杂质者为佳。"},"李根皮":{"a":"甘李根白皮(《金匮要略》)。","s":"苦咸，寒。\n\n①《别录》：\"大寒。\"\n\n②《药性论》：\"味咸。\"\n\n③《日华于本草》：\"凉，无毒。\"\n\n④《滇南本草》：\"性寒，味苦涩。\"","f":"清热，下气。治消渴心烦，奔豚气逆，带下，齿痛。\n\n①《吴普本草》：\"治疮。\"\n\n②《别录》：\"主消渴，止心烦、逆奔气。\"\n\n③陶弘景：\"水煎含之，疗齿痛。\"\n\n④《药性论》：\"治脚下气，主热毒，烦躁。\"\n\n⑤孟诜：\"主女人卒赤白下。\"\n\n⑥《长沙药解》：\"下肝气之奔冲，清风木之郁热。\"","y":"内服：煎汤，2～3钱。外用：煎水含漱或磨汁涂。","d":"?"},"木姜花":{"a":"鱼香菜。","s":"辛，凉。","f":"清热，解毒，解表。治感冒，疗疮，鼻渊，喉蛾。","y":"?","d":"?"},"朱砂根":{"a":"凤凰肠、老鼠尾(《生草药性备要》)，平地木、石青子、凉伞遮金珠、山豆根、地杨梅(《植物名实图考》)，散血丹、浪伞根、金鸡爪(《岭南采药录》)，高脚罗伞(《陆川本草》)，小罗伞(《南宁市药物志》)，土丹皮(《广西中药志》)，金锁匙、开喉箭、三条根、三两金、高茶风、铁凉伞、雪里开花(《湖南药物志》)，金鸡凉伞(《杭州药植志》)，大罗伞、大凉伞、凤凰翔(广州部队《常用中草药手册》)，红铜盘、高脚铜盘、青红草、硬脚金鸡、珍珠伞、桂笃油(《浙江民间常用草药》)，真珠凉伞(《福建中草药》)。","s":"苦辛，凉。\n\n①《纲目》：\"苦，凉，无毒。\"\n\n②《生草药性备要》：\"味甘，性平。\"\n\n③《陆川本草》：\"辛苦，性寒。\"","f":"清热解毒，散瘀止痛。治上感，扁桃体炎，急性咽峡炎，白喉，丹毒，淋巴结炎，劳伤吐血，心胃气痛，风湿骨痛，跌打损伤。\n\n①《纲目》：\"治咽喉肿痹，磨水或醋咽之。\"\n\n②《生草药性备要))：\"治痰火，跌打，去瘀生新，宽筋续骨。\"\n\n③《岭南采药录》：\"治小儿干(疳)痞。\"\n\n④《广西中药志》：\"治风湿骨痛，鹤膝风。\"\n\n⑤《湖南药物志》：\"治劳伤吐血，血崩，心胃气痛，腹胀腹痛。\"\n\n⑥《浙江民间常用草药》：\"清热解毒。\"","y":"内服：煎汤，3～5钱；或研末为丸、浸酒。外用：捣敷。","d":"干燥根，多分枝，呈细圆柱状，略弯曲，长短不一，径4～10毫米。表面暗紫色或暗棕色，有纵向皱纹及须根痕。质坚硬，断面木部与皮部易分离，皮部发达，约占断面1／2，淡紫色，木部淡黄色。\n产福建、湖南、广西。\n\n湖南地区尚以同属植物两色紫金牛与本品同等使用。当地称为\"红浪伞\"、\"紫背朱砂根\"。"},"合欢":{"a":"合昏皮、夜合皮、合欢木皮。","s":"?","f":"?","y":"?","d":"?"},"龙眼核":{"a":"圆眼核、桂圆核仁。","s":"苦；涩；平；\r\n\n\n\n\n《泉州本草》：\"味涩。\"","f":"止血，定痛，理气，化湿。治创伤出血，疝气，瘰疬，疥癣，湿疮。\n\n①《滇南本草图说》：\"治瘿疾。\"\n\n②《医学入门》：\"烧烟熏鼻，治流涕不止。\"\n\n③《纲目》：\"治狐臭，龙眼核六枚同胡椒二七枚研，遇汗出即擦之。\"\n\n④《本草再新》：\"治瘰疬，消肿排脓拔毒。并治目痰。\"\n\n⑤《岭南采药录》：\"疗疝气，敷疮癣，又止金疮出血。\"","y":"外用：煅存性研末调敷或干撒。内服：煎汤，1～3钱；或研末。","d":"?"},"羌活鱼":{"a":"秉氏鲵、杉木鱼(《四川中药志》)。","s":"辛咸，平，无毒。","f":"行气止痛。治肝胃气痛及血虚脾弱，面色萎黄。","y":"内服：煎汤，3～5两；或研末。","d":"干燥的羌活鱼，全身皮肉皱缩，呈干枯状，长12～15厘米。头部口眼模糊不清，四肢枯瘦，趾尚明显可辨。尾部侧扁，背部棕褐色或枯棕色，腹部显黄棕色。气腥臭。以条大、肥实、身干、无霉蛀者为佳。\n产四川。"},"钟乳石":{"a":"石钟乳(《本经》)，虚中、钟乳(《吴普本草》)，公乳、留公乳，芦石、夏石(《别录》)，黄石砂(《药性论》)，卢布、夏乳根(《石药尔雅》)。","s":"甘，温。\n\n①《本经》：\"味甘，温。\"\"孔公孽、殷孽，味辛，温。\"\n\n②《吴普本草》：\"神农：辛。扁鹘：甘，无毒。\"\"孔公孽，岐伯：咸；扁鹊：酸，无毒。\"\n\n③《别录》：\"殷孽，无毒。\"\n\n④《药性论》：\"有大毒。\"\"孔公孽，昧甘，有小毒。\"","f":"温肺气，壮元阳，下乳汁。治虚劳喘咳，寒嗽，阳痿，腰脚冷痹，乳汁不通。\n\n①《本经》：\"主咳逆上气，明目益精，安五藏，通百节，利九窍，下乳汁。\"\"孔公孽，主伤食不化，邪结气，恶疮疽瘘痔，利九窍，下乳汁。\"\"殷孽，主烂伤瘀血，泄痢，寒热，鼠瘘，癥瘕结气。\"\n\n②《别录》：\"益气，补虚损，疗脚弱疼冷，下焦伤渴，强阴。\"\"孔公孽，主男子阴疮，女子阴蚀，及伤食病常欲眠睡。\"\"殷孽，主脚冷疼弱。\"\n\n③《药性论》：\"主泄精，寒嗽，壮元气，能通声。\"\"孔公孽，治腰冷膝痹毒风，能使喉声圆朗。\"\n\n④《日华子本草》：\"补五劳七伤。\"孔公孽，治瘫结。\"\"殷孽，治筋骨弱，并痔漏等疾及下乳汁。\"\n\n⑤《医林纂要》：\"补命门，破痼冷，温脾胃，生气血。\"\n\n⑥《本草求原》：\"暖肺纳气，治肺寒气逆，喘咳痰清。\"","y":"内服：煎汤，3～5钱；或入丸、散。","d":"①钟乳石\n呈圆柱形或圆锥形，大小不一，长5～15厘米，直径2～7厘米。表面白色、灰白色或灰褐色，粗糙凹凸不平。质坚而重，断面较平整，洁白色或棕黄色，中央多可见一圆孔，圆孔周围呈多数圈层。气无，味微咸。滴加稀盐酸则产生大量气泡。\n\n②滴乳石\n呈笔管状或圆柱状，中空，稍弯曲，长3～5厘米：直径1～1.5厘米，管壁厚约1毫米。表面乳白色或灰黄色，多半透明，粗糙或稍光滑。质硬而脆，易折断，断面具玻璃光泽，空洞较大，有的可见环形层次。气无，味微咸。\n以上两种均以色白、有光泽者为佳。\n产广西、广东、湖北、四川、贵州、云南、陕西、甘肃、山西等地。\n\n钟乳石由于形状不同，在《本草》中有着各种不同的名称。当碳酸钙液从洞顶下滴，逐渐凝结下垂而成冰檐状物，其附于石上的粗大根盘，称为\"股孽\"；其下较细部分或有中空者，为\"孔公孽\"；再下延成呈较细的圆柱状或管状者为钟乳。名称虽异，实属一物。今并作一条。但习惯上均用钟乳部分。\n\n滴乳石，《本草》称为鹅管石，但目前所用鹅管石药材，除部分地区用滴乳石外，多数地区使用栎珊瑚的石灰质骨胳，参见\"鹅管石\"条。"},"南瓜叶":{"a":"?","s":"味甘；微苦；性凉","f":"治痢疾，疳积，创伤。","y":"内服:煎汤，2～3两；或入散剂。外用:研末掺。","d":"?"},"青风藤":{"a":"清风藤,青藤,寻风藤","s":"苦，平。\n\n①《本草便读》：\"苦，平。\"\n\n②《浙江天目山药植志》：\"苦辛，寒。\"\n\n归肝、脾经。","f":"祛风湿，利小便。治风湿痹痛，鹤膝风，水肿，脚气。\n\n①《本草图经》：\"治风。\"\n\n②《纲目》：\"治风湿流注，历节鹤膝，麻痹瘙痒，损伤疮肿，入酒药中用。\"\n\n③《浙江天目山药植志》：\"行水利尿，泻下焦血分湿热。治风水肿，脚气，风湿关节疼痛，口眼歪斜，痈肿恶疮。\"\n\n④《中国药植志》：\"除湿，祛风，行气，利水。治膀胱水肿，风肿，脚气湿肿。\"\n\n⑤《温岭县药物资源名录》：\"驱风湿，通经络。治风寒湿痹，鹤膝风，肢节肿痛。\"","y":"内服，煎汤，3～5钱；浸酒或熬膏。外用：煎水洗。","d":"①青藤的干燥藤茎呈细长圆柱形，直径5～20毫米，外表灰褐色或棕褐色，有纵皱及横向皮孔，节处膨大。体轻，质坚实而脆，易折断，断面灰黄色或淡灰棕色，不平坦，横切面韧皮部很窄，木质部导管与射线呈放射状排列，导管较大，中央为圆形的髓。气弱，味苦。\n产江苏、浙江、湖北等地。\n\n②华防己的干燥藤茎呈圆柱形，长10～30厘米。表面灰棕色，有不规则的沟纹、裂隙和疤痕。质极坚硬，不易折断。切断面导管明显，维管束呈放射状，且显清晰的多层环纹，一般2～7圈，偏心性。气微弱，味微苦。\n产湖南。\n\n③清风藤的干燥老藤呈圆柱形，灰黑色，光滑，外表有纵皱纹及叶柄残基。横断面皮部较薄，灰黑色，木质部黄白色，射线不明显。味微苦。\n产浙江。\n\n青风藤的原植物，《本草》记载简略，殊难确定为何种，据目前药用情况，主要为上述防己科的青藤。此外，四川所用者为防己科植物木防己的茎(参见\"青檀香\"条)；福建所用者为茜草科植物鸡矢藤的茎(参见\"鸡矢藤\"条)；浙江尚有用五加科植物常春藤的茎(参见\"常春藤\"条)。"},"石花":{"a":"石苔花(《草木便方》)，乳花(《北方常用中草药手册》)，地衣(《吉林中草药》)，道立克(蒙名)。","s":"甘，寒。\n\n①《山西中药志》：\"微甘，无毒。\"\n\n②《重庆草药》：\"味苦，性寒，无毒。\"","f":"养血，明目，补肾，利尿，清热，解毒。治视物模糊，吐血，血崩，腰膝疼痛，小便热痛，白浊，白带，汤火伤。\n\n①《草木便方》\"明目，益精，化痰，解热毒，生津止渴。润咽喉，涂冻疮、汤火伤。\"\n\n②《山西中药志》：\"清膈热，利小便，化痰消瘿，补血明目，益神增髓。\"\n\n③《重庆草药》：\"治刀伤。\"\n\n④《山东中草药手册》：\"补肾，壮筋骨。\"\n\n⑤《北方常用中草药手册》：\"养血明目，益精，壮筋骨，化积聚。治视物模糊，腰腿痛，腹中包块，肝炎。\"\n\n⑥《吉林中草药》：\"补中益气，祛湿利尿，清热化痰。治膀胱湿热，黄疸，金疮，腰腿风冷，血崩。\"","y":"内服：煎汤，2～3钱，研末或浸酒。外用：研末调敷。","d":"?"},"枸橼":{"a":"?","s":"?","f":"?","y":"?","d":"?"},"鸡娃草":{"a":"蓝雪草、小蓝雪草，刺矶松。","s":"《青海常用中草药手册》：\"苦，寒。\"","f":"治神经性皮炎，牛皮癣，头癣，手癣，足癣，疣痣。\n\n①《高原中草药治疗手册》：\"除疣痣，蚀恶肉。\"\n\n②《陕甘宁青中草药选》：\"杀虫止痒。治神经性皮炎，牛皮癣。\"","y":"外用：捣敷或酒浸；或研末制成油膏涂敷。","d":"?"},"鹿肾":{"a":"鹿茎筋(《千金·食治》)，鹿鞭、鹿阴茎(《医林纂要》)，鹿冲(《四川中药材生产技术》)，鹿冲肾(《四川中药志》)。","s":"甘咸，温。\n\n①《别录》：\"平。\"\n\n②《纲目》：\"甘，平，无毒。\"\n\n③《医林纂要》：\"甘咸，热。\"\n\n④《四川中药志》：\"性温，味咸辛，无毒。\"","f":"补肾，壮阳，益精。治劳损，腰膝酸痛，肾虚耳聋，耳鸣，阳痿，宫冷不孕。\n\n①《别录》：\"主补肾气。\"\n\n②《千金·食治》：\"主劳损。\"\n\n③《日华子本草》：\"补中，安五藏，壮阳气，作酒及煮粥服。\"\n\n④《日用本草》：\"补腰脊。\"\n\n⑤《河北药材》：\"补肾益精，活血催乳。\"\n\n⑥《四川中药志》：\"治阳萎，肾虚耳呜，妇人子宫寒冷，久不受孕，慢性睾丸发炎。\"","y":"内服：煎汤，2～5钱：煮食、熬膏或入丸、散。","d":"呈长条状。马鹿肾长45～60厘米，直径4～5厘米，梅花鹿肾长约15厘米，直径3～4厘米；表面棕色，有纵行的皱沟，顶端有一丛棕色的毛。中部有睾丸二枚，椭圆形，略扁。质坚韧；气微腥。以粗壮、条长。无残肉及油脂者为佳。\n产东北、河北、青海、甘肃、四川、云南等地。"},"鱼香草":{"a":"留兰香(《四川中药志》)，土薄荷(《重庆草药》)，血香菜、狗肉香、圆叶留兰香(《贵州药植目录》)。","s":"《重庆草药》：\"味辛，性凉，无毒。\"","f":"散风热，消肿毒。治伤风感冒，胃气痛，鼻衄，目赤，疔疮热疖。\n\n①《分类草药性》：\"去风，明目，散痰，清气。\"\n\n②《四川中药志》：\"健胃止吐。治胃气痛；外用涂脚生皲裂。\"\n\n③《贵州药植目录》：\"驱风，散热，止血，消肿毒。治乌疔，眼赤，回归热，鼻匿，全身麻木，小儿疮疖，鼻血，伤风感冒。\"","y":"内服：煎汤，1～3钱(鲜品0.5～1两)。外用：煎水熏洗或研末调涂。","d":"?"},"千年健":{"a":"一包针(《中药志》)，千年见(《药材资料汇编》)。","s":"辛，温。\n\n①《本草再新》：\"味苦，性寒，有小毒。\"\n\n②《本草求原》：\"辛，温。\"\n\n③《药材资料汇编》：\"苦，温，无毒。\"","f":"祛风湿，壮筋骨，止痛，消肿。治风湿痹痛，肢节酸痛，筋骨痿软，胃痛，痈疽疮肿。用于风湿痹痛、腰膝冷痛、下肢拘挛麻木。本品能祛风湿，强盘骨。以本品与钻地风、虎骨、牛膝、枸杞子等浸酒服。\n\n①《柑园小识》：\"可入药酒，风气痛老人最宜。\"\n\n②《纲目拾遗》：\"壮筋骨，浸酒；止胃痛，酒磨服。\"\n\n③《本草再新》，\"治痈痿疮疽，杀虫败毒，消肿排脓。\"\n\n④《饮片新参》：\"入血分，祛风湿痹痛，强筋骨，治肢节酸疼。\"\n\n⑤《中药材手册》：\"治风气痛，筋骨痪软，半身不遂。\"","y":"内服：煎汤，1.5～3钱；或浸酒。外用：研末调敷。","d":"干燥根茎呈长圆柱形，弯曲，长短不等，通常长约40厘米，直径6～8毫米，棕红色或棕黄色，表面粗糙，有多数扭曲的深纵沟纹及黄白色的针状突出物，沟纹成层排列，每层长约1.5厘米，末端即成针刺突出。质脆，易折断，折断面不平，树脂样，有很多粗韧的针状纤维群，并散布去除纤维后所留下的针眼状小孔。横切面淡棕色至棕红色，纤维群成黄色点状散列。气芳香，久闻有不悦感，味微辛辣。以棕红色、条祖、香浓者为佳。\n\n产广西南部。"},"川木通":{"a":"淮木通(《中药志》)，油木通、白木通(《四川中药志》)。","s":"《四川中药志》：\"性寒，味淡苦，无毒。\"","f":"清热利水，活血通乳。治湿热癃闭，水肿，琳病，妇女乳难，月经闭止。\n\n①《植物名实图考》：\"小木通利小便。\"\n\n②《四川中药志》：\"利水，清热，通血脉。治肾脏病水肿，急性肾炎小便不利，湿热癃闭，淋病，妇女径闭及乳闭。\"","y":"内服：煎汤，1～3钱。","d":"①小木通的干燥茎呈细圆柱形，长30～60厘米，直径O.8～2匣米。外皮红棕色或灰黄色，多呈撕裂状，易与木质部剥离，有纵条纹，节部膨大，有叶柄及侧枝脱落的痕迹；木质部淡黄褐色或黄白色。体轻质硬，不易折断，断面呈放射形的裂片状，导管孔排列较致密，髓部明显。气弱，味苦。\n产四川、贵州，湖南等地。\n\n②绣球藤的干燥茎呈圆柱形，长6O～100厘米，直径1．5～3厘米。外皮黄棕色，常有剥落起层的皮片，并有纵条纹；节部稍膨大。体轻，质坚韧，断面有放射状纹理及多数排列整齐的导管孔。气微弱，味微苦。以条粗、色黄白者为佳。\n产四川。\n\n同属植物中称木通入药者甚多，主要的有：①女萎(参见\"女萎\"条)，湖南以之作木通；②单叶铁线莲，四川南川作木通；③山木通，四川、湖南作木通；④毛木通，四川巴县作木通；⑤皮翁铁线蓬，亦称小木通；⑥黄藤通，湖南称木通，四川称毛木通，云南称大木通；⑦小蓑衣藤(参见叫、蓑衣藤\"条)云南亦称木通．"},"救必应":{"a":"白木香(《岭南采药录》)。","s":"苦，寒。\n\n①《岭南采药录》：\"味苦。\"\n\n②《南宁市药物志》：\"苦，寒，无毒。\"","f":"清热解毒，利湿，止痛。治感冒发热，扁桃体炎，咽喉肿痛，急慢性肝炎，急性肠胃炎，胃及十二指肠溃疡，风湿关节痛，跌打损伤，汤火伤。\n\n①《岭南采药录》：\"清热毒。\"\n\n②《南宁市药物志》：\"清凉解毒。治痧症，内热。熬膏可涂热疮。\"\n\n③江西《草药手册》：\"清热利湿，消肿止痛。治感冒发热，扁桃体炎，咽喉肿痛，急性肠胃炎，胃及十二指肠溃疡，跌打损伤，风湿病。\"","y":"内服：煎汤，3～7钱。外用：捣敷或熬膏涂。","d":"理化鉴别 取本品粉末约2g，加乙醇10ml，浸渍30min，时时振摇，滤过。滤液作以下试验：①取上述乙醇滤液2ml，加三氯化铁试液，显绿蓝色。（检查黄酮）②取上述乙醇滤液5ml，置水浴上蒸干，残渣加醋酐数滴，再加硫酸1-2滴，即显紫蓝色或红紫色。（检查三萜）"},"鱼眼草":{"a":"星莠草、星宿草(《滇南本草》整理本)，三仙菜(《云南中医验方》)，地胡椒、鼓丁草(《云南中草药》)。","s":"《滇南本草》：\"味苦，性寒。\"","f":"清热解毒，利湿，祛翳。治疟疾，痢疾，腹泻，肝炎，妇女白带，日翳，口疮，疮疡。\n\n①《滇南本草》：\"治小儿脏腑积热，泻绿水者，捣汁，乳炖服。或捣汁点水酒服，截疟。\"\n\n②《云南中草药》：\"清热解毒。治肝炎，小儿消化不良，夜盲，疮疡。\"\n\n③《贵州药植目录》：\"清热除湿，解毒去翳。治疔疮，眼翳，小儿口疮，妇女白带。\"\n\n④《云南中草药选》：\"清热解毒，止痛，止泻。治感冒高热，腹泻，肝炎。\"","y":"内服：煎汤，2～4钱。外用：捣敷或煎水洗。","d":"?"},"桑耳":{"a":"桑菌、木麦(《别录》)，桑上寄生(《证类本草》)，桑檽(《唐本草》)，桑蛾、桑鸡(《广菌谱》)。","s":"甘，平。\n\n①《别录》：\"味甘，有毒。\"\n\n②《药性论》：\"平。\"\n\n③孟诜：\"寒，无毒。\"","f":"治肠风，痔血，衄血，崩漏，带下，妇人心腹痛。\n\n①《本经》：\"黑者主女子漏下赤白汁，血病，癥瘕积聚，阴痛，阴阳寒热，无子。\"\n\n②《别录》：\"疗月水不调，其黄熟陈白者止久泄，益气不饥。其金色者治癖饮，积聚腹痛，金疮。\"\n\n③《药性论》：\"能治风，破血，益力。\"\n\n④《日华子本草》：\"止肠风泻血，妇人心腹痛。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。","d":"?"},"孩儿草":{"a":"蓝色草(《广州植物志》)，明萼草(《种子植物名称》)，甴曱草、黄蜂草(《广东中药》Ⅱ)，积药草、土夏枯草(广州空军《常用中草药手册》)。","s":"甘苦，凉。\n\n①《广东中药》Ⅱ：\"甘，平，微凉。\"\n\n②广州空军《常用中草药手册》：\"淡微苦，凉。\"","f":"清肝明目，消积止痢。治肝炎，急性结合膜炎，小儿食积，痢疾，颈淋巴结结核。\n\n①《岭南采药录》：\"消小儿食积，清肝火，与白芍功用相同。\"\n\n②《广东中药》Ⅱ：\"明目，止痢。\"\n\n③广州空军《常用中草药手册》：\"平肝清热，消积导滞。治小儿消化不良，食欲不振，肝炎，急性结合膜炎，感冒，喉痛，颈淋巴结结核，疖肿。\"","y":"内服：煎汤，3～5钱。","d":"干燥全草高约30余厘米，茎细稍硬，径约2～3毫米，暗绿褐色或黄白色，有纵皱纹，近基部数节着生细根，节部稍膨大。质脆易折断，断面髓部呈针孔状，木部质轻，白色。叶对生，青绿色或灰绿色，常脱落。穗状花序，花偏于一侧，多数脱落；苞片绿色或黄绿色而有膜质边缘。气微，味淡。"},"菠菜":{"a":"菠薐、波棱菜、红根菜、赤根菜、波斯草、鹦鹉菜、鼠根菜、角菜、甜茶、拉筋菜、敏菜、飞薐菜、飞龙菜","s":"甘，凉。\n\n①《嘉祐本草》：\"冷，微毒。\"\n\n②《日用本草》：\"甘，寒，无毒。\"\n\n③《医林纂要》：\"甘酸，寒。\"\n入胃肠经\n①《得配本草》：入手太阳、阳明经。\n②《本草求真》：入肠、胃。","f":"养血，止血，敛阴，润燥。治衄血，便血，坏血病，消渴引饮，大便涩滞。\n\n①孟诜；\"利五脏，通肠胃热，解酒毒。\"\n\n②《日用本草》：\"解热毒。\"\n\n③《纲目》：\"通血脉，开胸膈，下气调中，止渴润爆。根尤良。\"\n\n④《医林纂要》：\"敛阴，和血。\"\n\n⑤《陆川本草》：\"入血分。生血、活血、止血、去瘀。治衄血，肠出血，坏血症。\"","y":"内服：煮食或研末。","d":"?"},"黄瓜根":{"a":"?","s":"《四川中药志》：\"性凉，味甘苦，无毒。\"","f":"治腹泻，痢疾。\n\n①《日华子本草》：\"捣敷，狐刺毒肿。\"\n\n②《四川中药志》：\"能利水通淋，消胀。治小儿腹泻及日久转痢。\"","y":"内服：煎汤，1～2两。外用：捣敷。","d":"?"},"苘麻子":{"a":"青麻子、野棉花子、白麻子、冬葵子、青麻、葵子、白麻","s":"性平，味苦。","f":"利水，滑肠，下乳。治二便不通，淋病，水肿，妇女乳汁不行，乳房肿痛。\n\n\n　　①《本经》：主五脏六府寒热羸瘦，五癃，利小便。\n\n\n　　②《本草经集注》：葵子汁解蜀椒毒。\n\n\n　　③《别录》：疗妇人乳难内(’内’一作’血’)闭。\n\n\n　　④《药性论》：治五淋，主奶肿，下乳汁。\n\n\n　　⑤《本草衍义》：患痈疖毒热内攻，未出脓者，水吞三、五枚，遂作窍，脓出。\n\n\n　　⑥《纲目》：通大便，消水气，滑胎，治痢。\n\n\n　　⑦《本草通玄》：达诸窍。\n\n\n　　⑧《本草汇》：下胞衣。","y":"3～9g。","d":"本品横切面：表皮细胞1列，扁长方形，有的分化成单细胞非腺毛，下皮细胞1列，略径向延长。栅状细胞1列，长柱形，长约至88μm，壁极厚，上部可见线形胞腔，其末端膨大，内含细小球状结晶。色素层4～5列细胞，含黄棕色或红棕色物。胚乳及子叶细胞含脂肪油和糊粉粒，子叶细胞并含少数细小草酸钙簇晶。\n\n\n　　性状鉴别苘麻果实由7-9个小分果组成，呈扁平圆盘状，底部有宿存花萼。分果呈橘瓣状或肾形，直径1.5-2mm，较薄的一边中央凹下。果皮外表为棕黄色，背面较光滑，两侧面靠凹下处各有一微凹下圆点，由圆点向外有放射性条纹。种子橘瓣状肾形，种皮黑色至棕褐色。质坚硬，破碎后子叶心形，两片重叠折曲。气微、味涩。\n\n\n　　显微鉴别粉末特征：灰褐色。①胚乳细胞较多见，呈多角形或类方形，直径11-35μm，壁略呈念珠状增厚。②种皮栅状细胞表面观细胞界限不清晰，细胞细小，呈星状;侧面观为一列柱状细胞，长33-46μm，直径8-12μm，壁甚厚、木化，胞腔梭形，内含球状结晶。③星状毛易见，由5-7细胞组成，亦有单个散在，呈披针形，基部钝圆，直径5-15μm，长106-245μm，壁厚1-2μm。④色素细胞类多角形，类长方形，胞腔内含红棕色块状物。⑤子叶表皮细胞类长方形，薄壁细胞呈类多角形或椭圆形，含拟晶体。⑤螺纹导管多见，直径27-33μm，网纹导管较少见。"},"冬青子":{"a":"冬青实(《本草图经》)，冻青树子(《濒湖集简方》)。","s":"《纲目》：\"甘苦，凉，无毒。\"","f":"去风。补虚。治风湿痹痛，痔疮。\n\n①《本草图经》：\"浸酒，去风补血。\"\n\n②《本草求真》：\"补肝强筋，补肾健骨。\"\n\n③《江苏药材志》：\"治风湿痹痛。\"","y":"内服：煎汤，1.5～3钱；或浸酒。","d":"?"},"黄荆叶":{"a":"蚊枝叶(《生草药性备要》)，白背叶(《岭南采药录》)，姜荆叶(《湖南药物志》)，埔姜叶(《广东中药》)，姜子叶(《农村常用草药手册》)。","s":"甘苦，平。\n\n①《草木便方》：\"寒。\"\n\n②《岭南采药录》：\"甘苦，平。\"\n\n③《农村常用草药手册》：\"苦，寒。\"","f":"解表清热，利湿解毒。治感冒，中暑，吐泻，痢疾，疟疾，黄疸，风湿，跌打肿痛，疮痈疥癣。\n\n①《救生苦海》：\"治九窍出血，捣汁，酒和，服二合。\"\n\n②《本草求原》：\"洗癣疥恶毒。\"\n\n③《岭南采药录》：\"治小儿五疳。煎汤浴身，散热，消疮肿痛。和米炒淬水饮之，止吐泻。\"\n\n④《广州植物志》：\"治久痢，霍乱转筋，脚气肿满。\"\n\n⑤《贵州民间方药集》：\"治痢疾，血淋；利水，治浮肿，黄疽。\"\n\n⑥《南宁市药物志》：\"捣烂酒炒外敷，治跌打，风湿。\"\n\n⑦《农村常用草药手册》：\"解表发汗，消暑止渴。\"","y":"内服：煎汤，鲜者0.5～2两。外用：捣敷或煎水洗。","d":"干燥叶片皱缩，灰黑色或绿褐色，背面色较暗淡，被短毛；为掌状复叶，小叶5枚，间或3枚，长卵圆形至披针形，先端长尖，基部楔形；叶柄方形被毛。叶脆易碎，有香气。\n主产广东、广西等地。\n\n同属植物灰毛牡荆的叶在西藏地区与本品同等入药。"},"胡桃仁":{"a":"虾蟆(《酉阳杂俎》)，胡桃肉(《海上集验方》)，核桃仁(《纲目》)。","s":"甘，温。\n\n①《七卷食经》:\"味甘，温。\"\n\n②《本草图经》:\"性热。\"\n\n③《医林纂要》:\"甘而微辛，连皮涩。\"\n\n入肾、肺经","f":"补肾固精，温肺定喘，润肠，治肾虚喘嗽，腰痛脚弱，阳痿，遗精，小便频数，石淋，大便燥结。\n\n①孟诜:\"通经脉，润血脉，黑须发，常服骨肉细腻光润。\"\n\n②崔禹锡《食经》:\"下气，主喉痹，杀白虫。\"\n\n③《本草拾遗》:\"食之令人肥健。\"\n\n④《开宝本草》:\"多食利小便，去五痔。\"\n\n⑤《七卷食经》:\"去积气。\"\n\n⑥《纲目》:\"补气养血，润燥化痰，益命门，利三焦，温肺润肠。治虚寒喘嗽，腰脚重痛，心腹疝痛，血痢肠风，散肿毒，发痘疮，制铜毒。\"\n\n⑦《医林纂要》:\"补肾，润命门，固精，润大肠，通热秘，止寒泻虚泻。\"\n\n⑧《本草从新》:\"治痿，强阴。\"","y":"内服:煎汤，3～5钱；或入丸、散。外用:捣敷。","d":"种仁多破碎成不规则的块状，完整者类球形，由二瓣种仁合成，皱缩多沟，凹凸不平。外被棕褐色薄膜状的种皮包围，剥去种皮显黄白色。质脆，子叶富油质。气微弱，子叶味淡，油样，种皮味涩。以色黄、个大、饱满、油多者为佳。\n主产河北、山西、山东。以河北产量最大，山西所产品质佳。"},"鸡骨香":{"a":"山豆根,木沉香,土沉香,驳骨消,滚地龙,黄牛香,过山香","s":"味辛苦，性温\n\n《生草药性备要》：\"味辛苦，性温。\"\n\n入心、肺、肝、胃、肾五经","f":"理气止痛，祛风除湿，舒筋活络。治胃痛，胃肠气胀，风湿痹痛，跌打损伤。\n\n①《生草药性备要》：\"治咽喉肿痛，心气痛。\"\n\n②《本草求原》：\"祛风，壮筋骨，消疬。\"\n\n③广州部队《常用中草药手册》：\"行气止痛，舒筋活络。治跌打扭伤，风湿性关节炎，胃及十二指肠溃疡，胃肠功能紊乱，胃肠胀气。外治毒蛇咬伤。\"","y":"内服：煎汤，2～5钱；或浸酒、研末。外用：研末调敷。","d":"根细长条状，径2～4毫米，表面灰棕色，有纵纹及突起，有时栓皮脱落。质脆易断，断面黄色，不平坦，纤维性。气微弱芳香，味苦涩。"},"珍珠菜":{"a":"扯根菜、矮桃(《植物名实图考》)，狗尾巴草(《南京民间药草》)，山高梁、山地榆、山酸汤秆、黄参草、大红袍、山马尾(《贵州民间方药集》)，通筋草、白花蓼草(《浙江中医杂志》(12):31，1958)，蓼子草(《贵阳民间药草》)，红根草(《浙江中药资源名录》)，野荷子、荷树草、金鸡土下黄、红头绳、水荷子、矮脚荷、赤脚草(《江西草药》)，红丝毛、高脚酸味草、大酸米草、酸罐罐(《陕西中草药》)，狼尾草(《江苏药材志》)。","s":"辛涩，平。\n\n①《江西草药》:\"性平，味辛微涩。\"\n\n④《陕西中草药》:\"酸涩，凉。\"","f":"活血调经，利水消肿。治妇女月经不调，白带，小儿疳积，水肿，痢疾，跌打损伤，喉痛，乳痈。\n\n①《植物名实图考》:\"散血。\"\n\n②《贵州民间方药集》:\"利尿。治水肿，小儿疳积。\"\n\n③《四川武隆药植图志》:\"开胃。\"\n\n④《贵阳民间药草》:\"行血调经，外洗消肿。\"\n\n⑤《浙江中药资源名录》:\"治腰背四肢扭伤。\"\n\n⑥苏医《中草药手册》:\"清热解毒。治蛇咬伤，乳腺炎，白带过多，痈疖，鼻出血。\"","y":"内服:煎汤，0.5～1两，外用:煎水洗或捣敷。","d":"?"},"獐牙菜":{"a":"当药(《内蒙古中草药》)。","s":"苦，寒。","f":"清热，健胃，利湿。治消化不良，胃炎，黄疸，火眼，牙痛，口疮。","y":"内服：煎汤，1～3钱；或研末，每次5分。","d":"?"},"白豆":{"a":"饭豆(《日用本草》)，眉豆、白目豆、甘豆(《广州植物志》)。","s":"甘咸，平。\n\n①《孙寡人食忌》：\"味咸。\"\n\n②《嘉祐本草》：\"平，无毒。\"\n\n③《品汇精要》；\"味甘，性平，无毒。\"","f":"调中益气，健脾益肾。\n\n①《孙真人食忌》：\"肾病宜食。\"\n\n②孟诜：\"补五脏，调中，助十二经脉。\"\n\n③《日华子本草》：\"豆，暖肠胃。叶，利五脏，下气。\"","y":"?","d":"?"},"防风草":{"a":"落马衣、假紫苏、马衣叶(《生草药性备要》)，稀莶草、土防风(《岭南采药录》)，四方茎、臭草(《广西中兽医药植》)，臭苏头、鸭儿蔑(《陆川本草》)，秽草(《南宁市药物志》)，大篾草、大羊古骚(《广西中药志》)，排风草(广州部队《常用中草药手册》)，臭苏(《福建中草药》)。","s":"辛苦，温。\n\n①《生草药性备要》：\"性温。\"\n\n②《陆川本草》：\"苦辛，微温。\"\n\n③《南宁市药物志》：\"辛，温，微苦。\"","f":"祛风，除湿，解毒。治感冒身热，呕吐，腹痛，筋骨疼痛，疮疡，湿疹，痔疾。\n\n①《生草药性备要》：\"止痛，壮筋骨，消风散热，去毒疮，除筋骨疼痛，肾虚人取其头浸酒饮。\"\"祛风湿，壮筋骨，乌须，明目，洗痔疮，洗疳，去肿。\"\n\n②《陆川本草》：\"驱风发表，行气疏滞。治感冒身热，呕吐，腹痛，四肢麻痹，蜂、蝎虫伤。\"\n\n③《南宁市药物志》：\"祛风散热，解毒止痛。治疮疡，关节疼痛。\"","y":"内服：熬汤，3～5钱；浸酒或入丸剂。外用：煎水洗或捣敷。","d":"干燥全草，长1～1.5米。茎草质，四棱形，粗可达5毫米。表面棕色或红棕色，被毛，尤以棱角处为多；质硬，断面纤维性，中央有白色的髓。叶多皱缩，边缘具锯齿，上面灰棕色，下面灰绿色，两面均有毛，质脆，易破碎。有时可见密被毛茸的花序，花多脱落，仅留灰绿色的花萼，往往包有1～4枚小坚果。气微，味淡微苦。以叶多、干燥、无杂质者为佳。\n产广东、广西等地。"},"土贝母":{"a":"大贝母,假贝母。","s":"苦，凉。\n\n①《本草从新》：\"味苦。\"\n\n②《百草镜》：\"味苦，性平微寒，无毒。\"","f":"散结毒，消痈肿。治乳痈，瘰疬痰核，疮疡肿毒及蛇虫毒。\n\n①《本草从新》：\"治外科痰毒。\"\n\n②《百草镜》：\"能散痈毒，化脓行滞，解广疮结毒，除风湿，利痰，敷恶疮敛疮口。\"\n\n③《陕西中草药》：\"清热解毒消肿。治淋巴腺结核，急性乳腺炎初起，痈肿。\"","y":"内服：煎汤，0．3～1两；或入丸、散。外用：研末调敷或熬膏摊贴。","d":"干燥块茎呈不规则块状，多角或三棱形，高0．6～1．6厘米，直径0．7～2厘米。暗棕色至半透明的红棕色，表面凹凸不平，多裂纹，顶端常有一突起的芽状物。质坚硬，不易折断。断面角质，光亮而平滑。微有焦糊气，味微咸而苦。以个大、红棕色、质坚实、有亮光，半透明者为佳。\n\n主产河南、陕西、山西、河北等地。"},"紫梢花":{"a":"紫霄花(《苏州本产药材》)。","s":"《纲目》：\"甘，温，无毒。\"","f":"益阳涩精。治阳痿，遗精，白浊，带下，小便不禁，阴囊湿疹。\n\n①《医学入门》：\"主阳衰阴痿。\"\n\n②《纲目》：\"益阳秘精，疗真元虚惫，阴痿，遗精，余沥，白浊如脂，小便不禁，囊下湿痒，女人阴寒冷带，入丸散及坐汤用。\"","y":"内服：研末，0.5～1.5钱；或入丸、散。外用：煎汤温洗局部。","d":"呈不规则的块状或棒状，大小不一，中央常附有水草或树枝。长约3～10厘米，直径1～2.5厘米。表面灰白色或灰黄色，有多数小孔，呈海绵状。体轻，质松泡，断面呈放射网状，网眼内有灰黄色类圆形小颗粒(芽球)，振摇易脱落。气无，味淡。以个大、身干、轻松、柔软、无杂质者为佳。\n主产江苏、河南等地。"},"芋头":{"a":"蹲鸱(《史记》)，芋魁(《汉书》)，芋根(《汉书》颜师古注)，土芝(《别录》)，芋奶(《种芋法》)，芋艿(《中国医学大辞典》)。","s":"甘辛，平。\n\n①《别录》：\"辛，平，有毒。\"\n\n②陶弘景：\"生则有毒，性滑。\"\n\n③《日华子本草》：\"冷。\"\n\n④《滇南本草》：\"味甘麻。\"","f":"消疬散结，治瘰疬，肿毒，腹中癖决，牛皮癣，汤火伤。\n\n①《别录》：\"主宽肠胃，充肌肤，滑中。\"\n\n②《唐本草》：\"蒸煮冷啖，疗热止渴。\"\n\n③孟诜：\"浴去身上浮风，慎风半日。\"\n\n④《本草拾遗》：\"吞之开胃，通肠闭，产后煮食之破血，饮其汁，止血、渴。\"\n\n⑤《日华子本草》：\"破宿血，去死肌。和鱼煮，甚下气，调中补虚。\"\n\n⑥《滇南本草》：\"治中气不足，久服补肝肾，添精益髓。\"\n\n⑦《医林纂要》：\"行水。\"\n\n⑧《本草求原》：\"止泻。\"\n\n⑨《随息居饮食谱》：\"生嚼治绞肠痧，捣涂痈疡初起，丸服散瘰疬。\"\n\n⑩《岭南采药录》：\"以此煮粥，研末和粥食之，能治小儿连珠疬及虚疬，大人亦合，并可免一切疥疮。\"\n\n⑾《中国药植图鉴》：\"调以胡麻油，敷治火伤，开水烫伤；用芋片不断摩擦疣部，可除去。\"","y":"内服：煎汤，2～4两：或入丸、散。外用：捣敷或煎水洗。","d":"?"},"海浮石":{"a":"水花,海石,水泡石,浮海石,浮水石,羊肚石","s":"咸，寒。\n\n①《本草拾遗》：\"平，无毒。\"\n\n②朱震亨：\"咸。\"\n\n③《纲目》：\"大寒。\"","f":"清肺火，化老痰，软坚，通淋。治痰热喘嗽，老痰积块，瘿瘤，瘰疬，淋病，疝气，疮肿，目翳。\n\n①陶弘景：\"止咳。\"\n\n②《本草拾遗》：\"主渴。\"\n\n③《日华子本草》：\"止渴，治淋，杀野兽毒。\"\n\n④《本草衍义》：\"水飞，治目中翳。\"\n\n⑤朱震亨：\"清金降火，消积块，化老痰。\"\n\n⑥《纲目》：\"消瘿瘤结核疝气，下气，消疮肿。\"\n\n⑦《本草正》：\"消食，消热痰，解热渴热淋，止痰嗽喘急，软坚癥，利水湿。\"","y":"内服：煎汤，3～5钱；或入丸、散。外用：研末撒或水飞点眼。","d":"①浮石\n为不规则的块状，大小不一，通常直径2～7厘米，有的可达20厘米。表面粗糙，有多数大小不等的细孔，灰白色或灰黄色。质硬而松脆，易砸碎，断面租糙有小孔，有的具绢丝样光泽或无。体轻，投入水中，浮而不沉。气微弱，味淡。以体轻、灰白色、浮水者为佳。\n产广东、福建、山东、辽宁等地。\n\n②石花(《本草衍义》)\n为脊突苔虫或瘤苔虫的骨胳，㈠脊突苔虫骨胳呈珊瑚样不规则块状，略作扁圆形或长圆形。大小不一，直径2～5厘米。灰白色或灰黄色。基部略平坦，另一面多突起，作叉状分枝，中部交织如网状。叉状小枝长3～5毫米，直径约2毫米，先端多折断，少数完整者呈钝圆形。质硬而脆，表面与断面均密具细孔。体轻，入水不沉。气微腥，味微咸。㈡瘤苔虫的骨胳为不规则块状，直径1～3厘米，多为碎块。表面灰黄色或灰黑色。珊瑚状分枝短而较粗，直径约4毫米。先端钝圆，极少折断。气味同上。\n产浙江、福建、广东。"},"莙荙菜":{"a":"菾菜(《别录》)，甜菜(《日华子本草》)，牛皮菜(《滇南本草》)，石菜(《本草求原》)，杓菜、猪牳菜(《广州植物志》)，光菜(《中国蔬菜栽培学》)。","s":"甘，凉。\n\n①《别录》：\"甘苦，大寒。\"\n\n②《日华子本草》：\"冷，无毒。\"\n\n③《嘉祐本草》：\"平，微毒。\"\n\n④《救荒本草》：\"味咸，性平寒，微毒。\"","f":"清热解毒，行瘀止血。治麻疹透发不快，热毒下痢，闭经淋浊，痈肿伤折。\n\n①《别录》：\"疗时行壮热，解风热毒。\"\n\n②《唐本草》：\"夏月以其菜研作粥，解热，又止热毒痢。捣敷灸疮，止痛。\"\n\n③《本草拾遗》：\"捣绞汁服之，主冷热痢。又止血生肌，人有伤折，敷之。\"\n\n④《日华子本草》：\"炙作热水饮，开胃，通心膈。\"\n\n⑤《嘉祐本草》：\"补中下气，理脾气，去头风，利五脏。\"\n\n⑥《随息居饮食谱》：\"清火祛风，杀虫解毒，涤垢浊，稀痘疮，止带调经，通淋治痢，妇人小儿尤宜食之。\"\n\n⑦《民间常用草药汇编》：\"清热，行血。治肛门肿痛。\"\n\n⑧《四川中药志》：\"治麻疹初起，见点未透和颜色不红，并治妇女经闭停瘀，血肿和肛门肿痛。\"","y":"内服：煎汤，0.5～1两(鲜者2～4两)；或捣汁。外用：捣敷。","d":"?"},"星星草":{"a":"小花碱茅","s":"全草：甘、淡，凉。\n花序：淡，平。","f":"治脓疱疮(黄水疮)：星星草花朵，炒黑存性，研细，用香油调成糊状，涂患处。每日一次，连涂3～5次，皮肤即发干，逐步恢复正常。","y":"全草3～5钱；花序外用适量。","d":"?"},"牛马藤":{"a":"过山龙(《草木便方》)，油麻血藤(《中草药资料》)。","s":"①《四川中药志》：\"甘，温，无毒。\"\n\n②《中药鉴别手册》：\"性温，味苦。\"","f":"行血补血，通经活络。治风湿疼痛，四肢麻木，贫血，月经不调。\n\n①《草木便方》：\"活血化瘀，舒筋，利关节。治腰脊痛。\"\n\n②《分类草药性》：\"治寒脾风，风湿麻木，筋骨疼痛，消肿。\"\n\n③江西《草药手册》：\"治妇女经闭，膝盖骨痛。\"","y":"内服：煎汤，0.4～1两；或浸酒。","d":"?"},"薯良":{"a":"赭魁(《别录》)，朱砂莲、鸡血莲、血母(《贵州民间方药集》)，血三七、雄黄七、血葫芦、朱砂七、红药子、恶边(《湖南药物志》)，酱头、避血雷(《贵州草药》)，金花果(《云南中草药》)，红孩儿、孩儿血(江西《草药手册》)，血娃(《曲靖医药》)。","s":"甘酸，平。\n\n①《别录》：\"味甘，平，无毒。\"\n\n②《唐本草》：\"有小毒。\"\n\n③《贵州民间药物》：\"性平，味涩微酸。\"\n\n④《云南中草药》：\"涩，苦，寒。\"","f":"活血，止血，理气，止痛。治产后腹痛，月经不调，崩漏，内伤吐血，风湿关节痛，痢疾，疮疖，蛇咬伤，外伤出血。\n\n\n①《别录》：\"主心腹积聚，除三虫。\"\n\n②《药性考》：\"浸酒服，能活血。\"\n\n③《馈州民间方药集》：\"止痢疾。治产后腹痛，臌胀。又治哮喘。\"\n\n④《湖南药物志》：\"活血，补血，止痛，散气。治筋骨痛，关节炎腰痛，内伤吐血。\"","y":"内服：煎汤，1～3钱；研末或磨汁。外用：研末敷或磨汁涂。","d":"干燥的块茎，长圆形或卵圆形，表面赤褐色，有明显的纵皱和环形凹陷，形成结节状和起伏不平的突起。在凹陷缩小部分有1圈须根痕。质坚硬，断面红棕色，粉性，有规则的网状花纹。在放大镜下观察有折光率强的白色结晶物。\n产贵州、湖南、云南等地。"},"荠菜":{"a":"荠、靡草、护生草、羊菜、鸡心菜、净肠草、上e菜、菱角菜、清明菜、香田芥、枕头草、地米","s":"甘，平。\n\n①《别录》:\"味甘，温，无毒。\"\n\n②《千金·食治》:\"味甘涩，温，无毒。\"\n\n⑧《日用本草》:\"味辛甘，凉平。\"","f":"凉肝止血；平肝明目；清热利湿。治\n①《别录》:\"主利肝气，和中。\"\n\n②《药性论》:\"烧灰(服)，能治赤白痢。\"\n\n③《千金·食治》:\"杀诸毒。根，主目涩痛。\"\n\n④崔禹锡《食经》:\"补心脾。\"\n\n⑤《日用本草》:\"凉肝明目。\"\n\n⑥《纲目》:\"明目，益胃。\"\n\n⑦《现代实用中药》:\"止血。治肺出血，子宫出血，流产出血，月经过多，头痛、目痛或视网膜出血。\"\n\n⑧《陆川本草》:\"消肿解毒，治疮疖，赤眼。\"\n\n⑨《南宁市药物志》:\"治乳糜屎。\"\n\n⑩《广西中药志》:\"健胃消食，化积滞。\"","y":"内服:煎汤，3～5钱(鲜者1～2两)；或入丸、散。外用:研末调敷、捣敷或捣汁点眼。","d":"干燥的全草，根作须状分枝，弯曲或部分折断，淡褐色或乳白色；根出叶羽状分裂，卷缩，质脆易碎，灰绿色或枯黄色；茎纤细，分枝，黄绿色，弯曲或部分折断，近顶端疏生三角形的果实，有细柄，淡黄绿色。气微，味淡。以干燥、茎近绿色、无杂草者为佳。\n全国大部地区均产。"},"九里香":{"a":"千里香,万里香,七里香。","s":"①《生草药性备要》：\"味辛，性温。\"\n\n②《福建中草药》：\"辛、苦，温。\"","f":"行气，活血，祛风，除湿，并有麻醉镇痛作用。治脘腹气痛，胃痛，风湿痹痛，肿毒，疥疮，皮肤瘙痒，跌打肿痛，牙痛，虫蛇咬伤。\n\n①《生草药性备要》：\"止痛，消肿毒，通窍，能止疮痒，去皮风，杀螆疥。\"\n\n②《岭南采药录》：\"患百子痰打，用叶一撮，捣烂煮粥，和糖服之。\"\n\n③《广西中药志》：\"行气止痛，活血散瘀。治跌打肿痛，风湿，气痛。\"","y":"内服：煎汤，3～6钱；或浸酒服。外用：捣敷。","d":"干燥茎细圆形，一般截成长3～6厘米的段，直径最大不超过7毫米；外表灰黄色，有细纵纹，栓皮剥落，露出肉色木质部；横切面中心颜色较淡，质坚硬。干燥叶带革质，卵形或椭圆形，长约2～7厘米，宽约1～3厘米，呈黄绿色，基部楔形，全缘，主脉在背面明显突出。叶柄极短。气香。\n\n产广东、广西、福建等地。"},"千针万线草":{"a":"麦参、筋骨草(《云南中草药》)，大鹅肠菜(《云南中草药选》)。","s":"甘，平。\n\n①《滇南本草》：\"性微温，味甘。\"\n\n②《滇南本草图说》：\"甘，平。无毒。\"","f":"健牌，养肝，益肾。治体虚贫血，精神短少，头晕心慌，耳鸣眼花，潮热，遗精，腰痛脚弱，月经不调，带下淋沥，小儿疳积。\n\n①《滇南本草》：\"补肝、脾、肾。治阴血虚弱，精神短少，头昏心慌，耳鸣眼花及五心烦热，小肚胀坠，腰痛脚酸，妇人白带、漏下淋沥。\"\n\n②《滇南本草图说，：\"止咳血。\"\n\n③《云南中草药》：\"治月经不调，贫血，小儿疳积，肾虚遗精，阴虚潮热。\"\n\n④《云南中草药选》：\"治骨折，外伤，肾炎。\"","y":"内服：煎汤，0.5～1两；或炖肉服。外用：捣敷。","d":"?"},"果上叶":{"a":"小果上叶、石串莲(《昆明民间常用草药》)。","s":"甘淡，凉。\n\n①《昆明民间常用草药》：\"味微酸涩，性平。\"\n\n②《云南中草药选》：\"甘淡，凉。\"","f":"润肺化痰，行气止痛。治肺结核，咯血，慢性气管炎，慢性咽炎，疝气疼痛，月经不调，骨折。\n\n①《昆明民间常用草药》：\"祛风湿，活络，行气，止痛。\"\n\n②《云南中草药选》：\"接骨消炎，润肺化痰。治骨折，肺结核，咯血，慢性气管炎，肺炎恢复期，慢性咽炎，月经不调。\"\n\n③《贵州药植目录》：\"清热润燥，生津止渴。\"","y":"内服：煎汤，0.3～1两。外用：研末调敷。","d":"?"},"大血藤":{"a":"血藤(《本草图经》)，红皮藤(《任城日记》)，千年健(《简易草药》)，大活血(《植物名实图考》)，五花血藤(《贵州民间方药集》)，红藤、赤沙藤(《浙江中药手册》)，蕨心藤(《广西中兽医药植》)，活血藤、血通、血木通(《中药志》)，穿尖龙、半血莲、过血藤、血灌肠、花血藤(《湖南药物志》)，黄梗藤、八卦薛、黄鸡藤、血陈根、红牛鼻陈(《闽东本草》)，山红藤(广州部队《常用中草药手册》)，五花七、五花血通、大血通(《陕西中草药》)，红血藤、黄省藤、鱼藤、红菊花心(《浙江民间常用草药》)。","s":"苦，平。\n\n①《浙江民间草药》：\"性平，味酸涩。\"\n\n②《四川中药志》：\"性凉，味苦，无毒。\"","f":"败毒消痈，活血通络，祛风杀虫。治急、慢性阑尾炎，风湿痹痛，赤痢，血淋，月经不调，疳积，虫痛，跌扑损伤。清热解毒，活血，祛风。用于肠痈腹痛、经闭痛经、风湿痹痛、跌打扑痛。\n\n①《本草图经》：\"攻血，治血块。\"\n\n②《简易草药》：\"治筋骨疼痛，追风，健腰膝，壮阳事。\"\n\n③《中药志》：\"祛风通经络，利尿杀虫。治肠痈，风湿痹痛，麻风，淋病：蛔虫腹痛。\"\n\n④《湖南药物志》：\"通经补血，强筋壮骨，驱虫。治跌打损伤，风湿疼痛，血晕，血淋，筋骨疼痛，疮疖，血丝虫病。\"\n\n⑤《闽东本草》\"治心腹绞痛，赤白痢疾。\"\n\n⑥广州部队《常用中草药手册》：\"治肢节酸痛，麻木拘挛，水肿，血虚头昏。\"\n\n⑦《陕西中草药》：\"抗菌消炎，消肿散结，理气活血，祛风杀虫。治阑尾炎，月经不调，崩漏，小儿疳积，蛔虫、蛲虫症。\"","y":"内服：煎汤，3～5钱；研末或浸酒。外用：捣敷。","d":"干燥茎呈圆柱形，略弯曲，通常截成长约30厘米的段状，直径1～3厘米。外表棕色或灰棕色，粗糙，具有浅的纵槽纹及明显的横裂纹，有时可见膨大的节部及略凹陷的枝痕或叶柄痕，栓皮常呈鳞片状开裂，脱落处露出淡红棕色的内皮部。质坚韧，有弹性，折断面裂片状；平整的横切面，本质部黄白色，导管呈细孔状，髓射线棕红色，放射状排列。气异香，味淡微涩。以条匀、径粗者佳。\n\n产湖北、四川、江西，河南、江苏、浙江、安徽等地。\n\n本品在华北、东北、中南地区作鸡血藤使用。"},"透骨草":{"a":"珍珠透骨草、竹格叉、吉盖草、枸皮草","s":"辛；性温 \n\n①《本草原始》：\"味甘，无毒。\"\n\n②《中药志》：\"辛，温。\"\n\n归肺；肝经","f":"祛风，除湿，舒筋，活血，止痛。治风湿痹痛，筋骨挛缩，寒湿脚气，疮癣肿毒。\n\n①《纲目》：\"治筋骨一切风湿疼痛挛缩，寒湿脚气。\"\n\n②《灵秘丹药笺》：\"疗热毒。\"\n\n③《山东中草药手册》：\"祛风湿，活血，止痛。\"","y":"内服：煎汤，3～5钱；或入丸、散。外用：煎水熏洗。","d":"①珍珠透骨草\n为植物地构叶的带有根茎的干燥全草。根茎圆柱状，长约10厘米；表面灰黄色，断面黄白色，木质状。茎圆柱形或微有棱，长10～20厘米，下端直径1～2毫米；表面淡绿色至灰绿色，被有灰白色柔毛；质坚硬，易折断，断面黄白色。叶多卷曲皱缩，灰绿色，被灰白色柔毛；质脆，易脱落。有时花序上留有圆形小花和果实。气微，味淡。以色绿、枝嫩、带有珍珠状果实者为佳。\n主产山东、河南、江苏。此外，甘肃、山西、陕西亦产。\n\n②风仙透骨草\n为植物风仙的干燥茎，呈长圆柱状，长30～60厘米，下端直径1～2厘米，多皱缩，具纵棱，表面黄棕色至淡棕色，节部膨大，有叶痕及芽痕，或少有分枝。质轻脆，易折断，断面中空，或有白色膜质状髓。气微弱，味微酸。\n产安徽、江苏、浙江、江西、河北、新疆等地。\n\n透骨草的药材品种比较复杂，除上述使用较广的两种外，尚有下列几种：\n\n①羊角透骨草\n为紫葳科植物角蒿的全草。产辽宁、吉林、黑龙江、山东等地。参见\"角蒿\"条。\n\n②铁线透骨草(《医学指南》)\n为毛茛种植物黄花铁线莲的干燥全草，产河北、北京。参见\"黄花铁线莲\"条。铁线透骨草商品中尚有用细叶铁线莲的全草者。\n\n③东北地区尚用豆科植物山野豌豆、广布野豌豆，假香野豌豆的全草作透骨草。参见\"山野豌豆\"条。\n\n④云南、贵州地区则用杜鹃花科植物云南白珠树的枝叶作透骨草。参见\"透骨香\"条。\n\n透骨草始见于《救荒本草》，据所述图形，为唇形科植物益母草，并非本品。《纲目》有名未用中载有透骨草，但形态不详。《本草原始》的透骨草系指大戟科的地构叶。《纲目拾遗》引《灵秘丹药笺》云：\"风仙花一名透骨草。\"即凤仙花科的凤仙；所引《医学指南》的铁线透骨草，则为毛茛科铁线莲属的透骨草，可见古代药用的透骨草已非一种。"},"九节茶":{"a":"草珊瑚,观音茶,接骨木,九节风,驳节茶,嫩头子,草珠兰,山石兰,按骨兰,山鸡茶,鸡膝风,山胡椒,骨风消,大威灵仙,九节兰,青甲子,满山香,隔年红,九节红,十月红,九节蒲,鸡骨香,接骨茶,鱼子兰","s":"辛，平。\n\n①《生草药性备要》：\"味劫，性平。\"\n\n②《南宁市药物志》：\"辛温而苦。\"","f":"抗菌消炎，祛风除湿，活血止痛。治肺炎，急性阑尾炎，急性胃肠炎，菌痢，风湿疼痛，跌打损伤，骨折。\n\n①《生草药性备要))：\"煲水饮，退热。\"\n\n②《分类草药性》：\"治一切跌打损伤，风湿麻木，筋骨疼痛。\"\n\n③《峨嵋药植》：\"叶，可止呕吐。\"\n\n④《陆川本草》：\"接骨，破积，止痛。治跌打骨折，损伤肿痛，风湿骨痛，烂疮，毒蛇咬伤。\"\n\n⑤《湖南药物志》：\"通经。治产后腹痛。\"\n\n⑥《闽东本草》：\"健脾，活血，止渴，消肿胀。治产后外感.寒热往来，头身疼痛，口渴，肿胀。\"","y":"内服：煎汤，2～5钱；或浸酒。外用：捣敷或煎水熏洗。","d":"干燥的嫩枝叶，茎枝有明显的节，圆形，棕色。叶对生，薄革质，卵状长圆形或披针状长圆形，棕色或绿褐色，边缘除基部外有粗锯齿，齿尖有硬骨质。气微味淡。\n\n产四川、湖南、广东、广西等地。"},"疳积药":{"a":"食疙瘩(《贵州草药》)。","s":"涩，温。","f":"健脾利湿，镇吐理气。","y":"?","d":"?"},"凤仙花":{"a":"金凤花、灯盏花、好女儿花、指甲花、海莲花、指甲桃花、金童花、竹盏花","s":"甘微苦，温。\n\n①《滇南本草》：\"性寒，味苦。，\n\n②《纲目》：\"甘，温，无毒。\"\n\n③《本草汇言》：\"味苦，气寒，有毒。\"\n\n④《本草正》：\"味微苦，性微温。\"","f":"祛风，活血，消肿，止痛。治风湿偏废，腰胁疼痛，妇女经闭腹痛，产后瘀血未尽，跌打损伤，痈疽，疔疮，鹅掌风，灰指甲。\n\n①《滇南本草》：\"治小儿脓耳。\"\n\n②《纲目》：\"活血消积。治蛇伤，腰胁引痛。\"\n\n③《本草求原》：\"治偏废。\"\n\n④《天宝本草》：\"治鼻血不止。\"\n\n⑤《西藏常用中草药》：\"通经活血，利尿。治经闭腹痛，产后瘀血不尽，下死胎，小便不利，疔毒痈疽。\"","y":"内服：煎汤，0.5～1钱(鲜者1～3钱)；研末或浸酒。外用：捣汁滴耳、捣敷或煎水熏洗。","d":"西藏地区使用的凤仙花，其原植物为锐齿凤仙花ImpatiensargutaHook.F.EtThoms.，分布西藏、云南等地。"},"碧桃干":{"a":"桃枭、鬼髑髅、桃奴、枭景、干桃、气桃、阴桃子、桃干、瘪桃干","s":"酸苦，平。\n\n①《本经》：\"微温。\"\n\n②《别录》：\"味苦。\"\n\n③《纲目》：\"苦，微温，有小毒。\"\n\n④《饮片新参》：\"甘酸，平。\"\n\n⑤《四川中药志》：\"性平，味淡苦，无毒。\"\n\n归肺、肝经 \n\n《本草汇言》：\"入手足厥阴经。\"","f":"治盗汗，遗精，吐血，疟疾，心腹痛；妊娠下血。\n\n①《别录》：\"疗中恶腹痛。\"\n\n②《日华子本草》：\"治肺气，腰痛，破血，治心痛，酒摩暖服之。\"\n\n③汪颖《食物本草》：\"主吐血，烧存性，研末，米汤调服。\"\n\n④《纲目》：\"治小儿虚汗，妇人妊娠下血，破伏梁结气，止邪疟，烧烟熏痔疮，烧黑油调敷小儿头上肥疮软疖。\"\n\n⑤《本经逢原》：\"疗瘀血癥坚。\"\n\n⑥《分类草药性》：\"治膀胱疝气，遣精，妇女月经闭塞。\"\n\n⑦《饮片新参》：\"生津，止汗。治劳咳，养胃除烦。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。外用：研末调敷或烧烟熏。","d":"干燥未成熟的果实，矩圆形或卵圆形，长1.8～3厘米，径1.5～2厘米，厚0.9～1.5厘米，先端渐尖，乌喙状，基部不对称，有的留存少数棕红色的果柄。表面黄绿色，具网状皱缩的纹理，密被短柔毛；内果皮腹缝线凸出，背缝线不明显。质坚实，不易折断。气微弱，味微酸涩。以干燥、实大、坚硬、色黄绿者为佳。\n主产江苏、浙江、安徽等地。\n\n本品在江苏地区称核已硬化者为碧桃干；核未硬化者为碧桃奴。"},"肾蕨":{"a":"圆羊齿(《广州植物志》)，天鹅抱蛋(《广西药植图志》)，凤凰草、圆蕨(《南宁市药物志》)，蜈蚣蕨、水槟榔、冰果草(《贵州民间药物》)，篦子草、梳篦草(《四川中药志》)，飞天蜈蚣、金鸡孵蛋、神仙对坐草(《泉州本草》)，蜈蚣草、石上丸、石黄皮(广州部队《常用中草药手册》)，凤凰蕨(《广西中草药》)，何汗蕨、蛇蛋参(《云南中草药》)，金鸡尾(《福建中草药》)。","s":"苦辛，平。\n\n①《贵州民间药物》：\"性平，味苦，无毒。\"\n\n②《四川中药志》：\"性温，味淡辛，无毒。\"\n\n③《泉州本草》：\"味甘辛，性平而涩，无毒。\"","f":"清热，利湿，消肿，解毒。治黄疸，淋浊，小便涩痛，痢疾，疝气，乳痈，瘰疬，烫伤，刀伤。\n\n①《贵州民间药物》：\"清热。治刀伤，吐血，淋浊，不孕。\"\n\n②《四川中药志》：\"治乳痈及产后乳肿。\"\n\n③《泉州本草》：\"清热解毒，利小便。治湿热黄疸，小便不利，反胃噎膈，疝气。\"\n\n④《广西实用中草药新选》：\"治肺热咳嗽，蜈蚣咬伤，汤火伤，小儿疳积，淋巴腺结核。\"","y":"内服：煎汤，2～5钱(鲜者1～2两)。外用：捣敷。","d":"?"},"穿根藤":{"a":"春根藤(《广东中药》)，木头疳(《广西药植名录》)，崧根藤、伸筋藤、石邦子(《广东中草药》)。","s":"苦辛，平。\n\n①《泉州本草》：\"苦辛，平。\"\n\n②《广东中草药》：\"涩微甘，微温。\"","f":"祛风湿，壮筋骨，止痛，消肿。治风湿关节痛，咽喉肿痛，痈肿，疥疮。\n\n①《广州植物志》：\"煎服或浸酒饮，壮筋骨，消风湿。\"\n\n②《广东中药》：\"强壮剂，治腰痛；又为通经镇痛药，能消散疮，去喉头肿痛；又可治腰部骨节痛及关节疼痛。\"\n\n③《广西药植名录》：\"全株：治头痛、气痛、小儿疳积。茎、叶：消炎，解毒，去腐，接骨，祛风湿，治跌伤。\"\n\n④《广东中草药》：\"全草：祛风止痛，舒筋活络。\"","y":"内服：煎汤，0.5～1两(鲜者1～2两)；捣汁或漫酒。外用：捣汁涂或研末调敷。","d":"干燥枝条粗者达6毫米，黑褐色，着生不定根，横切面中心有髓。叶对生。枝端常带有花序或果实，果实棕褐色，表面有棱线，顶端具宿萼，横切面有2室。以叶多，无根头、杂质者为好。\n主产广东，福建、广西亦有。\n\n少数地区将本品作络石藤使用。参见\"络石藤\"条。"},"淫羊藿根":{"a":"羊藿根(《分类草药性》)。","s":"味辛；甘；性温","f":"治虚淋，白浊，白带，月经不调，小儿雀盲，痈疽成脓不溃。\n\n\n《分类草药性》：\"治男子虚淋，白浊，头眩;女人白带，经水不调;并治吼喘。\"","y":"内服：煎汤，0.5～1两；或研末为散。","d":"?"},"哈士蟆":{"a":"哈什蟆、红肚田鸡、蛤蚂(《中药通报》2(5)：205，1956)，田鸡(《辽宁主要药材》)，雪哈(《药材资料汇编》)，蛤蟆、吧拉蛙(《吉林中草药》)。","s":"咸，凉，无毒。","f":"养肺滋肾。治虚劳咳嗽。","y":"内服：炖汤，1～3个。","d":"干燥的哈士蟆，全身僵直，有紫褐色斑点，腹部黄白色，微带红色，腹中空虚，后肢腹面常呈淡红色。肉质干枯，体轻松，气腥。以体大，腹面色泽黄红，身干者为佳。\n产于四川、黑龙江、吉林、辽宁，内蒙古等地。"},"草石蚕":{"a":"地蚕(《日用本草》)，甘露子、滴露(《饮腾正要》)，甘露儿(《救荒本草》)，土蛹(《余冬录》)，宝塔菜(《中国植物图鉴》)，蜗儿菜(《江苏植药志》)，土虫草(《陆川本草》)，地牯牛草、地纽(《贵州草药》)。","s":"①《饮膳正要》:\"甘，平，无毒。\"\n\n②《贵州草药》:\"性平，味甘微辛。\"","f":"治风热感冒，虚劳咳嗽，小儿疳积。\n\n①《钦膳正要》:\"利五脏，下气，清神。\"\n\n②《江苏植药志》:\"治心痛。\"\n\n③《陆川本草》:\"滋养强壮，清补肺金，功类冬虫草。治身体羸瘦，虚劳咳嗽，小儿疳积。\"\n\n④《贵州草药》:\"清肺解表。全草:治风热感冒；根:治肺痨。\"","y":"内服:煎汤，全草0.5～1两，根1～2两；浸酒或焙干研末。外用:煎水洗或捣敷。","d":"?"},"藏青果":{"a":"西青果,西藏青果","s":"味苦；微甘；涩；性微寒 \n\n①《饮片新参》：\"酸苦涩，微寒。\"\n\n②《高原中草药治疗手册》：\"苦涩，寒。\"\n\n《高原中草药治疗手册》：\"入肺、胃等经。\"","f":"治虚证白喉，喉炎，扁桃体炎，菌痢。\n\n①《饮片新参》：\"治阴虚白喉，杀虫生津。\"\n\n②《高原中草药治疗手册》：\"清热生津，解毒涩肠。治肺炎，痢疾，阴虚白喉。解乌头毒。\"","y":"内服：煎汤，0.5～1.5钱。","d":"干燥幼果呈扁长卵形，略似橄榄，下部有果柄痕，长2～3厘米，宽0.5～1.2厘米，外表黑褐色，有明显的纵皱纹。质坚硬，断面不平坦，有胶质样光泽；果肉厚，黄绿色，核不明显，稍空心，小者黑褐色，无空心。气无，味苦涩，微甘。以干燥、坚实，断面无空心者为佳。\n本品以往由尼泊尔进口，经西藏运销各地。"},"白背叶根":{"a":"白膜根、白朴根、野桐根","s":"味微苦；涩；性平 \n\n《岭南草药志》：\"味微涩微苦，性平。\"\n\n归脾；肾；膀胱经","f":"清热，利湿，固脱，消瘀。治肠炎，脱肛，淋浊，疝气，肝炎，脾肿，子宫下垂，产后风瘫，白带，赤眼，喉蛾，耳内流脓。\n\n①《岭南草药志》：\"收涩固脱。\"\n\n②《广西药植名录》：\"祛风湿，治刀伤。\"","y":"内服：煎汤。0.5～1两。外用：浸汁滴耳。","d":"?"},"槐根":{"a":"槐花根","s":"性味：味苦；性平\n性状：性状鉴别 根呈圆柱形，长短粗细不一，有的略弯曲。表面黄色或黄褐色。质坚硬。折断面黄白色，纤维性，木部占大部分。气微，味微苦涩。","f":"治痔疮，喉痹，蛔虫病。\n\n①《别录》：\"主喉痹寒热。\"\n\n②《医林纂要》：\"洗痔，杀虫。\"\n\n③《昆明药植调查报告》：\"健胃。驱蛔虫。\"","y":"内服：煎汤，1～2两。外用：煎水洗。","d":"干燥的根粗壮而呈圆柱形，略弯曲。外表黄色或黄褐色。质坚硬。断面黄白色，木质，纤维性。"},"博落回":{"a":"落回(《酉阳杂俎》)，号筒草、勃勒回(《植物名实图考长编》)，号简秆(《湖南野生植物》)，号筒青(《土农药志》)，滚地龙(《广西中兽医药楂》)，山号筒、山麻骨(《中国土农药志》)，猢狲竹、空洞草、角罗吹、号角斗竹、亚麻筒(《浙江农药志》)，三钱三(《广西中药志》)，山火筒(《农药植物手册》)，山梧桐(《杭州药植志》)，通大海、泡通珠、边天蒿、通天大黄(《湖南药物志》)，土霸王(《江西民间草药验方》)，号桐树(《江西医药》(7)：371，1966)。","s":"辛苦，温，有毒。\n\n①《本草拾遗》：\"有大毒。\"\n\n②《四川中药志》：\"苦辛，温，有大毒。\"\n\n③《湖南药物志》：\"辛涩，寒，有小毒。\"","f":"消肿，解毒，杀虫。治指疔，脓肿，急性扁桃体炎，中耳炎，滴虫性阴道炎，下肢溃疡，烫伤，顽癣。\n\n①《江西民间草药》：\"治臁疮，顽癣，白秃子，以叶浸醋内七、八日，杵烂敷患处，一日一换。\"\n\n②《广西中药志》：\"外用治跌打。\"\n\n③《湖南药物志》：\"祛风解毒，行气消肿，杀虫。\"","y":"外用：捣敷；煎水熏洗或研末调敷。","d":"?"},"岩豆":{"a":"?","s":"性温，味微苦辛。","f":"行血，除湿。治风湿关节痛，体虚白带，慢性阑尾炎。","y":"内服：煎汤，0.5～1两。","d":"?"},"六月寒":{"a":"大风寒草、红花野芝麻(《民间常用草药汇编》)，路边梢、化骨丹、野芝麻(《陕西中草药》)，蜂子草(《常用草药治疗手册》)。","s":"《陕西中草药》：\"辛微苦，平。\"","f":"解表宣肺。治外感头痛，咳嗽，外障目翳，烫伤。\n\n①《天宝本草》：\"散寒清火，治诸疼，外障目翳，诸般咳嗽。\"\n\n②《常用草药治疗手册》：\"发表散寒，宣肺止咳。治风寒咳嗽。\"","y":"内服：煎汤，1～3钱。外用：捣敷。","d":"?"},"胡麻花":{"a":"乌麻花(《千金方》)。","s":"?","f":"治秃发，冻疮。\n\n①《千金·食治》:\"生秃发。\"\n\n②苏轼《物类相感志》:\"身上生肉丁，擦之。\"\n\n③《纲目》:\"润大肠。\"","y":"内服:煎汤或研末。外用:研末调敷或酒浸涂擦。","d":"?"},"黄花仔":{"a":"吸血草(《闽南民间草药》)，索仔草(《实用中草药》)。","s":"《实用中草药》：\"性平，味甘微辛。\"","f":"《实用中草药》：\"活血行气，清热解毒。治肝炎，痢疾，腰肌劳损，乏力，脓疡。\"","y":"内服：煎汤，鲜根1～2两。外用：鲜叶捣敷。","d":"?"},"饴糖":{"a":"饧(《方言》)，胶饴(陶弘景)，饧糖(孟诜)，软糖(《蜀本草》)。","s":"甘，温。\n\n①《别录》：\"味甘，微温。\"\n\n②《本草蒙筌》：\"味甘苦。\"\n\n③《纲目》：\"甘，大温，无毒。\"","f":"缓中，补虚，生津，润燥。治劳倦伤脾，里急腹痛，肺燥咳嗽，吐血，口渴，咽痛，便秘。\n\n①《别录》：\"主补虚乏，止渴，去血。\"\n\n②《千金·食治》：\"补虚冷，益气力，止肠鸣、咽痛，除唾血，却咳嗽。\"\n\n③孟诜：\"补虚止渴，健脾胃气，去留血，补中。\"\n\n④《日华子本草》：\"益气力，消痰止嗽，并润五脏。\"\n\n⑤《圣惠方》：\"解乌头、天雄、附子毒。\"\n\n⑥《本草蒙筌》：\"和脾，润肺，止渴，消痰。治喉骾鱼骨，疗误吞钱环。\"\n\n⑦《本草汇言》：\"治中焦营气暴伤，眩晕，消渴，消中，怔忡烦乱。\"\n\n⑨《长沙药解》：\"补脾精，化胃气，生津，养血，缓里急，止腹痛。\"","y":"内服：烊化冲入汤药中，1～2两；熬膏或入丸剂。","d":"饴糖有软、硬之分，软者为黄褐色浓稠液体，粘性很大；硬者系软饴糖经搅拌，混入空气后凝固而成，为多孔之黄白色糖饼。味甘，药用以秋饴糖为佳。\n全国各地均产。"},"荨麻":{"a":"寻麻(《益部方物略记》)，蝎子草(《人海记》)。","s":"辛苦，寒，有毒。\n\n①《纲目》:\"辛苦，寒，有大毒。\"\n\n②《四川中药志》:\"甘，微寒，有小毒。\"\n\n③《新疆中草药手册》:\"苦辛，温，有小毒。\"","f":"治风湿疼痛，产后抽风，小儿惊风，荨麻疹。\n\n①《益部方物略记》:\"善治风肿。\"\n\n②《本草图经》:\"疗蛇毒。\"\n\n③《蜀语》:\"红者可治齁症。\"\n\n④《纲目》:\"风疹初起，以此点之。\"\n\n⑤《黔书》:\"可已疯。\"\n\n⑥《纲目拾遗》:\"浴风，采取煮汁洗。\"\n\n⑦《新疆中草药手册》:\"祛风湿，解痉，和血。\"\n\n⑧《黑龙江主要野生药用植物的鉴别及中草药新制剂》:\"治小儿麻痹，风湿，疝痛。\"","y":"内服:煎汤，1～3钱；或炖肉。外用:捣汁涂或煎水洗。","d":"?"},"球兰":{"a":"铁加杯,金雪球,牛舌黄,石壁梅,金丝叶,绣球叶,大石仙挑,爬岩板,草鞋板,玉叠梅,玉蝶梅,壁梅,古梅,绣球龙,厚叶藤,达斗藤,雪梅,肺炎草","s":"苦，平。\n\n①《福建民间草药》：\"苦，平。\"\n\n②《贵州民间药物》：\"味微甘，性温，无毒。\"","f":"清热化痰，消肿止痛。治肺热咳嗽，痈肿，瘰疬，乳妇奶少，关节疼痛，睾丸炎。\n\n①《福建民间草药》：\"祛风湿，清肝热，消痈肿。\"\n\n②《南宁市药物志》：\"内服化痰止咳，消食去积。外用消肿止痛，跌打接骨，瘰疬(煨盐)。\"\n\n③《贵州民间药物》：\"补虚弱，催乳。\"","y":"内服：煎汤(不宜久煎)，2～3钱(鲜者1～3两)；或捣汁。外用：捣敷。","d":"?"},"天青地白":{"a":"毛女儿菜(《质问本草》)，清明草(《分类草药性》)，细叶鼠曲草(《植物学大辞典》)，父子草；小地罗汉、小叶金鸡舌、白招曲(《福建民间草药》)，小火草(《四川中药志》)，野清明草(《重庆草药》)，毛水蚁、雷公青、菠萝草(《湖南药物志》)，叶下白、锦鸡舌、白草仔、小白根菊(《闽东本草》)，乌云盖雪、棉花草(《福建中草药》)。","s":"甘，凉。\n\n①《福建民间草药9：\"甘，平，无毒。\"\n\n②《四川中药志》：\"甘淡，微寒，无毒。\"\n\n③《重庆草药》：\"味涩，性微寒，无毒。\"","f":"解表，清热，明目，利尿。治感冒，咳嗽，头痛，喉痛，目赤翳障，小便热闭，淋浊，白带，痈肿，疔疮。\n\n①《分类草药性》：\"治咽喉火痛，白浊，崩带。和肝食能明目。\"\n\n②《福建民间草药》：\"明目益肝，利尿解热。\"\n\n③《广西中药志》：\"治一切眼科内外障，金疮伤口。\"\n\n④《四川中药志》：\"治咳嗽痰多，风寒骨节疼痛。\"\n\n⑤《湖南药物志》：\"治百日咳，白带。\"\n\n⑥《闽东本草》：\"祛风解表，化痰止咳。治伤风感冒，头痛目赤，咳嗽。\"","y":"内服：煎汤，鲜者1～3两；或捣汁。外用：捣敷。","d":"?"},"牛脾":{"a":"牛连贴(《滇南本草》)。","s":"《滇南本草》：\"水牛连贴，性温，味甘微酸。\"","f":"健脾消积。治脾胃失健，消化不良，食积痞满。\n\n①《本草拾遗》：\"补脾。\"\n\n②《滇南本草》：\"水牛连贴，健肿开胃，消积磨宿食，宽中醒脾，消痞满、胸胀。\"\n\n③《韩氏医通》：\"黄牛连贴，用朴硝怍脯，消痞块。\"\n\n④《纲目》：\"腊月淡煮，日食一度，治痔瘘。\"","y":"内服：煮食或焙干研末。","d":"?"},"牛尾菜":{"a":"马尾伸根、过江蕨，老龙须(《江西草药》)，金刚豆藤(《贵州草药》)，草菝葜、大伸筋草(《陕西中草药》)，千层塔、鲤鱼须、山豇豆(金华《常用中草药单方验方选编》)。","s":"甘苦，平。\n\n①《江西草药》：\"性温，味甘微苦。\"\n\n②《贵州草药》：\"性平，味甘。\"\n\n③《陕西中草药》：\"味苦，性平。\"","f":"补气活血，舒筋通络。治气虚浮肿，筋骨疼痛，偏瘫，头晕头痛，咳嗽吐血，骨结核，白带。\n\n①《江西草药》：\"祛风散瘀。治风湿痹痛，跌打损伤。\"\n\n②《贵州草药》：\"清热止咳，补虚益损。\"\n\n③《陕西中草药》：\"祛风湿，活血通络，消炎镇痛。治风湿性关节炎，筋骨疼痛，高血压所致之偏瘫，骨髓炎，骨结核。\"\n\n④金华《常用中草药单方验方选编》：\"治白带过多，淋巴结炎。\"\n\n⑤《湖南药物志》：\"舒筋活血，补气通络。\"","y":"内服：煎汤，3～5钱；浸酒或炖肉。外用：捣敷。","d":"?"},"肾子草":{"a":"灯笼草(《贵州民间药物》)。","s":"《贵州民间药物》：\"性平，味辛苦咸。\"","f":"①《贵州民间药物》：\"解热毒，治肾虚，疗风湿。\"\n\n②《贵州草药》：\"截疟。\"","y":"内服：煎汤，15-30g。外用：适量，煎水熏洗。","d":"?"},"鸡屎藤果":{"a":"五香藤、臭狗藤、解暑藤、玉明砂","s":"?","f":"《中国树木分类学》：\"汁液可治毒虫螫伤，敷于患处。又可为冻疮药。\"","y":"外用：适量，捣敷。","d":"?"},"紫荆花":{"a":"红花紫荆、洋紫荆、玲甲花","s":"性味：苦；平\n性状：性状鉴别 花蕾椭圆形，开放的花蝶形，长约1cm。花萼钟状，先端5裂，钝齿状，长约3mm，黄绿色。花冠蝶形，花瓣5，大小不一，紫色，有黄白色晕纹。雄蕊10，分离，基部附着于萼内，花药黄色。雌蕊1，略扁，有柄，光滑无毛，花柱上部弯曲，柱头短小，呈压扁状，色稍深。花梗细，长1-1.5mm。质轻脆。有茶叶样气，味酸略甜。以色紫，无杂质者为佳。显微鉴别 粉末特征：黄绿色。①花瓣表皮细胞多角形，排列紧密，平周壁具不规则放射状纹理。②花丝表皮细胞长条形，排列紧密。③花药表皮细胞多角形，平周壁具不规则放射状纹理；花药内壁细胞长圆形，平周壁有网状增厚。④花萼表皮细胞均匀增厚或连珠状增厚。⑤花萼非腺毛常呈扭曲状，1-3个细胞，表面平滑。⑥花柱表皮细胞长条形，平周壁具细密条状纹理。⑦花粉粒近圆形，直径16-22μm，表面较平滑，具3孔沟。⑧柱头薄壁细胞类圆形，排列边疏松。⑨导管网纹、环纹或螺纹。","f":"①《日华子本草》：\"通小肠。\"\n\n②《民间常用草药汇编》：\"清热凉血，去风解毒。\"\n\n③《江苏药材志》：\"治风湿筋骨痛。\"","y":"内服：煎汤，1～2钱；或浸酒。外用：研末敷。","d":"?"},"海参":{"a":"辽参、海男子","s":"咸，温。\n\n①《本草从新》：\"甘咸，温。\"\n\n②《药性考》：\"咸，寒。\"\n\n③《本草求原》：\"甘咸，微寒，滑，无毒。\"","f":"补肾益精，养血淘燥。治精血亏损，虚弱劳怯，阳痿，梦遗，小便频数，肠燥便艰。\n\n①《本草从新》：\"补肾益精，壮阳疗痿。\"\n\n②《药性考》：\"降火滋肾，通肠润燥，除劳怯症。\"\n\n③《食物宜忌》：\"补肾经，益精髓，消痰涎，摄小便，壮阳疗痿，杀疮虫。\"\n\n④《纲目拾遗》：\"生百脉血，治休息痢。\"\n\n⑤《本草求原》：\"润五脏，滋精利水。\"\n\n⑥《随息居饮食谱》：\"滋阴，补血，健阳，润燥，调经，养胎，利产。凡产后、病后衰老尪孱，宜同火腿或猪羊肉煨食之。\"\n\n⑦《现代实用中药》：\"为滋养品。治肺结核，神经衰弱及血友病样的易出血患者，用作止血剂。\"","y":"内服：煎汤、煮食或入丸剂。","d":"?"},"夏至草":{"a":"夏枯草、白花夏枯(《滇南本草》)，灯笼棵(《江苏植药志》)，风轮草(《陕西中草药》)。","s":"《陕西中草药》：\"味微苦，性平，有小毒。\"","f":"《陕西中草药》：\"活血，调经。治贫血性头昏，半身不遂，月经不调。\"","y":"内服：煎汤，3～4钱；或熬膏。","d":"?"},"七星剑":{"a":"小叶不红、星色草、假芥兰、独行千里、野香薷、酒瓶草、痱子草","s":"《本草求原》：\"香，辛，温。\"","f":"治狂犬、毒蛇咬伤，皮肤湿疹，疮毒。\n\n①《生草药性备要》：\"治癫狗、毒蛇、恶物咬伤，理跌打，敷大疮。\"\n\n②《本草求原》：\"治阴疽。\"","y":"外用：煎水洗或捣敷。内服：煎汤，3～6钱；或捣汁饮。","d":"?"},"虎肉":{"a":"?","s":"甘酸，温。\n\n①《千金·食治》：\"味酸，温，无毒。\"\n\n②《本草衍义》：\"微咸。\"\n\n③《医林纂要》：\"甘酸，热。\"","f":"补脾胃，益气力，壮筋骨。治脾胃虚弱，恶心呕吐，疟疾。\n\n①《别录》：\"疗恶心欲呕，益气力。\"\n\n②《千金·食治》：\"止多唾。\"\n\n③《本草拾遗》：\"肉及皮主疟。\"\n\n④《医林纂要》：\"壮筋骨，消食积，化骨哽。\"","y":"内服：煮食。","d":"?"},"苘麻":{"a":"白麻、青麻、野棉花、叶生毛、磨盘单、车轮草、点圆子单、馒头姆、孔麻、磨仔盾、毛盾草、野火麻、野芝麻、紫青、绿箐、野苘、野麻、鬼馒头草、金盘银盏。","s":"《上海常用中草药》：\"全草：苦，平。\"","f":"①《福建民间草药》：\"叶：治痈疽肿毒。\"\n\n②《上海常用中草药》：\"全草：解毒，祛风。治痢疾，中耳炎，耳鸣，耳聋，关节酸痛。\"","y":"内服：煎汤，0.3～1两。外用：捣敷。","d":"?"},"鱼鳔":{"a":"鱁鮧(《齐民要木》)，鱁鯷、鱼白、鳔(《本草拾遗》)，鱼胶(《三因方》)，白鳔(《普济方》)，鱼脬、縼胶(《纲目》)，鱼肚(《医林纂要》)。","s":"甘，平。\n\n①《海药本草》：\"无毒。\"\n\n②《纲目》：\"甘，平，无毒。\"\"鳔胶，甘咸，平，无毒。\"\n\n③《本草新编》：\"味甘，气温。\"","f":"补肾益精，滋养筋脉，止血，散瘀，消肿。治肾虚滑精，产后风痉，破伤风，吐血，血崩，创伤出血，痔疮。\n\n①《本草拾遗》：\"主竹木入肉经久不出者，取白敷疮上四边，肉烂即出刺。\"\n\n②《海药本草》：\"主月蚀疮，阴疮，痔疮，并烧灰用。\"\n\n③《饮膳正要》：\"与酒化服之，消破伤风。\"\n\n④《纲目》：\"鳔，止折伤血出不止；鳔胶，烧存性，治妇人难产，产后风搐，破伤风痉，止呕血，散瘀血，消肿毒。\"\n\n⑤《本草新编》：\"补精益血。\"\n\n⑥《本草求原》：\"养筋脉，定手战，固精。\"","y":"内服：煎汤，3～5钱；熬膏或研末入丸，散。外用：溶化涂敷。","d":"干燥的鳔多压制成长圆形的薄片，淡黄色，角质状，略有光泽。黄鱼的鳔较小，鲟鱼及蝗鱼的鳔大，并附有垂带2条。质坚韧，不易撕裂，裂断处呈纤维性；入水易膨胀，煮沸则几乎全溶，浓厚的溶液冷却后凝成冻胶，粘性很强。气微腥，味淡。商品统称为鱼肚。鲟鱼、鳇鱼的鳔称为\"黄唇肚\"或\"黄鲟胶\"。有切成线条的称为\"线鱼胶\"。\n产浙江，福建、上海等地。"},"土荆芥":{"a":"臭草、杀虫芥、鸭脚草","s":"辛，温，有毒。\n\n①《生草药性备要》：\"味辛，性温。\"\n\n②《江西中药》：\"辛凉，有小毒。\"\n\n③《广西药植图志》：\"味苦辛烈，性温，有毒。\"","f":"祛风，杀虫，通经，止痛。治皮肤风湿痹痛，钩虫，蛔虫，痛经，经闭，皮肤湿疹，蛇虫咬伤。\n\n①《生草药性备要》：\"祛风止痛，宜煎水洗，小儿麻痘脱靥后洗之，胜过蚬水。\"\n\n②《岭南采药录》：\"能除风热，杀虫，健胃，止痛。煎水洗皮肤疥癞。\"\n\n③《贵州民间方药集》：\"可驱肠中寄生虫。外用治蛇虫咬伤。\"\n\n④《江西中药》：\"适用于钩虫病，消化不良，胃肠充气及月经闭止，痛经。\"","y":"内服：煎汤，1～2钱(鲜者5～8钱)；或入丸、散。外用：煎水洗或捣敷。","d":"干燥带有果穗的茎枝。茎下部圆柱形，粗壮，光滑；上部方形有纵沟，具毛茸。下部叶大多脱落，仅留有茎梢线状披针形的苞片；果穗成束，簇生于枝腋及茎梢，触之即落，淡绿色或黄绿色；剥除宿萼，内有1棕黑色的果实。有强烈的特殊香气，味辣而微苦。\n\n产于广西、广东、福建、贵州等地。"},"龙利叶":{"a":"龙舌叶、龙味叶、龙脷叶牛耳叶","s":"性平，味甘\n\n①《陆川本草》：\"性平，味淡。\"\n\n②《南宁市药物志》：\"甘，平。\"","f":"清热润肺；化痰止咳。 主治肺热咳喘痰多；口干；便秘。 \n\n①《陆川本草》：\"清肺，治肺热咳嗽。\"\n\n②《南宁市药物志》：\"止痰火咳嗽哮喘。治内伤肺痨失音。喉痛。\"","y":"内服：煎汤，2～5钱。","d":"干燥叶呈卵状或倒卵状披针形，似舌状，先端钝或浑圆而有小尖，基部短尖近圆形，全缘，枯黄色或黑绿色，叶背中脉突出，侧脉羽状，网脉子近边缘处合拢。纸质，较厚。气微，味淡。以片大、完整者佳。\n产于广东，广西。"},"龙虱":{"a":"水鳖虫(《江苏中药名实考》)，射尿龟、尿缸贼(《陆川本草》)，水龟子(《中药志》)。","s":"《陆川本草》：\"甘，平。\"","f":"补肾，活血。治小便频敷，小儿遗尿。\n\n①《物理小识》：\"食之除面黚，活血。\"\n\n②《药材资料汇编》：\"用于老人夜溺频繁。\"\n\n③《陆川本草》：\"滋养强壮，治小儿遗尿。\"","y":"内服：0.8～1.5钱，炙，研末或入丸剂。","d":"干燥的虫体，呈长卵形，全体有光泽。背面黑色。鞘翅边缘有棕黄色狭边。除去鞘翅，可见浅色的膜质翅1对。腹面红褐色至黑褐色。腹部有横纹。质松脆，气腥，味微咸。\n\n主产江苏、福建、浙江、广东等地。"},"虎掌草":{"a":"见风青、见风蓝、乌骨鸡(《贵州民间方药集》)，羊九、狗脚迹(《贵阳民间药草》)，土黄芩(《中国药植图鉴》)，五朵云(《中国高等植物图鉴》)。","s":"苦辛，平，有毒。\n\n①《滇南本草》：\"性寒，味微苦辣，有小毒。\"\n\n②《贵阳民间药草》：\"苦，平，有小毒。\"\n\n③《贵州草药》：\"性平，味苦微辛，有小毒。\"","f":"清热解毒，活血舒筋。治喉蛾，痄腮，瘰疬结核，痈疽肿毒，疟疾，风湿疼痛，胃痛，跌打损伤。\n\n①《滇南本草》：\"行经络，攻热毒，除胃痰。胃有痰毒，人多呃逆。消红肿痈疖疮疽，血风疥癞，痰疬结核，流痰横痃，外乳蛾、痄腮，内乳蛾、咽喉疼痛，牙根热毒。\"\n\n②《贵州民间方药集》：\"治跌打损伤，可舒筋活血，强壮补虚。又治痢疾，外用治疔疮。\"\n\n③《贵阳民间药草》：\"平虚热，解热毒。治疟疾，咳嗽，风湿痛；外治疮肿。\"\n\n④《贵州草药》：\"清热解毒，化瘀镇痛。\"\n\n⑤《青藏高原药物图鉴》：\"补血，暖体，消积，去湿，愈创，排脓。治病后体温不足，淋病，关节积黄水，黄水疮(外敷可治黄水疮或提出关节中黄水)，慢性气管炎，末梢神经麻痹，催吐胃酸。\"\n\n⑥《云南中草药选》：\"消炎止痛，疏肝利胆，舒筋活络。\"","y":"内服：煎汤，2～3钱(鲜者0.5～1两)；或浸酒。外用：研末调敷，或鲜品捣敷；或煎汤含漱。","d":"理化鉴别 （1）取本品粉末4g，加水20ml，置热水浴中浸渍20-30min，滤过。取滤液5ml，置试管中，振摇1min，发生持久性的蜂窝状泡沫，再加碱或醋酸铅试液2-3滴，有类白色沉淀生成。（2）取本品粉末2g，加70%乙醇5ml，温浸10-20min，滤过。取滤液2ml，加70%盐酸羟胺的甲醇溶液4-5滴，再加10%氢氧化钾的甲醇溶液2-3滴，置水浴上加热数分钟，冷却后加稀盐酸调节至pH3-4，再加1%三氯化铁的乙醇溶液2-4滴，显橙红色至紫红色。"},"三角草":{"a":"犁铧草、箭叶草、山韮菜、土麦冬、割鸡刀，三稔草","s":"广州部队《常用中草药手册》：\"微苦，凉。\"","f":"①《广西药植名录》：\"根：治黄疸，内伤。\"\n\n②广州部队《常用中草药手册》：\"清热解毒，消肿止痛。治毒蛇咬伤，跌打肿痛。\"","y":"内服：煎汤，3～6钱(大剂1～2两)。外用：捣敷。","d":"?"},"白毛夏枯草":{"a":"金疮小草(《本草拾遗》)，雪里青、土犀角(《纲目拾遗》)，见血青、白头翁、筋骨草、石灰菜、紫背金盘、破血丹(《植物名实图考》)，退血草、散血草(《分类草药性》，伏地筋骨草(《江苏植物名录》)，白夏枯草(《苏州本产药材》)，散血丹、白毛串、白喉草、四季春草、大叶刀焮草(《福建民间草药》)，青鱼胆草、苦地胆、透骨消(《广西中兽医药植》)，四时春(《闽南民间草药》)，地龙胆、活血草(《四川中药志》)，雪里开花、青石藤、朋花、一盏灯、野鹿衔花、天青地红、叶下红、爬爬草(《湖南药物志》)，白调羹、和胶毒草(《闽东本","s":"苦甘，寒。\n\n①《本草拾遗》：\"味甘，平，无毒。\"\n\n②《纲目拾遗》：\"性寒，味苦。\"\n\n③《本草再新》：\"有小毒。\"","f":"止咳化痰，清热，凉血，消肿，解毒。治气管炎，吐血，衄血，赤痢，淋病，咽喉肿痛，疔疮，痈肿，跌打损伤。\n\n①《本草拾遗》：\"主金疮止血，长肌，断鼻中衄血，取叶挼碎敷之；亦煮服断血瘀及卒下血。\"\n\n②《纲目拾遗》：\"专清肝火。\"\n\n③《木草再新》：\"清火开气。\"\n\n④《植物名实图考》：\"养筋，和血，散寒，酒煎服。\"\"捣敷疮毒。\"\n\n⑤《分类草药性》：\"退火散血，消肿毒。跌打损伤，泡酒服。\"\n\n⑥《福建中草药》：\"清热泻火，消肿解毒。治痢疾，白喉，喉炎，扁桃腺炎，婴儿头面湿疹，疔疮，牙痈，牙痛，乳痈，狂犬咬伤。\"\n\n⑦《四川中药志》：\"治痨伤，咳嗽。吐血及妇人血气痛。\"\n\n⑧《闽东本草》：\"治手掌或手指刺伤，蛇虫叹伤。\"","y":"内服：煎汤，3～5钱(鲜者2～3两)；打汁或研末。外用：捣敷；或捣汁含漱。","d":"理化鉴别 （1）取本品粗粉1.5g，加乙醇15ml，沸水浴提取15min，冷后滤过，滤液浓缩至2ml：①取滤液0.5ml，加盐酸3滴，辊镁粉少许，略加湿，深液呈红色。（检查黄酮类）②取滤液0.5ml，置水浴上蒸干，加醋酐5滴及硫酸1滴，初呈淡紫红色，很快变为蓝绿色。（检杳甾体）（2）取本品粗粉0.5g，加蒸馏水温浸15min，冷后滤过。取滤液0.5ml，加三氯化铁1滴，呈绿黑色。（检查酚类）"},"柠檬叶":{"a":"黎檬,洋柠檬","s":"辛甘，温。\n\n①《生草药性备要》:\"味辛，性温。\"\n\n②《木草求原》:\"辛甘，温。\"\n\n③《南宁市药物志》:\"辛苦，温，无毒。\"","f":"化痰止咳，理气，开胃。治咳喘，腹胀，泄泻。\n\n①《生草药性备要》:\"止咳，化痰，开胃。辟腥甚佳.\"\n\n②《陆川本草》:\"行气，止喘咳。治气喘，咳嗽，腹胀，腹泻。\"\n\n③《南宁市药物志》:\"行气，驱风，祛痰，健胃。治咳嗽气痛。\"","y":"内服:煎汤，3～5钱。","d":"?"},"雾水葛":{"a":"地清散、脓见消、咄脓膏(《生草药性备要》)，啜脓膏(《岭南采药录》)，石茹(《福州草药》)，田薯(《闽南民间草药》)，拔脓膏、生肉药、糯米藤(《广西药植名录》)，粘榔根，水麻秧(《文山中草药》)。","s":"甘淡，寒。\n\n①《生草药性备要》：\"味甜，性寒。\"\n\n②《闽南民间草药》：\"苦酸，平。\"\n\n③《广东中药》Ⅱ：\"性凉，味淡。\"","f":"?","y":"外用：捣敷或捣汁含漱。内服：煎汤，0.5～1两(鲜者1～2两)。","d":"干燥带根全草，根系细小，主茎短，分枝披散，疏被毛，红棕色。叶膜质而脆，易碎，叶柄纤细。气微，味淡。\n产广东、福建等地。"},"红芪":{"a":"晋芪,独根,黑芪,真盘子。","s":"性温，味甘。归肺经、脾经。","f":"?","y":"9～30g。","d":"理化鉴别 （1）取本品粉末3g，加水30ml，加0.2%三酮溶液2滴，至沸水浴中加热5min，冷后呈紫红色。（检查氨基酸、多肽）（2）薄层色谱 取本品粉末3g，加水15ml冷浸过夜，滤过，作供试品溶液。另取精氨酸、脯氨酸、苏氨酸，以乙醇溶解成每ml含1mg的对照溶液。取上述两种溶液点于同一硅酸G薄层板上，以乙醇-氨水-水（7：1：2）展开，展距20cm，取出晾干，喷雾吲哚醌试剂，105℃烘烤数分钟，供试品色谱中在与对照品色谱相应的位置上显相同颜色的斑点。"},"竹节草":{"a":"竹节菜、翠蝴蝶、翠娥眉、笪竹花、倭青草(《救荒本草》)，竹菜、鸭跖草(《岭南采药录》)。","s":"《生草药性备要》：\"味淡，性寒。\"","f":"①《生草药性备要》：\"治白浊，消热散毒，利小便。\"\n\n②《岭南采药录》：\"根茎捣烂，敷疮疖。\"","y":"内服：煎汤，10-20g，鲜品30-60g。外用：适量，捣敷；或研末撒。","d":"?"},"蘑菇":{"a":"鸡足磨菇、磨菇蕈(《广菌谱》)，肉蕈(《纲目》)。","s":"甘，凉。\n\n①《日用本草》：\"味甘，平，无毒。\"\n\n②《随息居饮食谱》：\"甘，凉。\"","f":"①《医学入门》：\"悦神，开胃，止泻，止吐。\"\n\n②《生生编》：\"益肠胃，化痰，理气。\"","y":"内服：煎汤，2～3钱。","d":"?"},"管仲":{"a":"番白叶(《滇南本草》)，翻白地榆、槟榔仁(《滇南本草》)整理本)，翻背白草、白头翁、涩疙瘩(《贵州民间药物》)，地管子(《云南思茅中草药选》)，地摈榔、白地榆(《云南中草药选》)。","s":"⑦《滇南本草》：\"性寒，味苦涩。\"\n\n②《云南思茅中草药选》：\"苦涩，平。\"","f":"清热消炎，凉血止血。治赤白痢疾，肠炎，胃痛，肺结核咯血，鼻衄，便血，血崩，外伤出血，疔疮。\n\n①《滇南本草》：\"治血崩，白带，大肠下血，用新瓦焙；治面寒疼，烧酒为引。\"\n\n②《贵州民间药物》：\"治痢疾，疔疮，风湿。\"\n\n③《云南思茅中草药选》：\"清热止血，消炎收敛。治痢疾，肠炎，胃痛，咯血，吐血，外伤出血，痛经。\"\n\n④《云南中草药选》：\"凉血止血，收敛止泻。治肺结核咯血，吐血，鼻衄，消化不良，贫血，赤白痢疾。\"","y":"内服：煎汤，0.5～1两；研末，3～5分；或浸酒。外用：捣敷或研末撒。","d":"?"},"茶树根":{"a":"?","s":"苦，平。\n\n归心；肾经","f":"治心脏病，口疮，牛皮癣。\n\n《救生苦海》:\"治口烂，茶树根煎汤代茶，不时饮。\"","y":"内服:煎汤，1～2两。","d":"?"},"水田七":{"a":"水三七(《贵州卫生》(11)：19，1959)，屈头鸡、水鸡头(《南宁市药物志》)，水鸡仔(《广西中药志》)，囫头鸡、水虾公、马老头(广州空军《常用中草药手册》)，山大黄(《云南思茅中草药选》)，水槟榔，水萝卜、长须果(《广西植物名录》)。","s":"甘苦，凉。\n\n①《广西中药志》：\"苦，寒。\"\n\n②《云南中草药》：\"苦，微寒，小毒。\"","f":"凉血，散瘀，消炎止痛。治消化道溃疡，肠炎，肺结核，百日咳，跌打损伤，刀伤出血，咽痛，痈肿，牙痛。\n\n①《南宁市药物志》：\"消炎，解毒，止痛。治胃气痛，吐酸，咳嗽，白痢，咽痛，外敷治痈疮。\"\n\n②《广西中药志》：\"止血。治跌打损伤，止咳化痰，各种痛症，调经。\"\n\n③《云南思茅中草药选》：\"清热解毒，消炎止痛。治胃及十二指肠溃疡，高血压，肝炎，胃痛，烫伤，烧伤，疮疡。\"\n\n④《广西实用中草药新选》：\"凉血止痛，散瘀消肿。治溃疡病，小儿疳积，腹痛，跌打损伤，痈肿，无名肿毒，胃热痛，急性肠胃炎，牙痛。\"","y":"内服：煎汤，3～5钱。外用：捣敷或研末调敷。","d":"干燥块茎呈圆球形成长圆形，稍弯曲，长2～4厘米，径约1.5～2厘米，上端有残存的膜质叶基，表面黄白色或浅棕黄色，有粗皱纹，须根痕多数。质稍硬，折断面较平，颗粒性，暗黄褐色，微有蜡样光泽，散有点状维管束。\n产广西、贵州、广东等地。\n\n同属植物水狗仔的块茎亦同供药用，形态与上种相似，唯块茎不弯曲，断面带蓝色。"},"水芹菜":{"a":"水芹、野芹菜、山芹菜","s":"辛，凉。","f":"平肝，解表，透疹。治麻疹初期，高血压，失眠。","y":"内服：煎汤，3～5钱。","d":"?"},"黄花菜":{"a":"连珠炮、下奶药(《昆明民间常用草药》)，条参、绿葱根、镇心丹、金针菜(《云南中草药选》)，野皮菜、真金花、鸡脚参、小提药、鸡药葛根、风尾一枝蒿、萱草(《云南中草药》)。","s":"甘，平。\n\n①《昆明民间常用草药》：\"性平，味甘。有小毒。\"\n\n②《云南中草药选》：\"甘微辛，平。\"","f":"养血平肝，利尿消肿。治头晕，耳鸣，心悸，腰痛，吐血，衄血，大肠下血，水肿，淋病，咽痛，乳痈。\n\n①《昆明民间常用草药》：\"补虚下奶，平肝利尿，消肿止血。\"\n\n②《云南中草药选》：\"镇静，利尿，消肿。治头昏，心悸，小便不利，水肿，尿路感染，乳汁分泌不足，关节肿痛。\"\n\n③《云南中草药》：\"养血补虚，清热。\"","y":"内服：煎汤，3～5钱；或炖肉。外用：捣敷。","d":"?"},"棕树根":{"a":"?","s":"性平，味苦涩。心经\n《四川中药志》：\"性平，味苦涩，无毒。\"","f":"止血，祛湿，消肿解毒。治吐血，便血，血淋，血崩，带下，痢疾，关节痛，水肿，瘰疬，流注，跌打损伤。\n①《滇南本草》：治妇人血崩不止，又治大肠下血，男子五淋便浊。\n②《民间常用草药汇编》：通经，祛湿。\n③《四川中药志》：养血收敛，涩肠止痢。治吐血，肠风下血，崩、带，跌打损伤及腰痛。","y":"内服：煎汤，3～5钱。外用：煎水洗。","d":"?"},"苹果皮":{"a":"?","s":"甘；凉","f":"《滇南本草图说》：\"治反胃吐痰。\"","y":"内服：煎汤，0.5～1两；或沸汤泡服。","d":"?"},"山椒根":{"a":"铁杆椒根,黄椒根,单面针根","s":"辛，温。\n\n①《贵州草药》：\"性温，味辛。\"\n\n②《四川常用中草药》：\"性温，味辛涩，有小毒。\"","f":"化痰，活血，止痛。治劳伤咳嗽、吐血，跌打损伤，牙痛。\n\n①《广西药植名录》：\"治牙痛。\"\n\n②《贵州草药》：\"理气祛痰，和血定痛。\"\n\n③《四川常用中草药》：\"活血，散瘀，接骨，续筋。治跌打损伤，骨折，扭伤。\"","y":"内服：煎汤，3～5钱；或浸酒。","d":"生药材鉴定 性状鉴别 干品多缠绕成团。茎细长圆柱形，褐色或绿褐色，有较多的须状不定根，灰白色。叶皱缩，展平后歪倒卵形，先端钝圆，边缘有疏锯齿，基部楔形，外侧耳状圆形，叶腋可见球形花序。质脆。气微，味微苦。"},"野樱桃":{"a":"缠条子。","s":"果实：甘，微凉。种子：酸，温。","f":"果实：清血热，益肾，治咽喉肿痛，声哑；捣汁，每服一酒杯，每天两次。种子：透疹，治麻疹初起，疹出不透；野樱桃核三钱，芫荽二钱。水煎服。","y":"内服：煎汤，15-30g；或捣汁。","d":"?"},"粪箕笃":{"a":"蛤乸草、田鸡草(《岭南采药录》)，雷砵嘴、畚箕草、飞天雷公(《南宁市药物志》)，犁壁藤、铁板膏药草(福建)。","s":"①《岭南采药录》：\"味腥，性平。\"\n\n②《陆川本草》：\"苦，寒。\"","f":"清热解毒，利湿通便，消疮肿。治热病发狂，黄疸，胃肠炎，痢疾，便秘，尿血，疮痈肿毒。\n\n①《岭南采药录》：\"生肌止血。治痢疾，又治发黄，发狂。乳疮，和片糖捣烂敷之。\"\n\n②《陆川本草》：\"清凉解毒，通大便。治肠胃炎，大便秘结；蛇咬伤。\"\n\n③《南宁市药物志》：\"清热利水，治炎症性腹泻及尿血；外敷恶疮，消肿毒。\"","y":"内服：煎汤，1～3钱(鲜者0.5～1两)。外用：捣敷。","d":"干燥全草，藤茎柔细，扭曲，粗1～2毫米，棕褐色，有明显的纵行线条；叶三角状卵形，灰绿色或绿褐色，多皱缩卷曲。根茎圆柱状或不规则块状，下面分生许多根，长可达30厘米，径5～12毫米，表面土黄色至暗棕色，有纵皱；质坚韧，不易折断，断面纤维性，有粉尘。\n产广东、广西等地。"},"黄藤":{"a":"土黄连(《南宁市药物志》)，藤黄连(《广西中药志》)，黄连藤(《中国药植图鉴》)，伸筋蘑、山大王(《广西药植名录》)，大黄藤(广西《中草药新医疗法处方集》)。","s":"甘苦，寒，有毒。\n\n①《纲目》：\"甘苦，平，无毒。\"\n\n②《陆川本草》：\"苦，寒。\"\n\n③《广西植物名录》：\"有小毒。\"","f":"清热，解毒，利尿，通便。治饮食中毒，热郁便秘，痢疾，传染性肝炎，疮痈，赤眼，咽喉肿痛。\n\n①《纲目》：\"治饮食中毒，利小便，煮汁频服。\"\n\n②《陆川本草》：\"泻热解毒，通便，去水毒，消肿。治热郁便秘，痢疾，石水，疮痈，天泡疮，赤眼。\"\n\n③《广西中药志》：\"治阳黄，枪炮伤，烫伤。\"\n\n④《中国药植图鉴》：\"煎水服治发热头痛；磨碎敷疔疮。\"\n\n⑤《广西中草药》：\"清心火，利小便。治痢疾，急性胃肠炎，急性扁桃体炎，咽喉炎，结膜炎，肺结核，疮疖，汤火伤；可预防流脑。\"","y":"内服：煎汤，2～4钱。外用：磨汁或研末调敷。","d":"①干燥根呈圆柱形，弯曲扭转，长15～75厘米，粗0.5～2厘米。外表土棕色，去栓皮后呈棕黄色，皮孔不明显；皮部易剥落。横切面木栓层极薄，暗棕色；韧皮部发达；木质部放射状排列，多空隙，坚硬，韧皮部与木质部均鲜黄色。味极苦，能使唾液成黄色。\n\n②干燥茎呈圆柱形，稍弯曲，粗达3厘米以上。外表土灰色，节微隆起，具多数细纵沟和横裂。横切面木栓层较根部稍厚，约0.7～1毫米，暗棕色；皮层及韧皮部厚约2～9毫米，黄色，有空隙；木质部黄色至棕黄色，中心有小形髓部，辐射线色较暗。气味同根。以条大、色黄、断面有菊花纹，味苦者为佳。\n产广西、广东。"},"槐耳":{"a":"槐糯(《千金方》)，槐菌(《唐本草》)，槐鸡(《蜀本草》)，槐鹅(《圣惠方》)，槐蛾、赤鸡(《纲目》)。","s":"①《药性论》：\"平。\"\n\n②《唐本草》：\"味苦辛，平，无毒。\"","f":"治痔疮，便血，脱肛，崩漏。\n\n①《药性论》：\"能治风，破血，益力。\"\n\n②《唐本草》：\"主五痔，心痛，女人阴中疮痛。\"\n\n③《本草图经》：\"治大便血及五痔、脱肛等。\"","y":"内服：煎汤，2～3钱；或烧存性研末服。","d":"?"},"红蓝地花":{"a":"灯盏花、白带丹。","s":"甘微苦，平。","f":"解毒消肿，活血。治结核型、瘤型麻风。","y":"全草1～3钱；根3～5钱。炖肉服治眼病。","d":"?"},"樟树根":{"a":"香通、樟脑树根、土沉香、山沉香","s":"性微温，味辛。","f":"祛风散寒。治风湿骨痛，跌打损伤，感冒头痛。","y":"内服：煎汤，１～3钱。","d":"?"},"狗肾":{"a":"狗鞭,黄狗肾,广狗肾。","s":"①《滇南本草》：\"气味平。\"\n\n②《纲目》：\"平，微毒。\"","f":"《本草拾遗》：\"主妇人产后肾劳如疟者(体热用猪肾，体冷用犬肾)。\"","y":"内服：煮食。","d":"?"},"老白花树皮":{"a":"?","s":"《云南思茅中草药选》：\"苦涩，平。\"","f":"《云南思茅中草药选》：\"收敛健胃，消炎解毒。治消化不良，急性胃肠炎。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"通经草":{"a":"金丝草(《山西中药志》)，止惊草、金线铜皮、铁骨草(《浙江中药资源名录》)，分经草、小孩拳、伸筋草(《河南中草药手册》)。","s":"《河南中草药手册》：\"性平，味淡；叶：味苦。\"\n\n\n入肺经，肝经","f":"止咳，调经，祛湿。治咳嗽，月经不调，赤白带下。\n\n①《山西中药志》：\"活血通经。\"\n\n②《浙江中药资源名录》：\"治小儿惊挛抽搐。\"\n\n③《广西药植名录》：\"止咳，治妇女病，\"\n\n④《河南中草药手册》：\"活血调经，祛湿，散寒，止痛。\"","y":"内服：煎汤，3～5钱。","d":"干燥全草，叶柄细如金丝，褐栗色，光泽，中空，中间有绿心，叶上面绿色，下面灰白色，边缘有孢子囊着生。根茎黑褐色，被鳞片，须根众多。气无，味淡。\n产山西、浙江、陕西等地。"},"含羞草根":{"a":"?","s":"微苦，温，有毒\n\n《云南中草药》：\"涩微苦，温，有毒。\"\n入肾经","f":"止咳化痰，利湿通络，和胃，消积。治慢性支气管炎，风湿疼痛，慢性胃炎，小儿消化不良。\n\n《云南中草药》：\"利湿通络，明目，镇静。\"","y":"内服：煎汤，3～5钱；或浸酒。","d":"?"},"金丝带":{"a":"金腰带(《陕西中草药》)。","s":"甘苦，平。","f":"除风湿，止血止痛，调经活血，镇静安神，健脾胃。治劳伤腰腿痛，外伤出血，月经不调，子宫脱垂，白带，精神病，痫症，半身不遂，阳痿，头晕目眩。\"","y":"1～3钱，水煎或泡酒服，外用适量，研粉撒患处。","d":"?"},"繁缕":{"a":"蔜(《尔雅》)，蘩蒌(《别录》)，滋草(《千金·食治》)，鹅肠菜、鹅儿肠菜(《纲目》)，五爪龙(《湖南药物志》)，狗蚤菜(《广西药植名录》)，鹅馄饨(苏医《中草药手册》)。","s":"甘微咸，平。\n\n①《别录》：\"酸，平，无毒。\"\n\n②孟诜：\"温。\"\n\n③《纲目》：\"甘微咸。\"","f":"活血，去瘀，下乳，催生。治产后瘀滞腹痛，乳汁不多，暑热呕吐，肠痈，淋病，恶疮肿毒，跌打损伤。\n\n①《别录》：\"主积年恶疮不愈。\"\n\n②《药性论》：\"主治产后血块，炒热和童子小便服。\"\n\n③《本草拾遗》：\"主破血，产妇煮食之，及下乳汁；产后腹中有块痛，以酒炒，绞取汁温服；又取暴干为末，醋煮为丸，空腹服三十丸，下恶血。\"\n\n④《本草图经》：\"揩齿宣露，干作未有益。\"\n\n⑤《贵州民间方药集》：\"解热利尿，催生，催乳，活血去瘀。治跌打损伤，消伤肿，又治无名肿毒。\"\n\n⑥《中国药植图鉴》：\"生叶揉汁，外用治疮伤；茎叶拌盐咬之，能治齿痛；醋和，或烧存性麻油调敷疮及肿毒。\"\n\n⑦《湖南药物志》：\"止小便利，遗尿，洗手足风丹，遍身痒痛。\"","y":"内服：煎汤，1～2两；或捣汁。外用：捣敷；或烧存性研末调敷。","d":"?"},"干地黄":{"a":"地髓、生地黄、原生地、干生地","s":"甘苦，凉。\n\n①《本经》：\"味甘，寒。\"\n\n②《别录》：\"苦，无毒。\"","f":"滋阴，养血。治阴虚发热，消渴，吐血，衄血，血崩，月经不调，胎动不安，阴伤便秘。\n\n①《本经》：\"主折跌绝筋，伤中，逐血痹，填骨髓，长肌肉，作汤除寒热积聚，除痹。生者尤良。\"\n\n②《别录》：\"主男子五劳七伤，女子伤中，胞漏下血，破恶血，溺血，利大小肠，去胃中宿食，补五脏，内伤不足，通血脉，益气力，利耳目。\"\n\n③《药性论》：\"补虚损，温中下气，通血脉，治产后腹痛，主吐血不止。\"\n\n④《日华子本草》：\"治惊悸劳劣，心肺损，吐血，鼻衄，妇人崩中血晕，助筋骨。\"\n\n⑤王好古：\"主心病，掌中热痛，痹气痿蹙，嗜卧，足下热而痛。\"\n\n⑥《本草从新》：\"治血虚发热，常觉饥馁，倦怠嗜卧，胸膈痞闷；调经安胎。\"","y":"内服：煎汤，3～5钱，大剂1～2两；熬膏或入丸、散。外用：捣敷。","d":"呈不规则的圆形或长圆形块状，长6～12厘米，直径3～6厘米。表面灰棕色或灰黑色，全体皱缩不平，具不规则的横曲纹。细小的多为长条状，稍扁而扭曲。质柔软，干后则坚实，体重。不易折断，断面子坦，紫黑色或乌黑色而光亮，显油润，具粘性。气微香，味微甜。以肥大、体重、断面乌黑油润者为佳。\n\n主产河南、浙江。河北、陕西、甘肃、湖南、湖北、四川、山西等地亦产。以河南所产者最为著名。"},"酸石榴":{"a":"醋石榴","s":"酸，温。\n\n①孟诜：\"温。\"\n\n②《蜀本草》：\"《图经》云，味甘酸。\"\n\n③《纲目》：\"酸涩，温，无毒。\"","f":"止渴；涩肠；止血。主津伤燥渴；滑泻；久痢；崩漏；带下\n1.诜孟：治赤白痢腹痛者，取一枚并子捣汁顿服。\n2.《本草拾遗》：止渴。\n3.《蜀本草》：《图经》云，止痢。\n4.《纲目》：止泻痢，崩中，带下。\n5.《随息居饮食谱》：解渴，醒醒。\n6.《广州植物志》：可治胃病。 \n该","y":"内服：捣汁或烧存性研末。","d":"?"},"刘寄奴":{"a":"金寄奴(《日华子本草》)，乌藤菜(《通志》)，六月雪、九里光(《药材资料汇编》)，白花尾、炭包包、千粒米、斑枣子、细白花草、九牛草(《湖南药物志》)，苦连婆(《闽东本草》)。","s":"苦，温。\n\n①《唐本草》：\"味苦，温。\"\n\n②《日华子本草》：\"无毒。\"","f":"破血通经，敛疮消肿。治经闭癥瘕，胸腹胀痛，产后血瘀，跌打损伤，金疮出血，痈毒焮肿。\n\n①《唐本草》：\"主破血，下胀。\"\n\n②《日华子本草》：\"治心腹痛，下气水胀、血气，通妇人经脉癥结，止霍乱水泻。\"\n\n③《开宝本草》：\"疗金疮，止血为要药；产后余疾，下血、止痛。\"\n\n④《本草蒙筌》：\"消焮肿痈毒，灭汤火热疼。\"\n\n⑤《纲目》：\"小儿尿血，新者研末服。\"\n\n⑥《本草求原》：\"治心气痛，疳疮出血。\"","y":"内服：煎汤，1.5～3钱；或入散剂。外用：捣敷或研末撒。","d":"干燥的带花全草，枝茎长60～90厘米，通常已弯折，直径2～4毫米，表面棕黄色至棕褐色，常被白色毛茸，茎质坚而硬，折断面呈纤维状，黄白色，中央白色而疏松。叶互生，通常干枯皱缩或脱落，表面暗绿色，背面灰绿色，密被白毛，质脆易破碎或脱落，枝梢带花穗，枯黄色。气芳香，味淡。以叶绿、花穗黄而多、无霉斑及杂质者为佳。\n主产江苏、浙江、江西等地。\n\n商品刘寄奴，各地所用品种很不一致。唯上述一种与《本草》所载近似，但仅在江苏、上海、浙江、江西、福建等地使用，习称\"南刘寄奴\"。另一种\"北刘寄奴\"，系玄参科植物阴行草的带果全草，主产河北、山东、河南、吉林、黑龙江等地。虽与《本草》所载者不同，但亦有较长的使用历史。参见\"铃茵陈\"条。\n\n此外，四川所用的刘寄奴为菊科植物狭叶艾的全草，又名红陈艾、芦蒿。其特征：茎呈红紫色。叶通常3～4深裂，裂片披针形或线状披针形，上部叶片披针形或线状披针形。头状花序直立，成穗状圆锥花丛；苞片略被白色细柔毛。"},"天茄子":{"a":"刺天茄(《滇南本草》)，小闹杨、小颠茄(《生草药性备要》)，金钮头(《岭南采药录》)，五宅茄(《中国树木分类学》)，金扣钮、细黄茄(《陆川本草》)，勒矮瓜、细颠茄、假茄子、天星子、满天星、五角颠茄(《广西药植名录》)，刺茄(《福建中草药》)。","s":"《滇南本草》：\"性寒，味苦。\"","f":"《滇南本草》：\"治牙齿痛，为末涂之。疗鼻渊，祛风，止头疼，除风邪。\"","y":"内服：煎汤，6-10g。外用：适量，研末调敷。","d":"?"},"驴蹄":{"a":"?","s":"味甘；性平","f":"《纲目》：\"悬蹄烧灰敷痈疽，散脓水；和油敷小儿解颅，以瘥为度。\"","y":"内服：煎汤，15-30g；或入丸剂。外用：适量烧灰调敷或干掺。","d":"?"},"兔耳草":{"a":"和气草(《昆明民间常用草药》)，土玉竹、白蝶花(《广西药植名录》)。","s":"性微温，味甘。","f":"温肾壮阳。","y":"1～3钱。","d":"?"},"补血草":{"a":"匙叶草、海赤芍、海罗卜、海金花、土地榆","s":"苦；微咸；性凉\n《新疆中草药手册》：\"味甘，性平，无毒。\"","f":"清热；利湿；止血；解毒。主湿热便血；脱肛；血淋；月经过多，白带；痈肿疮毒\n\n\n《新疆中草药手册》：\"止血散瘀。治功能性子宫出血，宫颈癌及其他出血。\"","y":"","d":"?"},"金耳环":{"a":"土细辛,长花轴细辛,大叶细辛,大叶山茨菇,一块瓦","s":"辛，温，有毒。\n\n①《岭南采药录》：\"甘淡。\"\n\n②《广西中草药》：\"辛，温。\"\n\n③《广西实用中草药新选》：\"辛微苦，温，有小毒。\"\n\n归肺；肝；脾；胃经","f":"散寒，止咳。平喘，止痛。治风寒咳嗽，哮喘，腹中寒痛，龋齿痛，跌打损伤。\n\n①《岭南采药录》：\"理跌打，治毒蛇仿，又能生肌去腐。\"\n\n②《广西中草药》：\"祛风散寒，平喘止咳，行气止痛，解毒消肿。治风寒咳嗽，支气管哮喘，腹寒痛，龋齿痛，毒蛇咬伤，跌打肿痛。\"\n\n③《广西实用中草药新选》：\"熄风开窍。治小儿抽搐。\"","y":"内服：煎汤，0.3～1钱；或入丸、散。外用：捣敷或研末酒调外擦。","d":"性状鉴别 1.金耳环根茎粗短。根丛生，直径2-3mm，灰黄色。叶片展平后呈长卵形、卵形或三角状卵形，长10-15cm，宽6-11cm，先端急尖或渐尖，上面中脉两侧有白色去斑，脉上及边缘有柔毛，下面放大镜下可见颗粒状油点；叶柄有柔毛。可见花，紫褐色，较大，花被管钟状，喉部无膜环。气辛香，有浓烈麻辣味。 2.长茎金耳环根茎细长，节间长6-12cm。根纤细，稀肉质而较粗状。叶片长方状、卵形或卵状椭圆形，上面散生短毛；叶柄无毛。花紫绿色，花被管圆筒状，喉部膜环宽2mm，内壁有纵行脊棱。"},"云实蛀虫":{"a":"黄牛刺虫,黄寮刺虫,天牛幼虫,云实蠹虫","s":"辛；甘；温 　　\n\n归肝；脾经","f":"治小儿疳积，麻疹透发不快，筋骨痛。\n\n①《湖南药物志》：\"治麻毒内陷。\"\n\n②《温岭县药物资源名录》：\"治小儿营养不良，筋骨痛，小儿初生不乳。\"","y":"内服：研末，3-6g；或制成食品。","d":"?"},"大叶千斤拔根":{"a":"天根不倒(《贵州民间药物》)，千斤红(广州部队《常用中草药手册》)。","s":"《贵州民间药物》：\"性温，味甘。\"\n\n入肾经。","f":"祛风湿，活血脉，强筋骨。治风湿骨痛，腰肌劳损，偏瘫，阳痿。\n\n①《贵州民间药物》：\"治肾虚阳痿，泡酒服。\"\n\n②《广西药植名录》：\"祛风活血。治风湿骨痛，疮疥。\"\n\n③广州部队《常用中草药手册》：\"舒筋活络，强腰壮骨。治腰肌劳损，偏瘫痿痹，气虚脚肿，劳伤久咳，咽喉肿痛。\"","y":"内服：煎汤,1～2两；或浸酒。","d":"?"},"麻叶":{"a":"火麻头(《疮科心要》)。","s":"《纲目》：\"辛，有毒。\"","f":"治疟疾，气喘，蛔虫。\n\n①《唐本草》：\"捣叶水绞取汁服五合，主蛔虫；捣敷蝎毒。\"\n\n②《东北药植志》：\"有解痛、麻醉、利尿作用。\"\n\n③《中国药植图鉴》：\"夹入烟草中吸之，治喘息。\"","y":"内服：捣汁，入丸、散。外用：捣敷。","d":"?"},"甘蔗皮":{"a":"?","s":"甘；寒","f":"治小儿口疳，秃疮，坐板疮。","y":"外用：煅存性研末撒或调敷。","d":"?"},"蜂窝草":{"a":"蜂巢草(广州部队《常用中草药手册》)，绣球防风(《文山中草药》)。","s":"广州部队《常用中草药手册》：\"苦辛，温。\"","f":"解表，止咳，通经，明目。治感冒，咳嗽，哮喘，百日咳，闭经，夜盲症，疥癣。\n\n①广州部队《常用中草药手册》：\"驱风解表，止咳化痰。治感冒，咳嗽，风火牙痛，肠胃不适，百日咳。\"\n\n②《文山中草药》：\"解表止咳，明目通经。治感冒，头痛，身窟，支气管哮喘，闭经，消化不良，夜盲症。\"\n\n②《广西药植名录》：\"治疥癣，皮肤病。\"","y":"内服：煎汤，3～5钱。","d":"?"},"肉桂油":{"a":"桂皮油(《中国药典》)。","s":"①《纲目拾遗》：\"性热。\"\n\n②《广西中药志》：\"味甜辛，性温。\"","f":"①《纲目拾遗》：\"功同肉桂。\"\n\n②《广西中药志》：\"芳香健胃，驱风。外用：治风湿及皮肤瘙痒。\"","y":"内服：开水冲，0.2～1分。外用：摩涂。","d":"为黄色或黄棕色的澄明液体。有桂皮的特臭，味甜、辛。露置空气中，或存放日久，其色逐渐变深，质渐浓厚。微溶于水，能溶于相同体积的醇及冰醋酸中。"},"女儿茶":{"a":"岩果紫(《贵州民间药物》)，黄茶根、女儿红(《四川常用中草药》)。","s":"《贵州民间药物》：\"性凉，味涩微苦，无毒。\"","f":"清热，凉血，止血。治吐血，痔血，崩漏，月经不调，痢疾。\n\n①《贵州民间药物》：\"清热，凉血。\"\n\n②南川《常用中草药手册》：\"捣绒敷疮毒。\"\n\n③《四川常用中草药》：\"清热消积，活血通经。治食积，肝经积滞，月经不调，吐血，劳伤，咳嗽，气痛。\"","y":"内服：煎汤，0.3～1两(鲜者1～2两)。","d":"?"},"四方藤":{"a":"宽筋藤、红宽筋藤、春根藤、伸筋藤(《陆川本草》)，蚂蝗藤、软筋藤、风藤(《广西药植名录》)，方藤、红四方藤(《广西中草药》)。","s":"甘，平。\n\n①《陆川本草》：\"甘，寒。\"\n\n②《广西中药志》：\"味微苦，性平。\"\n\n③《广西中草药》：\"味微酸涩，性平。\"","f":"治风湿痛，跌打伤筋。\n\n①《陆川本草》：\"去风湿。治四肢挛急，抽搐，风湿痛，跌打伤筋。\"\n\n②《广西中药志》：\"舒筋活络，去瘀生新。治跌打内伤，筋络拘挛。\"","y":"内服：煎汤，0.3～1两；或浸酒。外用：酒炒敷。","d":"茎呈四角形条状，长50～70厘米，径5～18毫米，稍扭曲，节上有托叶和卷须的残基，节间长7～20厘米，棱上略有翅，表面灰棕色至黑褐色，粗糙；具皮孔、皱纹。质坚韧。断面不整齐，皮部薄，木质部稍带红黄色，密具导管，木部射线极狭，髓部带紫色。"},"茶子饼":{"a":"枯饼、茶枯、茶麸、茶油巴、茶子麸、茶油麸","s":"味辛苦涩\n\n《岭南草药志》:\"味辛苦涩，有小毒。\"","f":"收湿杀虫。治阴囊湿疹，跌打损伤。\n\n①《药性考》:\"烧灰敷疮，亦可下积。\"\n\n②《岭南草药志》:\"祛湿杀虫。治湿疹痛痒。\"","y":"外用:煎水洗或研末调敷。内服:煅存性研末，1～2钱(内服必须煅存性，否则有剧烈催吐怍用)或煎汤。","d":"?"},"人指甲":{"a":"手爪甲、人退、筋退","s":"甘咸，平。\n\n①《日华子本草》：\"平。\"\n\n②《本草蒙筌》：\"甘咸，无毒。\"\n\n③《医林纂要》：\"咸，温。\"","f":"治鼻衄，尿血，喉蛾，目生翳障，中耳炎。\n\n①《本草拾遗》：\"取细末置目中，去翳障。\"\n\n②《本草衍义》：\"治鼻衄，细细刮取，俟血稍定，去瘀血，于所衄鼻中搐之。\"\n\n③《纲目》：\"治破伤中风。\"","y":"内服：入丸、散。外用：研末点目、搐鼻，吹耳。","d":"?"},"母丁香":{"a":"鸡舌香(《抱朴子》)，亭炅独生(《酉阳杂俎))，雌丁香(《本草蒙筌》)。","s":"辛，温。\n\n①《别录》：\"微温。\"\n\n②《药性论》：\"味辛，无毒。\"","f":"温中，散寒。治暴心气痛，胃寒呕逆，风冷齿痛，牙宣，口臭，妇人阴冷，小儿疝气。\n\n①《别录》：\"疗风水毒肿。去恶气，疗霍乱心痛。\"\n\n②陶弘景：\"疗恶核毒肿。\"\n\n③《蜀本草》：\"疗呕逆甚验。\"\n\n④《本耳图经》：\"疗口臭最良，治气亦效。\"","y":"内服：煎汤，0.3～1钱；或研末。外用：研末调敷或作栓剂。","d":"干燥果实呈卵圆形或椭圆形，长约2～3厘米，直径约0.6～1厘米。外表呈褐色，或带有土红色粉末，粗糙，多细皱纹，上端宿萼有4裂片。质坚脆，破之常纵裂为2瓣，内藏少数种子(因种子来成熟，故多已干瘪，不易察见)。气微香，味辛辣。"},"苦荞头":{"a":"荞叶七(《陕西草药》)。","s":"甘苦，平。\n\n①《纲目》：\"甘苦，温，有小毒。\"\n\n②《贵阳民间药草》：\"涩，平，无毒。\"\n\n③《贵州草药》：\"性平，味苦。\"\n\n脾；胃；大肠经","f":"治胃痛，消化不良，痢疾，劳伤，腰腿痛。\n\n①《贵州民间方药集》：\"健胃顾气，祛风除痰。治狂犬咬伤；外治恶疮，虫、蚊咬伤。\"\n\n②《内蒙古中草药》：\"除湿止痛，解毒消肿，健胃。治跌打损伤，腰腿疼痛，疮痈肿毒，消化不良。\"","y":"内服：煎汤，0.3～1两；浸酒或研末。外用：捣敷。","d":"?"},"杠板归":{"a":"蛇倒退,老虎脷,犁头刺。","s":"性寒，味酸。归肺经、膀胱经。","f":"?","y":"0.5～1两；外用适量，鲜品捣烂敷或干品煎水洗患处。","d":"?"},"葱子":{"a":"?","s":"性温，味辛。","f":"补肾明目。用于肾虚、阳痿、目眩。","y":"?","d":"种子三角状扁卵形，有棱线1～2条，长3～4mm，宽2～3mm，表面黑色，多光滑或偶有疏皱纹，凹面平滑。基部有两上突起，较短的突起顶端灰棕色或灰白色，为种脐；较长的突起顶端为珠孔。估轻，质坚硬。气特异嚼之有葱味。"},"鹰不扑":{"a":"小郎伞、鸟不宿(《广西中草药》)，楤木、打散根、百鸟不落、雷公木(《广西实用中草药新选》)。","s":"《广西中草药》：\"味辛，性温，无毒。\"","f":"散瘀消肿，祛风利湿。治跌打损伤，风湿痹痛，胃痛，腹泻，痢疾，白带，痈疽，疔肿。\n\n①《广西中草药》：\"散瘀消肿，祛风湿。治跌打，风湿疼痛。\"\n\n②《广西实用中草药新选》：\"散瘀消肿，抗菌止痛。治跌打损伤，痈，疖，肝炎，肾炎，前列腺炎，急性关节炎，胃痛，腹泻，痢疾，白带。\"","y":"内服：煎汤，3～5钱；或浸酒。外用：煎水洗或捣敷。","d":"?"},"安息香":{"a":"白花榔,拙贝罗香","s":"辛苦，温。\n\n①《唐本草》：\"味辛苦，平，无毒。\"\n\n②《本经逢原》：\"辛苦微甘，平，无毒。\"\n\n③《玉楸药解》：\"味辛苦，性温。\"","f":"开窍，辟秽，行气血。治卒中暴厥，心腹疼痛，产后血晕，小儿惊痫，风痹腰痛。\n\n①《唐本草》：\"主心腹恶气。\"\n\n②《海药本草》：\"主男子遗精，暖肾，辟恶气。\"\n\n③《日华子本草》：\"治血邪，霍乱，风痛，妇人血噤并产后血运。\"\n\n④《纲目》：\"治中恶，劳瘵。\"\n\n⑤《东医宝鉴》：\"辟瘟疫。\"\n\n⑥《本草述》：\"治中风，风痹，风痫，鹤膝风，腰痛，耳聋。\"\n\n⑦《本经逢原》：\"止卒然心痛、呕逆。\"\n\n⑧《本草从新》：\"宣行气血。研服行血下气，安神。\"\n\n⑨《本草便读》：\"治卒中暴厥，心腹诸痛。\"\n\n⑩《中药材手册》：\"治小儿惊痫。\"","y":"内服：研末，1～5分；或入丸、散。外用：烧烟熏。","d":"①苏门答腊安息香\n为植物安息香树的干燥树脂，为球形颗粒压结成的团块，大小不等，外面红棕色至灰棕色，嵌有黄白色及灰白色不透明的杏仁样颗粒，表面粗糙，不平坦。常温下质坚脆，加热即软化。气芳香，味微辛。\n产印度尼西亚。\n\n②越南安息香\n为植物越南安息香的干燥树脂，为微扁圆的泪滴状物或团块。泪滴状物直径约1至数厘米，厚约1厘米。外表面黄棕色或污棕色，内面乳白色。常温下质坚脆，加热则软化。气味与上种相似。\n产越南、泰国等地。\n\n安息香历来依赖进口，据中国医学科学院药物研究所报道，我国的粉背安息香树(分布云南、广西、广东)、青山安息香树(分布广西)、白叶安息香树(分布广西、广东)亦能生产安息香。经定性定量试验结果，除青山安息香树、白叶安息香树二种树脂的总香脂酸含量略低于我国《药典》规定之外，树脂的其他指标及化学鉴别反应均合乎《药典》规定。"},"红药子":{"a":"红药、赤药、朱砂七、黄药子、朱砂莲、猴血七、血三七、毛葫芦","s":"味苦、微涩；性凉。入肺，大肠，肝经。","f":"清热，解毒，止血活血，止痛，抗菌消炎。用于肠炎，痢疾，腰腿痛，便血，崩漏；外用治烧烫伤，疮疖，狂犬咬伤。","y":"内服：煎汤，生品0.5～2钱(制品3～4钱)；或泡酒、研粉冲服。外用：研粉敷。","d":"干燥块根，外皮棕褐色，紧贴，不易剥离。根头部常有残茎疤痕，坚硬，不易破碎。商品常横切成块，径3～6厘米，厚0.8～2.5厘米。断面凹凸不平，土黄色或黄棕色，鲜根断面橘红色或粉红色；有时呈现如何首乌之异形维管束，并有细条状淡黄色纹理。味微香而不苦，嚼之唾液染成黄色，粉末遇碱液立显紫红色反应。\n产陕西、甘肃、河南等地。"},"松油":{"a":"松脂(《唐本草》)，沥油(《纲目拾遗》)。","s":"苦；性温","f":"《纲目拾遗》：\"治疥疮久远不愈。以此油新浴后擦之，或加白矾末少许，和擦。\"","y":"外用：适量，涂擦。","d":"?"},"牛蒡根":{"a":"恶实根、鼠粘根、牛菜","s":"苦，寒。\n\n①《纲目》：\"苦，寒，无毒。\"\n\n②《分类草药性》：\"味甜，性刚。\"\n\n③《四川中药志》：\"性温，味苦涩，无毒。\"\n\n归肺；心经  \n\n《得配本草》：\"入手太阴经。\"","f":"祛风热，消肿毒。治风毒面肿，头晕，咽喉热肿，齿痛，咳嗽，消渴，痈疽疮疥。\n\n①《别录》：\"根、茎疗伤寒寒热，汗出中风、面肿，消渴，热中，逐水。\"\n\n②《药性论》：\"根，细切如豆，面拌作饭食之，消胀壅。又能拓一切肿毒，用根、叶少许盐花捣。\"\n\n③《唐本草》：\"主牙齿疼痛，劳疟，脚缓弱，风毒，痈疽，咳嗽伤肺，肺壅；疝瘕，积血。主诸风，癥瘕，冷气。\"\n\n④《本草拾遗》：\"浸酒去风，又主恶疮。\"\n\n⑤《分类草药性》：\"治头晕，风热，眼昏云翳，耳鸣，耳聋，腰痛，外治脱肛。\"\n\n⑥《贵州民间方药集》：\"治伤暑。\"\n\n⑦《四川中药志》：\"治疥疮。\"","y":"内服：煎汤或捣汁。外用：捣敷、熬膏涂贴或煎水洗","d":"根呈纺锤状，肉质而直，皮部黑褐色，有皱纹，内呈黄白色；味微苦而性粘。"},"丝瓜藤":{"a":"?","s":"味苦；性微寒 \n\n《本草求原》：\"苦，微寒，小毒。\"\n\n归心；脾；肾经 \n\n《本草再新》：\"入心、脾、肾三经。\"","f":"舒筋，活血，健脾，杀虫。治腰膝四肢麻木，月经不调，水肿；齿露，鼻渊，牙宣。\n\n①《纲目》：\"藤及根，治齿匿、脑漏，杀虫解毒。\"\n\n②《本草求原》：\"和血脉，话筋络，滋水，止阴痛，补中健脾，消水肿。治血枯少，腰膝四肢麻木，产后惊风，调经。\"\n\n③《岭南采药录》：\"解暑热。\"","y":"内服：煎汤，1～2两；或烧存性研末。外用：煨存性研末调敷。","d":"?"},"脐带":{"a":"坎气(《本草从新》)。","s":"甘咸，温。\n\n①《本草汇言》：\"甘咸，气温，无毒。\"\n\n②《医林纂要》：\"甘苦咸，温。\"","f":"益肾，纳气，治虚劳羸弱，气血不足，肾虚喘咳。\n\n①《本草拾遗》：\"主疟，烧为灰，饮下之。\"\n\n②《纲目》：\"解胎毒。敷脐疮。\"\n\n③《本草汇言》：\"补肾命，解胎毒，化痘毒。\"\n\n④《本草通玄》：\"充养血气。\"\n\n⑤《饮片新参》：\"治虚劳，纳肾气，定喘咳，敛汗。\"","y":"内服：研末，2～6分；入丸剂或煎汤。","d":"干燥的脐带，呈细长条状，淡黄或黑棕色，长10～15厘米，内有2个动脉管和一个静脉管，质坚韧，不易拆断。气微腥。"},"萝芙木":{"a":"山辣椒、山马蹄、山胡椒、萝芙藤(《中国药植志》)，矮青木、羊屎子、青辣椒、塘婢粘，野辣椒(《广西野生资源植物》)，假辣椒、鱼胆木、羊姆奶、毒狗药(《广西药植图志》)，假鱼胆、火烙木(《南宁市药物志》)：万药归家(《广西中药志》)，通骨消、甘榕木、刀伤药、三叉虎。","s":"苦，寒。\n\n①《广西药植图志》：\"味苦，性寒，有小毒。\"\n\n②《南宁市药物志》：\"苦甘，凉，无毒。\"\n\n③《贵州草药》：\"性平，味咸微辛。\"","f":"清风热，降肝火，消肿毒。治感冒发热，咽喉肿痛，高血压头痛眩晕，痧症腹痛吐泻，风痒疮疥。\n\n①《中药形性经验鉴别法》：\"清热。治头痛。\"\n\n②《南宁市药物志》：\"退热，消炎，利尿，抗高血压。治热病斑疹，头痛。\"\n\n③《广西中药志》：\"泻肝降火。治高血压，头痛，风热痧气。\"","y":"内服：煎汤，0.5～1两。","d":"干燥根呈圆锥形，支根为圆柱形，弯曲而略扭转，上端直径约1～2厘米，下端细至0.5厘米以下，长15～30厘米或更长，多有支根。外表面灰棕色至灰黄色.有不规则而纵长的隆起和纵沟。栓皮较松，易于脱落。质坚硬，不易折断，折断面不平坦；横切面射线极纤细，微带芳香，味苦，皮部较木质部更苦。\n产云南、广西等地。"},"柑核":{"a":"?","s":"苦，温，无毒。","f":"主肾疰腰痛，膀胱气痛，小肠疝气，卵肿偏坠。","y":"内服:煎汤，2～3钱；或研末。","d":"?"},"猪胰":{"a":"?","s":"①《本草图经》：\"寒。\"\n\n②《纲目》：\"甘，平，微毒。\"","f":"益肺，补脾，润燥。治肺损咳嗽、咯血，肺胀喘急，脾虚下痢，乳汁不通，手足皲裂。\n\n①《药对》：\"通乳汁。\"\n\n②《本草拾遗》：\"主肺痿咳嗽，和枣肉浸酒服之，亦能主痃癖羸瘦。\"\n\n③《本草图经》：\"主肺气干胀喘急，润五脏，去皴、疱、酐蹭，并肪膏。并杀斑猫、地胆、亭长等毒。\"\n\n④《本经逢原》：\"同胡黄连等药，治霉疮。\"\n\n⑤《随息居饮食谱》：\"润燥，涤垢化痰，运食清胎，泽颜止嗽。\"","y":"内服：煮食或煎汤。外用：捣涂。","d":"?"},"母猪藤":{"a":"过路边、蜈蚣藤。","s":"?","f":"捣敷，治骨折。","y":"?","d":"?"},"山枝根":{"a":"?","s":"甘苦辛，凉。\n\n广州部队《常用中草药手册》：\"甘苦辛，微温。\"","f":"补肺肾，祛风湿，活血通络。治虚劳喘咳，遗精早泄，失眠，头晕，高血压病，风湿性关节疼痛，小儿瘫痪。\n\n①广州部队《常用中草药手册》：\"活血通络，解痉止痛。治风湿性关节炎，坐骨神经痛，跌打骨折，小儿麻痹后遗症，产后风瘫，心胃气痛，牙痛。\"\n\n②《广西植物名录》：\"祛风活络，消肿解毒，活血止痛。治风湿性关节炎，跌打骨折，产后风瘫，胃痛，毒蛇咬伤，疮疖肿毒。\"\n\n③《常用中草药配方》：\"治肾虚遗精，多年哮喘，虚劳咳嗽，神经衰弱。\"","y":"内服：煎汤，2～5钱。","d":"?"},"金莲花":{"a":"旱金莲(《五台山志》)，金梅草(《山西通志》)，旱地莲、金芙蓉(《纲目拾遗》)，金疙瘩(《山西中药志》)。","s":"《纲目拾遗》：\"味苦，性寒，无毒。\"","f":"清热解毒。治上感，扁桃体炎，咽炎，急性中耳炎，急性鼓膜炎，急性结膜炎，急性淋巴管炎，口疮，疔疮。\n\n①《山海草函》：\"治疔疮大毒，诸风。\"\n\n②《纲目拾遗》：\"治口疮，喉肿，浮热牙宣，耳疼，目痛，明目，解岚瘴。\"\n\n③《河北中药手册》：\"清热解毒。\"","y":"内服：煎汤，1～2钱。外用：煎水含漱。","d":"干燥的花朵形状不规则，通常带有灰绿色的花柄，长1.5厘米左右。萼片与花瓣呈金黄色，花瓣编成线状，雄蕊黄白色，多数。气浓香，味微苦。以身干、色金黄、不带杂质者为佳。\n产山西等地。"},"红田乌草":{"a":"红节节草。","s":"甘微酸，凉，无毒。","f":"清热解毒，凉血止血，消积逐瘀。","y":"?","d":"?"},"寸金草":{"a":"?","s":"辛微苦，凉。","f":"清热平肝。治牙痛。","y":"内服：煎汤，3～5钱。","d":"?"},"鸡嗉":{"a":"鸡喉咙(《卫生易简方》)。","s":"味甘；性平","f":"治噎膈不通，小便不禁，发背肿毒。\n\n《纲目》：\"治小便不禁，及气噎，食不消。\"","y":"内服：煮食，适量，或研末。外用：适量，焙研撒或调搽。","d":"?"},"漆姑草":{"a":"漆姑(陶弘景)，珍珠草(《滇南本草》)，瓜槌草、牛毛粘(《植物名实图考》)，地松、匿鼻药(《贵州民间方药集》)，大龙叶(《贵州草药》)，羊儿草(南川《常用中草药手册》)。","s":"苦辛，凉。\n\n①《四川中药志》：\"性凉，味苦，无毒。\"\n\n②《湖南药物志》：\"酸甘。\"","f":"治漆疮，秃疮，痈肿，瘰疬，龋齿，小儿乳积，跌打内伤。\n\n①陶弘景：\"疗漆疮。\"\n\n②《滇南本草》：\"治面寒疼。新瓦焙干为末，热烧酒服。\"\n\n③《植物名实图考》：\"利小便。治小儿乳积。\"\n\n④《国药的药理学》：\"绞取其汁，治恶疮、秃疮及漆疮，又疗龋齿。\"\n\n⑤《贵州民间方药集》：\"外用治痈肿、疮毒；口含治虫牙；塞鼻治鼻匿。\"\n\n⑥《四川中药志》：\"提脓拔毒；治瘰疬结核。\"","y":"内服：煎汤，3～5钱：或研末。外用：捣汁涂或捣敷。","d":"?"},"荔枝":{"a":"离支(《上林赋》)，荔支(《齐民要术》)，丹荔(《纲目》)，火山荔(《生草药性备要》)。丽枝(《纲目拾遗》)，勒荔(《广西中药志》)。","s":"甘酸，温。\n\n\n①《食疗本草》:\"微温。\"\n\n\n②《本草拾遗》:\"酸。\"\n\n\n③《海药本草》:\"甘酸。\"\n\n\n④《开宝本草》:\"甘，平，无毒。\"","f":"生津，益血，理气，止痛。治烦渴，呃逆，胃痛，瘰疬，疔肿，牙痛，外伤出血。\n\n\n①《食疗本草》:\"益智:健气，\"\n\n\n②《海药本草》:\"主烦渴，头重，心躁，背膊劳闷。\"\n\n\n③《日用本草》:\"生津，散无形质之滞气。\"\n\n\n④《本草衍义补遗》:\"消瘤赘赤肿。\"\n\n\n⑤《纲目》:\"治瘰窃，疗肿，发小/瞳疮。\"\n\n\n⑥《玉楸药解》:\"暖补脾精，温滋肝血。\"\n\n\n⑦《本草从新》:\"解烦渴，止呃逆。\"\n\n\n⑧《医林纂要》:\"补肺，宁心，和脾。开胃。治胃脘寒痛，气血滞痛。\"\n\n\n⑨《泉州本草》:\"壮阳益气，补中清肺，生津止渴，利咽喉。治产后水肿，脾虚下面，咽喉肿痛，呕逆等证。\"","y":"内服:煎汤，5～10枚；烧存性研末或浸酒。外用:捣敷或烧存性研末撒。","d":"?"},"薜荔根":{"a":"?","s":"苦，平。","f":"祛风除湿，舒筋通络。治头痛眩晕，关节风湿痛，产后风。","y":"内服：煎汤，1～2两。","d":"?"},"红三七":{"a":"扭子七(《四川中药志》)，九节犁、九节雷、赶山鞭、蜈蚣七、伞墩七、螺丝七(《陕西中草药》)，螺丝三七、血三七(《浙江天目山药植志》)。","s":"①《四川中药志》：\"味涩，性平，无毒。\"\n\n②《陕西中草药》：\"味苦涩，性凉。\"\n\n肝；脾经","f":"散血，止血，行气，调经。治跌打损伤，劳伤吐血，便血，崩漏，月经不调。\n\n①《四川中药志》：\"散血行气。治跌打损伤及五劳七伤。\"\n\n②《陕西中草药》：\"收敛止血，活血调经，止痛生肌。治跌打损伤，外伤出血，便血，崩漏，月经不调，淋症，白带，红白痢疾，大骨节病。\"","y":"内服：煎汤，3～5钱；或浸酒、研末。","d":"干燥根茎近圆柱形，根头处稍粗壮，外表棕黑色，粗糙凹凸不平、具节，节上有明显疙瘩突起，须根黑色，卷曲而长。质坚硬，断面粉红色至棕红色。气微，味淡微涩。\n产四川、陕西等地。"},"棉花子":{"a":"木棉子(《本草经疏》)，棉花核(《兰台轨范》)。","s":"《本草经疏》：\"辛，热，有毒。\"","f":"温肾，补虚，止血。治阳痿，睾丸偏坠，遗尿。痔血，脱肛，崩漏，带下。\n\n①《本经逢原》：\"烧存性，解梅疮毒，痔漏，脱肛，下血，每服半两，黑豆淋酒服之。\"\n\n②《药性考》：\"补虚，暖腰，治损。\"\n\n③《现代实用中药》：\"有促进母乳分泌之效。\"\n\n④《民间常用草药汇编》：\"温肾，止痛。治白带，并治小儿遗尿。\"","y":"内服：煎汤，2～4钱；或入丸、散。外用：煎水熏洗。","d":"?"},"乌药叶":{"a":"蒡箕茶(《医林纂要》)。","s":"辛；温","f":"温中，理气，止痛。治腹中寒痛，小便滑数，食积，风湿关节痛。\n\n①《本草拾遗》：\"炙研煎饮代茗，补中益气，止小便滑数。\"\n\n②《本草蒙筌》：\"下气。\"\n\n③《医林纂要》：\"温中燥脾，消食杀蛔。治腹中寒痛。\"","y":"内服：煎汤。外用：捣敷。","d":"?"},"丝瓜络":{"a":"天萝筋、丝瓜网、丝瓜壳、瓜络、絮瓜瓤、天罗线、丝瓜筋、丝瓜瓤、千层楼、丝瓜布","s":"甘，平。\n\n①《本草便读》：\"味甘，性寒。\"\n\n②《南宁市药物志》：\"甘，平，无毒。\"\n\n归肺；肝；胃经","f":"通经活络，清热化痰。治胸胁疼痛，腹痛，腰痛，睾丸肿痛，肺热痰咳，妇女经闭，乳汁不通，痈肿，痔漏。炭：能止血。治便血、血崩。\n\n①《医林纂要》：\"凉血渗血，通经络，托痘毒。\"\n\n②《本草再新》：\"通经络，和血脉，化痰顺气。\"\n\n③《分类草药性》：\"治乳肿疼痛，火煅存性冲酒服。研末调香油涂汤火伤。\"\n\n④《现代实用中药》：\"通乳汁，发痘疮。治痈疽不敛。作黑烧内服，治肠出血，赤痢，子宫出血，睾丸炎肿，痔疮流血等。\"\n\n⑤《陆川本草》：\"凉血解毒，利水去湿。治肺热痪咳，热病谵妄，心热烦躁，手足抽搐。\"","y":"内服：煎汤，1.5～3钱；或烧存性研末。外用：煅存性研末调敷。","d":"①丝瓜络\n呈长圆筒形或长棱形，略弯曲，两端较细。长约25～60厘米，中间直径约6～8厘米。表面白色或黄白色，全体系由多层丝状纤维交织而成的网状物。体轻，质坚韧，不能折断。横切面可见子房3室，形成3个大空洞，内有少数残留的黑色种子。气无，味淡，以筋细、质韧。洁白、无皮者为佳。\n全国各地均产，以浙江、江苏所产者质量为好。\n\n②丝瓜布\n外形呈长圆筒形，一端具坚韧的果柄，果皮灰黄色，上有10条纵向棱线，果皮质脆。其余均与丝瓜络相似。\n主产广东。"},"芨芨草":{"a":"枳芨草(《内蒙古中草药》)，枳机草、席箕草(《中国沙漠地区药用植物》)。","s":"《内蒙古中草药》：\"味甘淡，性平。\"","f":"治尿路感染，尿闭。\n\n①《内蒙古中草药》：\"利尿。治尿路感染，尿闭。\"\n\n②《中国沙漠地区药用植物》：\"茎：利尿清热。花：止血。\"","y":"内服：煎汤，茎、花0.5～1两。种子3～5钱。","d":"?"},"臭梧桐":{"a":"海州常山(《本草图经》)，海桐(《群芳谱》)，臭桐(《群芳谱》)，臭芙蓉(《百草镜》)，地梧桐(《养生经验合集》)，秋叶、八角梧桐(汪连仕《采药书》)，凤眼子(《质问本草》)，泡花桐(《中国树木分类学》)，楸叶常山(《现代实用中药》)，矮桐子、岩桐子(《中国药植志》)。","s":"《现代实用中药》：\"味苦带甘。\"","f":"祛风湿，降血压。治风湿痹痛，半身不遂，高血压病，偏头痛，疟疾，痢疾，痔疮，痈疽疮疥。\n\n①《本草图经》：\"治疟。\"\n\n②《纲目拾遗》：\"洗鹅掌风、一切疮疥，煎汤洗汗斑，湿火腿肿久不愈者，同菴闾子浸酒服。并能治一切风湿，止痔肿，煎涌服，治臁疮，捣烂作饼，加桐油贴，\"\n\n③《岭南采药录》：\"治一切痈疽，捣烂罨之。\"\n\n④《现代实用中药》：\"治温疟，胸中痰结，一切风湿，四肢脉络壅塞不舒，消臌，止痢。\"\n\n⑤《上海常用中草药》：\"祛风湿，止痛，降血压。\"","y":"内服.煎汤，3～5钱(鲜者1～2两)：浸酒或入丸、散，外用：煎水洗，研末调敷或捣敷。","d":"干燥小枝类圆形，或略带方形，棕褐色，具黄色点状皮孔，密被短柔毛。叶对生，广卵形以至椭圆形，上面灰绿色，背面黄绿色，具短柔毛，叶片多巳皱缩、卷曲，或破碎；叶柄密被短柔毛。花多已枯萎，黄棕色，有长梗，雄蕊突出花冠外；已结实者，花萼宿存，枯黄色，内有果实一枚，灰褐色，三棱状卵形，有皱缩纹理，枝叶质脆易折断，小枝断面黄白色，中央具白色的髓，髓中有淡黄色分隔。有特异臭气，味苦而涩。以花枝干燥，带有绿色的叶，无杂质者为佳。\n主产江苏、安徽等地。"},"桦菌芝":{"a":"木蹄","s":"淡微苦，性平。","f":"消积，化瘀，抗癌。治小儿食积，食管癌，胃癌，子宫癌。","y":"内服：煎汤，4～5钱。","d":"?"},"天仙子":{"a":"莨菪子、莨菪实、牙痛子、小颠茄子、米罐子、熏牙子","s":"味苦辛，性温，有毒；归心、肝、胃经。\n\n①《本经》：\"味苦，寒。\"\n\n②《雷公炮炙论》：\"大毒。\"\n\n③《别录》：\"甘，有毒。\"\n\n④《药性论》：\"味苦辛。微热，有大毒。\"","f":"止痛，定惊，固脱。用于胃腹痛、牙痛、神经痛、气喘、癔病、久痢、痈肿恶疮\n.①《本经》：\"主齿痛出虫，肉痹拘急。\"\n\n②《别录》：\"疗癫狂风痫，颠倒拘挛。\"\n\n③《药性论》：\"生能泻人，热炒止冷痢，炒焦研细末，治下部脱肛。\"\n\n④《本草拾遗》：\"主痃癖，除邪逐风。\"\n\n⑤《日华子本草》：\"烧熏虫牙，洗阴汗。\"","y":"内服：煎汤，0.6-1.2g;散剂，0.06-0.6g。外用：适量，研末调敷衍;煎水洗;或烧烟熏。","d":"理化鉴别\n\n\n　　1、取本品粉末0.5g，置试管中，加乙醚5ml与10%，氨溶液数滴，密寒，振摇，2h后，吸取醚液少量于栽玻片上，挥干醚液，滴加碘化铋钾试液2滴，数分钟后，置显微镜下观察，可见黄紫色，似飞鸟状结晶。(检查莨菪类生物碱)\n\n\n　　2、取本品粉末0.5g，置试管中，加浓氨试液0.5ml，混匀，再加氯仿5ml，密寒，振摇0.5h，滤过。滤液蒸干，残渣加氯仿溶解，吸取溶液5滴，置水浴上蒸干，加发烟硝酸4滴，蒸干，残渣加无水乙醇1ml与氢氧化钾1小粒，显紫色。(检查莨菪类生物碱)\n\n\n　　3、薄层色谱 取本品粉末1g，加石油醚(30-60℃)10ml，超声处理15min，弃去石油醚液，同上再处理1次，药渣挥干溶剂，加浓氨试液与乙醇的等量混合溶液2ml湿润，加氯仿20ml，超声处理15min，滤过。滤液蒸干，残渣加无水乙醇0.5ml溶解，作供试品溶液。另取硫酸阿托品、氢溴酸东莨菪碱加无水乙醇制成每1ml各含1mg的混合溶液，作对照品溶液，吸取上述2种溶液5μm，分别点于同一硅胶G薄层板上，以醋酸乙酯-甲醇-浓氨试液(17：2：1)展开，取出，晾干，依次喷碘化铋钾与亚硝酸钠乙醇试液。样品色谱在与对照品色谱相应位置上显相同的两个桔红色斑点。"},"大青草":{"a":"青泽兰,臭根,野地骨,土地骨皮","s":"味苦；性寒 \n\n《苏州本产药材》：\"苦，大寒。\"","f":"清热，解毒，祛风，除湿。治乙脑，流脑，感冒高热，头痛，肠炎，痢疾，黄疸，齿痛，鼻衄，咽喉肿痛。 \n\n①《植物名实图考》：”治偏头风。” \n\n②《广西野生资源植物》：”洗烂疮。”\n \n\n③《福建民间草药》：”消炎镇痛，除湿祛风。”\n \n④《陆川本草》：”凉血退热，解皮肤热毒。治斑疹，血瘙，蜈蚣咬伤。” \n\n⑤《衡山民间草药》：”治痢疾，麻疹后之口腔炎，热病头痛。”\n \n⑥广州部队《常用中草药手册》：”清热泻火，凉血解毒，散瘀止血。治肠炎，菌痢，咽喉炎，扁桃腺炎，腮\n腺炎，感冒发热，齿龈出血。”","y":"内服：煎汤，3～5钱(鲜者1～2两)。外用：捣敷或煎水洗。","d":"?"},"九节菖蒲":{"a":"小菖蒲、外菖蒲、节菖蒲、鸡爪莲、九节离、穿骨七","s":"辛，微温。\n\n《药材资料汇编》：\"辛，温，无毒。\"","f":"开窍，豁痰，祛风，宣湿，健胃，解毒。治热病神昏谵语，癫痫痰厥，气闭耳聋，多梦健忘，胸痞呕恶，风湿痹痛，疮疥肿毒。\n\n①《药材资料汇编》：\"辟秽，开窍，宣气，逐痰。治神经衰弱，消化不良，风寒湿痹。\"\n\n②《中药志》：\"开窍醒神，散湿浊，开胃；外用解毒杀虫。治热病神昏谵语，癫痫发狂，下痢；因湿浊阻于胃中而致呕吐不食等。外敷治痈疽疥癣。\"\n\n③《中药材手册》：\"开心通窍，祛风湿，除痰消积。治心气不足，健忘，惊痫，耳聋，咳逆，烦闷，心腹痛，霍乱，风湿痹。\"","y":"内服：煎汤，0.8～1.5钱；或入丸、散。外用：煎水洗浴或研末调敷。","d":"干燥根茎略呈纺锤形，微弯曲，偶有分歧；长l～6厘米，中部直径约3～7毫米。表面黄白色至棕色，上具多数横向半环状突起的鳞叶痕，交互排列成节状，并可见细小根痕。质坚脆，易折断，断面平坦，类白色至浅黄色，粉性，气无，味淡而辛。以淡棕色、断面类白色、质坚、肥大者为佳。\n\n主产陕西、河南、山西等地.\n\n九节菖蒲在历代本草书籍中均指天南星科植物石菖蒲的根茎，所谓\"九节\"，系描述根茎之环节紧密，如《别录》云：\"一寸九节者良\"，与本品显著不同。参见\"石菖蒲\"条。"},"猫肉":{"a":"猫、猫狸、家狸、乌圆","s":"甘酸、温。\n\n①《纲目》：\"甘酸，温，无毒。\"\n\n②《医林纂要》：\"酸甘，平。\"\n\n③《四川中药志》：\"性温，味甘酸咸，无毒。\"","f":"治虚劳，风湿痹痛，瘰疬，恶疮，烫伤。\n\n①《纲目》：\"治劳疰，鼠瘘。\"\n\n②《本草求真》：\"补血，治痨疰，又治瘰疬。\"\n\n③《四川中药志》：\"治风湿痹痛，散瘰疬结核，补虚劳，消虫胀，疗汤火伤。\"","y":"内服：煮食或煅存性研末。外用：烧灰研末敷。","d":"?"},"松根":{"a":"松树根","s":"味苦；性温。归肺、胃经。\n《日华子本草》：\"味苦，温，无毒。\"","f":"祛风除湿；活血止血。。主风湿痹痛；风疹瘙痒；白带；咳嗽；跌打吐血；风虫牙痛。\n\n\n①《日华子本草》：\"松根白皮，补五劳，益气。\"\n\n②广州部队《常用中草药手册》：\"治风湿骨痛，跌打瘀痛。\"","y":"内服：煎汤，30-60g；外用：适量，鲜品捣敷；或煎水洗。","d":"?"},"猕猴桃":{"a":"藤梨、木子，猕猴梨(《开宝本草》)，羊桃(《医心方》)，阳桃(《日用本草》)，毛叶猕猴桃(《经济植物手册》)，大红袍(《贵州民间方药集》)，大零核、猴仔梨(《福建民间草药》)，杨桃(《江西草药》)，绳梨、金梨、野梨(《浙江民间常用草药》)，山洋桃(《贵州草药》)，狐狸桃(江西《草药手册》)。","s":"甘酸，寒。\n\n①崔禹锡《食经》：\"味甘，冷。\"\n\n②《福建民间草药》：\"甘，寒，滑，无毒。\"","f":"解热，止渴，通淋。治烦热，消渴，黄疸，石淋，痔疮。\n\n①崔禹锡《食经》：\"和中安肝。主黄疸，消渴。\"\n\n②《食疗本草》：\"取瓤和蜜煎，去烦热，止消渴。\"\n\n③《本草拾遗》：\"主骨节风，瘫缓不随，长年变白，痔病，调中下气。\"\n\n④《开宝本草》：\"止暴渴，解烦热，下石淋。热壅反胃者，取汁和生姜汁服之。\"","y":"内服：煎汤，1～2两。","d":"?"},"大透骨草":{"a":"?","s":"微苦，微温。","f":"祛风除湿，舒筋活络。治风湿关节疼痛。","y":"内服：煎汤，3～5钱；或浸酒。外用：水煎洗。","d":"?"},"狗肝":{"a":"狗","s":"《医林纂要》：\"甘苦咸，温。\"","f":"治脚气，下痢腹痛。\n\n《本草拾遗》：\"主脚气攻心，作生姜醋进之，当泄。先泄者勿服之。\"","y":"内服：煮食。","d":"?"},"升药":{"a":"灵药(《外科大成》)，三白丹(《张氏医通》)，三仙散(《吴氏医方汇编》)，小升丹、三仙丹(《疡医大全》)，升丹(《药籢启秘》)。","s":"有毒。","f":"搜脓，拔毒，去腐，生肌。治痈疽，疔疮，梅毒，下疳，一切疮疡肉暗紫黑，疮口坚硬，久不收口。\n\n\n①《张氏医通》：\"治霉疮结毒。\"\n\n\n②《吴氏医方汇编》：\"治一切阳症腐烂太甚者。\"\n\n\n③《沈氏经验方》：\"治痈疽烂肉未清，脓水未净。\"\n\n\n④《痴医大全》：\"提脓长肉。\"\n\n\n⑤《集成良方三百种》：\"治痈疽疔毒溃后。\"","y":"外用：合他药研末，干撒、调敷或作药拈。","d":"①红升(《外科传薪集》)\n\n\n又名：三仙红升丹(《集成良方三百种》)，红粉。为橙红色或橙黄色块状物或粉末。块状者，厚约2毫米，一面光滑，略有光泽，一面较为粗糙，呈蜂窝状。质重而脆。气无，露于日光下颜色变深。以红色、片状、有光泽者为佳。\n\n\n②黄升(《疡科遗编》)\n\n\n又名：黄升丹(《疡科遗编》)。为黄色或橙黄色的块状物或粉末，余同红升。以黄色、片状，有光泽者为佳。\n\n\n上述药材，各地均有制造，以河北、湖北、湖南、江苏等地产量较大。"},"赛葵":{"a":"黄花棉(《广西中草药》)，黄花草(《全展选编·传染病》)。","s":"《广西中草药》：\"微甘，凉。\"","f":"《广西中草药》：\"清热利湿，去瘀消肿。治黄疸，痢疾，疟疾，小儿食滞，肺热咳嗽，喉头炎，疮疖，跌打肿痛。\"","y":"内服：煎汤，3～5钱(鲜者2～4两)。外用：捣敷。","d":"?"},"假连翘叶":{"a":"番仔刺、篱笆树、洋刺、花墙刺、桐青、白解","s":"甘微辛，温，有小毒。","f":"活瘀消肿。","y":"外用：适量；捣敷","d":"?"},"柠檬":{"a":"黎檬子(《东坡志林》)，黎朦子(《桂海虞衡志》)，黎檬子(《岭外代答》)，宜母子、里木子、梨橡干(《事物绀珠》)，药果(《广东新语》)，檬子、梦子(《通雅》)，宜濛子、宜母果(《岭南杂记》)，柠果(《南宁市药物志》)。","s":"《桂海虞衡志》:\"味极酸。\"","f":"生津，止渴，祛暑，安胎。咽痛口干，胃脘胀气，高血压，心肌梗塞，不思饮食。\n\n①《食物考》:\"浆饮渴瘳，能辟暑。孕妇宜食，能安胎。\"\n\n②《粤语》:\"以盐腌，岁久色黑，可治伤寒痰火。\"\n\n③《岭南随笔》:\"治哕。\"\n\n④《纲目拾遗》:\"腌食，下气和胃。\"","y":"内服:绞汁饮或生食。","d":"?"},"护心草":{"a":"附心草(《分类草药性》)。","s":"①《分类草药性》：\"性热。\"\n\n②《四川中药志》：\"味淡辛，性平，无毒。\"","f":"①《分类草药性》：\"养血调经。\"\n\n②《四川中药志》：\"行气调经。治妇女月经痛及经行愆期，或一月二至三次者。\"","y":"内服：煎汤，0.4～1两；或研末。","d":"?"},"蟛蜞菊":{"a":"马兰草、蟛蜞花、路边菊(《生草药性备要》)，水兰(《广西药植名录》)，卤地菊、黄花龙舌草、黄花曲草(《福建中草药》)。","s":"①《本草求原》：\"甘淡，微寒。\"\n\n②《福建中草药》：\"微咸，凉。\"","f":"清热，解毒，祛瘀，消肿。治白喉，百日咳，痢疾，痔疮，跌打损伤。\n\n①《生草药性备要》：\"散疮，清热，咄脓，穿疮，并疬、痔。其根能脱牙。\"\n\n②《广西药植名录》：\"破瘀，消肿。治跌打，腹痛，风湿。\"\n\n③《福建中草药》：\"清热解毒。治白喉，百日咳，肺痨发热咳嗽，痢疾，肝火旺盛，烦热不眠，咽喉肿痛，齿龈炎。\"","y":"内服：煎汤，0.5～1两。外用：捣敷或捣汁含漱。","d":"理化鉴别 取粉末2g，加甲醇20ml，回流30min，滤过滤液用石油醚提取后供下列试验：㈠取1mol/L盐酸-羟胺甲醇液0.5ml，置小试管中，加供试液2ml，再加2mol/L氢氧化钾甲醇液使Ph ＜11，在水浴上加热煮沸2min，冷却后加5%盐酸使pH＜3，再加2滴1%三氯化铁深液显污红色。（检查内酯）。㈡取供试液2ml于试管中加镁粉知量，加浓盐酸1ml，水浴加热5min,，显棕以或褐红色。（检查黄酮）"},"鸡血":{"a":"?","s":"咸，平。\n\n①《别录》：\"平，无毒。\"\n\n②《纲目》：\"咸，平，无毒。\"\n\n③《医林纂要》：\"鸡冠血：咸，温。\"\n\n④《本草再新》：\"鸡血：味辛，性热，无毒。鸡冠血：味甘，性温，无毒。\"","f":"祛风、活血、通络。治小儿惊风，口面歪斜，痿痹，折伤，目赤流泪，痈疽疮癣。\n\n①《别录》：\"乌雄鸡血：主踒折骨痛及痿痹。黑雌鸡血：主中恶腹痛及踒折骨痛，乳难。乌雄鸡冠血：主乳难。\"\n\n②孟诜：\"目泪出不止者，以三年乌雄鸡冠血敷目睛上，日三度。\"\n\n③《本草拾遗》：\"马咬疮及剥驴马伤手，热鸡血及热浸之。\"\"雄鸡胁血：涂白癜风，疬疡风。\"\n\n④《痘疹正宗》：\"鸡冠血和酒服，发痘最佳。\"\n\n⑤《纲目》：\"热血服之，主小儿下血及惊风，解丹毒，安神定志。\"\"乌雄鸡冠血亦点暴赤目。丹鸡者并疗经络间风热；涂颊治口歪不正；卒饮之治小儿卒惊客忤；涂诸疮癣、蜈蚣、蜘蛛毒，马啮疮，百虫入耳。\"\n\n⑥《本草再新》：\"治心血枯，肝火旺，利关节，通经络。\"\"鸡冠血兼理血分气分，无血可生，血多可破；气弱可补，气逆可舒；补中益肾，利水通经。\"","y":"内服：热饮。外用：涂敷。","d":"?"},"地瓜藤":{"a":"地石榴(《滇南本草》)，过江龙、土瓜(《草木便方》)，野地瓜(《分类草药性》)，地蜈蚣(《天宝本草》)，牛马藤、过石龙(《贵州民间方药集》)，地枇杷、过山龙(《贵州民间药物》)，铺地蜈蚣(《四川中药志》)，牛托鼻、鸠草、冬枇杷、青风月、风藤、拦路虎、地木耳(《湖南药物志》)，野地瓜藤(《贵州草药》)，霜坡虎、爬地牛奶、钻地龙(《广西中草药》)，遍地金、地板藤、母猪地瓜、匐地蜈蚣、万年扒(《云南中草药》)","s":"苦，寒。\n\n①《贵州民间药物》：\"性凉。\"\n\n②《四川中药志》：\"性寒，味苦，无毒。\"\n\n③《云南中草药》：\"苦涩，凉。\"","f":"清热，利湿，活血，解毒。治风热咳嗽，痢疾，水肿，黄疸，风湿疼痛，痔疮出血，经闭，带下，小儿消化不良，跌打损伤，无名肿毒。\n\n①《分类草药性》：\"叶，包疮毒。\"\n\n②《天宝本草》：\"治红白痢症。\"\n\n③《贵州民间方药集》：\"可去风湿麻木，治筋骨疼痛，活血生血，消肿去毒，利尿解热，民间用为跌打损伤止痛药。\"\n\n④《四川中药志》：\"利小便，消湿热黄肿，通月闭，止白带；治痔疮出血及牙龈肿痛。\"\n\n⑤《湖南药物志》：\"清肺，解毒，利尿消肿。治水肿，腹水。\"\n\n⑥《贵州草药》：\"清热散毒，祛风除湿，止咳。治地瓜疮(多生于耳朵周围，形似地瓜果)。\"\n\n⑦《广西中草药》：\"健脾利湿，清肺止咳。治小儿消化不良，湿热黄疸，风热咳嗽，风湿骨痛。\"\n\n⑧《云南中草药》：\"收敛止痢。治痢疾，腹痛，瘰疬，毒蛇咬伤，骨折。\"","y":"内服：煎汤，3～8钱。外用：捣敷。","d":"?"},"千里找根":{"a":"小赖藤(《云南中草药选》)，绿包藤，癞浆包藤(《云南恩茅中草药选》)，克赛麻奈(傣名)","s":"《云南中草药选》：\"苦，凉。\"","f":"通经活血，清热解毒。治骨折，挫伤，刀伤，痢疾，腹胀，痈疖肿毒。\n\n①《云南中草药选》：\"通经活血，收口生肌。\"\n\n②《云南思茅中草药选》：\"清热解毒，驱虫。\"","y":"?","d":"?"},"白背三七":{"a":"大肥牛,枪刀药,清心菜,土生地,白仔菜药,散血姜,土田七,白血皮菜,胡豆七,胖儿草,三百棒,地滚子,磊救驾,百步还阳,石三七,树三七,大绿叶,接骨丹,玉枇杷,金丝枇杷,白东枫,厚面皮,鸡菜,白番苋,白红菜,疔拔,叉花三七,大晕病药","s":"甘，凉。\n\n①《广西药植图志》：\"味甘，性凉。\"\n\n②《广西中药志》：\"味淡，性平，无毒。\"\n\n③《云南中草药》：\"咸微辛，寒，有毒。\"\n\n入肺，心二经。","f":"清热凉血，散瘀消肿。治支气管炎，肺结核，崩漏痈肿，烫伤。跌打损仿，刀伤出血。\n\n①《广西药植图志》：\"煮汤内服，凉血解毒；捣烂外敷跌打伤，消肿散瘀；又用以敷热痈，散痛消肿。经九蒸十晒，浸酒或煎汤服补血。\"\n\n②《云南中草药》：\"清热消炎，舒筋活络。治骨折，外伤出血，支气管炎，肺结核，崩漏。\"","y":"内服：煎汤。2～3钱；或浸酒。外用：捣敷或研末调敷。","d":"根茎肥大、肉质，呈团块状，径2～3厘米，新鲜时灰黄色，侧生茎芽多枚，短圆锥状，有的可见环节。折断面灰白色。\n产广西等地。"},"黄蜀葵叶":{"a":"秋葵叶。","s":"①《福建民间草药》：\"甘，寒，滑，无毒。\"\n\n②福州军区《中草药手册》：\"甘，滑，微寒。\"","f":"《福建民间草药》：\"托疮解毒，排脓生肌。\"","y":"外用：适量，鲜品捣敷。内服：煎汤，10-15g，鲜品可用至30-60g。","d":"?"},"白僵蚕":{"a":"僵蚕(《千金方》)，天虫(《药材资料汇编》)，僵虫(《河北药材》)。","s":"辛咸，平。\n\n①《本经》：\"味咸，平。\"\n\n②《别录》：\"辛，平，无毒。\"\n\n③《药性论》：\"微温，有小毒。\"","f":"祛风解痉，化痰散结。治中风失音，惊痫，头风，喉风。喉痹，瘰疬结核。风疮瘾疹，丹毒，乳腺炎。\n\n①《本经》：\"主小儿惊痫夜啼，去三虫，灭黑黚，男子阴瘍病。\"\n\n②《别录》：\"女子崩中赤白，产后余痛，灭诸疮瘢痕。\"\"未之，封疔肿，根当自出。\"\n\n③《药性论》：\"治口噤，发汗，主妇人崩中下血不止。\"\n\n④《日华子本草》：\"治中风失音，并一切风疾，小儿客忤，男子阴痒痛，女子带下。\"\n\n⑤《本草图经》：\"治中风，急喉痹，捣筛细末，生姜自然汁调灌之。\"\n\n⑥《医学启源》：\"去皮肤间诸风。\"\n\n⑦《纲目》：\"散风痰结核，瘰疬，头风，风虫齿痛，皮肤风疮，丹毒作痒，痰疟癥结，妇人乳汁不通，崩中下血，小儿疳蚀鳞体，一切金疮，疔肿风痔。\"\n\n⑧《本草正》：\"治小儿疳蚀，牙龈溃烂，重舌，木舌。\"\n\n⑨《玉楸药解》：\"活络通经，驱风开痹。治头痛胸痹，口噤牙疼，瘾疹风瘙；烧研酒服，能溃痈破顶，又治血淋崩中。\"","y":"内服：煎汤，1.5～3钱；或入丸、散。外用：研末撒或调敷。","d":"呈圆柱形，多弯曲而皱缩。长约2～5厘米，直径4～7毫米。表面灰白色或现浅棕色，多被有白色粉霜。头、足及各节均清晰可辨。体外常杂有丝团缠绕。头部黄褐色，类圆形。足8对，呈突起状。质硬而脆，易折断；断面平坦，色棕、黑不一，多光亮，外层为白色，显粉性，内有4个褐色的亮圈。微有腐臭气，味微咸。以条直肥壮，质坚，色白，断面光者为佳。\n\n此外，用白僵菌接种于蚕蛹，使发病而成僵蛹，可代白僵蚕供药用，参见\"僵蛹\"条。"},"蓼子草":{"a":"小毛蓼(《种子植物名称》)，小蓼子草、红蓼子(《四川中药志》)。","s":"《四川中药志》：\"性温，味淡微辣，无毒。\"","f":"《四川中药志》：\"散寒活血。治麻疹，羊毛疔，跌损后受寒，阴寒及陈寒。\"","y":"内服：水煎或酒煎，2～5钱。外用：煎水洗。","d":"?"},"狐胆":{"a":"狐","s":"《陆川本草》：\"甘苦，寒。\"","f":"治癫痫，心气痛，疟疾。\n\n①《纲目》：\"辟邪疟，解酒毒。\"\n\n②《陆川本草》：\"泻胆火，治癫痫。\"\n\n③《四川中药志》：\"风干研细兑开水服，治心气痛。\"","y":"内服：研末，0.5～1钱；或入丸剂。","d":"?"},"昙花":{"a":"琼花,凤花,金钩莲","s":"平，淡\n\n《陆川本草》：\"平，淡。\"","f":"清肺，止咳，化痰\n\n《陆川本草》：\"清肺，止咳，化痰。治心胃气痛，吐血，最适于肺结核。\"","y":"内服：煎汤，3～6钱。","d":"?"},"倒赤伞":{"a":"大叶一支箭、刀口药、青皮草、一把箭、一支箭、兔耳防风","s":"辛微苦，温。","f":"祛风散寒，止咳止痢。治风寒咳嗽，肠炎，痢疾。","y":"内服：煎汤，2～5钱。","d":"?"},"鸡子":{"a":"鸡卵(《食疗本草》)，鸡蛋(《随息居饮食谱》)。","s":"甘，平。\n\n①《药对》：\"平。\"\n\n②《药性论》：\"味甘，微寒，无毒。\"\n\n③《本草便读》：\"生凉，熟温。\"","f":"滋阴润燥，养血安眙。治热病烦闷，燥咳声哑，目赤咽痛，胎动不安，产后口渴，下痢，烫伤。\n\n①《本经》：\"主除热火疮，痫痉。\"\n\n②《药性论》：\"治目亦痛。\"\n\n③《食疗本草》：\"治大人及小儿发热，可取卵三颗，白蜜一合，相和服之。\"\n\n④《本草拾遗》：\"益气，多食令人有声。一枚以浊水搅，煮两沸，合水服之，主产后痢。和蜡作煎讲，与小儿食之，止痢。\"\n\n⑤《日华子本草》：\"镇心，安五藏，止惊，安胎。治怀妊天行热疾狂走，男子阴囊湿痒，及开声喉。醋煮，治久痢。和光粉炒干，止小儿疳痢，及妇人阴疮。和豆淋酒服，治贼风麻痹。\"\n\n⑥《日用本草》：\"治汤火疼痛。\"\n\n⑦《随息居饮食谱》：\"补血安胎，濡燥除烦，解毒息风，润下止逆。\"","y":"内服：去壳生服、沸水冲、与他药同煮，或入丸剂。外用：去壳取黄、白，和药调敷。","d":"?"},"苜蓿":{"a":"牧蓿(《尔雅》郭填注)，木粟(《尔雅翼》)，怀风、光风、连枝草(《西京杂记》)，光风草(《纲目》)。","s":"苦，平。\n\n①《别录》：\"味苦，平，无毒。\"\n\n②《千金·食治》：\"苦，平，涩，无毒。·\n\n③《日华子本草》：\"凉。\"\n\n④《本草衍义》：\"微甘，淡。\"","f":"清脾胃，利大小肠，下膀胱结石。\n\n①孟诜：\"利五脏，洗去脾胃间邪气，诸恶热毒。\"\n\n②《日华子本草》：\"去腹藏邪气，脾胃间热气，通小肠。\"\n\n③《本草衍义》：\"利大小肠。\"\n\n④《现代实用中药》：\"治尿酸性膀胱结石。\"","y":"内服：捣汁，3～5两；研末，2～3钱。","d":"?"},"狗屎花":{"a":"一把抓,蓝狗屎花,蓝布裙,附地菜,牛舌头花,狗舌花,龙须草,七星箭,大肥根,莲子叶,绿花心,绿花叶,蓝花参","s":"苦；凉 \n\n《天宝本草》：\"苦，凉。\"","f":"清肺化痰，止血。治咳嗽，吐血，瘰疬，刀伤。\n\n①《四川通志》：\"治脚气，壮筋骨。\"\n\n②《天宝本草》：\"清肺止咳化痰，治气火瘰疬。\"\n\n③《四川中药志》：\"清热，止咳，生肌。治咳嗽，失音，吐血。\"\n\n④成都《常用草药治疗手册》：\"养阴润肺，清热止咳。治肺痨咳嗽，失音，狂犬咬伤。\"","y":"内服：煎汤，1～2两。外用：捣敷。","d":"?"},"理肺散":{"a":"接骨丹、小接骨。","s":"苦，凉。","f":"消炎，续骨。治肺炎，支气竹炎，口腔炎，肺结核，骨折。","y":"内服：煎汤，0.5～1两。外用：研末调敷或鲜品捣敷。","d":"?"},"海蜇":{"a":"石镜,水母,蜡,樗蒲鱼,水母鲜","s":"咸，平。\n\n①《本草拾遗》：\"味咸，无毒。\"\n\n②《纲目》：\"咸，温。\"\n\n③《医林纂要》：\"咸，平，滑。\"","f":"清热，化痰，消积，润肠。治痰嗽，哮喘，痞积胀满，大便燥结，脚肿，痰核。\n\n①《本草拾遗》：\"主生气及妇人劳损，积血，带下；小儿风疾，丹毒，汤火(伤)。\"\n\n②《医林纂要》：\"补心益肺，滋阴化痰，去结核，行邪湿，解渴醒酒，止嗽除烦。\"\n\n③《本草求原》：\"安胎。\"\n\n④《随息居饮食谱》：\"清热消痰，行瘀化积，杀虫止痛，开胃润肠，治哮喘，疳黄，癥瘕，泻痢，崩中带浊，丹毒，癫痫，痞胀，脚气。\"","y":"内服：煎汤，1～2两；或以姜、醋拌食。","d":"?"},"角茴香":{"a":"咽喉草、麦黄草、黄花草、雪里青(《河南中草药手册》)，野茴香(《中国沙漠地区药用植物》)。","s":"苦辛，凉。\n\n①《河南中草药手册》：\"苦，寒。\"\n\n②《中国沙漠地区药用植物》：\"辛，凉。\"","f":"治急性咽喉炎，气管炎咳嗽，目赤肿痛。\n\n①《河南中草药手册》：\"清热，消炎，止痛。\"\n\n②《中国沙漠地区药用植物》：\"泻火，解热，镇咳。\"","y":"内服：煎汤，2～3钱；研末，3～5分。","d":"?"},"白马阴茎":{"a":"白马茎","s":"甘咸，温。\n\n①《本经》：\"味咸，平。\"\n\n②《别录》：\"甘，无毒。\"\n\n③《本草经疏》：\"甘咸，温。\"\n\n归肾经","f":"补肾益气。治阳痿精衰，虚弱羸瘦。\n\n①《本经》：\"主伤中脉绝，阴不起。强志益气，长肌肉，肥健，生子。\"\n\n②《别录》：\"主小儿惊痫。\"\n\n③《药性论》：\"主男子阴痿。\"","y":"内服：入丸剂。","d":"?"},"横经席":{"a":"跌打将军、碎骨莲、皮子黄(广州部队《常用中草药手册》)，梳篦木、独角风(《广西中草药》)。","s":"广州部队《常用中草药手册》：\"微苦，平。\"","f":"①广州部队《常用中草药手册》：\"祛瘀止痛，补肾强腰。治跌打损伤，风湿骨痛，肾虚腰痛。\"\n\n②《广西中草药》：\"治月经不调，痛经。\"","y":"内服：煎汤，0.5～1两。","d":"?"},"黄花远志":{"a":"黄金卵、吊吊黄、黄花鸡骨(《江西草药》)，鸡根、小荷苞、鸡肚子果、荷苞山桂花(《云南中草药》)。","s":"①《江西草药》：\"甘，微温。\"\n\n②《云南中草药》：\"甘辛，平。\"\n入","f":"祛风除湿，补虚消肿，调经活血，治感冒，风湿疼痛，肺痨，水肿，产后虚弱，月经不调，跌打损伤。\n\n①《江西草药》：\"祛痰利窍，安神益智。\"\n\n②《云南中草药》；\"清热解毒，祛风除湿，补虚消肿。治风湿疼痛，跌打损伤，肺痨，水肿，产后虚弱，泌尿道感染，早期乳腺炎，肝炎，上呼吸道感染，肺炎。\"\n\n③《云南中草药选》：\"调经活血，祛风除湿，消炎止痛。治月经不调，腰腿疼痛，跌打损伤，急慢性胃肠炎，风湿性心脏病，妇女腰痛，子宫脱垂。\"","y":"内服：煎汤，0.5～1两(鲜者2～3两)。","d":"?"},"丝瓜子":{"a":"乌牛子(《纲目拾遗》)。","s":"姚可成《食物本草》：\"苦者：气寒，有毒。甜者：无毒。\"","f":"利水，除热。治肢面浮肿，石淋，肠风，痔瘘。\n\n①姚可成《食物本草》：\"苦者：主大水，面目四肢浮肿，下水，令人吐。甜者：除烦止渴，治心热，利水道，调心肺，治石淋，吐蛔虫。\"\n\n②《医林篆要》：\"治肠风，痔瘘，崩漏，下乳。\"\n\n③《南宁市药物志》：\"通大便。\"","y":"内服：煎汤，1～2钱；或炒焦研末。外用：研末调敷。","d":"干燥种子呈扁平的椭圆形，长约1.2厘米，宽约7毫米，厚约2毫米。种皮灰罴色至黑色，边缘有极狭的翅，翅灼一端有种脊，上方有一对呈叉状的突起。种皮稍硬，剥开后可见有膜状灰绿色的内种皮包于子叶之外。子叶2片，黄白色。气无；味微苦。\n全国大部地区均有。"},"了哥王根":{"a":"毒除根、地棉根、定元根、鱼胆根、地谷根、红赤七、七麻根、别南根、独薯根、狗信蔃。","s":"苦，寒，有毒。\n\n①《福建民间草药》：\"苦，寒，有毒。\"\n\n②《陆川本草》：\"辛微苦，凉。\"\n\n③《广西中药志》：\"味苦微辛，性寒，有毒。\"","f":"清热，利尿，解毒，杀虫，破积。治肺炎，腮腺炎，水肿臌胀，瘰疬，疮疡肿毒，跌打损防。\n\n①《生草药性备要》：\"十蒸九晒，治跌打，煲酒服。亦治恶疮，捶蜜敷亦效。\"\n\n②《岭南采药录》：\"解花柳毒，治恶毒疮和蜜捣敷。以之为末，遇损伤敷之，能止血。\"\n\n③《福建民间草药》：\"消坚破瘀，利尿逐水。\"\n\n④《陆川本草》：\"解热，利尿，破积，治痧积，跌打，疮毒。\"\n\n⑤《广西中药志》：\"杀虫拔毒，治麻风，恶疮，白浊。\"","y":"内服：煎汤(宜煎4小时以上)，3～5钱。外用：研末调敷。","d":"干燥根呈圆柱形，弯曲而有分枝；表面黄棕色，有突起的支根痕和不规则的纵皱纹。皮部纤维极多，不易折断。木部质硬，折断面呈破裂状。横切面近圆形，皮部易剥离，较厚，约占木部的1／2，外侧黄棕色，内部白色，有丝状纤维，形成层明显；木部淡黄色，射线清楚。\n\n产广东、广西、福建等地。"},"马尾连":{"a":"马尾黄连(《中药志》)，金丝黄连(《四川中药志》)，草黄连(《云南中草药》)。","s":"①《纲目拾遗》：\"性寒，味苦。\"\n\n②《四川中药志》：\"性寒，味苦，无毒。\"","f":"清热燥湿，解毒。治痢疾，肠炎，传染性肝炎，感冒，麻疹，痈肿疮疖，结膜炎。\n\n①《纲目抬遗》：\"去皮里膜外及筋络之邪热、小儿伤风及痘科用。\"\n\n②《西藏常用中草药》：\"清热解毒，祛风凉血，消炎止痢。治结膜炎，传染性肝炎，痈肿疮疖，痢疾。叶、花治关节炎。\"\n\n③《新疆中草药手册)：\"清热燥湿。\"","y":"内服：煎汤，1～3钱.外用：研末调敷。","d":"干燥根茎上端有多数芦头，每个芦头粗约4毫米，其上残留茎苗痕迹，并常包有鳞叶薄片。根茎长形，外表棕褐色；腹面密生成束的须根，形如马尾；须根长13～25厘米，粗2～3毫米，外表红黄色或金黄色，有光泽，具纵向细纹，老栓皮及皮层往往呈环节状脱落，尚未剥落者，以手搓之即脱。体轻，质脆易断。根茎断面外圈棕褐色，内有黄色的木质心；须根断面深黄色，外表为一薄层金黄色的外皮。气微，味微苦。以根条均匀、色金黄者为佳。\n主产四川、青海、河北等地。\n\n此外，同属植物香唐松草(分布西藏、四川、青海、甘肃、陕西、山西、河北、内蒙古、新疆)、狭序唐松草(又名：水黄连，分布云南、四川、西藏)、高原唐松草(分布云南、四川、西藏、甘肃)、昭通唐松草(分布云南)，以及贝加尔唐松草长柱变种(分布四川、甘肃)等，亦同等入药。"},"蝌蚪":{"a":"活师(《山海经》)，蛞斗、活东(《尔雅》)，虾蟆子、玄鱼、玄针(崔豹《古今注》)，虾蟆儿(《本草拾遗》)，聒子、虾蟆台、虾蟆粘(《尔雅翼》)，悬针、水仙子(《纲目》)。","s":"性味：甘；寒\n性状：性状鉴别，本品呈扁圆形或不规则的圆状，皱缩，灰黑色，大部尾巴脱落，腹扁平，背隆起。长15mm，宽8-10mm，腹部有螺旋形圈紊或不明显。质脆易碎，气味腥臭。","f":"清热解毒。治热毒疮肿。\n\n①《本草拾遗》：\"主火飚热疮及疥疮，并捣碎敷之。\"\n\n②《本草蒙筌》：\"烂捣为火疮敷药，绝无瘢痕。\"","y":"外用：捣敷，或经埋藏化水后搽敷。","d":"?"},"红根":{"a":"长虫包谷、小独脚莲、见血飞。","s":"辛麻，寒，剧毒。","f":"清热消炎，拔脓。治疗疮，痈疽，无名肿毒，腮腺炎，乳痈。","y":"外用：捣敷或研末调敷。","d":"?"},"白兰花":{"a":"白兰,白玉兰","s":"苦辛，温。\n\n①《四川中药志》：\"苦，微温，无毒。\"\n\n②广州空军《常用中草药手册》：\"辛，温。\"","f":"止咳，化浊。治慢性支气管炎。前列腺炎，妇女白带。\n\n①《四川中药志》：\"治白浊及女子白带。\"\n\n②广州空军《常用中草药手册》：\"行气化浊，止咳。治前列腺炎，妇女白带，小儿支气管炎，虚劳久咳。\"","y":"内服：煎汤，3～5钱。","d":"?"},"鳝鱼血":{"a":"?","s":"味咸；性温 \n\n①《本草汇言》：\"味咸甘，气平，无毒。\"\n\n②《医林纂要》：\"咸，温。\"\n\n归肝；肾经 \n\n《本草汇言》：\"入足厥阴、少钥经。\"","f":"祛风，活血，壮阳。治口眼歪斜，耳痛，鼻衄，癣，瘘。\n\n①《本草拾遗》：\"主癣及瘘，断取血涂之。\"\n\n②《纲目》：\"疗口眼歪斜，同麝香少许，左歪涂右，右歪涂左，正即洗去。治耳痛，滴数点入耳。治鼻衄，滴数点入鼻。治疹后生翳，点少许入目。治赤疵，同蒜汁、墨汁频涂之，又涂赤游风。\"\n\n③《本草汇言》：\"去风活血。治血燥筋挛。\"\n\n④《本经逢原》：\"助阳。\"\n\n⑤《医林纂要》：\"正经络，去壅滞，缓风软坚，渗湿去热。\"","y":"外用：涂敷或滴入耳、鼻。内服：和药作丸。","d":"?"},"杏叶":{"a":"杏树叶","s":"辛；苦；微凉","f":"治目疾，水肿。\n\n①《滇南本草》：\"敷大恶疮。\"\n\n②《本草蒙筌》：\"煎汤洗眼止泪。\"","y":"内服：煎汤，3-10g；外用：煎水洗。","d":"?"},"百步还阳丹":{"a":"鸟巢兰","s":"甘，平。","f":"强心兴奋，活血散瘀，接骨生肌。治外伤性昏迷，跌打损伤，骨折。","y":"内服：研末，0.5～1钱。外用：研末调敷或捣敷。","d":"?"},"金银花露":{"a":"金银露（《金氏药帖》)，忍冬花露(《中国医学大辞典》)","s":"《纲目拾遗》：\"气芬郁而味甘。\"","f":"清热，消暑，解毒。治暑温口渴，热毒疮疖。\n\n①《金氏药帖》：\"专治胎毒及诸疮痘毒热毒。\"\n\n②《纲目拾遗》：\"开胃宽中，解毒消火，以之代茶，尤能散暑。\"\n\n③《中国医学大辞典》：\"养血，止渴。治温热痧痘，痈疽，梅毒，血痢。\"","y":"内服：隔水炖温饮，2～4两。","d":"?"},"珍珠草":{"a":"日开夜闭、十字珍珠草(《生草药性备要》)，阴阳草、假油柑(《临证指南》)，真珠苹(《纲目拾遗》)，鲫鱼草、胡羞羞(《广州植物志》)，老鸦珠(《福建民间草药》)，夜合珍珠(《民间常用草药汇编》)，落地油柑、小利柑(《陆川本草》)，蓇草(《南宁市药物志》)，夜合草(《江西民间草药》)，山皂角(《贵州民间药物》)，叶后珠(《四川中药志》)，油柑草(《福建中草药》)，鱼鳞草(徐州《单方验方新医疗法选编》)。","s":"甘苦，凉。\n\n①《植物名实图考》:\"性凉。\"\n\n②《福建民间草药》:\"苦，寒。\"\n\n③《南宁市药物志》:\"甘苦。\"","f":"平肝清热，利水解毒。治肠炎，痢疾，传染性肝炎，肾炎水肿，尿路感染，小儿疳积，火眼目翳，口疮头疮，无名肿毒。\n\n①《生草药性备要》:\"治小儿疳眼，疳积，煲肉食或煎水洗。\"\"治头上生疮仔成堆，痛痒难抵，煎水洗，研末开油搽亦可。\"\n\n②《临证指南》:\"治小儿诸疳瘦弱，眼欲盲。为末白汤下，或蒸煮鱼肉食。\"\n\n③《植物名实图考》:\"治瘴气。\"\n\n④《福建民间草药》:\"平肝，退火，明目，治蛇咬伤。\"\n\n⑤《贵州民间药物》:\"理气消肿。\"\n\n⑥广州部队《常用中草药手册》:\"清肝明目，渗湿利水。治肾炎水肿，尿路感染，尿路结石。\"","y":"内服:煎汤，0.5～1两(鲜者1～2两)；或捣汁。外用:捣敷。","d":"干燥带根全草，根茎外表浅棕色，有髓；主根不发达，须根多数，浅灰棕色。茎粗约2～3毫米，老茎基部灰褐色；茎枝有纵皱，灰棕色、灰褐色或棕红色；质脆易断，断面中空。分枝有纵皱及不甚明显的膜翅状脊线。叶片薄而小，灰绿色，皱缩，易脱落。花细小，腋生于叶背之下，多已于缩。有的带有扁圆形亦褐色的果实。气微香，叶味微苦。\n主产广东、广西、四川等地。"},"木黄连":{"a":"土黄连(《广西中药志》)。","s":"味苦，性寒，无毒。","f":"清心胃火，解毒。治阳黄、热痢、赤眼；外治刀伤，火烫伤。(性味以下出《广西中药志》)","y":"内服：煎汤，2～5钱。外用：捣敷。","d":"茎呈圆柱形，表面暗棕色或灰褐色，有浅纵沟和横向裂纹，幼茎较平滑，往往有突起的叶痕及叶柄残基，栓皮质松，脱落处可见黄色木部；质坚脆，折断面呈破裂状，淡黄色；横切面近圆形，髓部淡黄色，木部黄色，射线清晰。根呈圆柱状，略扭曲，表面棕黄色，有纵沟纹及支根疤痕；质坚硬，不易折断，断面黄色。\n\n同属植物苏氏十大功劳、半覆瓦十大功劳、独龙十大功劳等的根，在广西民间亦称木黄连或土黄连，并与本品同等使用。"},"黄疸树":{"a":"刺黄连、树黄连、土黄连(《广西中药志》)，长叶小檗、土黄柏(《中国高等植物图鉴》)，三颗针(《广西中草药》)。","s":"《广西中药志》：\"味苦，性寒，无毒。\"","f":"清热解毒。治肝炎，胆囊炎，肠炎，菌痢，咽喉炎，结膜炎，尿道炎，疮疡肿毒。\n\n①《广西中药志》：\"治消化不良，腹痛，肠炎下痢等症。\"\n\n②《广西中草药》：\"清热解毒。治细菌性痢疾，肠胃炎，咽喉炎，口腔炎，尿道炎，急性结膜炎，疮疡溃烂。预防流脑。\"\n\n③苏医《中草药手册》：\"治急性肝炎，胆囊炎。\"","y":"内服；煎汤，3～5钱。外用：煎水洗。","d":"干燥的茎呈类圆柱形，表面灰棕色，有沟纹，并有少数小形皮孔。上部多分枝，枝直径约3～5毫米，显灰棕至暗棕色，表面有明显的纵棱数条；针刺较多，单个或2～3分叉。主根呈圆柱形，直径达4～5厘米或以上；根头部留有茎基及芽；侧根及支根呈扭曲状；外表土黄色至灰棕色，栓皮易片状脱落而露出棕黄色的皮部。茎枝及根的质地坚硬，断面强纤维性，呈鲜黄色，茎及枝中央具髓部；根无髓，木质部占绝大部分。断面置萤光灯下可见强烈的黄色萤光。味极苦。\n产于广西、江苏等地。"},"三角风":{"a":"爬山虎、异叶地锦、小叶红藤、吊岩风、三皮风","s":"苦，温。\n\n①《贵州民间药物》：\"苦涩，无毒。\"\n\n②《浙江民间常用草药》：\"甘微涩，温。\"","f":"祛风除湿，通络，止血，解毒。治风湿痹痛，偏头痛，风湿疮毒，骨折。\n\n①《贵州民间药物》：\"祛风，解毒，接骨。\"\n\n②《浙江天目山药植志》：\"治疖毒，创伤。\"\n\n③《浙江民间常用草药》：\"祛风湿，通经络，止血。\"","y":"内服：煎汤，0.5～1两。外用：捣敷，煎水洗或磨汁涂。","d":"?"},"布荆":{"a":"五指疳、五指风、山紫荆(《广西药植名录》)，梅哈忍(傣名)。","s":"淡，平。","f":"止咳定喘，镇静退热。治急、慢性气管炎，支气管炎，喘咳，气促，小儿发热烦躁不安。","y":"内服：煎汤，2～3钱。(性味以下出《云南思茅中草药选》)","d":"?"},"薏苡根":{"a":"打碗子根(《草木便方》)，五谷根(《分类草药性》)，尿珠根(成都《常用草药治疗手册》)。","s":"苦甘，寒。\n\n①《滇南本草》：\"性寒，味苦微甘。\"\n\n②《纲目》：\"甘，微寒，无毒。\"\n\n③《浙江民间草药》：\"性凉，味淡，无毒。\"","f":"清热，利湿，健脾，杀虫。治黄疸，水肿，淋病，疝气，经闭，带下，虫积腹痛。\n\n①《本经》：\"下三虫。\"\n\n②《补缺肘后方》：\"治卒心腹烦满，又胸肿痛欲死，锉薏苡根，浓煮取汁服。\"\n\n③陶弘景：\"小儿病蛔虫，取根煮汁糜食之。\"\n\n④《滇南本草》：\"清利小便。治热淋疼痛，尿血，止血淋、玉茎疼痛，消水肿。\"\n\n⑤《本草蒙筌》：\"治肺痈。\"\n\n⑥《纲目》：\"捣汁和酒服，治黄疸。\"\n\n⑦《草木便方》：\"能消积聚癥瘕，通利二便，行气血。治胸痞满，劳力内伤。\"\n\n⑧《分类草药性》：\"治疝气。\"\n\n⑨《浙江民间草药》：\"治白带。\"","y":"内服：煎汤，3～5钱(鲜品1～2两)。","d":"?"},"百两金":{"a":"八爪龙、八爪金龙(《草木便方》)，开喉剑、叶下藏珠、状元红(《天宝本草》)，山豆根、铁雨伞、真珠凉伞(《福建中草药》)，野猴枣、珍珠伞(江西《草药手册》)。","s":"苦辛，凉。\n\n①《本草图经》：\"苦，平，无毒。\"\n\n②《分类草药性》：\"味涩。\"\n\n③《福建中草药》：\"微甘辛，凉。\"","f":"清热，祛痰，利湿。治咽喉肿痛，肺病咳嗽，咯痰不畅，湿热黄疸，肾炎水肿，痢疾，白浊，风湿骨痛，牙痛，睾丸肿痛。\n\n①《本草图经》：\"治壅热咽喉肿痛，含一寸许咽津。晒干用，治风涎。\"\n\n②《分类草药性》：\"治风湿筋骨疼痛。\"\n\n③《天宝本草》：\"治咽喉红肿，火牙肿疼。\"\n\n④《福建中草药》：\"清热利湿。治湿热黄疸，痢疾，白浊，睾丸肿大坠痛，秃疮，疥癣。\"\n\n⑤江西《中草药学》：\"消肿，祛痰。\"","y":"内服：煎汤，0.5～1两(鲜品1～2两)。外用：煎水含漱或研末调敷。","d":"取本品粉末10g，加甲醇50ml，加热回流10分钟，滤过。滤液加少量活性炭脱色，滤过。取滤液1ml，加亚硝酸钠少量与硫酸1ml，温热，放置后呈红色。(检查岩白菜素)"},"小柿子":{"a":"地石榴、跳八丈，小面瓜，牙万卖(傣名)。","s":"味苦，涩；性凉。归心、大肠经。\n《云南思茅中草药选》：\"苦涩，凉。\"","f":"清热利湿；凉血解毒。主外感发热；咽痛；泄泻；痢疾；崩漏；白带。\n①《云南中草药》：\"收敛止血。治月经过多，崩漏，痛经，白带，痢疾，腹泻，黄疸，预防流脑。\"\n\n②《云南思茅中草药选》：\"清热解毒，止血镇痛。治急性胃肠炎，痢疾，感冒发热，腹痛泄泻，咽喉炎，扁桃腺炎。\"","y":"外用：适量，鲜叶捣敷；或煎水洗；或晒干研粉撒包。","d":"?"},"李子":{"a":"李实(《别录》)，嘉庆子(《两京记》)。","s":"甘酸，平。\n\n①《别录》：\"味苦。\"\n\n②《干金·食治》：\"苦酸，微温，涩，无毒。\"\n\n③崔禹锡《食经》：\"小冷。\"\n\n④《日用本草》：\"味苦甘酸，微毒。\"","f":"清肝涤热，生津，利水。治虚劳骨蒸，消渴，腹水。\n\n①《别录》：\"除痼热，调中。\"\n\n②孟诜：\"去骨节间劳热。\"\n\n③《日华子本草》：\"益气。\"\n\n④《滇南本草》：\"治风湿气滞血凝。\"\n\n⑤《医林纂要》：\"养肝，泻肝，破瘀。\"\n\n⑥《随息居饮食谱》：\"清肝涤热，活血生津。\"\n\n⑦《泉州本草》：\"清湿热，解邪毒，利小便，止消渴。治肝病腹水，骨蒸劳热，消渴引饮等证。\"","y":"内服：生食或捣汁。","d":"?"},"木芙蓉叶":{"a":"拒霜叶(《世医得效方》)，芙蓉花叶(《普济方》)，铁箍散(《湖南药物志》)。","s":"辛，平。\n\n①《本草图经》：\"味辛，平，无毒。\"\n\n②《纲目》：\"微辛，平，无毒。\"","f":"凉血，解毒，消肿，止痛。治痈疽焮肿，缠身蛇丹，烫伤，目赤肿痛，跌打损伤。\n\n①《本草图经》：\"敷贴肿毒。\"\n\n②《滇南本草》：\"可箍疮出头。\"\n\n③《纲目》：\"清肺凉血，散热解毒。治一切大小痈疽肿毒恶疮，消肿排脓止痛。\"\n\n④《玉楸药解》：\"清风泄热，凉血消肿。\"\n\n⑤《民间常用草药汇编》：\"外用接骨。\"","y":"外用：研末调敷或捣敷。","d":"干燥叶片，有叶柄，粗约0.3厘米，黄褐色；叶片大形，常折叠，叶面灰绿色，叶背淡绿色，脉隆起，枝灰色星状毛。"},"鸡肝散":{"a":"黑头草(《云南思茅中草药选》)，细野菝子(《红河中草药》)，滇香薷、四棱蒿(《云南中草药选》)。","s":"苦辛，凉。\n\n①《云南思茅中草药选》：\"苦辛，凉。\"\n\n②《云南中草药》：\"微苦辛，平。\"","f":"清热，消炎，止痛。治肾盂肾炎，肾炎，感冒，肝炎，痢疾，肠炎，牙痛，结合膜炎，创伤出血。\n\n①《云南思茅中草药选》：\"清热解毒，止血镇痛。治肾盂肾炎，咽喉炎，扁桃腺炎，感冒，风火牙痛，龋齿痛，急性胃肠炎，创伤出血。\"\n\n②《云南中草药》：\"健脾利湿，消炎止痛。治夜盲症，痢疾腹痛，腋臭，火烧伤。\"\n\n③《红河中草药》：\"清肝明目，消疳，止痒。\"","y":"内服：煎汤，1～3钱；研末或捣汁；或炖肉，外用：捣汁涂或研末撒。","d":"?"},"枸杞叶":{"a":"地仙苗(《日华子本草》)，甜菜(《本草图经》)，枸杞尖(《滇南本草》)，天精草(《保寿堂经验方》)，枸杞苗(《纲目》)，枸杞菜(《生草药性备要》)，枸杞头(《江苏植药志》)。","s":"苦甘，凉。\n\n①《药性论》:\"味甘，平。\"\n\n②《千金·食治》:\"味苦，平，涩，无毒。\"\n\n③《纲目》:\"苦甘，凉。\"","f":"补虚益精，清热，止渴，祛风明目。治虚劳发热，烦渴，目赤昏痛，障翳夜盲，崩漏带下，热毒疮肿，\n\n①《药性论》:\"能补益精诸不足，易颜色，变白，明目，安神。和羊肉作羹，益人，甚除风，明目；若渴可煮作饮，代茶饮之；发热诸毒烦闷，可单煮汁解之，能消热面毒；主患眼风障赤膜昏痛，取叶捣汁注眼中。\"\n\n②《食疗本草》:\"坚筋耐老，除风，补益筋骨，能益人，去虚劳。\"\n\n③《口华子本草》:\"除烦益志，补五劳七伤，壮心气，去皮肤骨节间风，消热毒，散疮肿。\"\n\n④《纲目》:\"去上焦心肺客热。\"\n\n⑤《生草药性备要》:\"明目，益肾亏，安胎宽中，退热，治妇人崩漏下血。\"\n\n⑥《本经逢原》:\"能降火及清头目。\"","y":"内服:煎汤，鲜者2～8两；煮食或捣汁。外用:煎水洗或捣汁滴眼。","d":"性状鉴别 单叶或数处叶簇生于嫩枝上。叶片皱缩，展平后卵形或长椭圆形，长2-6cm，宽0.5-2.5cm，全缘。表面深绿色。质脆，易碎。气微，味苦。"},"马尿烧":{"a":"按骨木(《黑龙江中药》)，本巴木(《黑龙江常用中草药手册》)。","s":"《天津中草药》：\"甘苦，平。\"","f":"活血，止痛，祛风湿.治跌打损伤，骨折，风湿痹痛。\n\n①《黑龙江中药》：\"木顾部及叶，治筋骨折仿，挫伤，内服煎剂有利尿作用。根叶，治跌打损伤。\"\n\n②《黑龙江常用中草药手册》：\"活血止痛。治腰腿疼痛，关节炎和大骨节病的筋骨疼痛。\"\n\n③《天津中草药》：\"舒筋活血，去风湿，消肿，接骨。治产妇恶血，风痹。\"","y":"内服：煎汤0.5～l两(鲜者2～3两)。外用：捣敷戌煎水洗浴。","d":"?"},"红升麻根":{"a":"异叶泽兰","s":"苦微辛麻，凉。","f":"解表退热，","y":"?","d":"?"},"老虎姜":{"a":"白药子(《宁夏中草药手册》)，盘龙七、算盘七，鸡头参、山姜（《陕西中草药》)，惹涅(藏名)","s":"甘辛，平。\n\n①《陕西中草药》：\"味甘微辛，性温，有小毒。\"\n\n②《宁夏中草药手册》：\"辛，平。\"\n\n③《西藏常用中草药》：\"性平，味甘。\"\n\n入肺经。","f":"润肺养阴，健脾益气，祛痰止血，消肿解毒。治虚痨咳嗽，头昏，食少，遗精，盗汗，崩漏带下，产后体亏，吐血，衄血，外伤出血，咽喉肿痛，疮肿，瘰疬。\n\n①《陕西中草药》：\"补脾润肺，滋阴补肾，行气活血，收敛止血，拔毒杀菌。治脾虚少食，肺虚咳嗽，头昏体痛，遗精盗汗，崩漏白带，疮疖初起，瘰疬。\"\n\n②《宁夏中草药手册》：\"祛痰止血，消肿解毒。治咳嗽吐血，鼻出血，外伤出血，咽喉肿痛，疮疡肿毒。\"\n\n③《西藏常用中草药》：\"补益脾胃，润肺生津。治诸虚不足，虚痨咳嗽，筋骨痿软。\"\n\n④南川《常用中草药手册》：\"补肾益肺，益气滋阴。治产后气血虚弱。\"","y":"内服：煎汤，2～5钱；研末或浸酒。外用：捣敷或水磨汁涂。","d":"卷叶黄精，又名：轮叶黄精。\n多年生草本，高80～150厘米。根茎肥大，成不规则的结节块状，形似生姜，茎痕明显，呈圆盘状。茎圆柱形，具条棱，梢弯曲。叶3～8片轮生，线状披针形，长7.5～12厘米，先端卷曲，下面有粉。花小，白色、绿色或带紫色，每一总花梗着生1～4花，轮生；苞片披针形，白色，膜质；花被筒状，先端6裂，裂口有乳突状短柔毛；雄蕊生花被筒中部以上，花丝有缘毛；花柱长等于子房。浆果球形，熟时黑色。\n生于高山林缘。分布宁夏、西藏、新疆、陕西、甘肃、湖北、四川及东北等地。山东等地亦有栽培。"},"通光散":{"a":"奶浆藤(《贵州药植目录》)，乌骨藤、黄木香、下奶藤(《云南中草药选》)，大苦藤、地甘草(《云南思茅中草药选》)，扁藤、癞藤子、白暗消(《红河中草药》)。","s":"①《云南中草药选》：\"苦，微寒。\"\n\n②《红河中草药》：\"苦微甘，凉。\"","f":"清热解毒，止咳平喘。治肺炎，支气管炎，支气管哮喘，咽喉炎，扁桃体炎，膀胱炎，疗疮肿毒。\n\n①《云南中草药选》：\"消炎，止咳，平喘，抗癌。治支气管炎，支气管哮喘，各种癌症，风湿，跌打，骨折，眼底疾患，胃病。\"\n\n②《云南思茅中草药选》：\"清热解毒，消炎止痛。治咽喉炎，胃肠积热，肺炎，扁桃体炎，膀胱炎。\"\n\n③《贵州药植目录》：\"活血生肌，催乳，止咳。治咳嗽，跌打，筋断骨折，乳少。\"","y":"内服：煎汤，3～5钱。外用：捣敷。","d":"?"},"满山红":{"a":"映山红,迎山红,山崩子,靠山红,达子香,金达来,东北满山红","s":"辛；苦；性寒；小毒 。归肺经 。","f":"止咳，祛疾。治慢性支气管炎，咳嗽 。\n\n①《黑龙江常用中草药手册》：\"治慢性支气管炎，支气管喘息。\"\n\n②《东北常用中草药手册》：\"止咳，祛疾。治慢性支气管炎，咳嗽。\"","y":"内服：煎汤(鲜者)，0.5～1两。","d":"性状鉴别 叶片多反卷成筒状，有的皱缩破碎。完整叶片展平后呈长椭圆形或长倒卵形，长2-7．5cm，宽1-3cm，先端钝，基部近圆形或宽楔形，全缘，上表面暗绿色至褐绿色，散生浅黄色腺鳞，下表面灰绿色，腺鳞甚多，主脉于下面突起，侧脉4-6对。叶柄长3-10mm。近革质。气芳香而特异，味稍苦、微辛。以叶片完整、色暗绿者为佳。显微鉴别 叶表面观：上、下表皮细胞垂周壁均略呈波状弯曲。上表皮具多数单细胞非腺毛，长60-240μm，直径约8μm。下表皮具多数不定式气孔，并有多数大型圆形腺鳞；呈菊花状；腺头由2层狭长细胞放射状组成，边缘平整，直径120-150μm，细胞内常含油滴状物；腺柄短，横切面观可见由2-4细胞组成。薄壁组织和海绵组织中散有多数草酸钙簇晶，直径约8μm。（图（2)理化鉴别（1)取本品粉末5g，加乙醚50ml，加热回流1h，滤过，滤液蒸干，残渣加碳酸钠饱和溶液10ml，置水浴上加热使溶解，加氯化钠与无水碳酸钠各1g，充分振摇，滤过，滤液加盐酸调节pH至2-3滤过，沉淀，用水洗涤至洗液呈中性后，自滤纸上加乙醚4ml使溶解。取醚液1ml，加等量的乙醇摇匀，分为2份，一份中加乙酸铅饱和溶液1-2滴，振摇放置，析出黄色结晶；另一份中加镁粉少量与盐酸4滴，振摇，显淡红色至淡棕红色。（检查黄酮) （2)理化鉴别 薄层色谱①取叶粗粉5g，加1g碳酸钙，加乙醇50ml，水浴回流2h，残渣加乙醇50ml，回流1h，合并滤液，取半量，减压浓缩至干，残渣用热水洗，浓缩至5ml，用乙酸乙酯提取，经无水硫酸钠脱水，滤过，减压浓缩至干，残渣溶于甲醇0．5ml中，作供试品液，另取金丝桃甙、槲皮素作对照品，分别点样于同一聚酰胺薄膜上，以氯仿-甲醇-丁酮-乙酸丙酮（16：10：5：1)展开8cm，置紫外灯（254nm)下检视。供试品色谱在与对照品色谱相应的位置上，显相同颜色的斑点。②取①保留的半量乙醇提取液，减压浓缩到5ml，加等量蒸馏水，再加入足量的乙酸铅饱和水溶液，滤过，滤液用硫酸钠饱和水溶液脱铅后，滤过，滤液浓缩至5ml，用氯仿热提30min，用无水硫酸钠脱水，蒸干，残渣溶于甲醇0．25ml中，作供试品液，另以侵木毒素-1、莨菪亭作对照品，分别点样于同一硅胶G薄板上，以己烷-甲醇-乙酸乙酯（5：1：4)展开20cm，用10％三氯化锑氯仿液显色；置紫外灯（254nm)下检视。照山白供试品色谱在与对照品色谱的相应位置上，显相同颜色的斑点。满山红、烈香杜鹃、紫花杜鹃仅在与对照品莨菪亭相应位置上，显相同的色斑。品质标志《中华人民共和国药典》1995年版规定：本品按干燥品计算，含总黄酮以芦丁（C27H30O16)计，不得少于2．0％。"},"飞天蜈蚣":{"a":"蜈蚣草、神仙对坐草、石上蜈蚣、落地蜈蚣、百足草(《陆川本草》)，铁斑鸠、巴岩姜(《贵州民间药物》)。","s":"《贵州民间药物》：\"辛，温。\"\n入肺，肝二经。","f":"消肿止痛。治跌打损伤，痈肿疮毒，眼生翳膜。\n\n①《陆川本草》：\"消肿，止痛。治跌打，疮痈。\"\n\n②《贵州民间药》：\"接骨，止痛。治痨伤。\"","y":"内服：煎汤，0.5～1两；或泡酒。外用：捣敷。","d":"?"},"黄桷皮":{"a":"黄葛树皮","s":"《草木便方》：\"苦酸，温。\"","f":"治风湿痹痛，四肢麻木，半身不遂，癣疮。\n\n①《居易录》：\"愈癣。\"\n\n②《草木便方》：\"祛风，除湿，消肿满。治四肢顽痹，麻(木)不仁，半身不遂。\"\n\n③《中国药植志》：\"发汗发表。\"\n\n④《重庆草药》：\"煎水服治吐血，煎水洗治初生儿黄七风(初生儿五至七天，全身现黄，高热惊风)。\"","y":"内服：煎汤，0.5～1两。外用：煎水洗。","d":"?"},"梧桐叶":{"a":"?","s":"《福建民间草药》：\"苦，寒，无毒。\"","f":"祛风除湿，清热解毒。治风湿疼痛、麻木，痈疮肿毒，痔疮，臁疮，创伤出血，高血压病。\n\n①《中国树木分类学》：\"煮汁可熏治白带。\"\n\n②《贵州民间方药集》：\"镇咳祛痰，除风湿，治麻木。外用止刀伤出血。\"\n\n③广州部队《常用中草药手册》：\"清热解毒。治痈疮肿毒。\"","y":"内服：煎汤，0.5～1两。外用：鲜叶敷贴，煎水洗或研末调敷。","d":"?"},"飞机草":{"a":"香泽兰(广州部队《常用中草药手册》)","s":"广州部队《常用中草药手册》：\"微辛，温。\"","f":"广州部队《常用中草药手册》：\"杀虫，止血。治旱蚂蝗咬后流血不止，用鲜叶揉烂涂伤口。\"","y":"外用：适量，鲜品捣敷或揉碎涂擦。","d":"?"},"橘红珠":{"a":"橘珠、橘胎(《广西中药志》)。","s":"《广西中药志》：\"味酸苦，性温，无毒。\"","f":"《广西中药志》：\"止渴，助消化，除胸中气滞。治食积，癥瘕。\"","y":"内服：煎汤，1～3钱。","d":"干燥幼果近球形，径4～5厘米。表面黄绿色，密被灰绿色短绒毛，先端有花柱脱落的痕迹，基部有呈圆形果柄的疤痕。质坚硬，不易切开，断面平整，淡红棕色。气香，味苦而涩。"},"走马风":{"a":"吊钟黄(《广州植物志》)，水马胎、赶风茜(《广西民间常用草药》)，牛耳三稔、飞山虎、羊耳三稔(《广东中草药》)。","s":"①《广西民间常用草药》：\"辛，平，气香，无毒。\"\n\n②广州空军《常用中草药手册》：\"味苦微辛，性温。\"","f":"祛风湿，通经络。治妇女头风痛，风湿痹痛，跌打损伤。\n\n①《广西药植名录》：\"治外伤肿痛。\"\n\n②《广西民间常用草药》：\"治妇女产后骨痛，头痛，风湿骨痛，跌打肿痛。\"\n\n③《广西中草药》：\"驱风除湿，通经活络。\"\n\n④广州空军《常用中草药手册》：\"祛风湿，通经活络，解表止痛。治风湿性关节炎，头痛，跌打扭伤，毒蛇咬伤，湿疹，皮炎，痈疮，疖肿。\"","y":"内服：煎汤，1～2两。外用：捣敷或煎汤洗。","d":"?"},"蓖麻叶":{"a":"?","s":"《纲目》：\"有毒。\"","f":"治脚气，防囊肿痛，咳嗽痰喘，鹅掌风，疮疖。\"\n\n①《唐本草》：\"主脚气风肿不仁，捣蒸敷之。\"\"油除叶炙热熨囟上，止衄尤验也。\"\n\n②《纲目》：\"治痰喘咳嗽。\"\n\n③《陆川本草》：\"治恶疮。\"\n\n④《广东中药》Ⅱ：\"煎水外洗，治盗汗。\"","y":"内服：入丸、散。外用：煎洗、热熨或捣敷。","d":"干燥叶片大多破碎皱缩，完整者呈掌状深裂，径20～40厘米，裂片卵状披针形至矩圆形，边有不规则锯齿，上面绿褐色或红褐色，下面淡绿色，主脉掌状，侧脉羽状，两面凸起；纸质；叶柄盾状着生，暗红色。气微，味苦淡。以干燥无枝梗者佳。"},"天浆壳":{"a":"天将壳,萝摩荚,哈喇瓢,赖瓜瓢,羊角,麻雀棺材,剌猬瓜,野羊角,和尚瓢,初风瓢,老鸹瓢","s":"味甘、辛、性平 \n\n归肺；肾经","f":"清肺化痰。治咳嗽痰多，肺风痰喘，百日咳，惊病，麻疹不透。\n\n①《饮片新参》：\"软坚，化痰，清肺。治肺风痰喘，定惊痫。\"\n\n②《药材资料汇编》：\"治小儿麻疹。\"\n\n③江西《草药手册》：\"治肺风痰喘，损伤出血。\"\n\n④《上海常用中草药》：\"化痰，止咳，平喘，治咳嗽痰多，气喘，百日咳，麻疹透发不畅，发热咳嗽。\"","y":"内服：煎汤，2～3钱。","d":"干燥果壳，对开似舟状，基部钝圆，可见果柄或脱落的圆形疤痕；另端渐狭而长，顶端反卷；长约7～10厘米，宽约4厘米。果皮厚约1.5毫米，外表面黄绿色，具纤维状纹理及疣状突起；内表面黄白色，光滑而润泽。纤维性强，不易折断。无气味。以干燥、大而完整、青黄色，无杂质为佳。\n产于江苏、上海、浙江等地。"},"茉莉花":{"a":"小南强(《清异录》)，柰花(《丹铅杂录》)，鬘华(《群芳谱》)，木梨花(《中国树木分类学》)。","s":"辛甘，温。\n\n①《纲目》：\"辛，热，无毒。\"\n\n②《本草再新》：\"味甘辛，性热，无毒。\"\n\n③《随息居饮食谱》：\"辛甘，温。\"\n\n④《饮片新参》：\"苦微甘。\"","f":"理气，开郁，辟秽，和中。治下痢腹痛，结膜炎，疮毒。\n\n①《本草再新》：\"能清虚火，去寒积，治疮毒，消疽瘤。\"\n\n②《随息居饮食谱》：\"和中下气，辟秽浊。治下痢腹痛。\"\n\n③《饮片新参》：\"平肝解郁，理气止痛。\"\n\n④《现代实用中药》：\"洗眼，治结膜炎。\"\n\n⑤《四川中药志》：\"用菜油浸泡，滴入耳内，治耳心痛。\"","y":"内服：煎汤，0.5～1钱；或泡茶。外用：煎水洗目或菜油浸滴耳。","d":"干燥的花，长1.5～2厘米，直径约1厘米，鲜时白色，干后黄棕色至棕褐色，冠筒基部的颜色略深；末开放的花蕾全体紧密叠合成球形，花萼管状，具细长的裂齿8～10个，外表面有纵行的皱缩条纹，被稀短毛；花瓣片椭圆形，先端短尖或钝，基部联合成管状。气芳香，味涩。以纯净、洁白者为佳。\n产江苏、四川、广东等地。"}};
